def _friendly_faculty_db_error(e):
    """Map a raw Faculty INSERT/UPDATE failure to a message safe to show a
    user — never the raw Postgres exception text. faculty has exactly two
    uniqueness constraints that can fire here — verified directly against
    the live database (pg_constraint), since the live schema's actual
    constraint names (pk_faculty / uq_faculty_email) differ from the
    faculty_pkey / faculty_email_key names in the checked-in schema.sql."""
    if isinstance(e, psycopg2.errors.UniqueViolation):
        constraint = getattr(getattr(e, 'diag', None), 'constraint_name', '') or ''
        if constraint in ('pk_faculty', 'faculty_pkey'):
            return "This Faculty Number is already registered. Please use a different faculty number."
        if constraint in ('uq_faculty_email', 'faculty_email_key'):
            return "This email address is already registered. Please use a different email address."
        return "Unable to save faculty. This record conflicts with an existing one."
    return "Unable to save faculty. Please check the information and try again."

_SCHEMA_LOCK = threading.RLock()

_source_col_ensured = False
_original_status_col_ensured = False
_schedule_version_empnum_col_ensured = False

_SCHEDULE_VERSION_SCHEMA_SQL = (
    "ALTER TABLE public.schedule_version "
    "ADD COLUMN IF NOT EXISTS source VARCHAR(50) DEFAULT 'official'",
    "ALTER TABLE public.schedule_version "
    "ADD COLUMN IF NOT EXISTS original_status VARCHAR(20)",
    "ALTER TABLE public.schedule_version "
    "ADD COLUMN IF NOT EXISTS employeenumber VARCHAR(30) REFERENCES public.faculty(employeenumber)",
    "ALTER TABLE public.schedule_version "
    "ADD COLUMN IF NOT EXISTS is_removal BOOLEAN NOT NULL DEFAULT FALSE",

    """
    UPDATE public.schedule_version
    SET    original_status = status
    WHERE  original_status IS NULL AND status IN ('Draft', 'Published')
    """,
    """
    UPDATE public.schedule_version sv1
    SET    original_status = (
        SELECT MAX(sv2.original_status)
        FROM   public.schedule_version sv2
        JOIN   public.schedule sg2 ON sv2.scheduleid = sg2.scheduleid
        JOIN   public.schedule sg1 ON sv1.scheduleid = sg1.scheduleid
        WHERE  sv2.version_number  = sv1.version_number
          AND  sg2.semesterid      = sg1.semesterid
          AND  sv2.original_status IS NOT NULL
    )
    WHERE  sv1.original_status IS NULL AND sv1.status = 'Archive'
    """,
    """
    UPDATE public.schedule_version
    SET    original_status = 'Draft'
    WHERE  original_status IS NULL
    """,
)


def _schedule_version_schema_ready():
    return (_source_col_ensured and _original_status_col_ensured
            and _schedule_version_empnum_col_ensured)


def _ensure_schedule_version_schema():
    """Apply the schedule_version column migrations on a dedicated connection.

    Idempotent and cheap once done. lock_timeout makes it fail fast (logged, flags
    left unset, retried later) instead of waiting behind a busy table. Returns True
    when the schema is ready.
    """
    if _schedule_version_schema_ready():
        return True
    with _SCHEMA_LOCK:
        if _schedule_version_schema_ready():
            return True
        return _apply_schedule_version_schema()


def _apply_schedule_version_schema():
    global _source_col_ensured, _original_status_col_ensured, _schedule_version_empnum_col_ensured
    conn = None
    try:
        conn = get_db_connection()
        cur = conn.cursor()
        cur.execute("SET LOCAL lock_timeout = '5s'")
        for sql in _SCHEDULE_VERSION_SCHEMA_SQL:
            cur.execute(sql)
        conn.commit()
        _source_col_ensured = _original_status_col_ensured = True
        _schedule_version_empnum_col_ensured = True
        return True
    except Exception as e:
        try:
            if conn is not None:
                conn.rollback()
        except Exception:
            pass
        print(f'[schema] schedule_version columns not ensured yet: {e}')
        return False
    finally:
        try:
            if conn is not None:
                conn.close()
        except Exception:
            pass


# Legacy call sites pass their request cursor. These never execute DDL on it: they only
# make sure the dedicated-connection migration has run.
def _ensure_source_col(cur=None):
    _ensure_schedule_version_schema()


def _ensure_original_status_col(cur=None):
    _ensure_schedule_version_schema()


def _ensure_schedule_version_empnum_col(cur=None):
    _ensure_schedule_version_schema()

def _friendly_db_error(e):
    """Map a low-level DB/psycopg2 error to a message safe to show the Academic
    Head. Full technical detail (the actual str(e)) still goes to the server
    log/traceback via the caller — this is only what reaches the response body.
    """
    msg = str(e)
    if 'duplicate key value violates unique constraint' in msg:
        return ('Unable to save — a schedule record for this subject/section/semester '
                'already exists. Please refresh the page and try again.')
    if 'violates foreign key constraint' in msg:
        return 'Unable to save — one of the selected values (faculty/room/subject) is no longer valid. Please refresh and try again.'
    return 'Unable to save the schedule. Please review the schedule and try again.'

_local_tables_ensured = False
def _ensure_local_tables(cur=None):   # cur param kept for backward-compat but not used
    if _local_tables_ensured:
        return
    with _SCHEMA_LOCK:
        if not _local_tables_ensured:
            _apply_local_tables()


def _apply_local_tables():
    global _local_tables_ensured
    _conn = get_db_connection()
    _cur  = _conn.cursor()
    try:
        _cur.execute("""
            CREATE TABLE IF NOT EXISTS public.local_arrangement (
                arrangementid  SERIAL PRIMARY KEY,
                description    VARCHAR(200),
                programcode    VARCHAR(20),
                yearlevel      INT,
                sectionid      INT REFERENCES public.sections(sectionid),
                semesterid     INT,
                ref_versionid  INT,
                has_hc_violation BOOLEAN DEFAULT FALSE,
                violated_rules   JSONB   DEFAULT '[]'::jsonb,
                override_reason  TEXT,
                is_active        BOOLEAN DEFAULT TRUE,
                created_by       VARCHAR(100),
                created_at       TIMESTAMP DEFAULT NOW()
            )
        """)
        _cur.execute("""
            CREATE TABLE IF NOT EXISTS public.local_arrangement_sessions (
                sessionid              SERIAL PRIMARY KEY,
                arrangementid          INT REFERENCES public.local_arrangement(arrangementid),
                subjectcode            VARCHAR(50),
                daydesc                VARCHAR(20),
                starttimeid            INT,
                endtimeid              INT,
                roomid                 INT,
                faculty_employeenumber VARCHAR(50),
                official_sessionid     INT REFERENCES public.schedule_sessions(sessionid)
            )
        """)

        _cur.execute("""
            ALTER TABLE public.local_arrangement
            ADD COLUMN IF NOT EXISTS sectionid INT REFERENCES public.sections(sectionid)
        """)
        _cur.execute("""
            ALTER TABLE public.local_arrangement
            ADD COLUMN IF NOT EXISTS status VARCHAR(20) DEFAULT 'Draft'
        """)

        _cur.execute("""
            ALTER TABLE public.local_arrangement
            ADD COLUMN IF NOT EXISTS archive_reason TEXT
        """)
        _cur.execute("""
            ALTER TABLE public.local_arrangement
            ADD COLUMN IF NOT EXISTS archived_at TIMESTAMP
        """)
        _cur.execute("""
            ALTER TABLE public.local_arrangement
            ADD COLUMN IF NOT EXISTS draft_fingerprint VARCHAR(64)
        """)
        # Save/publish/archive write these and the optimistic-concurrency check reads
        # updated_at. The DEFAULT fills existing rows during ADD COLUMN itself — no
        # backfill UPDATE, which the Archived-immutability trigger below would reject.
        _cur.execute("""
            ALTER TABLE public.local_arrangement
            ADD COLUMN IF NOT EXISTS reason TEXT
        """)
        _cur.execute("""
            ALTER TABLE public.local_arrangement
            ADD COLUMN IF NOT EXISTS updated_at TIMESTAMP DEFAULT NOW()
        """)
        _cur.execute("""
            CREATE UNIQUE INDEX IF NOT EXISTS uq_local_active_draft_fingerprint
            ON public.local_arrangement (draft_fingerprint)
            WHERE status = 'Draft' AND draft_fingerprint IS NOT NULL
        """)
        _cur.execute("""
            CREATE UNIQUE INDEX IF NOT EXISTS uq_local_one_active_published_scope
            ON public.local_arrangement
               (UPPER(programcode), yearlevel, sectionid, semesterid)
            WHERE status = 'Published' AND is_active = TRUE
        """)
        _cur.execute("""
            CREATE TABLE IF NOT EXISTS public.schedule_exception_log (
                logid            SERIAL PRIMARY KEY,
                source_type      VARCHAR(30) NOT NULL,
                source_requestid INT         DEFAULT NULL,
                arrangementid    INT         DEFAULT NULL,
                violated_rules   JSONB       NOT NULL DEFAULT '[]'::jsonb,
                approved_by      VARCHAR(100) NOT NULL,
                approved_at      TIMESTAMP   DEFAULT NOW(),
                semesterid       INT
            )
        """)
        # Tracks Official slots that were vacated by a Local Arrangement override.
        # Subjects in this table are "unscheduled" in the Local Scheduler context;
        # their Official Published sessions are excluded from room-conflict detection.
        _cur.execute("""
            CREATE TABLE IF NOT EXISTS public.local_displaced_subjects (
                id              SERIAL PRIMARY KEY,
                programcode     VARCHAR(20)  NOT NULL,
                yearlevel       INT          NOT NULL,
                sectionid       INT          REFERENCES public.sections(sectionid),
                semesterid      INT          NOT NULL,
                subjectcode     VARCHAR(50)  NOT NULL,
                displaced_by    INT          REFERENCES public.local_arrangement(arrangementid),
                is_active       BOOLEAN      DEFAULT TRUE,
                displaced_at    TIMESTAMP    DEFAULT NOW(),
                UNIQUE (programcode, yearlevel, sectionid, semesterid, subjectcode)
            )
        """)
        # Catch existing databases up to the section-aware Local Scheduler schema.
        _cur.execute("""
            ALTER TABLE public.local_arrangement
            ADD COLUMN IF NOT EXISTS sectionid INT REFERENCES public.sections(sectionid)
        """)
        _cur.execute("""
            ALTER TABLE public.local_displaced_subjects
            ADD COLUMN IF NOT EXISTS sectionid INT REFERENCES public.sections(sectionid)
        """)
        _cur.execute("""
            ALTER TABLE public.local_arrangement_sessions
            ADD COLUMN IF NOT EXISTS official_sessionid
                INT REFERENCES public.schedule_sessions(sessionid)
        """)
        _cur.execute("""
            CREATE INDEX IF NOT EXISTS idx_local_session_official_source
            ON public.local_arrangement_sessions (official_sessionid)
        """)
        _cur.execute("""
            CREATE INDEX IF NOT EXISTS idx_local_arrangement_section_context
            ON public.local_arrangement
               (programcode, yearlevel, sectionid, semesterid, status, is_active)
        """)
        _cur.execute("""
            CREATE INDEX IF NOT EXISTS idx_local_displaced_section_context
            ON public.local_displaced_subjects
               (programcode, yearlevel, sectionid, semesterid, subjectcode, is_active)
        """)

        # status column for Draft → Published → Archived lifecycle
        _cur.execute("""
            ALTER TABLE public.local_arrangement
            ADD COLUMN IF NOT EXISTS status VARCHAR(20) DEFAULT 'Draft'
        """)
        # Backfill: existing rows without explicit status → treat as Published
        _cur.execute("""
            UPDATE public.local_arrangement
            SET status = 'Published'
            WHERE status IS NULL OR status = 'Draft'
              AND is_active = TRUE
        """)
        _cur.execute("""
            ALTER TABLE public.local_arrangement
            ADD COLUMN IF NOT EXISTS restored_from_arrangementid
                INT REFERENCES public.local_arrangement(arrangementid)
        """)
        _cur.execute("""
            CREATE OR REPLACE FUNCTION public.guard_local_arrangement_history()
            RETURNS trigger AS $$
            BEGIN
                IF TG_OP = 'DELETE' AND OLD.status = 'Archived' THEN
                    RAISE EXCEPTION 'Archived Local Arrangement history is immutable';
                END IF;
                IF TG_OP = 'UPDATE' AND OLD.status = 'Archived' THEN
                    RAISE EXCEPTION 'Archived Local Arrangement history is immutable';
                END IF;
                IF TG_OP = 'UPDATE' AND OLD.status = 'Published' AND NEW.status = 'Draft' THEN
                    RAISE EXCEPTION 'Published Local Arrangement cannot be reverted in place';
                END IF;
                RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
            END;
            $$ LANGUAGE plpgsql
        """)
        _cur.execute("DROP TRIGGER IF EXISTS trg_local_archive_immutable ON public.local_arrangement")
        _cur.execute("""
            CREATE TRIGGER trg_local_archive_immutable
            BEFORE UPDATE OR DELETE ON public.local_arrangement
            FOR EACH ROW EXECUTE FUNCTION public.guard_local_arrangement_history()
        """)
        _cur.execute("""
            CREATE OR REPLACE FUNCTION public.guard_local_archived_sessions()
            RETURNS trigger AS $$
            DECLARE parent_status VARCHAR(20);
            BEGIN
                SELECT status INTO parent_status
                FROM public.local_arrangement
                WHERE arrangementid = OLD.arrangementid;
                IF parent_status = 'Archived' THEN
                    RAISE EXCEPTION 'Sessions belonging to Archived Local history are immutable';
                END IF;
                RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
            END;
            $$ LANGUAGE plpgsql
        """)
        _cur.execute("DROP TRIGGER IF EXISTS trg_local_archived_sessions_immutable ON public.local_arrangement_sessions")
        _cur.execute("""
            CREATE TRIGGER trg_local_archived_sessions_immutable
            BEFORE UPDATE OR DELETE ON public.local_arrangement_sessions
            FOR EACH ROW EXECUTE FUNCTION public.guard_local_archived_sessions()
        """)
        _conn.commit()
        _local_tables_ensured = True
    except Exception:
        _conn.rollback()
        raise
    finally:
        _cur.close()
        _conn.close()

# ── Program Name History table ──────────────────────────────────
# Lets a "what was this program called on date X" lookup survive a rename —
# Program Code is the immutable identifier every table actually links against
# (schedule/curriculum/sections all key off it), so renaming Program Name never
# breaks data linkage; this table exists purely so past/official records (e.g.
# a Reports export for a bygone semester) can keep showing the name that was
# in effect back then instead of silently reflecting today's name.
_program_name_history_ensured = False
def _ensure_program_name_history_table():
    global _program_name_history_ensured
    if _program_name_history_ensured:
        return
    _conn = get_db_connection()
    _cur  = _conn.cursor()
    try:
        _cur.execute("""
            CREATE TABLE IF NOT EXISTS public.program_name_history (
                id          SERIAL PRIMARY KEY,
                programcode VARCHAR(20) NOT NULL,
                old_name    VARCHAR(200) NOT NULL,
                new_name    VARCHAR(200) NOT NULL,
                changed_by  VARCHAR(100),
                changed_at  TIMESTAMP DEFAULT NOW()
            )
        """)
        _cur.execute("""
            CREATE INDEX IF NOT EXISTS idx_program_name_history_code_date
            ON public.program_name_history (programcode, changed_at)
        """)
        _conn.commit()
        _program_name_history_ensured = True
    except Exception:
        _conn.rollback()
    finally:
        _cur.close()
        _conn.close()

# Effective-name lookup: the name a program was known by on a given timestamp.
# Prefer the most recent rename at/before that date; if the program was only
# ever renamed AFTER that date, fall back to the earliest recorded old_name
# (the name in effect before its first rename); otherwise (never renamed)
# fall back to the program's current live name.
_EFFECTIVE_PROGRAM_NAME_SQL = """
    COALESCE(
        (SELECT h.new_name FROM public.program_name_history h
         WHERE h.programcode = {code_expr} AND h.changed_at <= {date_expr}
         ORDER BY h.changed_at DESC LIMIT 1),
        (SELECT h2.old_name FROM public.program_name_history h2
         WHERE h2.programcode = {code_expr}
         ORDER BY h2.changed_at ASC LIMIT 1),
        {fallback_expr}
    )
"""

