@app.route('/schedule')
def schedule():
    if 'loggedin' not in session: return redirect(url_for('login'))

    from datetime import date as _date
    programs   = query_db("""
        SELECT programcode, programname
        FROM   programs
        WHERE  isactive = TRUE
        ORDER  BY programname, programcode
    """)
    acad_years = query_db("SELECT academicyearid, yearstart, yearend FROM academicyear ORDER BY yearstart DESC")

    # Detect current semester for pre-selecting dropdowns
    today = _date.today()
    active_sem_res = query_db("""
        SELECT s.semestertype, ay.academicyearid
        FROM semester s JOIN academicyear ay ON s.academicyearid = ay.academicyearid
        WHERE %s BETWEEN s.semstartdate AND s.semenddate
        LIMIT 1
    """, [today])

    if active_sem_res:
        active_sem_type = active_sem_res[0]['semestertype']
        active_ay       = active_sem_res[0]['academicyearid']
    else:
        # No live semester — pick the AY+semester that has the most recent imported data
        most_recent_data = query_db("""
            SELECT sem.semestertype, sem.academicyearid
            FROM historical_data hd
            JOIN semester sem ON hd.semesterid = sem.semesterid
            GROUP BY sem.semestertype, sem.academicyearid
            ORDER BY MAX(hd.semesterid) DESC
            LIMIT 1
        """)
        if most_recent_data:
            active_sem_type = most_recent_data[0]['semestertype']
            active_ay       = most_recent_data[0]['academicyearid']
        else:
            # Final fallback: most recent AY, 2nd semester
            active_sem_type = 'B'
            active_ay       = acad_years[0]['academicyearid'] if acad_years else ''

    status_query = """
        SELECT
            p.programname,
            pyl.programcode,
            pyl.yearlevel,
            ay.academicyearid,
            ay.yearstart || '-' || ay.yearend AS acad_year,
            sem.semestertype,
            TO_CHAR(MAX(sv.datecreated), 'MM/DD/YYYY') AS date_imported
        FROM schedule_version sv
        JOIN schedule s ON sv.scheduleid = s.scheduleid
        JOIN sections sec ON s.sectionid = sec.sectionid
        LEFT JOIN program_yearlevel pyl ON sec.programyearlevelid = pyl.programyearlevelid
        LEFT JOIN programs p ON pyl.programcode = p.programcode
        JOIN semester sem ON s.semesterid = sem.semesterid
        JOIN academicyear ay ON sem.academicyearid = ay.academicyearid
        GROUP BY p.programname, pyl.programcode, pyl.yearlevel, ay.academicyearid, ay.yearstart, ay.yearend, sem.semestertype
        ORDER BY MAX(sv.datecreated) DESC
    """
    status_list = query_db(status_query)
    import json as _json
    status_list_json = _json.dumps([
        {
            'programname':   r['programname']   or '',
            'programcode':   r['programcode']   or '',
            'yearlevel':     int(r['yearlevel']) if r['yearlevel'] else 0,
            'academicyearid': str(r['academicyearid']) if r['academicyearid'] else '',
            'acad_year':     r['acad_year']     or '',
            'semestertype':  r['semestertype']  or '',
            'date_imported': r['date_imported'] or 'N/A',
        }
        for r in (status_list or [])
    ])

    sem_data = query_db("""
        SELECT academicyearid, semestertype, semenddate
        FROM semester
        WHERE academicyearid IN (SELECT academicyearid FROM academicyear WHERE yearend >= %s)
        ORDER BY academicyearid, semestertype
    """, [today.year])
    import json as _json
    sem_json = _json.dumps([
        {'ay': r['academicyearid'], 'type': r['semestertype'],
         'end': r['semenddate'].isoformat() if r['semenddate'] else None}
        for r in (sem_data or [])
    ])

    faculty_list = query_db("""
        SELECT employeenumber, lastname || ', ' || firstname AS fullname
        FROM faculty WHERE employeestatus != 'Archive'
        ORDER BY lastname, firstname
    """) or []
    import json as _json2
    faculty_json = _json2.dumps([
        {'emp': str(f['employeenumber']), 'name': f['fullname']}
        for f in faculty_list
    ])

    return render_template('academic/schedule.html',
                           programs=programs,
                           acad_years=acad_years,
                           status_list=status_list,
                           status_list_json=status_list_json,
                           active_sem_type=active_sem_type,
                           active_ay=active_ay,
                           current_year=today.year,
                           today=today.isoformat(),
                           sem_json=sem_json,
                           faculty_json=faculty_json)

@app.route('/api/schedule/list/delete', methods=['POST'])
def api_schedule_list_delete():
    if session.get('role') != 'Academic Head':
        return jsonify({'success': False, 'error': 'Unauthorized'}), 403
    data           = request.get_json() or {}
    programcode    = (data.get('programcode') or '').strip()
    yearlevel      = data.get('yearlevel')
    academicyearid = data.get('academicyearid')
    semestertype   = (data.get('semestertype') or '').strip()
    if not all([programcode, yearlevel, academicyearid, semestertype]):
        return jsonify({'success': False, 'error': 'Missing parameters'}), 400
    conn = None
    try:
        conn = get_db_connection()
        cur  = conn.cursor(cursor_factory=RealDictCursor)
        cur.execute("""
            SELECT semesterid FROM semester
            WHERE academicyearid = %s AND semestertype = %s
        """, (academicyearid, semestertype))
        sem_row = cur.fetchone()
        if not sem_row:
            cur.close(); conn.close()
            return jsonify({'success': False, 'error': 'Semester not found'}), 404
        sem_id = sem_row['semesterid']
        cur.execute("""
            SELECT s.scheduleid FROM schedule s
            JOIN sections sec ON s.sectionid = sec.sectionid
            JOIN program_yearlevel pyl ON sec.programyearlevelid = pyl.programyearlevelid
            WHERE UPPER(pyl.programcode) = UPPER(%s) AND pyl.yearlevel = %s AND s.semesterid = %s
        """, (programcode, yearlevel, sem_id))
        sched_ids = [r['scheduleid'] for r in cur.fetchall()]
        if not sched_ids:
            cur.close(); conn.close()
            return jsonify({'success': False, 'error': 'No schedule records found for this combination'}), 404
        blockers = _schedule_delete_blockers(cur, sched_ids)
        if blockers:
            conn.rollback(); cur.close(); conn.close()
            return jsonify({'success': False, 'code': 'SCHEDULE_HISTORY_REFERENCED',
                            'error': _schedule_delete_blocked_message(blockers),
                            'references': blockers}), 409
        cur.execute("DELETE FROM schedule_version WHERE scheduleid = ANY(%s)", (sched_ids,))
        cur.execute("DELETE FROM schedule WHERE scheduleid = ANY(%s)", (sched_ids,))
        conn.commit()
        cur.close(); conn.close()
        return jsonify({'success': True, 'deleted': len(sched_ids)})
    except Exception as e:
        if conn:
            conn.rollback()
            try: cur.close(); conn.close()
            except: pass
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/get_offerings_schedule')
def get_offerings_schedule():
    import re
    prog          = request.args.get('program')
    yl            = request.args.get('year_level')
    sem           = request.args.get('semester')
    ay            = request.args.get('ay')
    section_id    = request.args.get('section_id')
    emp_num       = request.args.get('emp_num')
    version_status = request.args.get('status')  # None unless the caller explicitly asked
    scheduler_mode = request.args.get('scheduler_mode', 'official')

    conn = get_db_connection()
    cur  = conn.cursor(cursor_factory=RealDictCursor)
    try:
        # ── Local Scheduler: Program View must show the section's EFFECTIVE schedule —
        # Official Published as the base for every subject, with a subject's own active
        # Local Arrangement overriding it (excluded from the Official side so it doesn't
        # also show at its old slot). Mirrors how Room View (/api/get_room_schedule)
        # already combines the two; Program View previously only queried Local
        # Arrangements, which meant every subject that hadn't been individually
        # overridden yet stayed invisible until its slice was opened at least once.
        if scheduler_mode == 'local':
            _yl_int_local = int(yl) if str(yl).lstrip('-').isdigit() and int(yl) > 0 else 0

            official_section_clause = ''
            official_params = [prog, _yl_int_local, sem, ay]
            if section_id:
                official_section_clause = 'AND sec.sectionid = %s'
                official_params.append(int(section_id))

            la_params = [prog, _yl_int_local, ay, sem]
            local_extra_clause = ''
            if section_id:
                local_extra_clause += ' AND la.sectionid = %s'
                la_params.append(int(section_id))
            if emp_num:
                local_extra_clause += ' AND las.faculty_employeenumber = %s'
                la_params.append(emp_num)

            cur.execute(f"""
                SELECT
                    cs.subjectcode                                               AS subjectcode,
                    cs.subjectname                                               AS subjectname,
                    COALESCE(f.lastname || ', ' || f.firstname, 'TBA')           AS instructor,
                    f.employeenumber                                             AS faculty_id,
                    COALESCE(r.roomname, 'TBA')                                  AS roomname,
                    ss.daydesc,
                    TO_CHAR(ts_s.timevalue, 'HH24:MI')                           AS start_time,
                    TO_CHAR(ts_e.timevalue, 'HH24:MI')                           AS end_time,
                    COALESCE(cs.lecturehours,    0)                              AS lecturehours,
                    COALESCE(cs.laboratoryhours, 0)                              AS laboratoryhours,
                    COALESCE(cs.creditunits,     0)                              AS creditunits,
                    (COALESCE(cs.lecturehours,0) + COALESCE(cs.laboratoryhours,0)) AS total_hours,
                    pyl.programcode                                              AS programcode,
                    pyl.yearlevel                                                AS yearlevel,
                    sec.sectionname                                              AS sectionname,
                    sec.sectionid                                                AS section_id,
                    sv.status                                                    AS status,
                    sv.versionid                                                 AS versionid,
                    ss.sessionid                                                 AS official_sessionid,
                    'Official'                                                   AS schedule_source
                FROM schedule_version sv
                JOIN schedule sc               ON sv.scheduleid             = sc.scheduleid
                JOIN curriculumsubject cs      ON sc.curriculumsubjectid    = cs.curriculumsubjectid
                JOIN sections sec              ON sc.sectionid              = sec.sectionid
                LEFT JOIN program_yearlevel pyl ON sec.programyearlevelid  = pyl.programyearlevelid
                LEFT JOIN faculty f            ON sc.employeenumber         = f.employeenumber
                LEFT JOIN schedule_sessions ss ON ss.versionid             = sv.versionid
                LEFT JOIN room r               ON ss.roomid                 = r.roomid
                LEFT JOIN timeslot ts_s        ON ss.starttimeid            = ts_s.timeid
                LEFT JOIN timeslot ts_e        ON ss.endtimeid              = ts_e.timeid
                WHERE sv.status = 'Published'
                  AND UPPER(pyl.programcode) = UPPER(%s)
                  AND pyl.yearlevel = %s
                  AND sc.semesterid = (
                      SELECT semesterid FROM semester
                      WHERE semestertype = %s AND academicyearid = %s LIMIT 1
                  )
                  {official_section_clause}
                  AND NOT EXISTS (
                      SELECT 1
                      FROM public.local_arrangement_sessions las
                      JOIN public.local_arrangement la
                        ON las.arrangementid = la.arrangementid
                      WHERE la.status = 'Published'
                        AND la.is_active = TRUE
                        AND la.semesterid = sc.semesterid
                        AND la.sectionid = sec.sectionid
                        AND las.official_sessionid = ss.sessionid
                  )
                  AND sv.version_number = (
                      SELECT MAX(sv2.version_number)
                      FROM schedule_version sv2
                      WHERE sv2.scheduleid = sv.scheduleid
                        AND sv2.status = sv.status
                  )

                UNION ALL

                SELECT
                    las.subjectcode                                              AS subjectcode,
                    COALESCE(cs2.subjectname, las.subjectcode)                   AS subjectname,
                    COALESCE(f2.lastname || ', ' || f2.firstname, 'TBA')         AS instructor,
                    las.faculty_employeenumber                                   AS faculty_id,
                    COALESCE(r2.roomname, 'TBA')                                 AS roomname,
                    las.daydesc,
                    TO_CHAR(ts_s2.timevalue, 'HH24:MI')                          AS start_time,
                    TO_CHAR(ts_e2.timevalue, 'HH24:MI')                          AS end_time,
                    COALESCE(cs2.lecturehours,    0)                             AS lecturehours,
                    COALESCE(cs2.laboratoryhours, 0)                             AS laboratoryhours,
                    COALESCE(cs2.creditunits,     0)                             AS creditunits,
                    (COALESCE(cs2.lecturehours,0) + COALESCE(cs2.laboratoryhours,0)) AS total_hours,
                    la.programcode                                              AS programcode,
                    la.yearlevel                                                AS yearlevel,
                    sec2.sectionname                                            AS sectionname,
                    la.sectionid                                                AS section_id,
                    'Local'                                                     AS status,
                    NULL                                                        AS versionid,
                    las.official_sessionid                                      AS official_sessionid,
                    'Local'                                                     AS schedule_source
                FROM public.local_arrangement_sessions las
                JOIN public.local_arrangement la ON las.arrangementid = la.arrangementid
                JOIN semester sem2     ON la.semesterid = sem2.semesterid
                JOIN academicyear ay2  ON sem2.academicyearid = ay2.academicyearid
                LEFT JOIN LATERAL (
                    SELECT subjectname, lecturehours, laboratoryhours, creditunits
                    FROM curriculumsubject
                    WHERE UPPER(subjectcode) = UPPER(las.subjectcode) LIMIT 1
                ) cs2 ON TRUE
                LEFT JOIN sections sec2  ON la.sectionid = sec2.sectionid
                LEFT JOIN faculty f2    ON las.faculty_employeenumber = f2.employeenumber
                LEFT JOIN room r2       ON las.roomid = r2.roomid
                LEFT JOIN timeslot ts_s2 ON las.starttimeid = ts_s2.timeid
                LEFT JOIN timeslot ts_e2 ON las.endtimeid   = ts_e2.timeid
                WHERE la.is_active = TRUE AND la.status = 'Published'
                  AND UPPER(la.programcode) = UPPER(%s)
                  AND la.yearlevel = %s
                  AND ay2.academicyearid = %s
                  AND sem2.semestertype = %s
                  {local_extra_clause}
            """, official_params + la_params)
            return jsonify([dict(r) for r in (cur.fetchall() or [])])

        # ── Determine data source: current semester → schedule tables,
        #    past semester (ended before today) → historical_data only ──────
        from datetime import date as _date
        _today = _date.today()
        cur.execute("""
            SELECT semenddate FROM semester
            WHERE semestertype = %s AND academicyearid = %s LIMIT 1
        """, (sem, ay))
        _sem_row = cur.fetchone()
        is_past_sem = bool(
            _sem_row and _sem_row['semenddate'] and _sem_row['semenddate'] < _today
        )
        print(f"[DEBUG get_offerings_schedule] ay={ay!r} sem={sem!r} is_past_sem={is_past_sem}")

        # 'active' = both Published and Draft (excludes Archive). A past-term
        # SIS import lands as schedule_version status='Archive' (see
        # sis_import_confirm), so a caller that didn't explicitly ask for a
        # status needs 'Archive' here once the term is over, or its rows never
        # show — 'Published' alone (the old hardcoded default) would silently
        # never match anything for a past semester.
        if version_status == 'active':
            status_clause = "sv.status IN ('Published', 'Draft')"
            status_param  = None
        elif version_status in ('Published', 'Draft', 'Archive'):
            status_clause = "sv.status = %s"
            status_param  = version_status
        elif is_past_sem:
            status_clause = "sv.status = %s"
            status_param  = 'Archive'
        else:
            status_clause = "sv.status = %s"
            status_param  = 'Published'

        print(f"\n[DEBUG get_offerings_schedule] prog={prog!r} yl={yl!r} sem={sem!r} ay={ay!r} status={status_param!r}")

        # ── 1. Normalized schedule tables (always queried) ───────────────
        normalized_rows = []
        if True:
            # Build WHERE clauses dynamically so instructor-only queries work
            # (no program required when filtering by emp_num alone)
            q_params = ([status_param] if status_param else [])
            prog_clause = ''
            yl_clause   = ''
            if prog:
                prog_clause = 'AND UPPER(pyl.programcode) = UPPER(%s)'
                q_params = q_params + [prog]
            _yl_int = int(yl) if str(yl).lstrip('-').isdigit() and int(yl) > 0 else 0
            if _yl_int:
                yl_clause = 'AND pyl.yearlevel = %s'
                q_params = q_params + [_yl_int]
            q_params = q_params + [sem, ay]
            section_clause = ''
            if section_id:
                section_clause = 'AND sec.sectionid = %s'
                q_params = q_params + [int(section_id)]
            instructor_clause = ''
            if emp_num:
                instructor_clause = 'AND sc.employeenumber = %s'
                q_params = q_params + [emp_num]
            cur.execute(f"""
            SELECT
                cs.subjectcode,
                cs.subjectname,
                COALESCE(f.lastname || ', ' || f.firstname || COALESCE(' ' || f.middlename, ''), 'TBA') AS instructor,
                f.employeenumber                                    AS faculty_id,
                COALESCE(r.roomname, 'TBA')                         AS roomname,
                ss.daydesc,
                TO_CHAR(ts_s.timevalue, 'HH24:MI')                 AS start_time,
                TO_CHAR(ts_e.timevalue, 'HH24:MI')                 AS end_time,
                COALESCE(cs.lecturehours,    0)                    AS lecturehours,
                COALESCE(cs.laboratoryhours, 0)                    AS laboratoryhours,
                COALESCE(cs.creditunits,     0)                    AS creditunits,
                (COALESCE(cs.lecturehours,0) + COALESCE(cs.laboratoryhours,0)) AS total_hours,
                pyl.programcode                                     AS programcode,
                pyl.yearlevel                                       AS yearlevel,
                sec.sectionname                                     AS sectionname,
                sec.sectionid                                       AS section_id,
                sv.status,
                sv.versionid,
                -- Occurrence id: lets the editor hide exactly the row a local mirror replaces.
                ss.sessionid
            FROM schedule_version sv
            JOIN schedule sc              ON sv.scheduleid             = sc.scheduleid
            JOIN curriculumsubject cs     ON sc.curriculumsubjectid    = cs.curriculumsubjectid
            JOIN sections sec             ON sc.sectionid              = sec.sectionid
            LEFT JOIN program_yearlevel pyl ON sec.programyearlevelid  = pyl.programyearlevelid
            LEFT JOIN faculty f           ON sc.employeenumber         = f.employeenumber
            LEFT JOIN schedule_sessions ss ON ss.versionid             = sv.versionid
            LEFT JOIN room r              ON ss.roomid                 = r.roomid
            LEFT JOIN timeslot ts_s       ON ss.starttimeid            = ts_s.timeid
            LEFT JOIN timeslot ts_e       ON ss.endtimeid              = ts_e.timeid
            WHERE {status_clause}
              {prog_clause}
              {yl_clause}
              AND sc.semesterid = (
                  SELECT semesterid FROM semester
                  WHERE semestertype = %s AND academicyearid = %s LIMIT 1
              )
              {section_clause}
              {instructor_clause}
              AND sv.version_number = (
                  SELECT MAX(sv2.version_number)
                  FROM schedule_version sv2
                  WHERE sv2.scheduleid = sv.scheduleid
                    AND sv2.status = sv.status
              )
            ORDER BY
                CASE WHEN sv.status = 'Published' THEN 0 ELSE 1 END,
                pyl.programcode, pyl.yearlevel, ts_s.timevalue NULLS LAST
        """, q_params)
            normalized_rows = cur.fetchall()
            # 'active' (Manual Editor Program View): a subject+section's Draft is the complete
            # replacement of its Published schedule — same rule as existing_sessions and
            # get_room_schedule — so the superseded Published rows are not drawn beside it.
            if version_status == 'active':
                _drafted = {(str(r['subjectcode']).upper(), r['section_id'])
                            for r in normalized_rows if r['status'] == 'Draft'}
                normalized_rows = [r for r in normalized_rows
                                   if not (r['status'] == 'Published' and
                                           (str(r['subjectcode']).upper(), r['section_id']) in _drafted)]
            print(f"[DEBUG] normalized_rows count={len(normalized_rows)}")
            for r in normalized_rows[:3]:
                print(f"  norm: subj={r['subjectcode']!r} start={r['start_time']!r} day={r['daydesc']!r}")

        # ── 2. historical_data — reference only for semesters that already ended.
        # Must NOT leak into the current/upcoming term being actively scheduled,
        # otherwise Program View shows subjects as "scheduled" (room/instructor filled
        # in) for a section that has no Draft/Published session at all.
        raw_rows = []
        if is_past_sem:
            hist_params = [prog, str(yl), ay, sem, ay]
            hist_instructor_clause = ''
            if emp_num:
                hist_instructor_clause = 'AND employeenumber = %s'
                hist_params.append(emp_num)
            cur.execute(f"""
                SELECT
                    "Subject Code"      AS subjectcode,
                    "Subject Name"      AS subjectname,
                    "Instructor"        AS instructor,
                    "Room"              AS roomname,
                    "Day/s"             AS raw_days,
                    "Time"              AS raw_time,
                    "Lecture Hours"     AS lecturehours,
                    "Laboratory Hours"  AS laboratoryhours,
                    "Credit Units"      AS creditunits,
                    "Hours"             AS total_hours
                FROM historical_data
                WHERE REGEXP_REPLACE("Program", '\\s+\\d+$', '') ILIKE %s
                  AND CAST("Year Level" AS TEXT) = %s
                  AND academicyearid = %s
                  AND (
                    semesterid = (
                        SELECT semesterid FROM semester
                        WHERE semestertype = %s AND academicyearid = %s
                        LIMIT 1
                    )
                    OR semesterid IS NULL
                  )
                  {hist_instructor_clause}
            """, hist_params)
            raw_rows = cur.fetchall()
            print(f"[DEBUG] historical raw_rows count={len(raw_rows)}")
            for r in raw_rows[:3]:
                print(f"  hist: subj={r['subjectcode']!r} raw_days={r['raw_days']!r} raw_time={r['raw_time']!r} ay={r.get('total_hours')!r}")

        # ── Greedy day tokenizer — longest token wins, handles all formats ──
        # Order matters: longer tokens must come before shorter prefixes
        _DAY_TOKENS = [
            ('WEDNESDAY', 'Wednesday'), ('THURSDAY',  'Thursday'),
            ('SATURDAY',  'Saturday'),  ('SATURDAY',  'Saturday'),
            ('TUESDAY',   'Tuesday'),   ('SUNDAY',    'Sunday'),
            ('MONDAY',    'Monday'),    ('FRIDAY',    'Friday'),
            ('THURS',     'Thursday'),  ('THUR',      'Thursday'),
            ('TUES',      'Tuesday'),   ('WED',       'Wednesday'),
            ('THU',       'Thursday'),  ('SAT',       'Saturday'),
            ('SUN',       'Sunday'),    ('MON',       'Monday'),
            ('TUE',       'Tuesday'),   ('FRI',       'Friday'),
            ('TH',        'Thursday'),  ('M',         'Monday'),
            ('T',         'Tuesday'),   ('W',         'Wednesday'),
            ('F',         'Friday'),    ('S',         'Saturday'),
        ]

        def resolve_days(raw):
            raw = raw.strip().upper()
            raw = re.sub(r'[^A-Z/]', '', raw)   # strip digits, spaces, etc.
            if not raw:
                return []
            # Slash-separated → recurse each segment
            if '/' in raw:
                result = []
                for part in raw.split('/'):
                    result.extend(resolve_days(part))
                return result
            # Greedy left-to-right tokenize
            result, s = [], raw
            while s:
                for tok, day in _DAY_TOKENS:
                    if s.startswith(tok):
                        result.append(day)
                        s = s[len(tok):]
                        break
                else:
                    s = s[1:]   # skip unrecognised character
            return result

        def clean_time_str(t):
            if not t:
                return None
            t = str(t).strip().upper()
            is_pm = 'PM' in t
            is_am = 'AM' in t
            t = t.replace('AM', '').replace('PM', '').replace(' ', '')
            if ':' not in t:
                t = t.zfill(4)
                t = t[:2] + ':' + t[2:]
            parts = t.split(':')
            try:
                hh = int(parts[0])
                mm = int(parts[1][:2]) if len(parts) > 1 else 0
                if is_pm and hh != 12:
                    hh += 12
                elif is_am and hh == 12:
                    hh = 0   # explicit 12:xx AM → midnight
                elif not is_pm and not is_am:
                    total_mins = hh * 60 + mm
                    # Anything before school-day start of 07:30 → PM
                    if 60 <= total_mins < 7 * 60 + 30:
                        hh += 12
                    # 12 no meridiem stays 12 (noon); ≥07:30 no meridiem stays AM
                return f"{hh:02d}:{mm:02d}"
            except (ValueError, IndexError):
                return None

        def parse_time_range(raw):
            s = raw.strip()
            if not s:
                return None, None
            if ' - ' in s:
                parts = s.split(' - ', 1)
            else:
                parts = re.split(r'-(?=\s*\d)', s, maxsplit=1)
            if len(parts) != 2:
                return None, None
            ts, te = clean_time_str(parts[0]), clean_time_str(parts[1])
            if ts and te:
                sm = int(ts[:2]) * 60 + int(ts[3:5])
                em = int(te[:2]) * 60 + int(te[3:5])
                # Invalid/reversed range (e.g., "19:00-09:00" from "7:00-9:00 AM"
                # where start got inferred PM but end's explicit AM left it < start).
                # School sessions never cross noon/midnight, so bump end by 12h.
                if em <= sm:
                    new_h = (int(te[:2]) + 12) % 24
                    te = f"{new_h:02d}:{te[3:5]}"
            return ts, te
 
        # ── Build output — one record per (subject × day × time-block) ────
        def _hist_slot_hours(t_seg):
            ts, te = parse_time_range(t_seg)
            if not ts or not te:
                return 0.0
            def _m(t): return int(t[:2]) * 60 + int(t[3:5])
            dur = _m(te) - _m(ts)
            if dur <= 0:
                dur += 720  # 12-hr PM correction
            return dur / 60.0

        result = []
        for row in raw_rows:
            raw_days    = str(row.get('raw_days') or '').strip()
            raw_time    = str(row.get('raw_time') or '').strip()
            total_hours = int(row.get('total_hours') or 0)

            full_days = resolve_days(raw_days)
            # Split on "/" or newlines, then on spaces-between-ranges
            _raw_t = [b.strip() for b in re.split(r'[/\n]', raw_time) if b.strip()]
            time_parts = []
            for _blk in _raw_t:
                _sub = re.split(r'(?<=\d)\s+(?=\d{1,2}:\d{2}\s*-)', _blk)
                time_parts.extend([s.strip() for s in _sub if s.strip()])

            def _make_row(day_name, t_start, t_end):
                return {
                    'subjectcode':     row.get('subjectcode') or '',
                    'subjectname':     row.get('subjectname') or '',
                    'instructor':      row.get('instructor')  or 'TBA',
                    'roomname':        row.get('roomname')    or 'TBA',
                    'daydesc':         day_name,
                    'start_time':      t_start,
                    'end_time':        t_end,
                    'lecturehours':    row.get('lecturehours')    or 0,
                    'laboratoryhours': row.get('laboratoryhours') or 0,
                    'creditunits':     row.get('creditunits')     or 0,
                    'total_hours':     total_hours,
                }

            if not full_days:
                t_raw = time_parts[0] if time_parts else ''
                ts, te = parse_time_range(t_raw) if t_raw else (None, None)
                result.append(_make_row(None, ts, te))
                continue

            n_days, n_times = len(full_days), len(time_parts)
            if n_times == 0:
                for day_name in full_days:
                    result.append(_make_row(day_name, None, None))
            elif n_days == 1:
                # All time blocks on the single listed day
                for t_seg in time_parts:
                    ts, te = parse_time_range(t_seg)
                    result.append(_make_row(full_days[0], ts, te))
            elif total_hours <= 0:
                # Hours unknown: cycle through blocks for all days
                for i, day_name in enumerate(full_days):
                    ts, te = parse_time_range(time_parts[i % n_times])
                    result.append(_make_row(day_name, ts, te))
            else:
                _block_h = [_hist_slot_hours(t) for t in time_parts]
                _hours_if_shared = sum(_block_h) * n_days
                if _hours_if_shared <= total_hours:
                    # Shared: every block on every day
                    for day_name in full_days:
                        for t_seg in time_parts:
                            ts, te = parse_time_range(t_seg)
                            result.append(_make_row(day_name, ts, te))
                else:
                    # Cycling: one block per day, wrap when more days than blocks
                    for i, day_name in enumerate(full_days):
                        ts, te = parse_time_range(time_parts[i % n_times])
                        result.append(_make_row(day_name, ts, te))

        # ── Merge both sources: schedule tables take priority over historical ─
        # schedule rows with time data → always included
        norm_subjects_with_time = {r['subjectcode'] for r in normalized_rows if r['start_time']}
        norm_timed = [dict(r) for r in normalized_rows if r['start_time']]
        # historical rows only for subjects not already covered by a timed schedule row
        hist_extra = [row for row in result if row['subjectcode'] not in norm_subjects_with_time]
        # schedule rows without time only if historical has nothing for that subject
        hist_subjects = {r['subjectcode'] for r in result}
        norm_untimed_fallback = [
            dict(r) for r in normalized_rows
            if not r['start_time'] and r['subjectcode'] not in hist_subjects
        ]
        combined = norm_timed + hist_extra + norm_untimed_fallback
        print(f"[DEBUG] combined={len(combined)} norm_timed={len(norm_timed)} hist_extra={len(hist_extra)} untimed_fb={len(norm_untimed_fallback)}")
        for c in combined[:3]:
            print(f"  out: subj={c['subjectcode']!r} day={c['daydesc']!r} start={c['start_time']!r} hours={c['total_hours']!r}")
        return jsonify(combined)
 
    except Exception as e:
        print(f"[get_offerings_schedule] ERROR: {e}")
        import traceback; traceback.print_exc()
        return jsonify([])
    finally:
        cur.close()
        conn.close()

@app.route('/api/debug_hist')
def debug_hist():
    conn = get_db_connection()
    cur  = conn.cursor(cursor_factory=RealDictCursor)
    try:
        cur.execute('SELECT academicyearid, semesterid, COUNT(*) as cnt FROM historical_data GROUP BY academicyearid, semesterid ORDER BY academicyearid, semesterid')
        counts = [dict(r) for r in cur.fetchall()]
        cur.execute('SELECT DISTINCT "Program", "Year Level", academicyearid, semesterid FROM historical_data WHERE academicyearid = \'AY2425\' ORDER BY "Program", "Year Level"')
        ay2425 = [dict(r) for r in cur.fetchall()]
        cur.execute('SELECT semesterid, semestertype, academicyearid FROM semester ORDER BY academicyearid, semestertype')
        sems = [dict(r) for r in cur.fetchall()]
        return jsonify({'counts': counts, 'ay2425_programs': ay2425, 'semesters': sems})
    finally:
        cur.close(); conn.close()

@app.route('/api/schedule/diagnose')
def schedule_diagnose():
    """Diagnostic endpoint — shows exactly what data exists for the given filters."""
    prog = request.args.get('program', '')
    yl   = request.args.get('year_level', '1')
    sem  = request.args.get('semester', 'B')
    ay   = request.args.get('ay', '')
    conn = get_db_connection()
    cur  = conn.cursor(cursor_factory=RealDictCursor)
    try:
        # 1. Semester lookup
        cur.execute("SELECT semesterid, semestertype, academicyearid, semstartdate, semenddate FROM semester WHERE semestertype=%s AND academicyearid=%s LIMIT 1", (sem, ay))
        sem_row = dict(cur.fetchone()) if cur.rowcount else None

        # 2. All semesters
        cur.execute("SELECT semesterid, semestertype, academicyearid FROM semester ORDER BY academicyearid, semestertype")
        all_sems = [dict(r) for r in cur.fetchall()]

        # 3. Historical data count for this filter
        cur.execute("""
            SELECT COUNT(*) as total,
                   SUM(CASE WHEN "Time" IS NOT NULL AND "Time" != '' THEN 1 ELSE 0 END) as with_time
            FROM historical_data
            WHERE REGEXP_REPLACE("Program", '\\s+\\d+$', '') ILIKE %s
              AND CAST("Year Level" AS TEXT) = %s
              AND academicyearid = %s
        """, (prog, str(yl), ay))
        hist_count = dict(cur.fetchone())

        # 4. Historical with exact semester match
        sem_id = sem_row['semesterid'] if sem_row else None
        if sem_id:
            cur.execute("""SELECT COUNT(*) as cnt FROM historical_data
                WHERE REGEXP_REPLACE("Program",'\\s+\\d+$','') ILIKE %s
                AND CAST("Year Level" AS TEXT)=%s AND academicyearid=%s AND semesterid=%s
            """, (prog, str(yl), ay, sem_id))
            hist_sem_count = cur.fetchone()['cnt']
        else:
            hist_sem_count = 'N/A (semester not found)'

        # 5. All historical programs for this AY
        cur.execute("SELECT DISTINCT \"Program\", \"Year Level\", semesterid, academicyearid FROM historical_data WHERE academicyearid=%s ORDER BY \"Program\", \"Year Level\"", (ay,))
        hist_programs = [dict(r) for r in cur.fetchall()]

        # 6. Published schedule_sessions count
        cur.execute("""
            SELECT COUNT(ss.*) as sessions_count
            FROM schedule_version sv
            JOIN schedule sc ON sv.scheduleid=sc.scheduleid AND sv.status='Published'
            JOIN sections sec ON sc.sectionid=sec.sectionid
            LEFT JOIN program_yearlevel pyl ON sec.programyearlevelid=pyl.programyearlevelid
            LEFT JOIN schedule_sessions ss ON ss.versionid=sv.versionid
            WHERE UPPER(pyl.programcode)=UPPER(%s)
              AND pyl.yearlevel=%s
        """, (prog, int(yl)))
        sched_row = cur.fetchone()

        return jsonify({
            'filters': {'program': prog, 'year_level': yl, 'semester': sem, 'ay': ay},
            'semester_lookup': sem_row,
            'all_semesters': all_sems,
            'historical_for_ay_any_sem': hist_count,
            'historical_matching_semester': hist_sem_count,
            'all_hist_programs_in_ay': hist_programs,
            'published_sessions_count': sched_row['sessions_count'] if sched_row else 0,
        })
    except Exception as e:
        import traceback
        return jsonify({'error': str(e), 'traceback': traceback.format_exc()})
    finally:
        cur.close(); conn.close()

@app.route('/api/export_schedule')
def export_schedule():
    if session.get('role') not in ('Academic Head', 'Admin'): return redirect(url_for('login'))
    prog = request.args.get('program', '')
    yl   = request.args.get('year_level', '')
    sem  = request.args.get('semester', '')
    ay   = request.args.get('ay', '')

    conn = get_db_connection()
    cur  = conn.cursor(cursor_factory=RealDictCursor)
    try:
        # ── 1. Normalized schedule_sessions (current schedule) ────────────
        norm_filters = []
        norm_params  = []
        norm_q = """
            SELECT
                COALESCE(f.lastname || ', ' || f.firstname || COALESCE(' ' || f.middlename, ''), 'TBA') AS "Instructor",
                cs.subjectcode   AS "SubjectCode",
                cs.subjectname   AS "SubjectName",
                COALESCE(cs.lecturehours, 0)    AS "LectureHours",
                COALESCE(cs.laboratoryhours, 0) AS "LaboratoryHours",
                COALESCE(cs.creditunits, 0)     AS "CreditUnits",
                pyl.programcode AS "Program",
                pyl.yearlevel  AS "YearLevel",
                (COALESCE(cs.lecturehours,0) + COALESCE(cs.laboratoryhours,0)) AS "Hours",
                ss.daydesc       AS "Day/s",
                TO_CHAR(ts_s.timevalue,'HH12:MI AM') || ' - ' || TO_CHAR(ts_e.timevalue,'HH12:MI AM') AS "Time",
                COALESCE(r.roomname, 'TBA') AS "Room"
            FROM schedule_version sv
            JOIN schedule sc              ON sv.scheduleid = sc.scheduleid AND sv.status = 'Published'
            JOIN curriculumsubject cs      ON sc.curriculumsubjectid = cs.curriculumsubjectid
            JOIN sections sec              ON sc.sectionid = sec.sectionid
            LEFT JOIN program_yearlevel pyl ON sec.programyearlevelid = pyl.programyearlevelid
            LEFT JOIN faculty f            ON sc.employeenumber = f.employeenumber
            LEFT JOIN schedule_sessions ss ON ss.versionid = sv.versionid
            LEFT JOIN room r               ON ss.roomid = r.roomid
            LEFT JOIN timeslot ts_s        ON ss.starttimeid = ts_s.timeid
            LEFT JOIN timeslot ts_e        ON ss.endtimeid   = ts_e.timeid
        """
        if prog: norm_filters.append("UPPER(pyl.programcode) = UPPER(%s)"); norm_params.append(prog)
        if yl:   norm_filters.append("pyl.yearlevel = %s");  norm_params.append(int(yl))
        if sem or ay:
            sem_sub = "SELECT semesterid FROM semester WHERE TRUE"
            if sem: sem_sub += " AND semestertype = %s"; norm_params.append(sem)
            if ay:  sem_sub += " AND academicyearid = %s"; norm_params.append(ay)
            sem_sub += " LIMIT 1"
            norm_filters.append(f"sc.semesterid = ({sem_sub})")
        if norm_filters:
            norm_q += " WHERE " + " AND ".join(norm_filters)
        norm_q += " ORDER BY f.lastname, cs.subjectcode, ss.daydesc NULLS LAST"
        cur.execute(norm_q, norm_params)
        norm_rows = cur.fetchall()

        # ── 2. historical_data fallback ───────────────────────────────────
        hist_filters = ["TRUE"]
        hist_params  = []
        if prog: hist_filters.append('REGEXP_REPLACE("Program", \'\\s+\\d+$\', \'\') ILIKE %s'); hist_params.append(prog)
        if yl:   hist_filters.append('CAST("Year Level" AS TEXT) = %s'); hist_params.append(str(yl))
        if ay:   hist_filters.append("academicyearid = %s"); hist_params.append(ay)
        if sem:
            hist_filters.append("""semesterid = (
                SELECT semesterid FROM semester WHERE semestertype = %s
                AND (%s = '' OR academicyearid = %s) LIMIT 1
            )""")
            hist_params.extend([sem, ay, ay])
        hist_q = """
            SELECT
                "Instructor"        AS "Instructor",
                "Subject Code"      AS "SubjectCode",
                "Subject Name"      AS "SubjectName",
                "Lecture Hours"     AS "LectureHours",
                "Laboratory Hours"  AS "LaboratoryHours",
                "Credit Units"      AS "CreditUnits",
                "Program"           AS "Program",
                "Year Level"        AS "YearLevel",
                "Hours"             AS "Hours",
                "Day/s"             AS "Day/s",
                "Time"              AS "Time",
                "Room"              AS "Room"
            FROM historical_data
            WHERE """ + " AND ".join(hist_filters) + """
            ORDER BY "Instructor", "Subject Code"
        """
        cur.execute(hist_q, hist_params)
        hist_rows = cur.fetchall()

        # Same logic as API: prefer normalized rows with time, fall back to historical
        norm_exp_with_time = {r['SubjectCode'] for r in norm_rows if r['Time']}
        norm_timed_exp     = [r for r in norm_rows if r['Time']]
        hist_exp_extra     = [r for r in hist_rows if r['SubjectCode'] not in norm_exp_with_time]
        hist_exp_subjects  = {r['SubjectCode'] for r in hist_rows}
        norm_untimed_exp   = [r for r in norm_rows if not r['Time'] and r['SubjectCode'] not in hist_exp_subjects]
        all_rows = norm_timed_exp + hist_exp_extra + norm_untimed_exp

        cols = ["Instructor","SubjectCode","SubjectName","LectureHours","LaboratoryHours",
                "CreditUnits","Program","YearLevel","Hours","Day/s","Time","Room"]

        output = io.StringIO()
        writer = csv.writer(output)
        writer.writerow(cols)
        for row in all_rows:
            writer.writerow([row.get(c) or '' for c in cols])

        prog_label = prog or 'all'
        filename = f"schedule_{prog_label}_{ay}_{sem}.csv"
        return Response(output.getvalue(), mimetype='text/csv',
                        headers={"Content-Disposition": f"attachment; filename={filename}"})
    except Exception as e:
        import traceback; traceback.print_exc()
        return jsonify({'error': str(e)}), 500
    finally:
        cur.close(); conn.close()


# ══════════════════════════════════════════════════════════════
#  SCHEDULE EXPORT  (multi-format: CSV / XLSX / DOCX / PDF)
# ══════════════════════════════════════════════════════════════


def _sch_exp_fetch(cur, ay_ids, sem_types, programs, year_levels, merge=True):
    """Return list of schedule rows (normalized + historical fallback).
    When merge=True (default), collapses multiple schedule_sessions rows per
    subject offering into one (used by Table View exports). When merge=False,
    returns one row per individual day/time session, needed by Calendar View
    exports to place each meeting on its own day/time cell."""
    nf, np_ = [
        "sv.status IN ('Published', 'Draft')",
        """(
            sv.status = 'Draft'
            OR NOT EXISTS (
                SELECT 1
                FROM public.local_arrangement_sessions las_x
                JOIN public.local_arrangement la_x
                  ON las_x.arrangementid = la_x.arrangementid
                WHERE la_x.status = 'Published'
                  AND la_x.is_active = TRUE
                  AND la_x.semesterid = sc.semesterid
                  AND la_x.sectionid = sc.sectionid
                  AND las_x.official_sessionid = ss.sessionid
            )
        )"""
    ], []
    if ay_ids:
        nf.append(f"ay.academicyearid IN ({','.join(['%s']*len(ay_ids))})"); np_.extend(ay_ids)
    if sem_types:
        nf.append(f"sem.semestertype IN ({','.join(['%s']*len(sem_types))})"); np_.extend(sem_types)
    if programs:
        nf.append(f"UPPER(pyl.programcode) IN ({','.join(['%s']*len(programs))})"); np_.extend([p.upper() for p in programs])
    if year_levels:
        nf.append(f"pyl.yearlevel IN ({','.join(['%s']*len(year_levels))})"); np_.extend(year_levels)

    norm_q = """
        SELECT
            COALESCE(f.lastname||', '||f.firstname||COALESCE(' '||f.middlename,''),'TBA') AS "Instructor",
            cs.subjectcode   AS "SubjectCode",
            cs.subjectname   AS "SubjectName",
            COALESCE(cs.lecturehours,0)    AS "LectureHours",
            COALESCE(cs.laboratoryhours,0) AS "LaboratoryHours",
            COALESCE(cs.creditunits,0)     AS "CreditUnits",
            pyl.programcode AS "Program",
            pyl.yearlevel  AS "YearLevel",
            sec.sectionname  AS "Section",
            sec.sectionid    AS "SectionID",
            (COALESCE(cs.lecturehours,0)+COALESCE(cs.laboratoryhours,0)) AS "Hours",
            ss.daydesc       AS "Day/s",
            CASE WHEN ts_s.timevalue IS NOT NULL AND ts_e.timevalue IS NOT NULL
                 THEN TO_CHAR(ts_s.timevalue,'HH12:MI AM')||' - '||TO_CHAR(ts_e.timevalue,'HH12:MI AM')
                 ELSE NULL END AS "Time",
            COALESCE(r.roomname,'TBA') AS "Room",
            r.roomid AS "RoomID",
            ay.yearstart||'-'||ay.yearend AS "AcademicYear",
            sem.semestertype AS "SemesterType",
            ss.sessionid AS "OfficialSessionID",
            'Official' AS "ScheduleSource"
        FROM schedule_version sv
        JOIN schedule sc           ON sv.scheduleid=sc.scheduleid
        JOIN curriculumsubject cs   ON sc.curriculumsubjectid=cs.curriculumsubjectid
        JOIN sections sec           ON sc.sectionid=sec.sectionid
        LEFT JOIN program_yearlevel pyl ON sec.programyearlevelid=pyl.programyearlevelid
        JOIN semester sem           ON sc.semesterid=sem.semesterid
        JOIN academicyear ay        ON sem.academicyearid=ay.academicyearid
        LEFT JOIN faculty f         ON sc.employeenumber=f.employeenumber
        LEFT JOIN schedule_sessions ss ON ss.versionid=sv.versionid
        LEFT JOIN room r            ON ss.roomid=r.roomid
        LEFT JOIN timeslot ts_s     ON ss.starttimeid=ts_s.timeid
        LEFT JOIN timeslot ts_e     ON ss.endtimeid=ts_e.timeid
        WHERE """ + " AND ".join(nf) + """
          AND sv.version_number = (
              SELECT MAX(sv2.version_number)
              FROM schedule_version sv2
              WHERE sv2.scheduleid = sv.scheduleid
                AND sv2.status = sv.status
          )
        ORDER BY pyl.programcode, pyl.yearlevel, cs.subjectcode, ss.daydesc NULLS LAST
    """
    cur.execute(norm_q, np_)
    norm_rows = list(cur.fetchall() or [])

    # PHASE 6.5-A — Published Local replacements are part of operational
    # Class Schedule exports. Draft Local and Archived Local never appear.
    lf, lp_ = ["la.status = 'Published'", "la.is_active = TRUE"], []
    if ay_ids:
        lf.append(f"ay_l.academicyearid IN ({','.join(['%s']*len(ay_ids))})"); lp_.extend(ay_ids)
    if sem_types:
        lf.append(f"sem_l.semestertype IN ({','.join(['%s']*len(sem_types))})"); lp_.extend(sem_types)
    if programs:
        lf.append(f"UPPER(la.programcode) IN ({','.join(['%s']*len(programs))})"); lp_.extend([p.upper() for p in programs])
    if year_levels:
        lf.append(f"la.yearlevel IN ({','.join(['%s']*len(year_levels))})"); lp_.extend(year_levels)

    local_q = """
        SELECT
            COALESCE(f_l.lastname||', '||f_l.firstname||COALESCE(' '||f_l.middlename,''),'TBA') AS "Instructor",
            las.subjectcode AS "SubjectCode",
            COALESCE(cs_l.subjectname, las.subjectcode) AS "SubjectName",
            COALESCE(cs_l.lecturehours,0) AS "LectureHours",
            COALESCE(cs_l.laboratoryhours,0) AS "LaboratoryHours",
            COALESCE(cs_l.creditunits,0) AS "CreditUnits",
            la.programcode AS "Program",
            la.yearlevel AS "YearLevel",
            sec_l.sectionname AS "Section",
            la.sectionid AS "SectionID",
            (COALESCE(cs_l.lecturehours,0)+COALESCE(cs_l.laboratoryhours,0)) AS "Hours",
            las.daydesc AS "Day/s",
            CASE WHEN ts_ls.timevalue IS NOT NULL AND ts_le.timevalue IS NOT NULL
                 THEN TO_CHAR(ts_ls.timevalue,'HH12:MI AM')||' - '||TO_CHAR(ts_le.timevalue,'HH12:MI AM')
                 ELSE NULL END AS "Time",
            COALESCE(r_l.roomname,'TBA') AS "Room",
            r_l.roomid AS "RoomID",
            ay_l.yearstart||'-'||ay_l.yearend AS "AcademicYear",
            sem_l.semestertype AS "SemesterType",
            las.official_sessionid AS "OfficialSessionID",
            'Local' AS "ScheduleSource"
        FROM public.local_arrangement_sessions las
        JOIN public.local_arrangement la ON las.arrangementid = la.arrangementid
        JOIN public.semester sem_l ON la.semesterid = sem_l.semesterid
        JOIN public.academicyear ay_l ON sem_l.academicyearid = ay_l.academicyearid
        LEFT JOIN public.sections sec_l ON la.sectionid = sec_l.sectionid
        LEFT JOIN public.faculty f_l ON las.faculty_employeenumber = f_l.employeenumber
        LEFT JOIN public.room r_l ON las.roomid = r_l.roomid
        LEFT JOIN public.timeslot ts_ls ON las.starttimeid = ts_ls.timeid
        LEFT JOIN public.timeslot ts_le ON las.endtimeid = ts_le.timeid
        LEFT JOIN LATERAL (
            SELECT subjectname, lecturehours, laboratoryhours, creditunits
            FROM public.curriculumsubject
            WHERE UPPER(subjectcode)=UPPER(las.subjectcode)
            LIMIT 1
        ) cs_l ON TRUE
        WHERE """ + " AND ".join(lf) + """
        ORDER BY la.programcode, la.yearlevel, las.subjectcode, las.daydesc
    """
    cur.execute(local_q, lp_)
    local_rows = list(cur.fetchall() or [])

    hf, hp_ = ["TRUE"], []
    if ay_ids:
        hf.append(f"hd.academicyearid IN ({','.join(['%s']*len(ay_ids))})"); hp_.extend(ay_ids)
    if sem_types:
        ay_clause = (f" AND s2.academicyearid IN ({','.join(['%s']*len(ay_ids))})" if ay_ids else '')
        hf.append(f"hd.semesterid IN (SELECT semesterid FROM semester s2 WHERE s2.semestertype IN ({','.join(['%s']*len(sem_types))}){ay_clause})")
        hp_.extend(sem_types)
        if ay_ids: hp_.extend(ay_ids)
    if programs:
        hf.append(f"UPPER(REGEXP_REPLACE(hd.\"Program\",'\\s+\\d+$','')) IN ({','.join(['%s']*len(programs))})")
        hp_.extend([p.upper() for p in programs])
    if year_levels:
        # "Year Level" may be TEXT in historical_data; cast for safe comparison
        hf.append(f"CAST(hd.\"Year Level\" AS TEXT) IN ({','.join(['%s']*len(year_levels))})")
        hp_.extend([str(y) for y in year_levels])

    hist_q = """
        SELECT
            hd."Instructor"        AS "Instructor",
            hd."Subject Code"      AS "SubjectCode",
            hd."Subject Name"      AS "SubjectName",
            hd."Lecture Hours"     AS "LectureHours",
            hd."Laboratory Hours"  AS "LaboratoryHours",
            hd."Credit Units"      AS "CreditUnits",
            hd."Program"           AS "Program",
            hd."Year Level"        AS "YearLevel",
            COALESCE(sec.sectionname, hd."Course") AS "Section",
            hd.sectionid            AS "SectionID",
            hd."Hours"             AS "Hours",
            hd."Day/s"             AS "Day/s",
            hd."Time"              AS "Time",
            hd."Room"              AS "Room",
            NULL                   AS "RoomID",
            ay.yearstart||'-'||ay.yearend AS "AcademicYear",
            sem.semestertype AS "SemesterType",
            NULL AS "OfficialSessionID",
            'Historical' AS "ScheduleSource"
        FROM historical_data hd
        LEFT JOIN academicyear ay ON hd.academicyearid=ay.academicyearid
        LEFT JOIN semester sem    ON hd.semesterid=sem.semesterid
        LEFT JOIN sections sec   ON hd.sectionid=sec.sectionid
        WHERE """ + " AND ".join(hf) + """
        ORDER BY hd."Program", hd."Year Level", hd."Subject Code"
    """
    cur.execute(hist_q, hp_)
    hist_rows = cur.fetchall()

    current_rows = norm_rows + local_rows
    norm_with_time = {r['SubjectCode'] for r in current_rows if r['Time']}
    norm_timed     = [r for r in current_rows if r['Time']]
    hist_extra     = [r for r in hist_rows if r['SubjectCode'] not in norm_with_time]
    hist_codes     = {r['SubjectCode'] for r in hist_rows}
    norm_untimed   = [r for r in current_rows if not r['Time'] and r['SubjectCode'] not in hist_codes]
    combined = norm_timed + hist_extra + norm_untimed
    return _sch_merge_session_rows(combined) if merge else combined


_SCH_WEEKDAY_ORDER = {'MONDAY': 0, 'TUESDAY': 1, 'WEDNESDAY': 2, 'THURSDAY': 3,
                       'FRIDAY': 4, 'SATURDAY': 5, 'SUNDAY': 6}
_SCH_WEEKDAY_ABBR  = {'MONDAY': 'MON', 'TUESDAY': 'TUE', 'WEDNESDAY': 'WED', 'THURSDAY': 'THU',
                       'FRIDAY': 'FRI', 'SATURDAY': 'SAT', 'SUNDAY': 'SUN'}


def _sch_merge_session_rows(rows):
    """A single subject offering can have several schedule_sessions rows (one
    per meeting day/time/room — e.g. lecture on Mon/Thu in one room, lab on Sat
    in another). Collapse those into one row per offering instead of repeating
    the whole row per session.

    Sessions are grouped by identical (Time, Room) FIRST: multiple days that
    share the exact same time and room (e.g. lecture on Tue AND Fri, same slot,
    same room) collapse into one time/room slot with their days combined
    ('TUE/FRI'), instead of repeating the identical time string once per day.
    A session whose time or room differs from the rest never merges with them
    and gets its own separate Time + Room slot (e.g. a lecture and lab on the
    SAME day but different hours — 'SAT' 10:30-12:00 then 'SAT' 12:30-2:00 —
    stay as two Time entries). Day/s, however, is the deduplicated set of days
    across ALL slots: repeating a day once per differently-timed slot on that
    same day (e.g. 'SAT/SAT') would misleadingly read as two different days.
    Slots are ordered by (weekday, start time) — grouping/sorting days, times
    and rooms as three independent lists (as this used to do) both duplicates
    identical time ranges and decouples which time/room belongs to which day
    once a subject has 3+ distinct meeting slots."""
    groups = {}
    order  = []
    for r in rows:
        key = (r.get('Instructor'), r.get('SubjectCode'), r.get('SubjectName'),
               r.get('LectureHours'), r.get('LaboratoryHours'), r.get('CreditUnits'),
               r.get('Program'), r.get('YearLevel'), r.get('SectionID'), r.get('Section'),
               r.get('AcademicYear'), r.get('SemesterType'))
        if key not in groups:
            groups[key] = {'base': r, 'by_time_room': {}, 'tr_order': []}
            order.append(key)
        g = groups[key]
        day  = (r.get('Day/s') or '').strip()
        time = (r.get('Time') or '').strip()
        room = (r.get('Room') or '').strip()
        if not (day or time or room):
            continue
        tr_key = (time, room)
        if tr_key not in g['by_time_room']:
            g['by_time_room'][tr_key] = []
            g['tr_order'].append(tr_key)
        if day and day not in g['by_time_room'][tr_key]:
            g['by_time_room'][tr_key].append(day)

    merged = []
    for key in order:
        g = groups[key]
        base = dict(g['base'])
        slots = []
        day_rank = {}  # day abbr -> weekday rank, for the global Day/s dedup below
        for tr_key in g['tr_order']:
            time, room = tr_key
            days_sorted = sorted(g['by_time_room'][tr_key],
                                  key=lambda d: _SCH_WEEKDAY_ORDER.get(d.strip().upper(), 99))
            rank = min((_SCH_WEEKDAY_ORDER.get(d.strip().upper(), 99) for d in days_sorted), default=99)
            for d in days_sorted:
                abbr = _SCH_WEEKDAY_ABBR.get(d.strip().upper(), d.strip())
                day_rank.setdefault(abbr, _SCH_WEEKDAY_ORDER.get(d.strip().upper(), 99))
            parsed = _sch_parse_time_range(time)
            start_min = parsed[0] if parsed else 9999
            slots.append({'time': time, 'room': room, 'rank': rank, 'start_min': start_min})
        slots.sort(key=lambda s: (s['rank'], s['start_min']))

        base['Day/s'] = '/'.join(sorted(day_rank, key=lambda a: day_rank[a]))
        base['Time']  = ' / '.join(s['time'] for s in slots if s['time'])
        room_seq = [s['room'] for s in slots if s['room']]
        distinct_rooms = list(dict.fromkeys(room_seq))
        base['Room'] = distinct_rooms[0] if len(distinct_rooms) <= 1 else ' / '.join(room_seq)
        merged.append(base)
    return merged


# ── Calendar View: paired-day columns (M/TH, T/F, W/S, SUN) with per-day
# sub-columns, on a fine-grained (30-min) time grid so schedule blocks can be
# positioned proportionally to their actual start/end time rather than
# snapped to the nearest standard slice boundary. ──
_SCH_CAL_GRID_START = 450    # 7:30 AM, in minutes-past-midnight
_SCH_CAL_GRID_END   = 1230   # 8:30 PM
_SCH_CAL_FINE_STEP  = 30     # minutes per fine grid row

_SCH_CAL_COLS = [
    ('M/TH', ('MON', 'THU')),
    ('T/F',  ('TUE', 'FRI')),
    ('W/S',  ('WED', 'SAT')),
    ('SUN',  ('SUN',)),
]
# day code -> (pair_idx, subcol_idx) e.g. 'THU' -> (0, 1)
_SCH_CAL_DAY_TO_COL = {d: (pi, si) for pi, (_lbl, members) in enumerate(_SCH_CAL_COLS) for si, d in enumerate(members)}
# absolute grid column (0 = Time) where each pair's subcol 0 begins: M=1,TH=2,T=3,F=4,W=5,S=6,SUN=7
_SCH_CAL_COL_BASE = [1, 3, 5, 7]
_SCH_CAL_NCOLS    = 8  # Time + M,TH,T,F,W,S + SUN
_SCH_CAL_SUBLBL   = {'MON': 'M', 'TUE': 'T', 'WED': 'W', 'THU': 'TH', 'FRI': 'F', 'SAT': 'S', 'SUN': 'SUN'}

# Standard PUP Lopez class scheduling time slices (start_min, end_min, display label),
# matching the official Tentative Faculty Schedule template (with lunch/dinner gaps).
_SCH_STANDARD_SLOTS = [
    (450,  540,  '7:30-9:00'),
    (540,  630,  '9:00-10:30'),
    (630,  720,  '10:30-12:00'),
    (750,  840,  '12:30-2:00'),
    (840,  930,  '2:00-3:30'),
    (930,  1020, '3:30-5:00'),
    (1050, 1140, '5:30-7:00'),
    (1140, 1230, '7:00-8:30'),
]


def _sch_build_fine_rows():
    """Split the 7:30 AM-8:30 PM grid into fixed 30-min rows; each row records
    the standard-slice label (only on the slice's first row, so it can be
    merged/shown once) and whether the row falls in a break/gap (12:00-12:30,
    5:00-5:30) between slices."""
    rows = []
    t = _SCH_CAL_GRID_START
    while t < _SCH_CAL_GRID_END:
        in_slot = None
        for s, e, lbl in _SCH_STANDARD_SLOTS:
            if s <= t < e:
                in_slot = (s, e, lbl)
                break
        if in_slot:
            s, e, lbl = in_slot
            rows.append((t, t + _SCH_CAL_FINE_STEP, lbl if t == s else None, False))
        else:
            rows.append((t, t + _SCH_CAL_FINE_STEP, None, True))
        t += _SCH_CAL_FINE_STEP
    return rows


_SCH_CAL_FINE_ROWS = _sch_build_fine_rows()  # 26 fixed-height rows (24 slice rows + 2 break rows)


def _sch_cal_row_range(start_min, end_min):
    """Map an actual [start_min,end_min) time range to the (first,last) fine
    grid row indices it covers, clamped to the grid range."""
    lo = max(_SCH_CAL_GRID_START, min(start_min, _SCH_CAL_GRID_END))
    hi = max(_SCH_CAL_GRID_START, min(end_min, _SCH_CAL_GRID_END))
    if hi <= lo:
        hi = lo + 1
    n = len(_SCH_CAL_FINE_ROWS)
    first_idx = (lo - _SCH_CAL_GRID_START) // _SCH_CAL_FINE_STEP
    last_idx  = max(first_idx, (hi - _SCH_CAL_GRID_START - 1) // _SCH_CAL_FINE_STEP)
    return max(0, min(first_idx, n - 1)), max(0, min(last_idx, n - 1))


_SCH_DAY_TOKENS   = {
    'MONDAY': 'MON', 'MON': 'MON', 'M': 'MON',
    'TUESDAY': 'TUE', 'TUE': 'TUE', 'TUES': 'TUE', 'T': 'TUE',
    'WEDNESDAY': 'WED', 'WED': 'WED', 'W': 'WED',
    'THURSDAY': 'THU', 'THU': 'THU', 'THUR': 'THU', 'THURS': 'THU', 'TH': 'THU',
    'FRIDAY': 'FRI', 'FRI': 'FRI', 'F': 'FRI',
    'SATURDAY': 'SAT', 'SAT': 'SAT', 'S': 'SAT',
    'SUNDAY': 'SUN', 'SUN': 'SUN', 'SU': 'SUN',
}
_SCH_DAY_SEQ_ORDER = ['THURS', 'THUR', 'MON', 'TUES', 'TUE', 'WED', 'SAT', 'SUN', 'THU', 'TH', 'FRI', 'SU', 'M', 'T', 'W', 'F', 'S']


def _sch_split_days(raw):
    """Parse a Day/s string ('Monday', 'MON/THU', 'MWF', 'TTh', ...) into a
    list of 3-letter day codes ('MON','TUE',...), for Calendar View placement."""
    import re
    if not raw:
        return []
    parts = [p for p in re.split(r'[\s,;/]+', raw.strip().upper()) if p]
    result = []
    for p in parts:
        a = _SCH_DAY_TOKENS.get(p)
        if a and a not in result:
            result.append(a)
    if result:
        return result
    # Compact form like "MWF" or "TTh" with no separators
    s = re.sub(r'[\s,;/]+', '', raw.strip().upper())
    found = []
    while s:
        hit = False
        for tok in _SCH_DAY_SEQ_ORDER:
            if s.startswith(tok):
                a = _SCH_DAY_TOKENS.get(tok)
                if a and a not in found:
                    found.append(a)
                s = s[len(tok):]
                hit = True
                break
        if not hit:
            s = s[1:]
    return found


def _sch_parse_time_range(time_str):
    """Parse 'H:MM AM - H:MM PM'-style strings into (start_min, end_min, display).
    Returns None if the string can't be parsed (e.g. blank/TBA)."""
    import re
    if not time_str or not time_str.strip():
        return None
    parts = re.split(r'\s*-\s*|\s+to\s+', time_str.strip(), maxsplit=1, flags=re.IGNORECASE)
    if len(parts) != 2:
        return None

    def _parse_one(t):
        t = t.strip().upper().replace('.', '')
        for fmt in ('%I:%M %p', '%I:%M%p', '%H:%M', '%I %p'):
            try:
                return datetime.strptime(t, fmt)
            except ValueError:
                continue
        return None

    sd, ed = _parse_one(parts[0]), _parse_one(parts[1])
    if not sd or not ed:
        return None
    disp = f"{sd.strftime('%I:%M %p').lstrip('0')} - {ed.strftime('%I:%M %p').lstrip('0')}"
    return (sd.hour * 60 + sd.minute, ed.hour * 60 + ed.minute, disp)


def _sch_cal_default_block_text(info):
    """Default schedule-block text (Subject Offerings Calendar View):
    Time / SubjectCode (Section) / Instructor / Room."""
    sec_suffix = f" ({info['section']})" if info['section'] else ''
    return f"{info['disp']}\n{info['subjectcode']}{sec_suffix}\n{info['instructor']}\n{info['room']}"


def _sch_build_calendar(yl_rows, text_fn=None):
    """Build the faculty-schedule-style weekly timetable from per-session
    (unmerged) rows, positioning each class as one block on the fine-grained
    time grid, proportional to its actual start/end time (the standard slices
    are only a printed guide, not a snapping boundary).

    A class meeting on both members of a paired column (e.g. Mon+Thu at the
    same time) is emitted as ONE block spanning both sub-columns, not two
    separate entries. A class meeting on only one member (e.g. Saturday only)
    occupies only that sub-column. A single row whose Day/s already lists
    days from different pairs (e.g. "MWF") is correctly split into one block
    per pair it touches (each still a single, non-duplicated occurrence
    within that pair's column). Genuinely concurrent classes that land in the
    same sub-column/time (different sections/rooms running in parallel) are
    stacked inside one merged block rather than corrupting the grid.

    Returns (blocks, unscheduled):
      blocks      - [{'pair_idx', 'subcols': (0,) or (1,) or (0,1),
                      'row_start', 'row_end', 'lines': [block_text, ...]}, ...]
      unscheduled - [entry_text, ...] for rows with no day/time, or a time
                    that falls entirely outside the 7:30 AM-8:30 PM grid
    """
    # Step 1: collapse repeated per-day rows that represent the SAME schedule
    # (same instructor/subject/section/room/time) into one identity, tracking
    # every day it was seen on.
    identities = {}
    order = []
    unscheduled = []
    for r in yl_rows:
        days   = _sch_split_days(r.get('Day/s'))
        parsed = _sch_parse_time_range(r.get('Time'))
        sec_suffix = f" ({r['Section']})" if r.get('Section') else ''
        note = (f"{r.get('SubjectCode') or ''}{sec_suffix} — {r.get('Day/s') or 'No Day'} "
                f"{r.get('Time') or 'No Time'} ({r.get('Room') or 'TBA'})")
        if not days or not parsed:
            unscheduled.append(note)
            continue
        start, end, disp = parsed
        if end <= _SCH_CAL_GRID_START or start >= _SCH_CAL_GRID_END:
            unscheduled.append(note)
            continue
        key = (r.get('Instructor'), r.get('SubjectCode'), r.get('Section'), r.get('Room'), start, end)
        if key not in identities:
            identities[key] = {
                'days': set(), 'start': start, 'end': end, 'disp': disp,
                'subjectcode': r.get('SubjectCode') or '', 'section': r.get('Section'),
                'instructor': r.get('Instructor') or 'TBA', 'room': r.get('Room') or 'TBA',
                'program': r.get('Program'),
            }
            order.append(key)
        identities[key]['days'].update(days)

    # Step 2: expand each identity into the (pair_idx -> subcols touched) it occupies.
    raw = []
    build_text = text_fn or _sch_cal_default_block_text
    for gi, key in enumerate(order):
        info = identities[key]
        touched = {}
        for d in info['days']:
            pc = _SCH_CAL_DAY_TO_COL.get(d)
            if pc is None:
                continue
            pair_idx, subcol_idx = pc
            touched.setdefault(pair_idx, set()).add(subcol_idx)
        text = build_text(info)
        for pair_idx, subcols in touched.items():
            raw.append({'pair_idx': pair_idx, 'subcols': subcols, 'start': info['start'],
                        'end': info['end'], 'text': text, 'group_id': gi})

    # Step 3: per (pair_idx, subcol), merge overlapping/concurrent time ranges
    # so two different classes that truly collide share one block instead of
    # producing an invalid overlapping region.
    per_subcol = {}
    for b in raw:
        for sc in b['subcols']:
            per_subcol.setdefault((b['pair_idx'], sc), []).append((b['start'], b['end'], b['text'], b['group_id']))

    merged_subcol = {}
    for key, items in per_subcol.items():
        items_sorted = sorted(items, key=lambda x: x[0])
        groups = []
        for start, end, text, gid in items_sorted:
            if groups and start < groups[-1]['end']:
                g = groups[-1]
                g['end'] = max(g['end'], end)
                g['items'].append((start, end, text, gid))
            else:
                groups.append({'start': start, 'end': end, 'items': [(start, end, text, gid)]})
        merged_subcol[key] = groups

    # Step 4: where both sub-columns of a pair have an identical single-identity
    # block at the same time, collapse it into one block spanning both.
    blocks = []
    for pair_idx in range(3):
        left  = merged_subcol.get((pair_idx, 0), [])
        right = merged_subcol.get((pair_idx, 1), [])
        consumed_l, consumed_r = set(), set()
        li = ri = 0
        while li < len(left) and ri < len(right):
            gl, gr = left[li], right[ri]
            if (gl['start'] == gr['start'] and gl['end'] == gr['end']
                    and len(gl['items']) == 1 and len(gr['items']) == 1
                    and gl['items'][0][3] == gr['items'][0][3]):
                blocks.append({'pair_idx': pair_idx, 'subcols': (0, 1),
                                'start': gl['start'], 'end': gl['end'], 'lines': [gl['items'][0][2]]})
                consumed_l.add(li); consumed_r.add(ri)
                li += 1; ri += 1
            elif gl['start'] <= gr['start']:
                li += 1
            else:
                ri += 1
        for idx, g in enumerate(left):
            if idx not in consumed_l:
                blocks.append({'pair_idx': pair_idx, 'subcols': (0,), 'start': g['start'],
                                'end': g['end'], 'lines': [it[2] for it in g['items']]})
        for idx, g in enumerate(right):
            if idx not in consumed_r:
                blocks.append({'pair_idx': pair_idx, 'subcols': (1,), 'start': g['start'],
                                'end': g['end'], 'lines': [it[2] for it in g['items']]})
    for g in merged_subcol.get((3, 0), []):
        blocks.append({'pair_idx': 3, 'subcols': (0,), 'start': g['start'],
                        'end': g['end'], 'lines': [it[2] for it in g['items']]})

    for b in blocks:
        b['row_start'], b['row_end'] = _sch_cal_row_range(b['start'], b['end'])

    return blocks, unscheduled


def _sch_cal_abs_cols(pair_idx, subcols):
    """Return (first_col, last_col) absolute grid columns (0=Time) for a
    block occupying the given subcol(s) of the given pair."""
    base = _SCH_CAL_COL_BASE[pair_idx]
    cols = sorted(base + sc for sc in subcols)
    return cols[0], cols[-1]


def _sch_calendar_html_grid(yl_rows, text_fn=None):
    """Reshape _sch_build_calendar's block geometry into a plain list of HTML
    table rows (each cell already carrying its rowspan/colspan) so the Reports
    preview template can render the exact same weekly-timetable grid as
    _sch_gen_xlsx_calendar / _sch_gen_docx_calendar / _sch_gen_pdf_calendar
    (Class Schedule report) or _room_gen_*_calendar (Room Schedule report,
    via text_fn=_room_cal_block_text) without duplicating any of that
    grid-merging logic in Jinja."""
    blocks, unscheduled = _sch_build_calendar(yl_rows, text_fn=text_fn)
    n_rows = len(_SCH_CAL_FINE_ROWS)
    n_cols = _SCH_CAL_NCOLS  # 8: Time + M,TH,T,F,W,S + SUN

    occupied = [[False] * n_cols for _ in range(n_rows)]

    time_spans = {}
    for s_start, s_end, s_label in _SCH_STANDARD_SLOTS:
        r0, r1 = _sch_cal_row_range(s_start, s_end)
        time_spans[r0] = (s_label, r1 - r0 + 1)
        for rr in range(r0, r1 + 1):
            occupied[rr][0] = True

    block_at = {}
    for b in blocks:
        col0, col1 = _sch_cal_abs_cols(b['pair_idx'], b['subcols'])
        block_at[(b['row_start'], col0)] = {
            'lines': b['lines'],
            'rowspan': b['row_end'] - b['row_start'] + 1,
            'colspan': col1 - col0 + 1,
        }
        for rr in range(b['row_start'], b['row_end'] + 1):
            for cc in range(col0, col1 + 1):
                occupied[rr][cc] = True

    grid_rows = []
    for ri, (_fs, _fe, _lbl, is_gap) in enumerate(_SCH_CAL_FINE_ROWS):
        cells = []
        if ri in time_spans:
            lbl, span = time_spans[ri]
            cells.append({'kind': 'time', 'text': lbl, 'rowspan': span})
        elif not occupied[ri][0]:
            cells.append({'kind': 'time', 'text': '', 'rowspan': 1})
        for ci in range(1, n_cols):
            if (ri, ci) in block_at:
                b = block_at[(ri, ci)]
                cells.append({'kind': 'class', 'lines': b['lines'], 'rowspan': b['rowspan'], 'colspan': b['colspan']})
            elif not occupied[ri][ci]:
                cells.append({'kind': 'empty'})
        grid_rows.append({'is_gap': is_gap, 'cells': cells})

    return grid_rows, unscheduled


def _sch_exp_groups(rows):
    g = {}
    for r in rows:
        p  = r['Program']   or 'Unknown'
        yl = r['YearLevel'] or 0
        g.setdefault(p, {}).setdefault(yl, []).append(r)
    return {p: dict(sorted(ylmap.items())) for p, ylmap in sorted(g.items())}


def _room_cal_block_text(info):
    """Room Schedule Calendar block text: Time / SubjectCode / Program+Section
    (e.g. 'BSIT 1A') / Instructor. No room shown — each calendar already
    represents a single room."""
    prog = (info.get('program') or '').strip()
    sec  = (info.get('section') or '').strip()
    suffix = sec
    if prog and sec.upper().startswith(prog.upper()):
        suffix = sec[len(prog):].lstrip('-').strip()
    prog_sec = f"{prog} {suffix}".strip() if (prog or suffix) else ''
    lines = [info['disp'], info.get('subjectcode') or '']
    if prog_sec:
        lines.append(prog_sec)
    lines.append(info.get('instructor') or 'TBA')
    return '\n'.join(lines)


def _room_exp_groups(rows):
    """Group per-session schedule rows by room. Keyed internally by RoomID
    (when known) so two different rooms that happen to share a name are never
    merged, but the returned list is always sorted and titled by Room Name
    alone — building is ignored for ordering, per Room Schedule Export spec.
    Rows with no real room assigned ('TBA'/blank) are excluded."""
    g = {}
    for r in rows:
        name = (r.get('Room') or '').strip()
        if not name or name.upper() == 'TBA':
            continue
        key = r.get('RoomID') if r.get('RoomID') is not None else name
        if key not in g:
            g[key] = {'name': name, 'rows': []}
        g[key]['rows'].append(r)
    return sorted(g.values(), key=lambda v: v['name'].upper())

def _sch_exp_groups(rows):
    g = {}
    for r in rows:
        p  = r['Program']   or 'Unknown'
        yl = r['YearLevel'] or 0
        g.setdefault(p, {}).setdefault(yl, []).append(r)
    return {p: dict(sorted(ylmap.items())) for p, ylmap in sorted(g.items())}


_SCH_SEM_ORDER = {'A': 0, 'B': 1, 'C': 2}
_SCH_SEM_LABEL = {'A': '1st Semester', 'B': '2nd Semester', 'C': 'Summer'}


def _sch_partition_by_period(rows):
    """Split rows into an ordered list of ((ay_label, sem_type), period_rows)
    entries — one per distinct Academic Year + Semester combination actually
    present in the data, sorted chronologically (by AY start year, then A/B/C).

    The Class Schedule report/export used to compute ONE aggregate title
    across every selected AY/semester, falling back to a vague "Multiple
    Academic Years" placeholder whenever more than one was picked. Every
    caller instead partitions by period first, so each period gets its own
    "SUBJECT OFFERINGS FOR <SEM>, ACADEMIC YEAR <AY>" header naming exactly
    one semester and one academic year — never an aggregate — and selecting
    two semesters (or two AYs) renders each as its own fully separate,
    correctly-labeled section instead of merging under one header."""
    import re
    buckets = {}
    order = []
    for r in rows:
        key = (r.get('AcademicYear') or '', r.get('SemesterType') or '')
        if key not in buckets:
            buckets[key] = []
            order.append(key)
        buckets[key].append(r)

    def _ay_sort_key(ay_label):
        m = re.match(r'^(\d+)', ay_label or '')
        return int(m.group(1)) if m else 0

    order.sort(key=lambda k: (_ay_sort_key(k[0]), _SCH_SEM_ORDER.get(k[1], 99)))
    return [(k, buckets[k]) for k in order]


def _sch_period_title(ay_label, sem_type):
    """Title for one (AY, semester) partition — always names one specific
    semester and one specific academic year, never an aggregate."""
    return _sch_official_title(_SCH_SEM_LABEL.get(sem_type, sem_type or 'All Semesters'), ay_label)


def _sch_export_context(cur, ay_ids, sem_types, programs, year_levels, layout='table'):
    """Fetch + group Class Schedule rows and compute the semester/AY labels and
    full program names used by the 'official' SUBJECT OFFERINGS layout
    (_sch_gen_xlsx/docx/pdf) — the exact same data prep the Class Schedule SIS
    tab's own Export Schedule button runs (schedule_export_multi below). Reports
    > Class Schedule (preview + export) calls this too so both stay identical
    to that feature instead of drifting into a separate report design."""
    layout = layout if layout in ('table', 'calendar') else 'table'
    rows   = _sch_exp_fetch(cur, ay_ids, sem_types, programs, year_levels)
    groups = _sch_exp_groups(rows)

    sem_map    = {'A': '1st Semester', 'B': '2nd Semester', 'C': 'Summer'}
    uniq_sems  = sorted({r['SemesterType'] for r in rows if r.get('SemesterType')})
    sem_labels = ' & '.join(sem_map.get(s, s) for s in uniq_sems) if uniq_sems else 'All Semesters'
    uniq_ays   = sorted({r['AcademicYear'] for r in rows if r.get('AcademicYear')})
    ay_label   = uniq_ays[0] if len(uniq_ays) == 1 else ('Multiple Academic Years' if len(uniq_ays) > 1 else '')

    prog_codes = list(groups.keys())
    prog_name_map = {}
    if prog_codes:
        cur.execute(f"SELECT programcode, programname FROM programs WHERE programcode IN ({','.join(['%s']*len(prog_codes))})", prog_codes)
        prog_name_map = {r['programcode']: r['programname'] for r in cur.fetchall()}

    # Calendar layout needs per-session (unmerged) rows so each day/time meeting
    # can be placed in its own grid cell — only fetched when actually needed.
    cal_rows = cal_groups = None
    if layout == 'calendar':
        cal_rows   = _sch_exp_fetch(cur, ay_ids, sem_types, programs, year_levels, merge=False)
        cal_groups = _sch_exp_groups(cal_rows)

    return rows, groups, cal_rows, cal_groups, sem_labels, ay_label, prog_name_map, layout

def _sch_filter_export(cur, rows, groups, cal_rows, cal_groups, section_id=None, faculty_id=None, room_id=None):
    """Narrow an _sch_export_context result to one section / instructor / room
    (Reports > Class Schedule and the Faculty Class Schedule export)."""
    if not (section_id or room_id or faculty_id):
        return rows, groups, cal_rows, cal_groups
    _fac_fname = None
    if faculty_id:
        cur.execute("SELECT lastname, firstname, middlename FROM faculty WHERE employeenumber = %s", (faculty_id,))
        _f = cur.fetchone()
        _fac_fname = (f"{_f['lastname']}, {_f['firstname']}" + (f" {_f['middlename']}" if _f.get('middlename') else '')) if _f else None


    def _filt(rs):
        if section_id: rs = [r for r in rs if str(r.get('SectionID')) == str(section_id)]
        if room_id:    rs = [r for r in rs if str(r.get('RoomID')) == str(room_id)]
        if faculty_id: rs = [r for r in rs if _fac_fname and r.get('Instructor') == _fac_fname]
        return rs


    rows = _filt(rows); groups = _sch_exp_groups(rows)
    if cal_rows is not None:
        cal_rows = _filt(cal_rows); cal_groups = _sch_exp_groups(cal_rows)
    return rows, groups, cal_rows, cal_groups



@app.route('/academic/schedule/export/count', methods=['POST'])
def schedule_export_count():
    if session.get('role') not in ('Academic Head', 'Admin'):
        return jsonify({'error': 'Unauthorized'}), 403
    data        = request.get_json() or {}
    ay_ids      = data.get('ay_ids', [])
    sem_types   = data.get('sem_types', [])
    programs    = data.get('programs', [])
    year_levels = [int(y) for y in data.get('year_levels', [])]
    conn = get_db_connection()
    cur  = conn.cursor(cursor_factory=RealDictCursor)
    try:
        rows   = _sch_exp_fetch(cur, ay_ids, sem_types, programs, year_levels)
        groups = _sch_exp_groups(rows)
        return jsonify({'count': len(rows), 'programs': len(groups)})
    except Exception as e:
        import traceback; traceback.print_exc()
        return jsonify({'error': str(e)}), 500
    finally:
        cur.close(); conn.close()


@app.route('/academic/schedule/export', methods=['POST'])
def schedule_export_multi():
    if session.get('role') not in ('Academic Head', 'Admin'):
        return jsonify({'error': 'Unauthorized'}), 403
    data        = request.get_json() or {}
    ay_ids      = data.get('ay_ids', [])
    sem_types   = data.get('sem_types', [])
    programs    = data.get('programs', [])
    year_levels = [int(y) for y in data.get('year_levels', [])]
    formats     = [f.lower() for f in data.get('formats', ['csv'])]
    layout      = (data.get('layout') or 'table').lower()
    if layout not in ('table', 'calendar'):
        layout = 'table'
    filename    = (data.get('filename', '') or 'schedule_export').strip()
    for ext in ('.pdf', '.docx', '.xlsx', '.csv', '.zip'):
        if filename.lower().endswith(ext):
            filename = filename[:-len(ext)]

    conn = get_db_connection()
    cur  = conn.cursor(cursor_factory=RealDictCursor)
    try:
        rows   = _sch_exp_fetch(cur, ay_ids, sem_types, programs, year_levels)
        groups = _sch_exp_groups(rows)
        sem_map    = {'A': '1st Semester', 'B': '2nd Semester', 'C': 'Summer'}
        uniq_sems  = sorted({r['SemesterType'] for r in rows if r.get('SemesterType')})
        sem_labels = ' & '.join(sem_map.get(s, s) for s in uniq_sems) if uniq_sems else 'All Semesters'
        uniq_ays   = sorted({r['AcademicYear'] for r in rows if r.get('AcademicYear')})
        ay_label   = uniq_ays[0] if len(uniq_ays) == 1 else ('Multiple Academic Years' if len(uniq_ays) > 1 else '')

        prog_codes = list(groups.keys())
        prog_name_map = {}
        if prog_codes:
            cur.execute(f"SELECT programcode, programname FROM programs WHERE programcode IN ({','.join(['%s']*len(prog_codes))})", prog_codes)
            prog_name_map = {r['programcode']: r['programname'] for r in cur.fetchall()}

        # Calendar View needs per-session (unmerged) rows so each day/time meeting
        # can be placed in its own grid cell — only fetched when actually needed.
        cal_rows = cal_groups = None
        if layout == 'calendar':
            cal_rows   = _sch_exp_fetch(cur, ay_ids, sem_types, programs, year_levels, merge=False)
            cal_groups = _sch_exp_groups(cal_rows)

        mime_map = {
            'csv':  ('text/csv', '.csv'),
            'xlsx': ('application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', '.xlsx'),
            'docx': ('application/vnd.openxmlformats-officedocument.wordprocessingml.document', '.docx'),
            'pdf':  ('application/pdf', '.pdf'),
        }

        if len(formats) == 1:
            fmt = formats[0]
            if fmt not in mime_map:
                return jsonify({'error': f'Unknown format: {fmt}'}), 400
            out = _sch_export_bytes(fmt, layout, rows, groups, cal_rows, cal_groups, sem_labels, ay_label, prog_name_map)
            mime, ext = mime_map[fmt]
            return Response(out, mimetype=mime,
                            headers={'Content-Disposition': f'attachment; filename="{filename}{ext}"'})
        else:
            import zipfile
            buf = io.BytesIO()
            with zipfile.ZipFile(buf, 'w', zipfile.ZIP_DEFLATED) as zf:
                for fmt in formats:
                    if fmt in mime_map:
                        out = _sch_export_bytes(fmt, layout, rows, groups, cal_rows, cal_groups, sem_labels, ay_label, prog_name_map)
                        zf.writestr(filename + mime_map[fmt][1], out)
            buf.seek(0)
            return Response(buf.read(), mimetype='application/zip',
                            headers={'Content-Disposition': f'attachment; filename="{filename}.zip"'})
    except Exception as e:
        import traceback; traceback.print_exc()
        return jsonify({'error': str(e)}), 500
    finally:
        cur.close(); conn.close()
    
def _faculty_active_term(cur):
    """The active (academicyearid, semestertype) — the only term the Faculty
    Class Schedule page and its export ever use, whatever the browser sends."""
    cur.execute("SELECT s.academicyearid, s.semestertype FROM semester s WHERE s.isactive = TRUE LIMIT 1")
    return cur.fetchone()

def _faculty_se_filters(data):
    """Program / Year Level lists from the shared Class Schedule export dialog.
    Any ay_ids / sem_types in the body are ignored on purpose."""
    programs = [str(p).strip() for p in (data.get('programs') or []) if str(p).strip()]
    year_levels = [int(y) for y in (data.get('year_levels') or []) if str(y).strip()]
    return programs, year_levels

@app.route('/faculty/schedule/export/count', methods=['POST'])
def faculty_schedule_export_count():
    """Row / program count for the Faculty Class Schedule export dialog — same
    as /academic/schedule/export/count, but always the active term and only
    Published schedules (what the Faculty page shows)."""
    if 'loggedin' not in session or session.get('role') != 'Faculty':
        return jsonify({'error': 'Unauthorized'}), 403
    data = request.get_json(silent=True) or {}
    try:
        programs, year_levels = _faculty_se_filters(data)
    except (TypeError, ValueError):
        return jsonify({'error': 'Invalid year level.'}), 400
    conn = get_db_connection(); cur = conn.cursor(cursor_factory=RealDictCursor)
    try:
        active = _faculty_active_term(cur)
        if not active:
            return jsonify({'count': 0, 'programs': 0})
        rows = _sch_exp_fetch(cur, [active['academicyearid']], [active['semestertype']],
                              programs, year_levels, published_only=True)
        return jsonify({'count': len(rows), 'programs': len(_sch_exp_groups(rows))})
    except Exception:
        import traceback; traceback.print_exc()
        return jsonify({'error': 'Could not count the schedule rows.'}), 500
    finally:
        cur.close(); conn.close()

@app.route('/faculty/schedule/export', methods=['POST'])
def faculty_schedule_export():
    """Faculty → Class Schedule (SIS) → Export. Documents come from the same
    official generators as the Academic Head's Class Schedule export and
    Reports > Class Schedule (_sch_export_context / _sch_export_bytes), so the
    file looks identical to every other class schedule the system produces.


    Two request shapes:
      • {formats: [...], programs: [...], year_levels: [...], layout, filename}
        — the shared Academic Head export dialog: one or more formats (several
        → one .zip), always the active term and Published schedules only.
      • {format, program, year_level, section_id | emp_num, layout, filename}
        — single format narrowed to one section / instructor (kept working)."""
    if 'loggedin' not in session or session.get('role') != 'Faculty':
        return jsonify({'error': 'Unauthorized'}), 403
    data    = request.get_json(silent=True) or {}
    if isinstance(data.get('formats'), list):
        return _faculty_schedule_export_multi(data)
    fmt     = (data.get('format') or '').strip().lower()
    layout  = (data.get('layout') or 'table').strip().lower()
    if layout not in ('table', 'calendar'):
        layout = 'table'
    mime_map = _ta_export.MIME
    if fmt not in mime_map:
        return jsonify({'error': 'Please choose one format: XLSX, CSV, PDF or DOCX.'}), 400


    program    = (data.get('program') or '').strip()
    section_id = str(data.get('section_id') or '').strip()
    emp_num    = str(data.get('emp_num') or '').strip()
    try:
        year_levels = [int(data['year_level'])] if str(data.get('year_level') or '').strip() else []
    except (TypeError, ValueError):
        return jsonify({'error': 'Invalid year level.'}), 400
    if not (section_id or emp_num):
        return jsonify({'error': 'Select a Section or an Instructor first.'}), 400


    conn = get_db_connection(); cur = conn.cursor(cursor_factory=RealDictCursor)
    try:
        # The Faculty page is locked to the active term, so the export is too.
        cur.execute("""SELECT s.academicyearid, s.semestertype FROM semester s
                       WHERE s.isactive = TRUE LIMIT 1""")
        active = cur.fetchone()
        if not active:
            return jsonify({'error': 'No active academic term found.'}), 400


        rows, groups, cal_rows, cal_groups, sem_labels, ay_label, prog_name_map, layout = \
            _sch_export_context(cur, [active['academicyearid']], [active['semestertype']],
                                [program] if program else [], year_levels, layout, published_only=True)
        rows, groups, cal_rows, cal_groups = _sch_filter_export(
            cur, rows, groups, cal_rows, cal_groups, section_id or None, emp_num or None)
        if not rows:
            return jsonify({'error': 'There is no published schedule for the selected filters.'}), 404


        out = _sch_export_bytes(fmt, layout, rows, groups, cal_rows, cal_groups, sem_labels, ay_label, prog_name_map)
        filename = _ta_export.clean_filename(data.get('filename')) or \
            _ta_export.clean_filename(f"Class_Schedule_{sem_labels}_{ay_label}")
        mime, ext = mime_map[fmt]
        return Response(out, mimetype=mime,
                        headers={'Content-Disposition': f'attachment; filename="{filename}{ext}"'})
    except Exception:
        import traceback; traceback.print_exc()
        return jsonify({'error': 'The export could not be generated. Please try again.'}), 500
    finally:
        cur.close(); conn.close()

def _faculty_schedule_export_multi(data):
    """The shared (Academic Head) export dialog on the Faculty page — same
    output as schedule_export_multi, locked to the active term, Published only."""
    formats = []
    for f in data.get('formats') or []:
        f = str(f or '').strip().lower()
        if f and f not in formats:
            formats.append(f)
    if not formats or any(f not in _ta_export.MIME for f in formats):
        return jsonify({'error': 'Please choose at least one format: PDF, DOCX, XLSX or CSV.'}), 400
    layout = (data.get('layout') or 'table').strip().lower()
    try:
        programs, year_levels = _faculty_se_filters(data)
    except (TypeError, ValueError):
        return jsonify({'error': 'Invalid year level.'}), 400


    conn = get_db_connection(); cur = conn.cursor(cursor_factory=RealDictCursor)
    try:
        active = _faculty_active_term(cur)
        if not active:
            return jsonify({'error': 'No active academic term found.'}), 400
        rows, groups, cal_rows, cal_groups, sem_labels, ay_label, prog_name_map, layout = \
            _sch_export_context(cur, [active['academicyearid']], [active['semestertype']],
                                programs, year_levels, layout, published_only=True)
        if not rows:
            return jsonify({'error': 'There is no published schedule for the selected filters.'}), 404
        filename = _ta_export.clean_filename(data.get('filename')) or 'schedule_export'
        if len(formats) == 1:
            mime, ext = _ta_export.MIME[formats[0]]
            out = _sch_export_bytes(formats[0], layout, rows, groups, cal_rows, cal_groups,
                                    sem_labels, ay_label, prog_name_map)
            return Response(out, mimetype=mime,
                            headers={'Content-Disposition': f'attachment; filename="{filename}{ext}"'})
        import zipfile
        buf = io.BytesIO()
        with zipfile.ZipFile(buf, 'w', zipfile.ZIP_DEFLATED) as zf:
            for f in formats:
                zf.writestr(filename + _ta_export.MIME[f][1],
                            _sch_export_bytes(f, layout, rows, groups, cal_rows, cal_groups,
                                              sem_labels, ay_label, prog_name_map))
        return Response(buf.getvalue(), mimetype='application/zip',
                        headers={'Content-Disposition': f'attachment; filename="{filename}.zip"'})
    except Exception:
        import traceback; traceback.print_exc()
        return jsonify({'error': 'The export could not be generated. Please try again.'}), 500
    finally:
        cur.close(); conn.close()


@app.route('/api/schedule/export-generated', methods=['POST'])
def api_export_generated_schedule():
    """
    Export the in-memory generated schedule (not yet saved to DB) in the requested format.
    Accepts: {schedule_data: [...], format: 'pdf'|'docx'|'xlsx'|'csv', context: {...}, filename: '...'}
    """
    try:
        data          = request.get_json() or {}
        fmt           = (data.get('format') or 'csv').lower()
        raw_sched     = data.get('schedule_data') or []
        ctx           = data.get('context') or {}
        filename_base = (data.get('filename') or 'schedule_export').strip()
        for ext in ('.pdf', '.docx', '.xlsx', '.csv'):
            if filename_base.lower().endswith(ext):
                filename_base = filename_base[:-len(ext)]

        program    = ctx.get('program', '')
        year_level = ctx.get('yearLevel', '')
        acad_year  = ctx.get('acadYear', '')
        term       = ctx.get('term', '')
        section    = ctx.get('section', '')
        sem_map    = {'A': '1st Semester', 'B': '2nd Semester', 'C': 'Summer'}
        sem_label  = sem_map.get(term, term)

        # Normalize the JS schedule_data format → the column keys expected by _sch_gen_*
        rows = []
        for cls in raw_sched:
            rows.append({
                'Instructor':      cls.get('instructor') or 'TBA',
                'SubjectCode':     cls.get('subject_code') or cls.get('subjectcode') or '',
                'SubjectName':     cls.get('description') or cls.get('subjectname') or '',
                'LectureHours':    cls.get('lec_hours') or cls.get('lecturehours') or 0,
                'LaboratoryHours': cls.get('lab_hours') or cls.get('laboratoryhours') or 0,
                'CreditUnits':     cls.get('credit_units') or cls.get('creditunits') or cls.get('units') or 0,
                'Program':         cls.get('course') or program,
                'YearLevel':       year_level,
                'Section':         section,
                'Hours':           cls.get('hours') or '',
                'Day/s':           cls.get('days') or '',
                'Time':            (cls.get('time') or '').replace('–', '-'),
                'Room':            cls.get('room') or 'TBA',
                'AcademicYear':    acad_year,
                'SemesterType':    sem_label,
            })

        groups = _sch_exp_groups(rows)

        if fmt == 'csv':
            out, mime, ext = _sch_gen_csv(rows), 'text/csv', '.csv'
        elif fmt == 'xlsx':
            out, mime, ext = _sch_gen_xlsx(rows, groups), \
                'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', '.xlsx'
        elif fmt == 'docx':
            out, mime, ext = _sch_gen_docx(rows, groups, f'{program} Year {year_level} — {sem_label} {acad_year}'), \
                'application/vnd.openxmlformats-officedocument.wordprocessingml.document', '.docx'
        elif fmt == 'pdf':
            out, mime, ext = _sch_gen_pdf(rows, groups, f'{program} Year {year_level} — {sem_label} {acad_year}'), \
                'application/pdf', '.pdf'
        else:
            return jsonify({'error': f'Unsupported format: {fmt}'}), 400

        return Response(out, mimetype=mime,
                        headers={'Content-Disposition': f'attachment; filename="{filename_base}{ext}"'})
    except Exception as e:
        import traceback; traceback.print_exc()
        return jsonify({'error': str(e)}), 500


def _sch_gen_csv(rows):
    cols = ['Instructor','SubjectCode','SubjectName','LectureHours','LaboratoryHours',
            'CreditUnits','Program','YearLevel','Section','Hours','Day/s','Time','Room',
            'AcademicYear','SemesterType']
    out = io.StringIO()
    w   = csv.writer(out)
    w.writerow(cols)
    for r in rows:
        w.writerow([r.get(c) or '' for c in cols])
    return out.getvalue().encode('utf-8-sig')


_SCH_OFF_HEADERS = ['Instructor', 'Subject Code', 'Subject Description', 'Lec. Hours',
                     'Lab. Hours', 'Credit Units', 'Course', 'Hours', 'Day/s', 'Time', 'Room (LQ xxx)']
_SCH_OFF_YL_LBL  = {1: 'FIRST YEAR', 2: 'SECOND YEAR', 3: 'THIRD YEAR', 4: 'FOURTH YEAR', 5: 'FIFTH YEAR'}

# ── Class Schedule report letterhead logo ──────────────────────────────────
# The SAME campus logo file is used everywhere (preview page + every export
# format) — the title text already changes per selected semester on its own
# (_sch_official_title uses whatever sem_label is passed in), so there is no
# per-semester logo to swap. To replace the logo image itself, just overwrite
# this one file; every consumer (this constant, and the `pup-logo.png`
# reference in reports_preview.html) points at the same path.
_SCH_LOGO_FILENAME = 'pup-logo.png'
_SCH_LOGO_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'static', 'img', _SCH_LOGO_FILENAME)

# Column widths (cm) for the PDF/DOCX portrait table — Subject Description gets
# the lion's share; the short numeric/code columns are trimmed to fit an A4
# portrait page (usable width ~19cm with 1cm margins; kept a bit under that
# so rounding never pushes the table past the page edge). Day/s, Time and Room
# are widened since a merged offering can list several sessions (e.g.
# 'MON/THU/SAT' with three distinct time ranges) — cells wrap onto multiple
# lines (see Paragraph usage in _sch_gen_pdf / native Word wrap in
# _sch_gen_docx) rather than clipping, so these just need enough room to keep
# wrapped text readable, not to fit everything on one line.
_SCH_OFF_COL_CM = [2.2, 1.5, 4.9, 0.9, 0.9, 1.0, 1.4, 0.8, 1.3, 2.6, 1.4]


def _sch_official_row(r):
    """One data row in official SIS column order: Instructor…Room.
    The Course column shows the specific section name (e.g. 'BSCE 1-1') so
    that two sections of the same program/year level are never visually
    indistinguishable; falls back to Program+YearLevel only when no section
    is known (e.g. historical_data rows)."""
    course = r.get('Section') or ' '.join(str(v) for v in (r.get('Program'), r.get('YearLevel')) if v).strip()
    return [
        r.get('Instructor') or '', r.get('SubjectCode') or '', r.get('SubjectName') or '',
        r.get('LectureHours') or 0, r.get('LaboratoryHours') or 0, r.get('CreditUnits') or 0,
        course, r.get('Hours') or 0, r.get('Day/s') or '', r.get('Time') or '', r.get('Room') or '',
    ]


def _sch_official_totals(yl_rows):
    return (sum(r.get('LectureHours') or 0 for r in yl_rows),
            sum(r.get('LaboratoryHours') or 0 for r in yl_rows),
            sum(r.get('CreditUnits') or 0 for r in yl_rows),
            sum(r.get('Hours') or 0 for r in yl_rows))


def _sch_split_by_section(yl_rows):
    """Split a Program+YearLevel row list into per-section groups so distinct
    sections (e.g. BSCE 1-1 vs BSCE 1-2) always render as their own table,
    even when their subjects, instructors, days, times and rooms are otherwise
    identical. Grouped by SectionID when known (precise identity), falling
    back to the section name string, and finally to a single ungrouped table
    for rows with no section at all (e.g. historical_data).
    Returns an ordered list of (section_label, section_rows) tuples."""
    g = {}
    order = []
    for r in yl_rows:
        sec_id   = r.get('SectionID')
        sec_name = r.get('Section') or ''
        key = sec_id if sec_id is not None else (sec_name or None)
        if key not in g:
            g[key] = {'label': sec_name, 'rows': []}
            order.append(key)
        g[key]['rows'].append(r)
    order.sort(key=lambda k: (g[k]['label'] or ''))
    return [(g[k]['label'], g[k]['rows']) for k in order]


def _sch_official_title(sem_label, ay_label):
    title = f'SUBJECT OFFERINGS FOR {sem_label.upper()}'
    if ay_label:
        title += f', ACADEMIC YEAR {ay_label}'
    return title


def _sch_official_prog_label(prog, prog_names):
    name = (prog_names or {}).get(prog)
    return f'{name.upper()} ({prog})' if name else prog


def _sch_gen_xlsx(rows, groups, sem_label='All Semesters', ay_label='', prog_names=None):
    from openpyxl import Workbook
    from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
    from openpyxl.utils import get_column_letter

    wb = Workbook()
    ws = wb.active
    ws.title = 'Subject Offerings'
    ws.sheet_view.showGridLines = False

    MAROON = PatternFill('solid', fgColor='7A0100')
    thin   = Side(style='thin', color='000000')
    brd    = Border(left=thin, right=thin, top=thin, bottom=thin)
    title_font  = Font(bold=True, size=12)
    campus_font = Font(bold=True, size=12, color='FFFFFF')
    prog_font  = Font(bold=True, size=11)
    yl_font    = Font(bold=True, size=10)
    sec_font   = Font(bold=True, size=9, italic=True)
    hdr_font   = Font(bold=True, size=9)
    data_font  = Font(size=9)
    center     = Alignment(horizontal='center', vertical='center', wrap_text=True)

    NCOLS    = len(_SCH_OFF_HEADERS)
    # Instructor, Subject Code, Subject Description, Lec., Lab., Credit Units,
    # Course, Hours, Day/s, Time, Room — Subject Description widened, the
    # short numeric/code columns narrowed, to cut wrapping and page count.
    # Day/s, Time and Room are wide enough for a typical merged multi-session
    # offering; row height is still estimated per-row below since a subject
    # with 3+ distinct sessions can still exceed one line.
    COL_W    = [20, 12, 44, 7, 7, 8, 9, 6, 11, 24, 14]
    NUM_COLS = (4, 5, 6, 8)
    WRAP_COLS = (3, 9, 10, 11)  # Subject Description, Day/s, Time, Room

    rn = 1
    periods = _sch_partition_by_period(rows) or [((ay_label, ''), rows)]

    from openpyxl.worksheet.pagebreak import Break
    first_period = True
    for (period_ay, period_sem), period_rows in periods:
        if not first_period:
            ws.row_breaks.append(Break(id=rn - 1))
        first_period = False

        title = _sch_period_title(period_ay, period_sem)
        period_groups = _sch_exp_groups(period_rows)

        # Letterhead logo — same file as the preview page and every other
        # export format (see _SCH_LOGO_PATH); the title text right below it
        # already changes per period on its own, so there's nothing
        # semester-specific about the logo itself.
        try:
            from openpyxl.drawing.image import Image as _XLImage
            logo_img = _XLImage(_SCH_LOGO_PATH)
            logo_img.height = 46; logo_img.width = 46
            ws.row_dimensions[rn].height = 36
            ws.add_image(logo_img, f'A{rn}')
        except Exception:
            pass
        rn += 1

        ws.merge_cells(start_row=rn, start_column=1, end_row=rn, end_column=NCOLS)
        c = ws.cell(rn, 1, title); c.font = title_font; c.alignment = Alignment(horizontal='center')
        ws.row_dimensions[rn].height = 20; rn += 1

        ws.merge_cells(start_row=rn, start_column=1, end_row=rn, end_column=NCOLS)
        c = ws.cell(rn, 1, 'LOPEZ, QUEZON CAMPUS'); c.font = campus_font; c.fill = MAROON
        c.alignment = Alignment(horizontal='center')
        ws.row_dimensions[rn].height = 18; rn += 1
        rn += 1

        for prog, ylmap in period_groups.items():
            ws.merge_cells(start_row=rn, start_column=1, end_row=rn, end_column=NCOLS)
            c = ws.cell(rn, 1, _sch_official_prog_label(prog, prog_names))
            c.font = prog_font; c.alignment = Alignment(horizontal='center')
            for col in range(1, NCOLS + 1):
                ws.cell(rn, col).border = brd
            ws.row_dimensions[rn].height = 20; rn += 1

            for yl, yl_rows in ylmap.items():
                c = ws.cell(rn, 1, _SCH_OFF_YL_LBL.get(yl, f'YEAR {yl}') if yl else 'UNCLASSIFIED')
                c.font = yl_font
                ws.row_dimensions[rn].height = 16; rn += 1

                for sec_label, sec_rows in _sch_split_by_section(yl_rows):
                    if sec_label:
                        c = ws.cell(rn, 1, f'Section: {sec_label}')
                        c.font = sec_font
                        ws.row_dimensions[rn].height = 14; rn += 1

                    for ci, h in enumerate(_SCH_OFF_HEADERS, 1):
                        c = ws.cell(rn, ci, h); c.font = hdr_font; c.border = brd; c.alignment = center
                    ws.row_dimensions[rn].height = 26; rn += 1

                    for r in sec_rows:
                        vals = _sch_official_row(r)
                        # Row height is fixed per-row in openpyxl (Excel won't auto-grow it for
                        # wrapped text once set), so a merged offering with several sessions
                        # ('MON/THU/SAT' / three time ranges) needs its height estimated from
                        # the longest wrapped column, or the extra lines get visually clipped.
                        max_lines = 1
                        for ci, v in enumerate(vals, 1):
                            c = ws.cell(rn, ci, v); c.border = brd; c.font = data_font
                            c.alignment = center if ci in NUM_COLS else Alignment(
                                vertical='center', horizontal='left' if ci in (1, 3) else 'center', wrap_text=True)
                            if ci in WRAP_COLS:
                                n = len(str(v)) if v not in (None, '') else 0
                                max_lines = max(max_lines, -(-n // max(COL_W[ci - 1], 1)))
                        ws.row_dimensions[rn].height = max(15, max_lines * 12); rn += 1

                    lec, lab, units, hrs = _sch_official_totals(sec_rows)
                    ws.merge_cells(start_row=rn, start_column=1, end_row=rn, end_column=3)
                    for col in range(1, NCOLS + 1):
                        ws.cell(rn, col).border = brd
                    c = ws.cell(rn, 1, 'TOTAL'); c.font = hdr_font; c.alignment = Alignment(horizontal='center')
                    for ci, val in ((4, lec), (5, lab), (6, units), (8, hrs)):
                        c = ws.cell(rn, ci, val); c.font = hdr_font; c.alignment = center
                    ws.row_dimensions[rn].height = 18; rn += 1
                    rn += 1

            rn += 1

    for i, w in enumerate(COL_W, 1):
        ws.column_dimensions[get_column_letter(i)].width = w

    ws.page_setup.orientation  = 'portrait'
    ws.page_setup.paperSize    = ws.PAPERSIZE_A4
    ws.page_setup.fitToWidth   = 1
    ws.page_setup.fitToHeight  = 0
    ws.sheet_properties.pageSetUpPr.fitToPage = True
    ws.page_margins.left = ws.page_margins.right = 0.4
    ws.page_margins.top  = ws.page_margins.bottom = 0.5

    buf = io.BytesIO()
    wb.save(buf); buf.seek(0)
    return buf.read()


def _sch_gen_docx(rows, groups, sem_label='All Semesters', ay_label='', prog_names=None):
    from docx import Document
    from docx.shared import Pt, RGBColor, Inches, Cm
    from docx.enum.text import WD_ALIGN_PARAGRAPH
    from docx.enum.table import WD_TABLE_ALIGNMENT, WD_ALIGN_VERTICAL
    from docx.oxml.ns import qn
    from docx.oxml import OxmlElement

    doc = Document()
    sec = doc.sections[0]
    sec.page_width  = Inches(8.27)   # A4 portrait
    sec.page_height = Inches(11.69)
    sec.left_margin = sec.right_margin  = Cm(1.0)
    sec.top_margin  = sec.bottom_margin = Cm(1.0)

    BLACK = RGBColor(0x00, 0x00, 0x00)
    COL_W = [Cm(w) for w in _SCH_OFF_COL_CM]

    def _bg(cell, hex6):
        tc   = cell._tc
        tcPr = tc.get_or_add_tcPr()
        shd  = OxmlElement('w:shd')
        shd.set(qn('w:val'), 'clear')
        shd.set(qn('w:color'), 'auto')
        shd.set(qn('w:fill'), hex6)
        tcPr.append(shd)

    def _cell_text(cell, text, bold=False, sz=8, fill=None, align=WD_ALIGN_PARAGRAPH.LEFT, color=None):
        cell.text = ''
        run = cell.paragraphs[0].add_run(str(text) if text is not None else '')
        run.font.bold = bold; run.font.size = Pt(sz); run.font.color.rgb = color or BLACK
        cell.paragraphs[0].alignment = align
        if fill: _bg(cell, fill)
        cell.vertical_alignment = WD_ALIGN_VERTICAL.CENTER

    def _set_col_widths(tbl):
        # python-docx needs the width set on the table, each column, AND every
        # individual cell — setting only table.columns[i].width is silently
        # ignored by Word when the table has autofit enabled.
        tbl.autofit = False
        tbl.allow_autofit = False
        for ci, w in enumerate(COL_W):
            tbl.columns[ci].width = w
            for row in tbl.rows:
                row.cells[ci].width = w

    periods = _sch_partition_by_period(rows) or [((ay_label, ''), rows)]

    first_period = True
    for (period_ay, period_sem), period_rows in periods:
        if not first_period:
            doc.add_page_break()
        first_period = False

        title = _sch_period_title(period_ay, period_sem)
        period_groups = _sch_exp_groups(period_rows)

        # Letterhead logo — same file as the preview page and every other
        # export format (see _SCH_LOGO_PATH); the title right below it
        # already changes per period on its own, so there's nothing
        # semester-specific about the logo itself.
        try:
            logo_p = doc.add_paragraph()
            logo_p.alignment = WD_ALIGN_PARAGRAPH.CENTER
            logo_p.add_run().add_picture(_SCH_LOGO_PATH, width=Cm(2.0))
        except Exception:
            pass

        h1 = doc.add_heading(title, 0)
        h1.alignment = WD_ALIGN_PARAGRAPH.CENTER
        for run in h1.runs:
            run.font.color.rgb = BLACK; run.font.size = Pt(14)

        camp = doc.add_table(rows=1, cols=1)
        camp.alignment = WD_TABLE_ALIGNMENT.CENTER
        _cell_text(camp.rows[0].cells[0], 'LOPEZ, QUEZON CAMPUS', bold=True, sz=11,
                   fill='7A0100', align=WD_ALIGN_PARAGRAPH.CENTER, color=RGBColor(0xFF, 0xFF, 0xFF))
        doc.add_paragraph()

        # No forced page break per program here — Word already paginates a
        # long table across pages on its own, and hard-breaking before every
        # program (regardless of how little content it has) is what used to
        # leave dozens of nearly-blank pages in a file with many small
        # programs. A period boundary above still forces its own page (a
        # deliberately strong separation between semesters/AYs); a plain
        # paragraph gap is enough between programs within the same period.
        first_prog = True
        for prog, ylmap in period_groups.items():
            if not first_prog:
                doc.add_paragraph()
            first_prog = False

            h2 = doc.add_heading(_sch_official_prog_label(prog, prog_names), level=1)
            h2.alignment = WD_ALIGN_PARAGRAPH.CENTER
            h2.paragraph_format.keep_with_next = True
            for run in h2.runs:
                # Word's built-in Heading styles render bold visually but leave the
                # run's own .bold as None (style-inherited, not run-level) — and
                # _parse_schedule_docx's programme-header detection checks
                # run.bold explicitly. Without this, re-importing this exact file
                # back through Class Schedule (SIS) → Import never recognizes any
                # programme header and drops every row.
                run.font.bold = True
                run.font.color.rgb = BLACK; run.font.size = Pt(13)

            for yl, yl_rows in ylmap.items():
                h3 = doc.add_heading(_SCH_OFF_YL_LBL.get(yl, f'YEAR {yl}') if yl else 'UNCLASSIFIED', level=2)
                h3.paragraph_format.keep_with_next = True
                for run in h3.runs:
                    run.font.color.rgb = BLACK; run.font.size = Pt(11)

                for sec_label, sec_rows in _sch_split_by_section(yl_rows):
                    if sec_label:
                        p_sec = doc.add_paragraph()
                        p_sec.paragraph_format.keep_with_next = True
                        run_sec = p_sec.add_run(f'Section: {sec_label}')
                        run_sec.font.bold = True; run_sec.font.italic = True; run_sec.font.size = Pt(10)
                        run_sec.font.color.rgb = BLACK

                    tbl = doc.add_table(rows=2 + len(sec_rows), cols=len(_SCH_OFF_HEADERS))
                    tbl.style = 'Table Grid'
                    tbl.alignment = WD_TABLE_ALIGNMENT.CENTER
                    _set_col_widths(tbl)

                    for ci, h_txt in enumerate(_SCH_OFF_HEADERS):
                        _cell_text(tbl.rows[0].cells[ci], h_txt, bold=True, sz=7, align=WD_ALIGN_PARAGRAPH.CENTER)

                    for ri, r in enumerate(sec_rows):
                        vals = _sch_official_row(r)
                        for ci, v in enumerate(vals):
                            align = WD_ALIGN_PARAGRAPH.CENTER if ci in (3, 4, 5, 7) else WD_ALIGN_PARAGRAPH.LEFT
                            _cell_text(tbl.rows[ri + 1].cells[ci], v, sz=7, align=align)

                    lec, lab, units, hrs = _sch_official_totals(sec_rows)
                    trow = tbl.rows[-1]
                    merged = trow.cells[0].merge(trow.cells[2])
                    _cell_text(merged, 'TOTAL', bold=True, sz=7, align=WD_ALIGN_PARAGRAPH.CENTER)
                    _cell_text(trow.cells[3], lec, bold=True, sz=7, align=WD_ALIGN_PARAGRAPH.CENTER)
                    _cell_text(trow.cells[4], lab, bold=True, sz=7, align=WD_ALIGN_PARAGRAPH.CENTER)
                    _cell_text(trow.cells[5], units, bold=True, sz=7, align=WD_ALIGN_PARAGRAPH.CENTER)
                    _cell_text(trow.cells[7], hrs, bold=True, sz=7, align=WD_ALIGN_PARAGRAPH.CENTER)

                    doc.add_paragraph()

    buf = io.BytesIO()
    doc.save(buf); buf.seek(0)
    return buf.read()


def _sch_gen_pdf(rows, groups, sem_label='All Semesters', ay_label='', prog_names=None):
    from reportlab.lib.pagesizes import A4
    from reportlab.lib import colors
    from reportlab.lib.units import cm
    from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
    from reportlab.platypus import SimpleDocTemplate, Table, TableStyle, Paragraph, Spacer, PageBreak, KeepTogether, Image as _RLImage
    from reportlab.lib.enums import TA_CENTER, TA_LEFT
    from xml.sax.saxutils import escape as _xml_escape

    buf = io.BytesIO()
    doc = SimpleDocTemplate(buf, pagesize=A4,
                            leftMargin=1.0*cm, rightMargin=1.0*cm,
                            topMargin=1.0*cm, bottomMargin=1.0*cm)

    BLACK  = colors.black
    WHITE  = colors.white
    MAROON = colors.HexColor('#7A0100')

    styles = getSampleStyleSheet()
    h1 = ParagraphStyle('H1', parent=styles['Heading1'], textColor=BLACK, fontSize=14, spaceAfter=2, alignment=TA_CENTER)
    campus_style = ParagraphStyle('Campus', parent=styles['Normal'], textColor=WHITE, fontSize=11,
                                   alignment=TA_CENTER, fontName='Helvetica-Bold')
    h2 = ParagraphStyle('H2', parent=styles['Heading2'], textColor=BLACK, fontSize=13, spaceAfter=2, alignment=TA_CENTER)
    h3 = ParagraphStyle('H3', parent=styles['Heading3'], textColor=BLACK, fontSize=10, spaceAfter=2, alignment=TA_LEFT)
    h4 = ParagraphStyle('H4', parent=styles['Normal'], textColor=BLACK, fontSize=9, spaceAfter=2,
                         alignment=TA_LEFT, fontName='Helvetica-BoldOblique')

    # Data cells are Paragraphs (not plain strings) so long merged Day/s ('MON/
    # THU/SAT'), Time ('10:00 AM - 12:00 PM / 10:00 AM - 11:30 AM / ...') and
    # Room values wrap onto multiple lines and grow the row height instead of
    # overflowing/clipping — a plain string in a reportlab Table cell doesn't wrap.
    cell_l = ParagraphStyle('CellL', parent=styles['Normal'], fontName='Helvetica', fontSize=6.5, leading=8, textColor=BLACK, alignment=TA_LEFT)
    cell_c = ParagraphStyle('CellC', parent=cell_l, alignment=TA_CENTER)
    hdr_c  = ParagraphStyle('HdrC',  parent=cell_c, fontName='Helvetica-Bold')
    tot_c  = ParagraphStyle('TotC',  parent=cell_c, fontName='Helvetica-Bold')
    tot_l  = ParagraphStyle('TotL',  parent=cell_l, fontName='Helvetica-Bold', alignment=TA_CENTER)
    CENTER_COLS = {3, 4, 5, 7}  # Lec., Lab., Credit Units, Hours

    def _pc(v, center):
        text = _xml_escape(str(v)) if v not in (None, '') else '&nbsp;'
        return Paragraph(text, cell_c if center else cell_l)

    COL_W = [w*cm for w in _SCH_OFF_COL_CM]
    periods = _sch_partition_by_period(rows) or [((ay_label, ''), rows)]

    story = []
    first_period = True
    for (period_ay, period_sem), period_rows in periods:
        if not first_period:
            story.append(PageBreak())
        first_period = False

        title = _sch_period_title(period_ay, period_sem)
        period_groups = _sch_exp_groups(period_rows)

        # Letterhead logo — see _SCH_LOGO_PATH; same file used everywhere.
        try:
            _logo = _RLImage(_SCH_LOGO_PATH, width=1.4*cm, height=1.4*cm)
            _logo.hAlign = 'CENTER'
            story.append(_logo)
        except Exception:
            pass
        story.append(Paragraph(title, h1))
        camp_tbl = Table([[Paragraph('LOPEZ, QUEZON CAMPUS', campus_style)]], colWidths=[sum(COL_W)])
        camp_tbl.setStyle(TableStyle([('BACKGROUND', (0, 0), (-1, -1), MAROON), ('BOX', (0, 0), (-1, -1), 0.5, BLACK)]))
        story.append(camp_tbl)
        story.append(Spacer(1, 0.3*cm))

        # No forced page break per program here — reportlab already paginates
        # a long table across pages on its own, and hard-breaking before
        # every program (regardless of how little content it has) is what
        # used to leave dozens of nearly-blank pages in a file with many
        # small programs. A period boundary above still forces its own page
        # (a deliberately strong separation between semesters/AYs); a plain
        # spacer is enough between programs within the same period. Each
        # section's own label+table is still kept together so a "Section: X"
        # line is never orphaned alone at the bottom of a page.
        first_prog = True
        for prog, ylmap in period_groups.items():
            if not first_prog:
                story.append(Spacer(1, 0.4*cm))
            first_prog = False

            story.append(Paragraph(_sch_official_prog_label(prog, prog_names), h2))

            for yl, yl_rows in ylmap.items():
                yl_label = _SCH_OFF_YL_LBL.get(yl, f'YEAR {yl}') if yl else 'UNCLASSIFIED'
                story.append(Paragraph(yl_label, h3))

                for sec_label, sec_rows in _sch_split_by_section(yl_rows):
                    sec_flow = []
                    if sec_label:
                        sec_flow.append(Paragraph(f'Section: {sec_label}', h4))

                    tbl_data = [[Paragraph(_xml_escape(h), hdr_c) for h in _SCH_OFF_HEADERS]]
                    for r in sec_rows:
                        vals = _sch_official_row(r)
                        tbl_data.append([_pc(v, ci in CENTER_COLS) for ci, v in enumerate(vals)])

                    lec, lab, units, hrs = _sch_official_totals(sec_rows)
                    tbl_data.append([
                        Paragraph('TOTAL', tot_l), Paragraph('', tot_l), Paragraph('', tot_l),
                        Paragraph(str(lec), tot_c), Paragraph(str(lab), tot_c), Paragraph(str(units), tot_c),
                        Paragraph('', tot_c), Paragraph(str(hrs), tot_c),
                        Paragraph('', tot_c), Paragraph('', tot_c), Paragraph('', tot_c),
                    ])
                    last_row = len(tbl_data) - 1

                    tbl = Table(tbl_data, colWidths=COL_W, repeatRows=1)
                    tbl.setStyle(TableStyle([
                        ('VALIGN',         (0,0),  (-1,-1), 'MIDDLE'),
                        ('GRID',           (0,0),  (-1,-1), 0.5, BLACK),
                        ('SPAN',           (0,last_row), (2,last_row)),
                        ('LEFTPADDING',    (0,0),  (-1,-1), 2),
                        ('RIGHTPADDING',   (0,0),  (-1,-1), 2),
                        ('TOPPADDING',     (0,0),  (-1,-1), 2),
                        ('BOTTOMPADDING',  (0,0),  (-1,-1), 2),
                    ]))
                    sec_flow.append(tbl)
                    story.append(KeepTogether(sec_flow))
                    story.append(Spacer(1, 0.25*cm))
            story.append(Spacer(1, 0.3*cm))

    doc.build(story)
    buf.seek(0)
    return buf.read()


def _sch_gen_xlsx_calendar(rows, groups, sem_label='All Semesters', ay_label='', prog_names=None):
    """Calendar View XLSX — faculty-schedule-style weekly timetable: paired-day
    columns (M/TH, T/F, W/S, SUN) with separate Mon/Thu, Tue/Fri, Wed/Sat
    sub-columns, on a fixed-height fine time grid. Each block is positioned
    (via cell merge) proportionally to its actual start/end time rather than
    snapped to the printed time-slice guide, grouped by Program → Year Level."""
    from openpyxl import Workbook
    from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
    from openpyxl.utils import get_column_letter

    wb = Workbook()
    ws = wb.active
    ws.title = 'Weekly Timetable'
    ws.sheet_view.showGridLines = False

    MAROON = PatternFill('solid', fgColor='7A0100')
    thin   = Side(style='thin', color='000000')
    brd    = Border(left=thin, right=thin, top=thin, bottom=thin)
    title_font  = Font(bold=True, size=12)
    campus_font = Font(bold=True, size=12, color='FFFFFF')
    prog_font  = Font(bold=True, size=11)
    yl_font    = Font(bold=True, size=10)
    hdr_font   = Font(bold=True, size=8.5)
    data_font  = Font(size=6.5)
    center     = Alignment(horizontal='center', vertical='center', wrap_text=True)

    NCOLS = _SCH_CAL_NCOLS
    COL_W = [10, 12, 12, 12, 12, 12, 12, 12]
    ROW_H_NORMAL = 20
    ROW_H_GAP    = 5

    rn = 1
    periods = _sch_partition_by_period(rows) or [((ay_label, ''), rows)]

    from openpyxl.worksheet.pagebreak import Break
    first_period = True
    for (period_ay, period_sem), period_rows in periods:
        if not first_period:
            ws.row_breaks.append(Break(id=rn - 1))
        first_period = False

        title = _sch_period_title(period_ay, period_sem)
        period_groups = _sch_exp_groups(period_rows)

        # Letterhead logo — see _SCH_LOGO_PATH; same file used everywhere.
        try:
            from openpyxl.drawing.image import Image as _XLImage
            logo_img = _XLImage(_SCH_LOGO_PATH)
            logo_img.height = 40; logo_img.width = 40
            ws.row_dimensions[rn].height = 30
            ws.add_image(logo_img, f'A{rn}')
        except Exception:
            pass
        rn += 1

        ws.merge_cells(start_row=rn, start_column=1, end_row=rn, end_column=NCOLS)
        c = ws.cell(rn, 1, title); c.font = title_font; c.alignment = Alignment(horizontal='center')
        ws.row_dimensions[rn].height = 16; rn += 1

        ws.merge_cells(start_row=rn, start_column=1, end_row=rn, end_column=NCOLS)
        c = ws.cell(rn, 1, 'LOPEZ, QUEZON CAMPUS'); c.font = campus_font; c.fill = MAROON
        c.alignment = Alignment(horizontal='center')
        ws.row_dimensions[rn].height = 14; rn += 1

        for prog, ylmap in period_groups.items():
            ws.merge_cells(start_row=rn, start_column=1, end_row=rn, end_column=NCOLS)
            c = ws.cell(rn, 1, _sch_official_prog_label(prog, prog_names))
            c.font = prog_font; c.alignment = Alignment(horizontal='center')
            for col in range(1, NCOLS + 1):
                ws.cell(rn, col).border = brd
            ws.row_dimensions[rn].height = 14; rn += 1

            for yl, yl_rows in ylmap.items():
                c = ws.cell(rn, 1, _SCH_OFF_YL_LBL.get(yl, f'YEAR {yl}') if yl else 'UNCLASSIFIED')
                c.font = yl_font
                ws.row_dimensions[rn].height = 13; rn += 1

                blocks, unscheduled = _sch_build_calendar(yl_rows)

                # Single header row — the M/TH, T/F, W/S grouping is already implied
                # by the adjacent day-letter columns, so no separate pair-label row.
                hdr_row = rn
                c = ws.cell(hdr_row, 1, 'TIME'); c.font = hdr_font; c.border = brd; c.alignment = center
                for pi, (lbl, members) in enumerate(_SCH_CAL_COLS[:3]):
                    base = _SCH_CAL_COL_BASE[pi]
                    for si, d in enumerate(members):
                        c = ws.cell(hdr_row, base + 1 + si, _SCH_CAL_SUBLBL[d])
                        c.font = hdr_font; c.border = brd; c.alignment = center
                sun_col = _SCH_CAL_COL_BASE[3] + 1
                c = ws.cell(hdr_row, sun_col, 'SUN'); c.font = hdr_font; c.border = brd; c.alignment = center
                ws.row_dimensions[hdr_row].height = 14

                data_start = hdr_row + 1
                for fi, (fs, fe, flbl, is_gap) in enumerate(_SCH_CAL_FINE_ROWS):
                    excel_row = data_start + fi
                    ws.row_dimensions[excel_row].height = ROW_H_GAP if is_gap else ROW_H_NORMAL
                    for col in range(1, NCOLS + 1):
                        ws.cell(excel_row, col).border = brd

                for s_start, s_end, s_label in _SCH_STANDARD_SLOTS:
                    r0, r1 = _sch_cal_row_range(s_start, s_end)
                    er0, er1 = data_start + r0, data_start + r1
                    if er1 > er0:
                        ws.merge_cells(start_row=er0, start_column=1, end_row=er1, end_column=1)
                    c = ws.cell(er0, 1, s_label); c.font = hdr_font; c.alignment = center

                for b in blocks:
                    col0, col1 = _sch_cal_abs_cols(b['pair_idx'], b['subcols'])
                    er0, er1 = data_start + b['row_start'], data_start + b['row_end']
                    ec0, ec1 = col0 + 1, col1 + 1
                    if er1 > er0 or ec1 > ec0:
                        ws.merge_cells(start_row=er0, start_column=ec0, end_row=er1, end_column=ec1)
                    c = ws.cell(er0, ec0, '\n\n'.join(b['lines'])); c.font = data_font; c.alignment = center

                rn = data_start + len(_SCH_CAL_FINE_ROWS)

                if unscheduled:
                    c = ws.cell(rn, 1, 'Unscheduled / TBA:'); c.font = hdr_font; rn += 1
                    for u in unscheduled:
                        ws.merge_cells(start_row=rn, start_column=1, end_row=rn, end_column=NCOLS)
                        c = ws.cell(rn, 1, u); c.font = data_font
                        rn += 1

                rn += 1
            rn += 1

    for i, w in enumerate(COL_W, 1):
        ws.column_dimensions[get_column_letter(i)].width = w

    buf = io.BytesIO()
    wb.save(buf); buf.seek(0)
    return buf.read()


def _sch_gen_docx_calendar(rows, groups, sem_label='All Semesters', ay_label='', prog_names=None):
    """Calendar View DOCX — faculty-schedule-style weekly timetable, mirroring
    _sch_gen_xlsx_calendar's fixed-height fine grid with Mon/Thu, Tue/Fri,
    Wed/Sat sub-columns and proportionally-merged schedule blocks."""
    from docx import Document
    from docx.shared import Pt, RGBColor, Inches, Cm, Emu
    from docx.enum.text import WD_ALIGN_PARAGRAPH
    from docx.enum.table import WD_TABLE_ALIGNMENT, WD_ALIGN_VERTICAL, WD_ROW_HEIGHT_RULE
    from docx.oxml.ns import qn
    from docx.oxml import OxmlElement

    doc = Document()
    sec = doc.sections[0]
    sec.page_width  = Inches(8.5)
    sec.page_height = Inches(11)
    sec.left_margin = sec.right_margin  = Cm(1.3)
    sec.top_margin  = sec.bottom_margin = Cm(1.0)

    BLACK = RGBColor(0x00, 0x00, 0x00)

    def _bg(cell, hex6):
        tc   = cell._tc
        tcPr = tc.get_or_add_tcPr()
        shd  = OxmlElement('w:shd')
        shd.set(qn('w:val'), 'clear')
        shd.set(qn('w:color'), 'auto')
        shd.set(qn('w:fill'), hex6)
        tcPr.append(shd)

    def _cell_lines(cell, entries, bold=False, sz=8, fill=None, align=WD_ALIGN_PARAGRAPH.CENTER, color=None):
        cell.text = ''
        p = cell.paragraphs[0]
        p.alignment = align
        # Word's default paragraph style adds space-before/after (and >1.0 line
        # spacing) to every paragraph; with EXACT row heights Word expands the
        # row to fit that extra space rather than clipping it, which silently
        # inflates every row and is what actually blew the page-fit budget.
        pf = p.paragraph_format
        pf.space_before = Pt(0)
        pf.space_after  = Pt(0)
        pf.line_spacing = 1.0
        flat = []
        for e in (entries or ['']):
            flat.extend(str(e).split('\n'))
        if not flat:
            flat = ['']
        for i, line in enumerate(flat):
            run = p.add_run(line)
            run.font.bold = bold; run.font.size = Pt(sz); run.font.color.rgb = color or BLACK
            if i < len(flat) - 1:
                run.add_break()
        if fill: _bg(cell, fill)
        cell.vertical_alignment = WD_ALIGN_VERTICAL.CENTER

    def _set_row_height(row, pts, exact=True):
        row.height = Pt(pts)
        row.height_rule = WD_ROW_HEIGHT_RULE.EXACTLY if exact else WD_ROW_HEIGHT_RULE.AT_LEAST

    def _cant_split(row):
        trPr = row._tr.get_or_add_trPr()
        el = OxmlElement('w:cantSplit')
        trPr.append(el)

    def _keep_with_next(row):
        # Chains every row's paragraphs to "keep with next", which combined with
        # cantSplit is the standard Word technique to stop a table breaking
        # across a page boundary between rows (not just within one row).
        for cell in row.cells:
            for p in cell.paragraphs:
                p.paragraph_format.keep_with_next = True

    periods = _sch_partition_by_period(rows) or [((ay_label, ''), rows)]

    first_period = True
    for (period_ay, period_sem), period_rows in periods:
        if not first_period:
            doc.add_page_break()
        first_period = False

        title = _sch_period_title(period_ay, period_sem)
        period_groups = _sch_exp_groups(period_rows)

        # Letterhead logo — see _SCH_LOGO_PATH; same file used everywhere.
        try:
            logo_p = doc.add_paragraph()
            logo_p.alignment = WD_ALIGN_PARAGRAPH.CENTER
            logo_p.add_run().add_picture(_SCH_LOGO_PATH, width=Cm(1.6))
        except Exception:
            pass

        h1 = doc.add_heading(title, 0)
        h1.alignment = WD_ALIGN_PARAGRAPH.CENTER
        h1.paragraph_format.space_after = Pt(2)
        for run in h1.runs:
            run.font.color.rgb = BLACK; run.font.size = Pt(12)

        camp = doc.add_table(rows=1, cols=1)
        camp.alignment = WD_TABLE_ALIGNMENT.CENTER
        _cell_lines(camp.rows[0].cells[0], ['LOPEZ, QUEZON CAMPUS'], bold=True, sz=9,
                    fill='7A0100', color=RGBColor(0xFF, 0xFF, 0xFF))

        first_prog = True
        for prog, ylmap in period_groups.items():
            if not first_prog:
                doc.add_page_break()
            first_prog = False

            h2 = doc.add_heading(_sch_official_prog_label(prog, prog_names), level=1)
            h2.alignment = WD_ALIGN_PARAGRAPH.CENTER
            h2.paragraph_format.space_before = Pt(4)
            h2.paragraph_format.space_after  = Pt(2)
            for run in h2.runs:
                run.font.color.rgb = BLACK; run.font.size = Pt(11)

            yl_items = list(ylmap.items())
            for yl_i, (yl, yl_rows) in enumerate(yl_items):
                h3 = doc.add_heading(_SCH_OFF_YL_LBL.get(yl, f'YEAR {yl}') if yl else 'UNCLASSIFIED', level=2)
                h3.paragraph_format.space_before = Pt(2)
                h3.paragraph_format.space_after  = Pt(1)
                for run in h3.runs:
                    run.font.color.rgb = BLACK; run.font.size = Pt(9)

                blocks, unscheduled = _sch_build_calendar(yl_rows)
                n_fine = len(_SCH_CAL_FINE_ROWS)

                # Single header row — the M/TH, T/F, W/S grouping is already implied
                # by the adjacent day-letter columns, so no separate pair-label row.
                tbl = doc.add_table(rows=1 + n_fine, cols=_SCH_CAL_NCOLS)
                tbl.style = 'Table Grid'
                tbl.alignment = WD_TABLE_ALIGNMENT.CENTER
                tbl.autofit = False
                # Fill the content width (page width minus the 1.3cm side margins)
                # instead of leaving the table narrow with extra centered whitespace.
                widths_in = [0.9, 0.92, 0.92, 0.92, 0.92, 0.92, 0.92, 0.92]
                for row in tbl.rows:
                    row_cells = row.cells  # cache — re-reading .cells per column re-triggers a full grid scan
                    for ci, w in enumerate(widths_in):
                        row_cells[ci].width = Inches(w)

                # NOTE: use tbl.rows[r].cells[c] (cheap list indexing), never
                # tbl.cell(r, c) — python-docx's Table.cell() recomputes the
                # entire merge-grid from scratch on every call, which turns a
                # ~200-cell table into an O(n^2) operation and was the actual
                # cause of multi-second (or worse) generation times per table.
                hdr_row_cells = tbl.rows[0].cells
                _cell_lines(hdr_row_cells[0], ['TIME'], bold=True, sz=7.5)
                for pi, (lbl, members) in enumerate(_SCH_CAL_COLS[:3]):
                    base = _SCH_CAL_COL_BASE[pi]
                    for si, d in enumerate(members):
                        _cell_lines(hdr_row_cells[base + si], [_SCH_CAL_SUBLBL[d]], bold=True, sz=7)
                sun_col = _SCH_CAL_COL_BASE[3]
                _cell_lines(hdr_row_cells[sun_col], ['SUN'], bold=True, sz=7.5)
                _set_row_height(tbl.rows[0], 9)

                for fi in range(n_fine):
                    _set_row_height(tbl.rows[1 + fi], 4 if _SCH_CAL_FINE_ROWS[fi][3] else 13)
                    fine_row_cells = tbl.rows[1 + fi].cells
                    for ci in range(_SCH_CAL_NCOLS):
                        _cell_lines(fine_row_cells[ci], [''], sz=6.5)

                for s_start, s_end, s_label in _SCH_STANDARD_SLOTS:
                    r0, r1 = _sch_cal_row_range(s_start, s_end)
                    cell = tbl.rows[1 + r0].cells[0]
                    if r1 > r0:
                        cell = cell.merge(tbl.rows[1 + r1].cells[0])
                    _cell_lines(cell, [s_label], bold=True, sz=7)

                for b in blocks:
                    col0, col1 = _sch_cal_abs_cols(b['pair_idx'], b['subcols'])
                    cell = tbl.rows[1 + b['row_start']].cells[col0]
                    if b['row_end'] > b['row_start'] or col1 > col0:
                        cell = cell.merge(tbl.rows[1 + b['row_end']].cells[col1])
                    _cell_lines(cell, b['lines'], sz=6.5)

                # Apply cantSplit/keepNext AFTER all cell content is written — _cell_lines
                # resets each cell's paragraph, which would otherwise wipe out these
                # properties if set beforehand. This is what actually stops Word from
                # breaking the table across a page boundary between rows.
                n_rows = len(tbl.rows)
                for ri, row in enumerate(tbl.rows):
                    _cant_split(row)
                    if ri < n_rows - 1:
                        _keep_with_next(row)

                if unscheduled:
                    p = doc.add_paragraph()
                    p.paragraph_format.space_before = Pt(1)
                    p.paragraph_format.space_after  = Pt(1)
                    run = p.add_run('Unscheduled / TBA: ' + '; '.join(unscheduled))
                    run.font.size = Pt(7); run.font.color.rgb = BLACK

                # Force exactly 2 calendar tables per page: break after every 2nd
                # year level (unless it's the section's last table already).
                if yl_i % 2 == 1 and yl_i < len(yl_items) - 1:
                    doc.add_page_break()

    buf = io.BytesIO()
    doc.save(buf); buf.seek(0)
    return buf.read()


def _sch_gen_pdf_calendar(rows, groups, sem_label='All Semesters', ay_label='', prog_names=None):
    """Calendar View PDF — faculty-schedule-style weekly timetable, mirroring
    _sch_gen_xlsx_calendar's fixed-height fine grid with Mon/Thu, Tue/Fri,
    Wed/Sat sub-columns and proportionally-positioned (SPAN-merged) blocks."""
    from reportlab.lib.pagesizes import A4
    from reportlab.lib import colors
    from reportlab.lib.units import cm
    from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
    from reportlab.platypus import SimpleDocTemplate, Table, TableStyle, Paragraph, Spacer, PageBreak, KeepTogether, Image as _RLImage
    from reportlab.lib.enums import TA_CENTER, TA_LEFT

    buf = io.BytesIO()
    doc = SimpleDocTemplate(buf, pagesize=A4,
                            leftMargin=1.3*cm, rightMargin=1.3*cm,
                            topMargin=1.2*cm, bottomMargin=1.2*cm)

    BLACK  = colors.black
    WHITE  = colors.white
    MAROON = colors.HexColor('#7A0100')

    styles = getSampleStyleSheet()
    h1 = ParagraphStyle('H1', parent=styles['Heading1'], textColor=BLACK, fontSize=12, spaceAfter=1, alignment=TA_CENTER)
    campus_style = ParagraphStyle('Campus', parent=styles['Normal'], textColor=WHITE, fontSize=9,
                                   alignment=TA_CENTER, fontName='Helvetica-Bold')
    h2 = ParagraphStyle('H2', parent=styles['Heading2'], textColor=BLACK, fontSize=11, spaceAfter=1, alignment=TA_CENTER)
    h3 = ParagraphStyle('H3', parent=styles['Heading3'], textColor=BLACK, fontSize=9, spaceAfter=1, alignment=TA_LEFT)
    hdr_style  = ParagraphStyle('Hdr', parent=styles['Normal'], textColor=BLACK, fontSize=7, alignment=TA_CENTER,
                                 fontName='Helvetica-Bold', leading=8)
    cell_style = ParagraphStyle('Cell', parent=styles['Normal'], textColor=BLACK, fontSize=5.8, alignment=TA_CENTER, leading=6.8)
    time_style = ParagraphStyle('TimeCell', parent=styles['Normal'], textColor=BLACK, fontSize=6.5, alignment=TA_CENTER,
                                 fontName='Helvetica-Bold', leading=7.5)
    note_style = ParagraphStyle('Note', parent=styles['Normal'], textColor=BLACK, fontSize=7.5, alignment=TA_LEFT)

    NCOLS   = _SCH_CAL_NCOLS
    TOTAL_W = (21 - 2.6) * cm
    TIME_W  = 1.7 * cm
    DAY_W   = (TOTAL_W - TIME_W) / (NCOLS - 1)
    COL_W   = [TIME_W] + [DAY_W] * (NCOLS - 1)
    ROW_H_NORMAL = 0.4 * cm
    ROW_H_GAP    = 0.12 * cm
    HDR_H        = 0.38 * cm

    periods = _sch_partition_by_period(rows) or [((ay_label, ''), rows)]

    story = []
    first_period = True
    for (period_ay, period_sem), period_rows in periods:
        if not first_period:
            story.append(PageBreak())
        first_period = False

        title = _sch_period_title(period_ay, period_sem)
        period_groups = _sch_exp_groups(period_rows)

        # Letterhead logo — see _SCH_LOGO_PATH; same file used everywhere.
        try:
            _logo = _RLImage(_SCH_LOGO_PATH, width=1.1*cm, height=1.1*cm)
            _logo.hAlign = 'CENTER'
            story.append(_logo)
        except Exception:
            pass
        story.append(Paragraph(title, h1))
        camp_tbl = Table([[Paragraph('LOPEZ, QUEZON CAMPUS', campus_style)]], colWidths=[TOTAL_W])
        camp_tbl.setStyle(TableStyle([('BACKGROUND', (0, 0), (-1, -1), MAROON), ('BOX', (0, 0), (-1, -1), 0.5, BLACK)]))
        story.append(camp_tbl)
        story.append(Spacer(1, 0.1*cm))

        first_prog = True
        for prog, ylmap in period_groups.items():
            if not first_prog:
                story.append(PageBreak())
            first_prog = False

            story.append(Paragraph(_sch_official_prog_label(prog, prog_names), h2))

            yl_items = list(ylmap.items())
            for yl_i, (yl, yl_rows) in enumerate(yl_items):
                yl_label = _SCH_OFF_YL_LBL.get(yl, f'YEAR {yl}') if yl else 'UNCLASSIFIED'
                yl_flow = [Paragraph(yl_label, h3)]

                blocks, unscheduled = _sch_build_calendar(yl_rows)
                n_fine = len(_SCH_CAL_FINE_ROWS)

                # Single header row — the M/TH, T/F, W/S grouping is already implied
                # by the adjacent day-letter columns, so no separate pair-label row.
                grid = [[Paragraph('', cell_style) for _ in range(NCOLS)] for _ in range(1 + n_fine)]
                span_cmds = []

                grid[0][0] = Paragraph('TIME', hdr_style)
                for pi, (lbl, members) in enumerate(_SCH_CAL_COLS[:3]):
                    base = _SCH_CAL_COL_BASE[pi]
                    for si, d in enumerate(members):
                        grid[0][base + si] = Paragraph(_SCH_CAL_SUBLBL[d], hdr_style)
                sun_col = _SCH_CAL_COL_BASE[3]
                grid[0][sun_col] = Paragraph('SUN', hdr_style)

                for s_start, s_end, s_label in _SCH_STANDARD_SLOTS:
                    r0, r1 = _sch_cal_row_range(s_start, s_end)
                    grid[1 + r0][0] = Paragraph(s_label, time_style)
                    if r1 > r0:
                        span_cmds.append(('SPAN', (0, 1 + r0), (0, 1 + r1)))

                for b in blocks:
                    col0, col1 = _sch_cal_abs_cols(b['pair_idx'], b['subcols'])
                    r0, r1 = 1 + b['row_start'], 1 + b['row_end']
                    cell_txt = '<br/><br/>'.join(line.replace('\n', '<br/>') for line in b['lines'])
                    grid[b['row_start'] + 1][col0] = Paragraph(cell_txt, cell_style)
                    if r1 > r0 or col1 > col0:
                        span_cmds.append(('SPAN', (col0, r0), (col1, r1)))

                row_heights = [HDR_H] + [
                    ROW_H_GAP if _SCH_CAL_FINE_ROWS[i][3] else ROW_H_NORMAL for i in range(n_fine)
                ]

                tbl = Table(grid, colWidths=COL_W, rowHeights=row_heights)
                tbl.setStyle(TableStyle(span_cmds + [
                    ('VALIGN',        (0, 0), (-1, -1), 'MIDDLE'),
                    ('GRID',          (0, 0), (-1, -1), 0.4, BLACK),
                    ('LEFTPADDING',   (0, 0), (-1, -1), 2),
                    ('RIGHTPADDING',  (0, 0), (-1, -1), 2),
                    ('TOPPADDING',    (0, 0), (-1, -1), 1),
                    ('BOTTOMPADDING', (0, 0), (-1, -1), 1),
                ]))
                yl_flow.append(tbl)

                if unscheduled:
                    yl_flow.append(Spacer(1, 0.05*cm))
                    yl_flow.append(Paragraph('Unscheduled / TBA: ' + '; '.join(unscheduled), note_style))

                story.append(KeepTogether(yl_flow))
                story.append(Spacer(1, 0.2*cm))

                # Force exactly 2 calendar tables per page: break after every 2nd
                # year level (unless it's the section's last table already).
                if yl_i % 2 == 1 and yl_i < len(yl_items) - 1:
                    story.append(PageBreak())

    doc.build(story)
    buf.seek(0)
    return buf.read()


def _room_official_title(sem_label, ay_label):
    title = f'ROOM SCHEDULE FOR {sem_label.upper()}'
    if ay_label:
        title += f', ACADEMIC YEAR {ay_label}'
    return title


# ══════════════════════════════════════════════════════════════════════════════
# Reports > Room Schedule — Building → Room grouped table layout, the report
# equivalent of the Class Schedule report's Program → Year Level → Section
# "SUBJECT OFFERINGS" layout. This is a separate, simpler table design from the
# weekly-calendar Room Schedule Export above (_room_gen_*_calendar) — Reports
# needs a flat sortable list per room, not a per-room timetable grid.
# ══════════════════════════════════════════════════════════════════════════════
_ROOM_RPT_HEADERS  = ['Day', 'Time', 'Subject Code', 'Subject Description', 'Program', 'Year', 'Instructor', 'A.Y.', 'Semester']
_ROOM_RPT_SEM_LABEL = {'A': '1st Semester', 'B': '2nd Semester', 'C': 'Summer'}
_ROOM_RPT_COL_CM   = [1.7, 2.6, 2.2, 5.2, 1.6, 1.0, 3.1, 1.7, 1.7]
_ROOM_RPT_CENTER_COLS = {0, 5, 8}  # Day, Year, Semester


def _room_report_fetch(cur, ay_ids, sem_types, building_id, room_type, room_id):
    """Fetch Reports > Room Schedule rows: LIVE room occupancy.

    The effective schedule (faculty_load.EFFECTIVE_SESSIONS_CTE): Published Official
    occurrences, minus those superseded by an active Published Local session (matched by
    official_sessionid), plus those Local sessions. Pending Drafts are not occupancy.
    """
    where, p = [], []
    if ay_ids:
        where.append(f"sem.academicyearid IN ({','.join(['%s']*len(ay_ids))})"); p.extend(ay_ids)
    if sem_types:
        where.append(f"sem.semestertype IN ({','.join(['%s']*len(sem_types))})"); p.extend(sem_types)
    if building_id:
        where.append("b.buildingid = %s"); p.append(int(building_id))
    if room_type:
        where.append("r.roomtype = %s"); p.append(room_type)
    if room_id:
        where.append("r.roomid = %s"); p.append(int(room_id))

    cur.execute("WITH " + faculty_load.EFFECTIVE_SESSIONS_CTE + f"""
        SELECT
            b.buildingname AS "Building", r.roomname AS "Room", r.roomtype AS "RoomType",
            es.daydesc AS "Day", es.daydesc AS "Day/s",
            TO_CHAR(ts_s.timevalue,'HH12:MI AM') || ' - ' ||
            TO_CHAR(ts_e.timevalue,'HH12:MI AM') AS "Time",
            cs.subjectcode AS "SubjectCode", cs.subjectname AS "SubjectName",
            sec.sectionname AS "Section", p.programcode AS "Program",
            pyl.yearlevel AS "Year",
            COALESCE(f.lastname||', '||f.firstname,'TBA') AS "Instructor",
            ay.yearstart||'–'||ay.yearend AS "AY", sem.semestertype AS "Sem",
            es.official_sessionid AS "OfficialSessionID", es.source AS "ScheduleSource"
        FROM effective_sessions es
        JOIN curriculumsubject cs ON es.curriculumsubjectid = cs.curriculumsubjectid
        JOIN sections sec ON es.sectionid = sec.sectionid
        JOIN program_yearlevel pyl ON sec.programyearlevelid = pyl.programyearlevelid
        JOIN programs p ON pyl.programcode = p.programcode
        JOIN semester sem ON es.semesterid = sem.semesterid
        JOIN academicyear ay ON sem.academicyearid = ay.academicyearid
        JOIN room r ON es.roomid = r.roomid
        JOIN building b ON r.buildingid = b.buildingid
        LEFT JOIN faculty f ON es.employeenumber = f.employeenumber
        LEFT JOIN timeslot ts_s ON es.starttimeid = ts_s.timeid
        LEFT JOIN timeslot ts_e ON es.endtimeid = ts_e.timeid
        {('WHERE ' + ' AND '.join(where)) if where else ''}
    """, p)
    effective = list(cur.fetchall() or [])
    effective.sort(key=lambda r: (
        str(r.get('Building') or ''), str(r.get('Room') or ''),
        str(r.get('Day') or ''), str(r.get('Time') or '')
    ))
    return effective


def _room_report_groups(rows):
    """Group flat Room Schedule report rows into Building -> Room, preserving
    the SQL's buildingname/roomname/day/time ordering. Returns an ordered list
    of (building_name, {room_name: {'type': roomtype, 'rows': [...]}}) tuples."""
    g = {}
    order = []
    for r in rows:
        bname = r.get('Building') or 'Unknown'
        if bname not in g:
            g[bname] = {}
            order.append(bname)
        rooms = g[bname]
        rname = r.get('Room') or 'TBA'
        if rname not in rooms:
            rooms[rname] = {'type': r.get('RoomType') or '', 'rows': []}
        rooms[rname]['rows'].append(r)
    return [(b, g[b]) for b in order]


def _room_official_row(r):
    """One data row in Reports > Room Schedule column order: Day...Semester."""
    return [
        r.get('Day') or '', r.get('Time') or '', r.get('SubjectCode') or '',
        r.get('SubjectName') or '', r.get('Program') or '', r.get('Year') or '',
        r.get('Instructor') or '', r.get('AY') or '',
        _ROOM_RPT_SEM_LABEL.get(r.get('Sem'), r.get('Sem') or ''),
    ]


def _room_report_gen_csv(groups):
    out = io.StringIO()
    w = csv.writer(out)
    for bname, rooms in groups:
        w.writerow([f'Building: {bname}'])
        for rname, info in rooms.items():
            type_sfx = f' ({info["type"]})' if info['type'] else ''
            w.writerow([f'Room: {rname}{type_sfx}'])
            w.writerow(_ROOM_RPT_HEADERS)
            for r in info['rows']:
                w.writerow(_room_official_row(r))
            w.writerow([])
        w.writerow([])
    return out.getvalue().encode('utf-8-sig')


def _room_report_gen_xlsx(groups, sem_label='All Semesters', ay_label=''):
    from openpyxl import Workbook
    from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
    from openpyxl.utils import get_column_letter

    wb = Workbook()
    ws = wb.active
    ws.title = 'Room Schedule'
    ws.sheet_view.showGridLines = False

    MAROON = PatternFill('solid', fgColor='7A0100')
    GRAY   = PatternFill('solid', fgColor='E4E4E4')
    thin   = Side(style='thin', color='000000')
    brd    = Border(left=thin, right=thin, top=thin, bottom=thin)
    title_font  = Font(bold=True, size=12)
    campus_font = Font(bold=True, size=12, color='FFFFFF')
    bldg_font  = Font(bold=True, size=11, color='222222')
    room_font  = Font(bold=True, size=9, italic=True)
    hdr_font   = Font(bold=True, size=9)
    data_font  = Font(size=9)
    center     = Alignment(horizontal='center', vertical='center', wrap_text=True)

    NCOLS = len(_ROOM_RPT_HEADERS)
    COL_W = [10, 20, 13, 42, 10, 6, 22, 12, 13]

    title = _room_official_title(sem_label, ay_label)
    rn = 1
    ws.merge_cells(start_row=rn, start_column=1, end_row=rn, end_column=NCOLS)
    c = ws.cell(rn, 1, title); c.font = title_font; c.alignment = Alignment(horizontal='center')
    ws.row_dimensions[rn].height = 20; rn += 1

    ws.merge_cells(start_row=rn, start_column=1, end_row=rn, end_column=NCOLS)
    c = ws.cell(rn, 1, 'LOPEZ, QUEZON CAMPUS'); c.font = campus_font; c.fill = MAROON
    c.alignment = Alignment(horizontal='center')
    ws.row_dimensions[rn].height = 18; rn += 1
    rn += 1

    for bname, rooms in groups:
        ws.merge_cells(start_row=rn, start_column=1, end_row=rn, end_column=NCOLS)
        c = ws.cell(rn, 1, f'BUILDING: {bname.upper()}')
        c.font = bldg_font; c.alignment = Alignment(horizontal='center')
        for col in range(1, NCOLS + 1):
            ws.cell(rn, col).border = brd; ws.cell(rn, col).fill = GRAY
        ws.row_dimensions[rn].height = 20; rn += 1

        for rname, info in rooms.items():
            type_sfx = f' — {info["type"]}' if info['type'] else ''
            c = ws.cell(rn, 1, f'Room: {rname}{type_sfx}')
            c.font = room_font
            ws.row_dimensions[rn].height = 16; rn += 1

            for ci, h in enumerate(_ROOM_RPT_HEADERS, 1):
                c = ws.cell(rn, ci, h); c.font = hdr_font; c.border = brd; c.alignment = center
            ws.row_dimensions[rn].height = 22; rn += 1

            for r in info['rows']:
                vals = _room_official_row(r)
                for ci, v in enumerate(vals, 1):
                    c = ws.cell(rn, ci, v); c.border = brd; c.font = data_font
                    c.alignment = center if (ci - 1) in _ROOM_RPT_CENTER_COLS else Alignment(
                        vertical='center', horizontal='left', wrap_text=True)
                ws.row_dimensions[rn].height = 15; rn += 1
            rn += 1
        rn += 1

    for i, w in enumerate(COL_W, 1):
        ws.column_dimensions[get_column_letter(i)].width = w

    ws.page_setup.orientation  = 'landscape'
    ws.page_setup.paperSize    = ws.PAPERSIZE_A4
    ws.page_setup.fitToWidth   = 1
    ws.page_setup.fitToHeight  = 0
    ws.sheet_properties.pageSetUpPr.fitToPage = True
    ws.page_margins.left = ws.page_margins.right = 0.4
    ws.page_margins.top  = ws.page_margins.bottom = 0.5

    buf = io.BytesIO()
    wb.save(buf); buf.seek(0)
    return buf.read()


def _room_report_gen_docx(groups, sem_label='All Semesters', ay_label=''):
    from docx import Document
    from docx.shared import Pt, RGBColor, Cm
    from docx.enum.text import WD_ALIGN_PARAGRAPH
    from docx.enum.table import WD_TABLE_ALIGNMENT, WD_ALIGN_VERTICAL
    from docx.enum.section import WD_ORIENT
    from docx.oxml.ns import qn
    from docx.oxml import OxmlElement

    doc = Document()
    sec = doc.sections[0]
    sec.orientation  = WD_ORIENT.LANDSCAPE
    sec.page_width, sec.page_height = sec.page_height, sec.page_width
    sec.left_margin = sec.right_margin  = Cm(1.0)
    sec.top_margin  = sec.bottom_margin = Cm(1.0)

    BLACK = RGBColor(0x00, 0x00, 0x00)
    title = _room_official_title(sem_label, ay_label)
    COL_W = [Cm(w) for w in _ROOM_RPT_COL_CM]

    def _bg(cell, hex6):
        tc   = cell._tc
        tcPr = tc.get_or_add_tcPr()
        shd  = OxmlElement('w:shd')
        shd.set(qn('w:val'), 'clear')
        shd.set(qn('w:color'), 'auto')
        shd.set(qn('w:fill'), hex6)
        tcPr.append(shd)

    def _cell_text(cell, text, bold=False, sz=8, fill=None, align=WD_ALIGN_PARAGRAPH.LEFT, color=None):
        cell.text = ''
        run = cell.paragraphs[0].add_run(str(text) if text is not None else '')
        run.font.bold = bold; run.font.size = Pt(sz); run.font.color.rgb = color or BLACK
        cell.paragraphs[0].alignment = align
        if fill: _bg(cell, fill)
        cell.vertical_alignment = WD_ALIGN_VERTICAL.CENTER

    def _set_col_widths(tbl):
        tbl.autofit = False
        tbl.allow_autofit = False
        for ci, w in enumerate(COL_W):
            tbl.columns[ci].width = w
            for row in tbl.rows:
                row.cells[ci].width = w

    h1 = doc.add_heading(title, 0)
    h1.alignment = WD_ALIGN_PARAGRAPH.CENTER
    for run in h1.runs:
        run.font.color.rgb = BLACK; run.font.size = Pt(14)

    camp = doc.add_table(rows=1, cols=1)
    camp.alignment = WD_TABLE_ALIGNMENT.CENTER
    _cell_text(camp.rows[0].cells[0], 'LOPEZ, QUEZON CAMPUS', bold=True, sz=11,
               fill='7A0100', align=WD_ALIGN_PARAGRAPH.CENTER, color=RGBColor(0xFF, 0xFF, 0xFF))
    doc.add_paragraph()

    # No forced page break per building — some buildings have only a room or
    # two, and hard-breaking before every one of them regardless of content
    # is what leaves a report full of nearly-blank pages (the same issue
    # fixed for the Class Schedule report's per-program breaks).
    first_bldg = True
    for bname, rooms in groups:
        if not first_bldg:
            doc.add_paragraph()
        first_bldg = False

        bldg_tbl = doc.add_table(rows=1, cols=1)
        bldg_tbl.alignment = WD_TABLE_ALIGNMENT.CENTER
        _cell_text(bldg_tbl.rows[0].cells[0], f'BUILDING: {bname.upper()}', bold=True, sz=12,
                   fill='E4E4E4', align=WD_ALIGN_PARAGRAPH.CENTER, color=RGBColor(0x22, 0x22, 0x22))
        bldg_tbl.rows[0].cells[0].paragraphs[0].paragraph_format.keep_with_next = True

        for rname, info in rooms.items():
            type_sfx = f' — {info["type"]}' if info['type'] else ''
            p_room = doc.add_paragraph()
            p_room.paragraph_format.keep_with_next = True
            run_room = p_room.add_run(f'Room: {rname}{type_sfx}')
            run_room.font.bold = True; run_room.font.italic = True; run_room.font.size = Pt(10)
            run_room.font.color.rgb = BLACK

            room_rows = info['rows']
            tbl = doc.add_table(rows=1 + len(room_rows), cols=len(_ROOM_RPT_HEADERS))
            tbl.style = 'Table Grid'
            tbl.alignment = WD_TABLE_ALIGNMENT.CENTER
            _set_col_widths(tbl)

            for ci, h_txt in enumerate(_ROOM_RPT_HEADERS):
                _cell_text(tbl.rows[0].cells[ci], h_txt, bold=True, sz=7, align=WD_ALIGN_PARAGRAPH.CENTER)

            for ri, r in enumerate(room_rows):
                vals = _room_official_row(r)
                for ci, v in enumerate(vals):
                    align = WD_ALIGN_PARAGRAPH.CENTER if ci in _ROOM_RPT_CENTER_COLS else WD_ALIGN_PARAGRAPH.LEFT
                    _cell_text(tbl.rows[ri + 1].cells[ci], v, sz=7, align=align)

            doc.add_paragraph()

    buf = io.BytesIO()
    doc.save(buf); buf.seek(0)
    return buf.read()


def _room_report_gen_pdf(groups, sem_label='All Semesters', ay_label=''):
    from reportlab.lib.pagesizes import A4, landscape
    from reportlab.lib import colors
    from reportlab.lib.units import cm
    from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
    from reportlab.platypus import SimpleDocTemplate, Table, TableStyle, Paragraph, Spacer, PageBreak, KeepTogether
    from reportlab.lib.enums import TA_CENTER, TA_LEFT
    from xml.sax.saxutils import escape as _xml_escape

    buf = io.BytesIO()
    doc = SimpleDocTemplate(buf, pagesize=landscape(A4),
                            leftMargin=1.0*cm, rightMargin=1.0*cm,
                            topMargin=1.0*cm, bottomMargin=1.0*cm)

    BLACK  = colors.black
    WHITE  = colors.white
    MAROON = colors.HexColor('#7A0100')
    GRAY   = colors.HexColor('#E4E4E4')

    styles = getSampleStyleSheet()
    h1 = ParagraphStyle('RH1', parent=styles['Heading1'], textColor=BLACK, fontSize=14, spaceAfter=2, alignment=TA_CENTER)
    campus_style = ParagraphStyle('RCampus', parent=styles['Normal'], textColor=WHITE, fontSize=11,
                                   alignment=TA_CENTER, fontName='Helvetica-Bold')
    bldg_style = ParagraphStyle('RBldg', parent=styles['Normal'], textColor=colors.HexColor('#222222'), fontSize=12,
                                 alignment=TA_CENTER, fontName='Helvetica-Bold')
    h3 = ParagraphStyle('RH3', parent=styles['Normal'], textColor=BLACK, fontSize=10, spaceAfter=2,
                         alignment=TA_LEFT, fontName='Helvetica-BoldOblique')

    cell_l = ParagraphStyle('RCellL', parent=styles['Normal'], fontName='Helvetica', fontSize=7, leading=8.5, textColor=BLACK, alignment=TA_LEFT)
    cell_c = ParagraphStyle('RCellC', parent=cell_l, alignment=TA_CENTER)
    hdr_c  = ParagraphStyle('RHdrC',  parent=cell_c, fontName='Helvetica-Bold')

    def _pc(v, center):
        text = _xml_escape(str(v)) if v not in (None, '') else '&nbsp;'
        return Paragraph(text, cell_c if center else cell_l)

    COL_W = [w*cm for w in _ROOM_RPT_COL_CM]
    title = _room_official_title(sem_label, ay_label)

    story = [Paragraph(title, h1)]
    camp_tbl = Table([[Paragraph('LOPEZ, QUEZON CAMPUS', campus_style)]], colWidths=[sum(COL_W)])
    camp_tbl.setStyle(TableStyle([('BACKGROUND', (0, 0), (-1, -1), MAROON), ('BOX', (0, 0), (-1, -1), 0.5, BLACK)]))
    story.append(camp_tbl)
    story.append(Spacer(1, 0.3*cm))

    # No forced page break per building — some buildings have only a room or
    # two, and hard-breaking before every one of them regardless of content
    # is what leaves a report full of nearly-blank pages (the same issue
    # fixed for the Class Schedule report's per-program breaks).
    first_bldg = True
    for bname, rooms in groups:
        if not first_bldg:
            story.append(Spacer(1, 0.4*cm))
        first_bldg = False

        bldg_tbl = Table([[Paragraph(f'BUILDING: {bname.upper()}', bldg_style)]], colWidths=[sum(COL_W)])
        bldg_tbl.setStyle(TableStyle([('BACKGROUND', (0, 0), (-1, -1), GRAY), ('BOX', (0, 0), (-1, -1), 0.5, BLACK)]))
        story.append(bldg_tbl)
        story.append(Spacer(1, 0.15*cm))

        for rname, info in rooms.items():
            type_sfx = f' — {info["type"]}' if info['type'] else ''
            room_flow = [Paragraph(f'Room: {rname}{type_sfx}', h3)]

            tbl_data = [[Paragraph(_xml_escape(h), hdr_c) for h in _ROOM_RPT_HEADERS]]
            for r in info['rows']:
                vals = _room_official_row(r)
                tbl_data.append([_pc(v, ci in _ROOM_RPT_CENTER_COLS) for ci, v in enumerate(vals)])

            tbl = Table(tbl_data, colWidths=COL_W, repeatRows=1)
            tbl.setStyle(TableStyle([
                ('VALIGN',         (0,0),  (-1,-1), 'MIDDLE'),
                ('GRID',           (0,0),  (-1,-1), 0.5, BLACK),
                ('LEFTPADDING',    (0,0),  (-1,-1), 2),
                ('RIGHTPADDING',   (0,0),  (-1,-1), 2),
                ('TOPPADDING',     (0,0),  (-1,-1), 2),
                ('BOTTOMPADDING',  (0,0),  (-1,-1), 2),
            ]))
            room_flow.append(tbl)
            story.append(KeepTogether(room_flow))
            story.append(Spacer(1, 0.25*cm))
        story.append(Spacer(1, 0.3*cm))

    doc.build(story)
    buf.seek(0)
    return buf.read()


def _room_report_gen_xlsx_calendar(groups, sem_label='All Semesters', ay_label=''):
    """Reports > Room Schedule, Calendar layout — one weekly-timetable
    calendar per room, grouped under its building (light-gray header, same
    as the Table layout), reusing the exact same _sch_build_calendar engine
    as the Class Schedule report's calendar view — just with room-flavoured
    block text (_room_cal_block_text: time/subject/program+section/
    instructor, no room name repeated since the calendar already IS that
    room's schedule)."""
    from openpyxl import Workbook
    from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
    from openpyxl.utils import get_column_letter

    wb = Workbook()
    ws = wb.active
    ws.title = 'Room Schedule (Calendar)'
    ws.sheet_view.showGridLines = False

    MAROON = PatternFill('solid', fgColor='7A0100')
    GRAY   = PatternFill('solid', fgColor='E4E4E4')
    thin   = Side(style='thin', color='000000')
    brd    = Border(left=thin, right=thin, top=thin, bottom=thin)
    title_font  = Font(bold=True, size=12)
    campus_font = Font(bold=True, size=12, color='FFFFFF')
    bldg_font   = Font(bold=True, size=11, color='222222')
    room_font   = Font(bold=True, size=9, italic=True)
    hdr_font    = Font(bold=True, size=8.5)
    data_font   = Font(size=6.5)
    center      = Alignment(horizontal='center', vertical='center', wrap_text=True)

    NCOLS = _SCH_CAL_NCOLS
    COL_W = [10, 12, 12, 12, 12, 12, 12, 12]
    ROW_H_NORMAL = 20
    ROW_H_GAP    = 5

    title = _room_official_title(sem_label, ay_label)
    rn = 1
    ws.merge_cells(start_row=rn, start_column=1, end_row=rn, end_column=NCOLS)
    c = ws.cell(rn, 1, title); c.font = title_font; c.alignment = Alignment(horizontal='center')
    ws.row_dimensions[rn].height = 16; rn += 1

    ws.merge_cells(start_row=rn, start_column=1, end_row=rn, end_column=NCOLS)
    c = ws.cell(rn, 1, 'LOPEZ, QUEZON CAMPUS'); c.font = campus_font; c.fill = MAROON
    c.alignment = Alignment(horizontal='center')
    ws.row_dimensions[rn].height = 14; rn += 1

    for bname, rooms in groups:
        ws.merge_cells(start_row=rn, start_column=1, end_row=rn, end_column=NCOLS)
        c = ws.cell(rn, 1, f'BUILDING: {bname.upper()}')
        c.font = bldg_font; c.alignment = Alignment(horizontal='center')
        for col in range(1, NCOLS + 1):
            ws.cell(rn, col).border = brd; ws.cell(rn, col).fill = GRAY
        ws.row_dimensions[rn].height = 18; rn += 1

        for rname, info in rooms.items():
            type_sfx = f' — {info["type"]}' if info['type'] else ''
            c = ws.cell(rn, 1, f'Room: {rname}{type_sfx}'); c.font = room_font
            ws.row_dimensions[rn].height = 15; rn += 1

            blocks, unscheduled = _sch_build_calendar(info['rows'], text_fn=_room_cal_block_text)

            hdr_row = rn
            c = ws.cell(hdr_row, 1, 'TIME'); c.font = hdr_font; c.border = brd; c.alignment = center
            for pi, (lbl, members) in enumerate(_SCH_CAL_COLS[:3]):
                base = _SCH_CAL_COL_BASE[pi]
                for si, d in enumerate(members):
                    c = ws.cell(hdr_row, base + 1 + si, _SCH_CAL_SUBLBL[d])
                    c.font = hdr_font; c.border = brd; c.alignment = center
            sun_col = _SCH_CAL_COL_BASE[3] + 1
            c = ws.cell(hdr_row, sun_col, 'SUN'); c.font = hdr_font; c.border = brd; c.alignment = center
            ws.row_dimensions[hdr_row].height = 14

            data_start = hdr_row + 1
            for fi, (fs, fe, flbl, is_gap) in enumerate(_SCH_CAL_FINE_ROWS):
                excel_row = data_start + fi
                ws.row_dimensions[excel_row].height = ROW_H_GAP if is_gap else ROW_H_NORMAL
                for col in range(1, NCOLS + 1):
                    ws.cell(excel_row, col).border = brd

            for s_start, s_end, s_label in _SCH_STANDARD_SLOTS:
                r0, r1 = _sch_cal_row_range(s_start, s_end)
                er0, er1 = data_start + r0, data_start + r1
                if er1 > er0:
                    ws.merge_cells(start_row=er0, start_column=1, end_row=er1, end_column=1)
                c = ws.cell(er0, 1, s_label); c.font = hdr_font; c.alignment = center

            for b in blocks:
                col0, col1 = _sch_cal_abs_cols(b['pair_idx'], b['subcols'])
                er0, er1 = data_start + b['row_start'], data_start + b['row_end']
                ec0, ec1 = col0 + 1, col1 + 1
                if er1 > er0 or ec1 > ec0:
                    ws.merge_cells(start_row=er0, start_column=ec0, end_row=er1, end_column=ec1)
                c = ws.cell(er0, ec0, '\n\n'.join(b['lines'])); c.font = data_font; c.alignment = center

            rn = data_start + len(_SCH_CAL_FINE_ROWS)

            if unscheduled:
                c = ws.cell(rn, 1, 'Unscheduled / TBA:'); c.font = hdr_font; rn += 1
                for u in unscheduled:
                    ws.merge_cells(start_row=rn, start_column=1, end_row=rn, end_column=NCOLS)
                    c = ws.cell(rn, 1, u); c.font = data_font
                    rn += 1

            rn += 1
        rn += 1

    for i, w in enumerate(COL_W, 1):
        ws.column_dimensions[get_column_letter(i)].width = w

    buf = io.BytesIO()
    wb.save(buf); buf.seek(0)
    return buf.read()


def _room_report_gen_docx_calendar(groups, sem_label='All Semesters', ay_label=''):
    """Reports > Room Schedule, Calendar layout, DOCX — see
    _room_report_gen_xlsx_calendar for the design; same per-room weekly grid
    via _sch_build_calendar, one Word table per room."""
    from docx import Document
    from docx.shared import Pt, RGBColor, Inches, Cm
    from docx.enum.text import WD_ALIGN_PARAGRAPH
    from docx.enum.table import WD_TABLE_ALIGNMENT, WD_ALIGN_VERTICAL, WD_ROW_HEIGHT_RULE
    from docx.enum.section import WD_ORIENT
    from docx.oxml.ns import qn
    from docx.oxml import OxmlElement

    doc = Document()
    sec = doc.sections[0]
    sec.orientation  = WD_ORIENT.LANDSCAPE
    sec.page_width, sec.page_height = sec.page_height, sec.page_width
    sec.left_margin = sec.right_margin  = Cm(1.0)
    sec.top_margin  = sec.bottom_margin = Cm(1.0)

    BLACK = RGBColor(0x00, 0x00, 0x00)

    def _bg(cell, hex6):
        tc   = cell._tc
        tcPr = tc.get_or_add_tcPr()
        shd  = OxmlElement('w:shd')
        shd.set(qn('w:val'), 'clear')
        shd.set(qn('w:color'), 'auto')
        shd.set(qn('w:fill'), hex6)
        tcPr.append(shd)

    def _cell_lines(cell, entries, bold=False, sz=8, fill=None, align=WD_ALIGN_PARAGRAPH.CENTER, color=None):
        cell.text = ''
        p = cell.paragraphs[0]
        p.alignment = align
        pf = p.paragraph_format
        pf.space_before = Pt(0); pf.space_after = Pt(0); pf.line_spacing = 1.0
        flat = []
        for e in (entries or ['']):
            flat.extend(str(e).split('\n'))
        if not flat:
            flat = ['']
        for i, line in enumerate(flat):
            run = p.add_run(line)
            run.font.bold = bold; run.font.size = Pt(sz); run.font.color.rgb = color or BLACK
            if i < len(flat) - 1:
                run.add_break()
        if fill: _bg(cell, fill)
        cell.vertical_alignment = WD_ALIGN_VERTICAL.CENTER

    def _set_row_height(row, pts, exact=True):
        row.height = Pt(pts)
        row.height_rule = WD_ROW_HEIGHT_RULE.EXACTLY if exact else WD_ROW_HEIGHT_RULE.AT_LEAST

    title = _room_official_title(sem_label, ay_label)
    h1 = doc.add_heading(title, 0)
    h1.alignment = WD_ALIGN_PARAGRAPH.CENTER
    h1.paragraph_format.space_after = Pt(2)
    for run in h1.runs:
        run.font.color.rgb = BLACK; run.font.size = Pt(12)

    camp = doc.add_table(rows=1, cols=1)
    camp.alignment = WD_TABLE_ALIGNMENT.CENTER
    _cell_lines(camp.rows[0].cells[0], ['LOPEZ, QUEZON CAMPUS'], bold=True, sz=9,
                fill='7A0100', color=RGBColor(0xFF, 0xFF, 0xFF))

    # No forced page break per building/room — see the Table layout generator
    # above for why (many nearly-blank pages otherwise).
    first_bldg = True
    for bname, rooms in groups:
        if not first_bldg:
            doc.add_paragraph()
        first_bldg = False

        bldg_tbl = doc.add_table(rows=1, cols=1)
        bldg_tbl.alignment = WD_TABLE_ALIGNMENT.CENTER
        _cell_lines(bldg_tbl.rows[0].cells[0], [f'BUILDING: {bname.upper()}'], bold=True, sz=11,
                    fill='E4E4E4', color=RGBColor(0x22, 0x22, 0x22))
        bldg_tbl.rows[0].cells[0].paragraphs[0].paragraph_format.keep_with_next = True

        for rname, info in rooms.items():
            type_sfx = f' — {info["type"]}' if info['type'] else ''
            p_room = doc.add_paragraph()
            p_room.paragraph_format.keep_with_next = True
            run_room = p_room.add_run(f'Room: {rname}{type_sfx}')
            run_room.font.bold = True; run_room.font.italic = True; run_room.font.size = Pt(10)
            run_room.font.color.rgb = BLACK

            blocks, unscheduled = _sch_build_calendar(info['rows'], text_fn=_room_cal_block_text)
            n_fine = len(_SCH_CAL_FINE_ROWS)

            tbl = doc.add_table(rows=1 + n_fine, cols=_SCH_CAL_NCOLS)
            tbl.style = 'Table Grid'
            tbl.alignment = WD_TABLE_ALIGNMENT.CENTER
            tbl.autofit = False
            widths_in = [0.9, 0.92, 0.92, 0.92, 0.92, 0.92, 0.92, 0.92]
            for row in tbl.rows:
                row_cells = row.cells
                for ci, w in enumerate(widths_in):
                    row_cells[ci].width = Inches(w)

            hdr_row_cells = tbl.rows[0].cells
            _cell_lines(hdr_row_cells[0], ['TIME'], bold=True, sz=7.5)
            for pi, (lbl, members) in enumerate(_SCH_CAL_COLS[:3]):
                base = _SCH_CAL_COL_BASE[pi]
                for si, d in enumerate(members):
                    _cell_lines(hdr_row_cells[base + si], [_SCH_CAL_SUBLBL[d]], bold=True, sz=7)
            sun_col = _SCH_CAL_COL_BASE[3]
            _cell_lines(hdr_row_cells[sun_col], ['SUN'], bold=True, sz=7.5)
            _set_row_height(tbl.rows[0], 9)

            for fi in range(n_fine):
                _set_row_height(tbl.rows[1 + fi], 4 if _SCH_CAL_FINE_ROWS[fi][3] else 13)
                fine_row_cells = tbl.rows[1 + fi].cells
                for ci in range(_SCH_CAL_NCOLS):
                    _cell_lines(fine_row_cells[ci], [''], sz=6.5)

            for s_start, s_end, s_label in _SCH_STANDARD_SLOTS:
                r0, r1 = _sch_cal_row_range(s_start, s_end)
                cell = tbl.rows[1 + r0].cells[0]
                if r1 > r0:
                    cell = cell.merge(tbl.rows[1 + r1].cells[0])
                _cell_lines(cell, [s_label], bold=True, sz=7)

            for b in blocks:
                col0, col1 = _sch_cal_abs_cols(b['pair_idx'], b['subcols'])
                cell = tbl.rows[1 + b['row_start']].cells[col0]
                if b['row_end'] > b['row_start'] or col1 > col0:
                    cell = cell.merge(tbl.rows[1 + b['row_end']].cells[col1])
                _cell_lines(cell, b['lines'], sz=6.5)

            if unscheduled:
                p = doc.add_paragraph()
                p.paragraph_format.space_before = Pt(1); p.paragraph_format.space_after = Pt(1)
                run = p.add_run('Unscheduled / TBA: ' + '; '.join(unscheduled))
                run.font.size = Pt(7); run.font.color.rgb = BLACK

            doc.add_paragraph()

    buf = io.BytesIO()
    doc.save(buf); buf.seek(0)
    return buf.read()


def _room_report_gen_pdf_calendar(groups, sem_label='All Semesters', ay_label=''):
    """Reports > Room Schedule, Calendar layout, PDF — see
    _room_report_gen_xlsx_calendar for the design; same per-room weekly grid
    via _sch_build_calendar, one reportlab table per room."""
    from reportlab.lib.pagesizes import A4, landscape
    from reportlab.lib import colors
    from reportlab.lib.units import cm
    from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
    from reportlab.platypus import SimpleDocTemplate, Table, TableStyle, Paragraph, Spacer, PageBreak, KeepTogether
    from reportlab.lib.enums import TA_CENTER, TA_LEFT

    buf = io.BytesIO()
    doc = SimpleDocTemplate(buf, pagesize=landscape(A4),
                            leftMargin=1.3*cm, rightMargin=1.3*cm,
                            topMargin=1.2*cm, bottomMargin=1.2*cm)

    BLACK  = colors.black
    WHITE  = colors.white
    MAROON = colors.HexColor('#7A0100')
    GRAY   = colors.HexColor('#E4E4E4')

    styles = getSampleStyleSheet()
    h1 = ParagraphStyle('RCH1', parent=styles['Heading1'], textColor=BLACK, fontSize=12, spaceAfter=1, alignment=TA_CENTER)
    campus_style = ParagraphStyle('RCCampus', parent=styles['Normal'], textColor=WHITE, fontSize=9,
                                   alignment=TA_CENTER, fontName='Helvetica-Bold')
    bldg_style = ParagraphStyle('RCBldg', parent=styles['Normal'], textColor=colors.HexColor('#222222'), fontSize=11,
                                 alignment=TA_CENTER, fontName='Helvetica-Bold')
    h3 = ParagraphStyle('RCH3', parent=styles['Normal'], textColor=BLACK, fontSize=9, spaceAfter=1, alignment=TA_LEFT)
    hdr_style  = ParagraphStyle('RCHdr', parent=styles['Normal'], textColor=BLACK, fontSize=7, alignment=TA_CENTER,
                                 fontName='Helvetica-Bold', leading=8)
    cell_style = ParagraphStyle('RCCell', parent=styles['Normal'], textColor=BLACK, fontSize=5.8, alignment=TA_CENTER, leading=6.8)
    time_style = ParagraphStyle('RCTime', parent=styles['Normal'], textColor=BLACK, fontSize=6.5, alignment=TA_CENTER,
                                 fontName='Helvetica-Bold', leading=7.5)
    note_style = ParagraphStyle('RCNote', parent=styles['Normal'], textColor=BLACK, fontSize=7.5, alignment=TA_LEFT)

    NCOLS   = _SCH_CAL_NCOLS
    TOTAL_W = (29.7 - 2.6) * cm
    TIME_W  = 1.7 * cm
    DAY_W   = (TOTAL_W - TIME_W) / (NCOLS - 1)
    COL_W   = [TIME_W] + [DAY_W] * (NCOLS - 1)
    ROW_H_NORMAL = 0.4 * cm
    ROW_H_GAP    = 0.12 * cm
    HDR_H        = 0.38 * cm

    title = _room_official_title(sem_label, ay_label)
    story = [Paragraph(title, h1)]
    camp_tbl = Table([[Paragraph('LOPEZ, QUEZON CAMPUS', campus_style)]], colWidths=[TOTAL_W])
    camp_tbl.setStyle(TableStyle([('BACKGROUND', (0, 0), (-1, -1), MAROON), ('BOX', (0, 0), (-1, -1), 0.5, BLACK)]))
    story.append(camp_tbl)
    story.append(Spacer(1, 0.15*cm))

    first_bldg = True
    for bname, rooms in groups:
        if not first_bldg:
            story.append(Spacer(1, 0.3*cm))
        first_bldg = False

        bldg_tbl = Table([[Paragraph(f'BUILDING: {bname.upper()}', bldg_style)]], colWidths=[TOTAL_W])
        bldg_tbl.setStyle(TableStyle([('BACKGROUND', (0, 0), (-1, -1), GRAY), ('BOX', (0, 0), (-1, -1), 0.5, BLACK)]))
        story.append(bldg_tbl)
        story.append(Spacer(1, 0.1*cm))

        for rname, info in rooms.items():
            type_sfx = f' — {info["type"]}' if info['type'] else ''
            room_flow = [Paragraph(f'Room: {rname}{type_sfx}', h3)]

            blocks, unscheduled = _sch_build_calendar(info['rows'], text_fn=_room_cal_block_text)
            n_fine = len(_SCH_CAL_FINE_ROWS)

            grid = [[Paragraph('', cell_style) for _ in range(NCOLS)] for _ in range(1 + n_fine)]
            span_cmds = []

            grid[0][0] = Paragraph('TIME', hdr_style)
            for pi, (lbl, members) in enumerate(_SCH_CAL_COLS[:3]):
                base = _SCH_CAL_COL_BASE[pi]
                for si, d in enumerate(members):
                    grid[0][base + si] = Paragraph(_SCH_CAL_SUBLBL[d], hdr_style)
            sun_col = _SCH_CAL_COL_BASE[3]
            grid[0][sun_col] = Paragraph('SUN', hdr_style)

            for s_start, s_end, s_label in _SCH_STANDARD_SLOTS:
                r0, r1 = _sch_cal_row_range(s_start, s_end)
                grid[1 + r0][0] = Paragraph(s_label, time_style)
                if r1 > r0:
                    span_cmds.append(('SPAN', (0, 1 + r0), (0, 1 + r1)))

            for b in blocks:
                col0, col1 = _sch_cal_abs_cols(b['pair_idx'], b['subcols'])
                r0, r1 = 1 + b['row_start'], 1 + b['row_end']
                cell_txt = '<br/><br/>'.join(line.replace('\n', '<br/>') for line in b['lines'])
                grid[b['row_start'] + 1][col0] = Paragraph(cell_txt, cell_style)
                if r1 > r0 or col1 > col0:
                    span_cmds.append(('SPAN', (col0, r0), (col1, r1)))

            row_heights = [HDR_H] + [
                ROW_H_GAP if _SCH_CAL_FINE_ROWS[i][3] else ROW_H_NORMAL for i in range(n_fine)
            ]

            tbl = Table(grid, colWidths=COL_W, rowHeights=row_heights)
            tbl.setStyle(TableStyle(span_cmds + [
                ('VALIGN',        (0, 0), (-1, -1), 'MIDDLE'),
                ('GRID',          (0, 0), (-1, -1), 0.4, BLACK),
                ('LEFTPADDING',   (0, 0), (-1, -1), 2),
                ('RIGHTPADDING',  (0, 0), (-1, -1), 2),
                ('TOPPADDING',    (0, 0), (-1, -1), 1),
                ('BOTTOMPADDING', (0, 0), (-1, -1), 1),
            ]))
            room_flow.append(tbl)

            if unscheduled:
                room_flow.append(Spacer(1, 0.05*cm))
                room_flow.append(Paragraph('Unscheduled / TBA: ' + '; '.join(unscheduled), note_style))

            story.append(KeepTogether(room_flow))
            story.append(Spacer(1, 0.2*cm))

    doc.build(story)
    buf.seek(0)
    return buf.read()


def _room_report_context(cur, ay_ids, sem_types, building_id, room_type, room_id):
    """Fetch + group Reports > Room Schedule rows and compute the semester/AY
    labels used by the title banner — the Room Schedule report's equivalent of
    _sch_export_context for Class Schedule."""
    rows   = _room_report_fetch(cur, ay_ids, sem_types, building_id, room_type, room_id)
    groups = _room_report_groups(rows)

    sem_map   = {'A': '1st Semester', 'B': '2nd Semester', 'C': 'Summer'}
    uniq_sems = sorted({r['Sem'] for r in rows if r.get('Sem')})
    sem_label = ' & '.join(sem_map.get(s, s) for s in uniq_sems) if uniq_sems else 'All Semesters'
    uniq_ays  = sorted({r['AY'] for r in rows if r.get('AY')})
    ay_label  = uniq_ays[0] if len(uniq_ays) == 1 else ('Multiple Academic Years' if len(uniq_ays) > 1 else '')

    return rows, groups, sem_label, ay_label


def _room_gen_xlsx_calendar(room_groups, sem_label='All Semesters', ay_label=''):
    """Room Schedule Calendar View XLSX — one weekly-timetable calendar per
    room (sorted alphabetically by room name), reusing the same paired-day,
    fixed-fine-grid layout as the Subject Offerings Calendar View."""
    from openpyxl import Workbook
    from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
    from openpyxl.utils import get_column_letter

    wb = Workbook()
    ws = wb.active
    ws.title = 'Room Schedules'
    ws.sheet_view.showGridLines = False

    YELLOW = PatternFill('solid', fgColor='FFFF00')
    thin   = Side(style='thin', color='000000')
    brd    = Border(left=thin, right=thin, top=thin, bottom=thin)
    title_font = Font(bold=True, size=12)
    room_font  = Font(bold=True, size=11)
    hdr_font   = Font(bold=True, size=8.5)
    data_font  = Font(size=6.5)
    center     = Alignment(horizontal='center', vertical='center', wrap_text=True)

    NCOLS = _SCH_CAL_NCOLS
    COL_W = [10, 12, 12, 12, 12, 12, 12, 12]
    ROW_H_NORMAL = 20
    ROW_H_GAP    = 5

    title = _room_official_title(sem_label, ay_label)
    rn = 1
    ws.merge_cells(start_row=rn, start_column=1, end_row=rn, end_column=NCOLS)
    c = ws.cell(rn, 1, title); c.font = title_font; c.alignment = Alignment(horizontal='center')
    ws.row_dimensions[rn].height = 16; rn += 1

    ws.merge_cells(start_row=rn, start_column=1, end_row=rn, end_column=NCOLS)
    c = ws.cell(rn, 1, 'LOPEZ, QUEZON CAMPUS'); c.font = title_font; c.fill = YELLOW
    c.alignment = Alignment(horizontal='center')
    ws.row_dimensions[rn].height = 14; rn += 1

    for room in room_groups:
        c = ws.cell(rn, 1, room['name']); c.font = room_font
        c.alignment = Alignment(horizontal='left')
        ws.row_dimensions[rn].height = 15; rn += 1

        blocks, unscheduled = _sch_build_calendar(room['rows'], text_fn=_room_cal_block_text)

        hdr_row = rn
        c = ws.cell(hdr_row, 1, 'TIME'); c.font = hdr_font; c.border = brd; c.alignment = center
        for pi, (lbl, members) in enumerate(_SCH_CAL_COLS[:3]):
            base = _SCH_CAL_COL_BASE[pi]
            for si, d in enumerate(members):
                c = ws.cell(hdr_row, base + 1 + si, _SCH_CAL_SUBLBL[d])
                c.font = hdr_font; c.border = brd; c.alignment = center
        sun_col = _SCH_CAL_COL_BASE[3] + 1
        c = ws.cell(hdr_row, sun_col, 'SUN'); c.font = hdr_font; c.border = brd; c.alignment = center
        ws.row_dimensions[hdr_row].height = 14

        data_start = hdr_row + 1
        for fi, (fs, fe, flbl, is_gap) in enumerate(_SCH_CAL_FINE_ROWS):
            excel_row = data_start + fi
            ws.row_dimensions[excel_row].height = ROW_H_GAP if is_gap else ROW_H_NORMAL
            for col in range(1, NCOLS + 1):
                ws.cell(excel_row, col).border = brd

        for s_start, s_end, s_label in _SCH_STANDARD_SLOTS:
            r0, r1 = _sch_cal_row_range(s_start, s_end)
            er0, er1 = data_start + r0, data_start + r1
            if er1 > er0:
                ws.merge_cells(start_row=er0, start_column=1, end_row=er1, end_column=1)
            c = ws.cell(er0, 1, s_label); c.font = hdr_font; c.alignment = center

        for b in blocks:
            col0, col1 = _sch_cal_abs_cols(b['pair_idx'], b['subcols'])
            er0, er1 = data_start + b['row_start'], data_start + b['row_end']
            ec0, ec1 = col0 + 1, col1 + 1
            if er1 > er0 or ec1 > ec0:
                ws.merge_cells(start_row=er0, start_column=ec0, end_row=er1, end_column=ec1)
            c = ws.cell(er0, ec0, '\n\n'.join(b['lines'])); c.font = data_font; c.alignment = center

        rn = data_start + len(_SCH_CAL_FINE_ROWS)

        if unscheduled:
            c = ws.cell(rn, 1, 'Unscheduled / TBA:'); c.font = hdr_font; rn += 1
            for u in unscheduled:
                ws.merge_cells(start_row=rn, start_column=1, end_row=rn, end_column=NCOLS)
                c = ws.cell(rn, 1, u); c.font = data_font
                rn += 1

        rn += 1

    for i, w in enumerate(COL_W, 1):
        ws.column_dimensions[get_column_letter(i)].width = w

    buf = io.BytesIO()
    wb.save(buf); buf.seek(0)
    return buf.read()


def _room_gen_docx_calendar(room_groups, sem_label='All Semesters', ay_label=''):
    """Room Schedule Calendar View DOCX — one weekly-timetable calendar per
    room (sorted alphabetically by room name), mirroring the Subject
    Offerings Calendar View's fixed-height fine grid and 2-per-page pagination."""
    from docx import Document
    from docx.shared import Pt, RGBColor, Inches, Cm
    from docx.enum.text import WD_ALIGN_PARAGRAPH
    from docx.enum.table import WD_TABLE_ALIGNMENT, WD_ALIGN_VERTICAL, WD_ROW_HEIGHT_RULE
    from docx.oxml.ns import qn
    from docx.oxml import OxmlElement

    doc = Document()
    sec = doc.sections[0]
    sec.page_width  = Inches(8.5)
    sec.page_height = Inches(11)
    sec.left_margin = sec.right_margin  = Cm(1.3)
    sec.top_margin  = sec.bottom_margin = Cm(1.0)

    BLACK = RGBColor(0x00, 0x00, 0x00)
    title = _room_official_title(sem_label, ay_label)

    def _bg(cell, hex6):
        tc   = cell._tc
        tcPr = tc.get_or_add_tcPr()
        shd  = OxmlElement('w:shd')
        shd.set(qn('w:val'), 'clear')
        shd.set(qn('w:color'), 'auto')
        shd.set(qn('w:fill'), hex6)
        tcPr.append(shd)

    def _cell_lines(cell, entries, bold=False, sz=8, fill=None, align=WD_ALIGN_PARAGRAPH.CENTER):
        cell.text = ''
        p = cell.paragraphs[0]
        p.alignment = align
        pf = p.paragraph_format
        pf.space_before = Pt(0)
        pf.space_after  = Pt(0)
        pf.line_spacing = 1.0
        flat = []
        for e in (entries or ['']):
            flat.extend(str(e).split('\n'))
        if not flat:
            flat = ['']
        for i, line in enumerate(flat):
            run = p.add_run(line)
            run.font.bold = bold; run.font.size = Pt(sz); run.font.color.rgb = BLACK
            if i < len(flat) - 1:
                run.add_break()
        if fill: _bg(cell, fill)
        cell.vertical_alignment = WD_ALIGN_VERTICAL.CENTER

    def _set_row_height(row, pts, exact=True):
        row.height = Pt(pts)
        row.height_rule = WD_ROW_HEIGHT_RULE.EXACTLY if exact else WD_ROW_HEIGHT_RULE.AT_LEAST

    def _cant_split(row):
        trPr = row._tr.get_or_add_trPr()
        el = OxmlElement('w:cantSplit')
        trPr.append(el)

    def _keep_with_next(row):
        for cell in row.cells:
            for p in cell.paragraphs:
                p.paragraph_format.keep_with_next = True

    h1 = doc.add_heading(title, 0)
    h1.alignment = WD_ALIGN_PARAGRAPH.CENTER
    h1.paragraph_format.space_after = Pt(2)
    for run in h1.runs:
        run.font.color.rgb = BLACK; run.font.size = Pt(12)

    camp = doc.add_table(rows=1, cols=1)
    camp.alignment = WD_TABLE_ALIGNMENT.CENTER
    _cell_lines(camp.rows[0].cells[0], ['LOPEZ, QUEZON CAMPUS'], bold=True, sz=9, fill='FFFF00')

    for room_i, room in enumerate(room_groups):
        h3 = doc.add_heading(room['name'], level=1)
        h3.alignment = WD_ALIGN_PARAGRAPH.LEFT
        h3.paragraph_format.space_before = Pt(4)
        h3.paragraph_format.space_after  = Pt(2)
        for run in h3.runs:
            run.font.color.rgb = BLACK; run.font.size = Pt(11)

        blocks, unscheduled = _sch_build_calendar(room['rows'], text_fn=_room_cal_block_text)
        n_fine = len(_SCH_CAL_FINE_ROWS)

        tbl = doc.add_table(rows=1 + n_fine, cols=_SCH_CAL_NCOLS)
        tbl.style = 'Table Grid'
        tbl.alignment = WD_TABLE_ALIGNMENT.CENTER
        tbl.autofit = False
        # Fill the content width (page width minus the 1.3cm side margins)
        # instead of leaving the table narrow with extra centered whitespace.
        widths_in = [0.9, 0.92, 0.92, 0.92, 0.92, 0.92, 0.92, 0.92]
        for row in tbl.rows:
            row_cells = row.cells  # cache — re-reading .cells per column re-triggers a full grid scan
            for ci, w in enumerate(widths_in):
                row_cells[ci].width = Inches(w)

        # NOTE: use tbl.rows[r].cells[c] (cheap list indexing), never
        # tbl.cell(r, c) — python-docx's Table.cell() recomputes the entire
        # merge-grid from scratch on every call, which turns a ~200-cell
        # table into an O(n^2) operation and was the actual cause of
        # multi-second (or worse) generation times per room's calendar.
        hdr_row_cells = tbl.rows[0].cells
        _cell_lines(hdr_row_cells[0], ['TIME'], bold=True, sz=7.5)
        for pi, (lbl, members) in enumerate(_SCH_CAL_COLS[:3]):
            base = _SCH_CAL_COL_BASE[pi]
            for si, d in enumerate(members):
                _cell_lines(hdr_row_cells[base + si], [_SCH_CAL_SUBLBL[d]], bold=True, sz=7)
        sun_col = _SCH_CAL_COL_BASE[3]
        _cell_lines(hdr_row_cells[sun_col], ['SUN'], bold=True, sz=7.5)
        _set_row_height(tbl.rows[0], 9)

        for fi in range(n_fine):
            _set_row_height(tbl.rows[1 + fi], 4 if _SCH_CAL_FINE_ROWS[fi][3] else 13)
            fine_row_cells = tbl.rows[1 + fi].cells
            for ci in range(_SCH_CAL_NCOLS):
                _cell_lines(fine_row_cells[ci], [''], sz=6.5)

        for s_start, s_end, s_label in _SCH_STANDARD_SLOTS:
            r0, r1 = _sch_cal_row_range(s_start, s_end)
            cell = tbl.rows[1 + r0].cells[0]
            if r1 > r0:
                cell = cell.merge(tbl.rows[1 + r1].cells[0])
            _cell_lines(cell, [s_label], bold=True, sz=7)

        for b in blocks:
            col0, col1 = _sch_cal_abs_cols(b['pair_idx'], b['subcols'])
            cell = tbl.rows[1 + b['row_start']].cells[col0]
            if b['row_end'] > b['row_start'] or col1 > col0:
                cell = cell.merge(tbl.rows[1 + b['row_end']].cells[col1])
            _cell_lines(cell, b['lines'], sz=6.5)

        n_rows = len(tbl.rows)
        for ri, row in enumerate(tbl.rows):
            _cant_split(row)
            if ri < n_rows - 1:
                _keep_with_next(row)

        if unscheduled:
            p = doc.add_paragraph()
            p.paragraph_format.space_before = Pt(1)
            p.paragraph_format.space_after  = Pt(1)
            run = p.add_run('Unscheduled / TBA: ' + '; '.join(unscheduled))
            run.font.size = Pt(7); run.font.color.rgb = BLACK

        # Force exactly 2 room calendars per page: break after every 2nd room
        # (unless it's the very last room already).
        if room_i % 2 == 1 and room_i < len(room_groups) - 1:
            doc.add_page_break()

    buf = io.BytesIO()
    doc.save(buf); buf.seek(0)
    return buf.read()


def _room_gen_pdf_calendar(room_groups, sem_label='All Semesters', ay_label=''):
    """Room Schedule Calendar View PDF — one weekly-timetable calendar per
    room (sorted alphabetically by room name), mirroring the Subject
    Offerings Calendar View's fixed-height fine grid and 2-per-page pagination."""
    from reportlab.lib.pagesizes import A4
    from reportlab.lib import colors
    from reportlab.lib.units import cm
    from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
    from reportlab.platypus import SimpleDocTemplate, Table, TableStyle, Paragraph, Spacer, PageBreak, KeepTogether
    from reportlab.lib.enums import TA_CENTER, TA_LEFT

    buf = io.BytesIO()
    doc = SimpleDocTemplate(buf, pagesize=A4,
                            leftMargin=1.3*cm, rightMargin=1.3*cm,
                            topMargin=1.2*cm, bottomMargin=1.2*cm)

    BLACK  = colors.black
    YELLOW = colors.HexColor('#FFFF00')

    styles = getSampleStyleSheet()
    h1 = ParagraphStyle('H1', parent=styles['Heading1'], textColor=BLACK, fontSize=12, spaceAfter=1, alignment=TA_CENTER)
    campus_style = ParagraphStyle('Campus', parent=styles['Normal'], textColor=BLACK, fontSize=9,
                                   alignment=TA_CENTER, fontName='Helvetica-Bold')
    h3 = ParagraphStyle('H3Room', parent=styles['Heading2'], textColor=BLACK, fontSize=11, spaceAfter=2, alignment=TA_LEFT)
    hdr_style  = ParagraphStyle('Hdr', parent=styles['Normal'], textColor=BLACK, fontSize=7, alignment=TA_CENTER,
                                 fontName='Helvetica-Bold', leading=8)
    cell_style = ParagraphStyle('Cell', parent=styles['Normal'], textColor=BLACK, fontSize=5.8, alignment=TA_CENTER, leading=6.8)
    time_style = ParagraphStyle('TimeCell', parent=styles['Normal'], textColor=BLACK, fontSize=6.5, alignment=TA_CENTER,
                                 fontName='Helvetica-Bold', leading=7.5)
    note_style = ParagraphStyle('Note', parent=styles['Normal'], textColor=BLACK, fontSize=7.5, alignment=TA_LEFT)

    NCOLS   = _SCH_CAL_NCOLS
    TOTAL_W = (21 - 2.6) * cm
    TIME_W  = 1.7 * cm
    DAY_W   = (TOTAL_W - TIME_W) / (NCOLS - 1)
    COL_W   = [TIME_W] + [DAY_W] * (NCOLS - 1)
    ROW_H_NORMAL = 0.4 * cm
    ROW_H_GAP    = 0.12 * cm
    HDR_H        = 0.38 * cm

    title = _room_official_title(sem_label, ay_label)

    story = [Paragraph(title, h1)]
    camp_tbl = Table([[Paragraph('LOPEZ, QUEZON CAMPUS', campus_style)]], colWidths=[TOTAL_W])
    camp_tbl.setStyle(TableStyle([('BACKGROUND', (0, 0), (-1, -1), YELLOW), ('BOX', (0, 0), (-1, -1), 0.5, BLACK)]))
    story.append(camp_tbl)
    story.append(Spacer(1, 0.1*cm))

    for room_i, room in enumerate(room_groups):
        room_flow = [Paragraph(room['name'], h3)]

        blocks, unscheduled = _sch_build_calendar(room['rows'], text_fn=_room_cal_block_text)
        n_fine = len(_SCH_CAL_FINE_ROWS)

        grid = [[Paragraph('', cell_style) for _ in range(NCOLS)] for _ in range(1 + n_fine)]
        span_cmds = []

        grid[0][0] = Paragraph('TIME', hdr_style)
        for pi, (lbl, members) in enumerate(_SCH_CAL_COLS[:3]):
            base = _SCH_CAL_COL_BASE[pi]
            for si, d in enumerate(members):
                grid[0][base + si] = Paragraph(_SCH_CAL_SUBLBL[d], hdr_style)
        sun_col = _SCH_CAL_COL_BASE[3]
        grid[0][sun_col] = Paragraph('SUN', hdr_style)

        for s_start, s_end, s_label in _SCH_STANDARD_SLOTS:
            r0, r1 = _sch_cal_row_range(s_start, s_end)
            grid[1 + r0][0] = Paragraph(s_label, time_style)
            if r1 > r0:
                span_cmds.append(('SPAN', (0, 1 + r0), (0, 1 + r1)))

        for b in blocks:
            col0, col1 = _sch_cal_abs_cols(b['pair_idx'], b['subcols'])
            r0, r1 = 1 + b['row_start'], 1 + b['row_end']
            cell_txt = '<br/><br/>'.join(line.replace('\n', '<br/>') for line in b['lines'])
            grid[b['row_start'] + 1][col0] = Paragraph(cell_txt, cell_style)
            if r1 > r0 or col1 > col0:
                span_cmds.append(('SPAN', (col0, r0), (col1, r1)))

        row_heights = [HDR_H] + [
            ROW_H_GAP if _SCH_CAL_FINE_ROWS[i][3] else ROW_H_NORMAL for i in range(n_fine)
        ]

        tbl = Table(grid, colWidths=COL_W, rowHeights=row_heights)
        tbl.setStyle(TableStyle(span_cmds + [
            ('VALIGN',        (0, 0), (-1, -1), 'MIDDLE'),
            ('GRID',          (0, 0), (-1, -1), 0.4, BLACK),
            ('LEFTPADDING',   (0, 0), (-1, -1), 2),
            ('RIGHTPADDING',  (0, 0), (-1, -1), 2),
            ('TOPPADDING',    (0, 0), (-1, -1), 1),
            ('BOTTOMPADDING', (0, 0), (-1, -1), 1),
        ]))
        room_flow.append(tbl)

        if unscheduled:
            room_flow.append(Spacer(1, 0.05*cm))
            room_flow.append(Paragraph('Unscheduled / TBA: ' + '; '.join(unscheduled), note_style))

        story.append(KeepTogether(room_flow))
        story.append(Spacer(1, 0.2*cm))

        # Force exactly 2 room calendars per page: break after every 2nd room
        # (unless it's the very last room already).
        if room_i % 2 == 1 and room_i < len(room_groups) - 1:
            story.append(PageBreak())

    doc.build(story)
    buf.seek(0)
    return buf.read()


# ── Subject / Faculty Assignment Export ───────────────────────────────────────
_FACSUB_TYPE_ORDER  = ['Designee', 'Part-time', 'Regular']
_FACSUB_TYPE_LABELS = {
    'Designee':  'DESIGNEES',
    'Part-time': 'PART-TIME FACULTY',
    'Regular':   'REGULAR FACULTY',
}


def _facsub_exp_fetch(cur, ay_ids, sem_types, faculty_types):
    """Faculty/Subject Assignment Export: one row per current schedule
    assignment (subject+section+semester+employee), joined to faculty type
    for grouping. Historical/legacy data is excluded — it has no employee
    link, so it can't be classified by faculty type."""
    nf, params = ["sv.status IN ('Published', 'Draft')"], []
    if ay_ids:
        nf.append(f"ay.academicyearid IN ({','.join(['%s']*len(ay_ids))})"); params.extend(ay_ids)
    if sem_types:
        nf.append(f"sem.semestertype IN ({','.join(['%s']*len(sem_types))})"); params.extend(sem_types)
    if faculty_types:
        nf.append(f"et.typename IN ({','.join(['%s']*len(faculty_types))})"); params.extend(faculty_types)

    q = """
        SELECT
            f.employeenumber AS "EmpNum",
            f.lastname  AS "LastName",
            f.firstname AS "FirstName",
            COALESCE(f.lastname||', '||f.firstname||COALESCE(' '||f.middlename,''),'TBA') AS "FacultyName",
            et.typename      AS "FacultyType",
            cs.subjectcode   AS "SubjectCode",
            cs.subjectname   AS "SubjectDescription",
            pyl.programcode  AS "Program",
            pyl.yearlevel    AS "YearLevel",
            sec.sectionname  AS "Section",
            (COALESCE(cs.lecturehours,0)+COALESCE(cs.laboratoryhours,0)) AS "Hours",
            ay.yearstart||'-'||ay.yearend AS "AcademicYear",
            sem.semestertype AS "SemesterType"
        FROM schedule sc
        JOIN schedule_version sv        ON sv.scheduleid = sc.scheduleid
        JOIN curriculumsubject cs       ON sc.curriculumsubjectid = cs.curriculumsubjectid
        JOIN sections sec               ON sc.sectionid = sec.sectionid
        LEFT JOIN program_yearlevel pyl ON sec.programyearlevelid = pyl.programyearlevelid
        JOIN semester sem               ON sc.semesterid = sem.semesterid
        JOIN academicyear ay            ON sem.academicyearid = ay.academicyearid
        JOIN faculty f                  ON sc.employeenumber = f.employeenumber
        JOIN employeetype et            ON f.employeetypeid = et.employeetypeid
        WHERE """ + " AND ".join(nf) + """
          AND sv.version_number = (
              SELECT MAX(sv2.version_number)
              FROM schedule_version sv2
              WHERE sv2.scheduleid = sv.scheduleid
                AND sv2.status = sv.status
          )
        ORDER BY et.typename, f.lastname, f.firstname, cs.subjectcode
    """
    cur.execute(q, params)
    return cur.fetchall()


def _facsub_roster_fetch(cur, faculty_types):
    """All active faculty matching the selected type(s), independent of
    Academic Year/Semester — so faculty with no assigned load this period
    still appear in the report."""
    nf, params = [], []
    if faculty_types:
        nf.append(f"et.typename IN ({','.join(['%s']*len(faculty_types))})")
        params.extend(faculty_types)
    where = f"WHERE {' AND '.join(nf)}" if nf else ""
    q = f"""
        SELECT
            f.employeenumber AS "EmpNum",
            f.lastname  AS "LastName",
            f.firstname AS "FirstName",
            COALESCE(f.lastname||', '||f.firstname||COALESCE(' '||f.middlename,''),'TBA') AS "FacultyName",
            et.typename AS "FacultyType"
        FROM faculty f
        JOIN employeetype et ON f.employeetypeid = et.employeetypeid
        {where}
        ORDER BY et.typename, f.lastname, f.firstname
    """
    cur.execute(q, params)
    return cur.fetchall()


def _facsub_exp_groups(roster_rows, assignment_rows):
    """Group into [{'type','label','faculty':[{'name','rows'}...]}]}],
    ordered Designee -> Part-time -> Regular (only types actually present).
    Every faculty member in the roster appears exactly once — those with no
    assignment_rows for the selected period get an empty 'rows' list (the
    generators render this as a 'no assigned load' placeholder). Faculty
    with assignments keep their subject rows in original (subject-code)
    order, so consecutive rows for the same faculty member can have their
    Name shown/merged only once."""
    assign_by_fac = {}
    for r in assignment_rows:
        key = (r.get('LastName'), r.get('FirstName'), r.get('EmpNum'))
        assign_by_fac.setdefault(key, []).append(r)

    by_type = {}
    for fr in roster_rows:
        ft  = fr.get('FacultyType') or 'Unclassified'
        key = (fr.get('LastName'), fr.get('FirstName'), fr.get('EmpNum'))
        by_type.setdefault(ft, []).append({'name': fr.get('FacultyName'), 'rows': assign_by_fac.get(key, [])})

    order = [t for t in _FACSUB_TYPE_ORDER if t in by_type]
    order += sorted(t for t in by_type if t not in _FACSUB_TYPE_ORDER)

    result = []
    for ft in order:
        faculty_list = sorted(by_type[ft], key=lambda f: (f['name'] or '').upper())
        result.append({'type': ft, 'label': _FACSUB_TYPE_LABELS.get(ft, ft.upper()), 'faculty': faculty_list})
    return result


def _facsub_course_label(r):
    """'Course' column: Program + Year/Section, e.g. 'BSIT 1A'."""
    prog = (r.get('Program') or '').strip()
    sec  = (r.get('Section') or '').strip()
    suffix = sec
    if prog and sec.upper().startswith(prog.upper()):
        suffix = sec[len(prog):].lstrip('-').strip()
    return f"{prog} {suffix}".strip() if (prog or suffix) else ''


def _facsub_official_title_lines(sem_label, ay_label):
    """Two-line report header, repeated before EACH faculty-type section:
    'SUBJECT / FACULTY ASSIGNMENT REPORT' then '1ST SEMESTER, ACADEMIC YEAR ...'."""
    line2 = sem_label.upper()
    if ay_label:
        line2 += f', ACADEMIC YEAR {ay_label}'
    return ['SUBJECT / FACULTY ASSIGNMENT REPORT', line2]


def _facsub_gen_csv(groups, sem_label='All Semesters', ay_label=''):
    out = io.StringIO()
    w = csv.writer(out)
    title_lines = _facsub_official_title_lines(sem_label, ay_label)
    for grp in groups:
        if not grp['faculty']:
            continue
        for line in title_lines:
            w.writerow([line])
        w.writerow([grp['label']])
        w.writerow(['Name', 'Subject Code', 'Subject Description', 'Course', 'Hours'])
        for fac in grp['faculty']:
            if not fac['rows']:
                w.writerow([fac['name'], '', '', '', ''])
                continue
            for i, r in enumerate(fac['rows']):
                name = fac['name'] if i == 0 else ''
                w.writerow([name, r.get('SubjectCode') or '', r.get('SubjectDescription') or '',
                            _facsub_course_label(r), r.get('Hours') or 0])
        w.writerow([])
    return out.getvalue().encode('utf-8-sig')


def _facsub_gen_xlsx(groups, sem_label='All Semesters', ay_label=''):
    from openpyxl import Workbook
    from openpyxl.styles import Font, Alignment, Border, Side, PatternFill
    from openpyxl.utils import get_column_letter
    from openpyxl.worksheet.pagebreak import Break

    wb = Workbook()
    ws = wb.active
    ws.title = 'Faculty Assignments'
    ws.sheet_view.showGridLines = False

    thin  = Side(style='thin', color='000000')
    brd   = Border(left=thin, right=thin, top=thin, bottom=thin)
    SHADE = PatternFill('solid', fgColor='F2F2F2')  # subtle alternating band per faculty member
    title_font = Font(bold=True, size=13)
    sub_font   = Font(bold=True, size=10)
    sect_font  = Font(bold=True, size=12)
    hdr_font   = Font(bold=True, size=9)
    data_font  = Font(size=9)
    center = Alignment(horizontal='center', vertical='center', wrap_text=True)
    left   = Alignment(horizontal='left', vertical='center', wrap_text=True)

    HEADERS = ['Name', 'Subject Code', 'Subject Description', 'Course', 'Hours']
    NCOLS   = len(HEADERS)
    COL_W   = [28, 14, 42, 14, 10]

    title_lines = _facsub_official_title_lines(sem_label, ay_label)
    rn = 1
    first_section = True
    for grp in groups:
        if not grp['faculty']:
            continue
        if not first_section:
            ws.row_breaks.append(Break(id=rn - 1))
        first_section = False

        ws.merge_cells(start_row=rn, start_column=1, end_row=rn, end_column=NCOLS)
        c = ws.cell(rn, 1, title_lines[0]); c.font = title_font; c.alignment = Alignment(horizontal='center')
        ws.row_dimensions[rn].height = 22; rn += 1

        ws.merge_cells(start_row=rn, start_column=1, end_row=rn, end_column=NCOLS)
        c = ws.cell(rn, 1, title_lines[1]); c.font = sub_font; c.alignment = Alignment(horizontal='center')
        ws.row_dimensions[rn].height = 18; rn += 1
        rn += 1

        ws.merge_cells(start_row=rn, start_column=1, end_row=rn, end_column=NCOLS)
        c = ws.cell(rn, 1, grp['label']); c.font = sect_font; c.alignment = Alignment(horizontal='left')
        for col in range(1, NCOLS + 1):
            ws.cell(rn, col).border = brd
        ws.row_dimensions[rn].height = 20; rn += 1

        for ci, h in enumerate(HEADERS, 1):
            c = ws.cell(rn, ci, h); c.font = hdr_font; c.border = brd; c.alignment = center
        ws.row_dimensions[rn].height = 20; rn += 1

        for fac_idx, fac in enumerate(grp['faculty']):
            start_row = rn
            fill = SHADE if fac_idx % 2 == 1 else None
            if not fac['rows']:
                c = ws.cell(rn, 1, fac['name']); c.font = data_font; c.border = brd; c.alignment = left
                if fill: c.fill = fill
                for col in range(2, NCOLS + 1):
                    c = ws.cell(rn, col, ''); c.border = brd
                    if fill: c.fill = fill
                ws.row_dimensions[rn].height = 15
                rn += 1
            else:
                for r in fac['rows']:
                    vals = ['', r.get('SubjectCode') or '', r.get('SubjectDescription') or '',
                            _facsub_course_label(r), r.get('Hours') or 0]
                    for ci, v in enumerate(vals, 1):
                        c = ws.cell(rn, ci, v); c.font = data_font; c.border = brd
                        c.alignment = center if ci in (2, 4, 5) else left
                        # Fill is applied to every physical row (including col 1,
                        # before it gets merged) rather than relying on
                        # merge_cells() to propagate the anchor's fill — unlike
                        # borders, openpyxl does not carry fill over to the
                        # other cells in a merged range on save.
                        if fill: c.fill = fill
                    ws.row_dimensions[rn].height = 15
                    rn += 1
                end_row = rn - 1
                c = ws.cell(start_row, 1, fac['name']); c.font = data_font; c.alignment = left
                if end_row > start_row:
                    ws.merge_cells(start_row=start_row, start_column=1, end_row=end_row, end_column=1)

        rn += 1

    for i, w in enumerate(COL_W, 1):
        ws.column_dimensions[get_column_letter(i)].width = w

    buf = io.BytesIO()
    wb.save(buf); buf.seek(0)
    return buf.read()


def _facsub_gen_docx(groups, sem_label='All Semesters', ay_label=''):
    from docx import Document
    from docx.shared import Pt, RGBColor, Inches, Cm
    from docx.enum.text import WD_ALIGN_PARAGRAPH
    from docx.enum.table import WD_TABLE_ALIGNMENT, WD_ALIGN_VERTICAL
    from docx.oxml.ns import qn
    from docx.oxml import OxmlElement

    doc = Document()
    sec = doc.sections[0]
    sec.page_width  = Inches(8.5)
    sec.page_height = Inches(11)
    sec.left_margin = sec.right_margin  = Cm(1.5)
    sec.top_margin  = sec.bottom_margin = Cm(1.5)

    BLACK = RGBColor(0x00, 0x00, 0x00)
    title_lines = _facsub_official_title_lines(sem_label, ay_label)
    SHADE = 'F2F2F2'  # subtle alternating band per faculty member's row block

    def _bg(cell, hex6):
        tc   = cell._tc
        tcPr = tc.get_or_add_tcPr()
        shd  = OxmlElement('w:shd')
        shd.set(qn('w:val'), 'clear')
        shd.set(qn('w:color'), 'auto')
        shd.set(qn('w:fill'), hex6)
        tcPr.append(shd)

    def _cell_text(cell, text, bold=False, sz=9, align=WD_ALIGN_PARAGRAPH.LEFT, fill=None):
        cell.text = ''
        p = cell.paragraphs[0]
        p.alignment = align
        p.paragraph_format.space_before = Pt(0)
        p.paragraph_format.space_after  = Pt(0)
        run = p.add_run('' if text is None else str(text))
        run.font.bold = bold; run.font.size = Pt(sz); run.font.color.rgb = BLACK
        if fill: _bg(cell, fill)
        cell.vertical_alignment = WD_ALIGN_VERTICAL.CENTER

    HEADERS   = ['Name', 'Subject Code', 'Subject Description', 'Course', 'Hours']
    # Fill the content width (page width minus the 1.5cm side margins) instead
    # of leaving the table narrow with extra centered whitespace.
    WIDTHS_IN = [1.35, 0.93, 3.21, 1.14, 0.62]

    first = True
    for grp in groups:
        if not grp['faculty']:
            continue
        if not first:
            doc.add_page_break()
        first = False

        h1 = doc.add_heading(title_lines[0], 0)
        h1.alignment = WD_ALIGN_PARAGRAPH.CENTER
        h1.paragraph_format.space_after = Pt(2)
        for run in h1.runs:
            run.font.color.rgb = BLACK; run.font.size = Pt(14)

        hsub = doc.add_paragraph(title_lines[1])
        hsub.alignment = WD_ALIGN_PARAGRAPH.CENTER
        hsub.paragraph_format.space_after = Pt(4)
        for run in hsub.runs:
            run.font.bold = True; run.font.size = Pt(11); run.font.color.rgb = BLACK

        h2 = doc.add_heading(grp['label'], level=1)
        for run in h2.runs:
            run.font.color.rgb = BLACK; run.font.size = Pt(12)

        total_rows = 1 + sum(max(len(fac['rows']), 1) for fac in grp['faculty'])
        tbl = doc.add_table(rows=total_rows, cols=len(HEADERS))
        tbl.style = 'Table Grid'
        tbl.alignment = WD_TABLE_ALIGNMENT.CENTER
        tbl.autofit = False
        for row in tbl.rows:
            row_cells = row.cells  # cache — re-reading .cells per column re-triggers a full grid scan
            for ci, w in enumerate(WIDTHS_IN):
                row_cells[ci].width = Inches(w)

        for ci, h in enumerate(HEADERS):
            _cell_text(tbl.rows[0].cells[ci], h, bold=True, sz=9, align=WD_ALIGN_PARAGRAPH.CENTER)

        ri = 1
        for fac_idx, fac in enumerate(grp['faculty']):
            fill = SHADE if fac_idx % 2 == 1 else None
            start_ri = ri
            if not fac['rows']:
                row_cells = tbl.rows[ri].cells  # cache — re-reading .cells per column re-triggers a full grid scan
                _cell_text(row_cells[0], fac['name'], sz=9, fill=fill)
                for ci in range(1, 5):
                    _cell_text(row_cells[ci], '', sz=9, fill=fill)
                ri += 1
            else:
                for r in fac['rows']:
                    row_cells = tbl.rows[ri].cells
                    _cell_text(row_cells[0], '', sz=9, fill=fill)
                    _cell_text(row_cells[1], r.get('SubjectCode') or '', sz=9, align=WD_ALIGN_PARAGRAPH.CENTER, fill=fill)
                    _cell_text(row_cells[2], r.get('SubjectDescription') or '', sz=9, fill=fill)
                    _cell_text(row_cells[3], _facsub_course_label(r), sz=9, align=WD_ALIGN_PARAGRAPH.CENTER, fill=fill)
                    _cell_text(row_cells[4], r.get('Hours') or 0, sz=9, align=WD_ALIGN_PARAGRAPH.CENTER, fill=fill)
                    ri += 1
                end_ri = ri - 1
                name_cell = tbl.rows[start_ri].cells[0]
                if end_ri > start_ri:
                    for extra_ri in range(start_ri + 1, end_ri + 1):
                        name_cell = name_cell.merge(tbl.rows[extra_ri].cells[0])
                _cell_text(name_cell, fac['name'], sz=9, fill=fill)

    buf = io.BytesIO()
    doc.save(buf); buf.seek(0)
    return buf.read()


def _facsub_gen_pdf(groups, sem_label='All Semesters', ay_label=''):
    from reportlab.lib.pagesizes import A4
    from reportlab.lib import colors
    from reportlab.lib.units import cm
    from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
    from reportlab.platypus import SimpleDocTemplate, Table, TableStyle, Paragraph, Spacer, PageBreak
    from reportlab.lib.enums import TA_CENTER, TA_LEFT

    buf = io.BytesIO()
    doc = SimpleDocTemplate(buf, pagesize=A4,
                            leftMargin=1.5*cm, rightMargin=1.5*cm,
                            topMargin=1.5*cm, bottomMargin=1.5*cm)

    BLACK = colors.black

    styles = getSampleStyleSheet()
    h1 = ParagraphStyle('H1', parent=styles['Heading1'], textColor=BLACK, fontSize=14, spaceAfter=2, alignment=TA_CENTER)
    hsub = ParagraphStyle('HSub', parent=styles['Normal'], textColor=BLACK, fontSize=11, spaceAfter=8,
                           alignment=TA_CENTER, fontName='Helvetica-Bold')
    h2 = ParagraphStyle('H2', parent=styles['Heading2'], textColor=BLACK, fontSize=12, spaceAfter=4, alignment=TA_LEFT)
    cell_style   = ParagraphStyle('Cell', parent=styles['Normal'], textColor=BLACK, fontSize=8, alignment=TA_LEFT, leading=10)
    cell_c_style = ParagraphStyle('CellC', parent=cell_style, alignment=TA_CENTER)

    COL_W = [3.2*cm, 2.1*cm, 7.7*cm, 2.8*cm, 1.6*cm]
    title_lines = _facsub_official_title_lines(sem_label, ay_label)

    HEADERS = ['Name', 'Subject Code', 'Subject Description', 'Course', 'Hours']

    story = []
    first = True
    for grp in groups:
        if not grp['faculty']:
            continue
        if not first:
            story.append(PageBreak())
        first = False

        story.append(Paragraph(title_lines[0], h1))
        story.append(Paragraph(title_lines[1], hsub))
        story.append(Paragraph(grp['label'], h2))

        tbl_data  = [HEADERS]
        span_cmds = []
        shade_cmds = []
        row_i = 1
        for fac_idx, fac in enumerate(grp['faculty']):
            start_i = row_i
            if not fac['rows']:
                tbl_data.append([
                    Paragraph(fac['name'], cell_style),
                    '', '', '', '',
                ])
                row_i += 1
            else:
                for r in fac['rows']:
                    tbl_data.append([
                        Paragraph('', cell_style),
                        Paragraph(r.get('SubjectCode') or '', cell_c_style),
                        Paragraph(r.get('SubjectDescription') or '', cell_style),
                        Paragraph(_facsub_course_label(r), cell_c_style),
                        Paragraph(str(r.get('Hours') or 0), cell_c_style),
                    ])
                    row_i += 1
                end_i = row_i - 1
                tbl_data[start_i][0] = Paragraph(fac['name'], cell_style)
                if end_i > start_i:
                    span_cmds.append(('SPAN', (0, start_i), (0, end_i)))
            # Subtle alternating shading per faculty member's row block, so
            # it's easy to see where one faculty member's load ends and the
            # next begins without relying on thicker borders.
            if fac_idx % 2 == 1:
                shade_cmds.append(('BACKGROUND', (0, start_i), (-1, row_i - 1), colors.HexColor('#F2F2F2')))

        style_cmds = span_cmds + shade_cmds + [
            ('FONTNAME',      (0, 0), (-1, 0),  'Helvetica-Bold'),
            ('FONTSIZE',      (0, 0), (-1, 0),  9),
            ('ALIGN',         (0, 0), (-1, 0),  'CENTER'),
            ('VALIGN',        (0, 0), (-1, -1), 'MIDDLE'),
            ('GRID',          (0, 0), (-1, -1), 0.5, BLACK),
            ('LEFTPADDING',   (0, 0), (-1, -1), 4),
            ('RIGHTPADDING',  (0, 0), (-1, -1), 4),
            ('TOPPADDING',    (0, 0), (-1, -1), 3),
            ('BOTTOMPADDING', (0, 0), (-1, -1), 3),
        ]

        tbl = Table(tbl_data, colWidths=COL_W, repeatRows=1)
        tbl.setStyle(TableStyle(style_cmds))
        story.append(tbl)
        story.append(Spacer(1, 0.5*cm))

    doc.build(story)
    buf.seek(0)
    return buf.read()


_FACSUB_ROLES = ('Admin', 'Academic Head')


@app.route('/admin/faculty/subject-export/count', methods=['POST'])
def facsub_export_count():
    if session.get('role') not in _FACSUB_ROLES:
        return jsonify({'error': 'Unauthorized'}), 403
    data          = request.get_json() or {}
    ay_ids        = data.get('ay_ids', [])
    sem_types     = data.get('sem_types', [])
    faculty_types = data.get('faculty_types', [])
    conn = get_db_connection()
    cur  = conn.cursor(cursor_factory=RealDictCursor)
    try:
        roster = _facsub_roster_fetch(cur, faculty_types)
        rows   = _facsub_exp_fetch(cur, ay_ids, sem_types, faculty_types)
        return jsonify({'count': len(rows), 'faculty': len(roster)})
    except Exception as e:
        import traceback; traceback.print_exc()
        return jsonify({'error': str(e)}), 500
    finally:
        cur.close(); conn.close()


@app.route('/admin/faculty/subject-export', methods=['POST'])
def facsub_export():
    if session.get('role') not in _FACSUB_ROLES:
        return jsonify({'error': 'Unauthorized'}), 403
    data          = request.get_json() or {}
    ay_ids        = data.get('ay_ids', [])
    sem_types     = data.get('sem_types', [])
    faculty_types = data.get('faculty_types', [])
    formats       = [f.lower() for f in data.get('formats', ['pdf'])]
    filename      = (data.get('filename', '') or 'faculty_subject_assignment').strip()
    for ext in ('.pdf', '.docx', '.xlsx', '.csv', '.zip'):
        if filename.lower().endswith(ext):
            filename = filename[:-len(ext)]

    conn = get_db_connection()
    cur  = conn.cursor(cursor_factory=RealDictCursor)
    try:
        roster = _facsub_roster_fetch(cur, faculty_types)
        rows   = _facsub_exp_fetch(cur, ay_ids, sem_types, faculty_types)
        groups = _facsub_exp_groups(roster, rows)

        # Derive the header's semester/AY text from the user's actual selection
        # (not from the fetched assignment rows) — with the new "include every
        # faculty member" behavior, a selected type can legitimately have zero
        # assignments, and the header must still reflect what was selected.
        sem_map   = {'A': '1st Semester', 'B': '2nd Semester', 'C': 'Summer'}
        sem_label = ' & '.join(sem_map.get(s, s) for s in sorted(sem_types)) if sem_types else 'All Semesters'
        ay_label = ''
        if ay_ids:
            cur.execute(
                f"SELECT yearstart, yearend FROM academicyear WHERE academicyearid IN "
                f"({','.join(['%s']*len(ay_ids))}) ORDER BY yearstart", ay_ids)
            ay_rows = cur.fetchall()
            if len(ay_rows) == 1:
                ay_label = f"{ay_rows[0]['yearstart']}-{ay_rows[0]['yearend']}"
            elif len(ay_rows) > 1:
                ay_label = 'Multiple Academic Years'

        mime_map = {
            'csv':  ('text/csv', '.csv'),
            'xlsx': ('application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', '.xlsx'),
            'docx': ('application/vnd.openxmlformats-officedocument.wordprocessingml.document', '.docx'),
            'pdf':  ('application/pdf', '.pdf'),
        }
        gen_map = {
            'csv':  lambda: _facsub_gen_csv(groups, sem_label, ay_label),
            'xlsx': lambda: _facsub_gen_xlsx(groups, sem_label, ay_label),
            'docx': lambda: _facsub_gen_docx(groups, sem_label, ay_label),
            'pdf':  lambda: _facsub_gen_pdf(groups, sem_label, ay_label),
        }

        if len(formats) == 1:
            fmt = formats[0]
            if fmt not in mime_map:
                return jsonify({'error': f'Unknown format: {fmt}'}), 400
            out = gen_map[fmt]()
            mime, ext = mime_map[fmt]
            return Response(out, mimetype=mime,
                            headers={'Content-Disposition': f'attachment; filename="{filename}{ext}"'})
        else:
            import zipfile
            buf = io.BytesIO()
            with zipfile.ZipFile(buf, 'w', zipfile.ZIP_DEFLATED) as zf:
                for fmt in formats:
                    if fmt in gen_map:
                        zf.writestr(filename + mime_map[fmt][1], gen_map[fmt]())
            buf.seek(0)
            return Response(buf.read(), mimetype='application/zip',
                            headers={'Content-Disposition': f'attachment; filename="{filename}.zip"'})
    except Exception as e:
        import traceback; traceback.print_exc()
        return jsonify({'error': str(e)}), 500
    finally:
        cur.close(); conn.close()


def _sch_export_bytes(fmt, layout, rows, groups, cal_rows, cal_groups, sem_labels, ay_label, prog_name_map):
    """Dispatch a single export format/layout combination to the right generator.
    CSV is always flat (layout has no effect on it)."""
    if fmt == 'csv':
        return _sch_gen_csv(rows)
    use_cal = (layout == 'calendar')
    r, g = (cal_rows, cal_groups) if use_cal else (rows, groups)
    if fmt == 'xlsx':
        return (_sch_gen_xlsx_calendar if use_cal else _sch_gen_xlsx)(r, g, sem_labels, ay_label, prog_name_map)
    if fmt == 'docx':
        return (_sch_gen_docx_calendar if use_cal else _sch_gen_docx)(r, g, sem_labels, ay_label, prog_name_map)
    if fmt == 'pdf':
        return (_sch_gen_pdf_calendar if use_cal else _sch_gen_pdf)(r, g, sem_labels, ay_label, prog_name_map)
    return None


def _classify_schedule_period(cur, ay_id, sem_type):
    """Classify an import's Academic Year + Semester relative to today.

    Returns None if the semester can't be found, else a dict with:
      period       'historical' (already ended -> archive to historical_data),
                   'current'    (in progress / the active term), or
                   'future'     (not yet started -- e.g. a schedule being
                                 prepared ahead of time for an Upcoming AY)
      sem_id       canonical semesterid to write against (prefers isactive)
      all_sem_ids  every semesterid matching this AY+type (a semester can be
                   re-created, leaving old rows under a stale id)
      sem_start / sem_end / ay_yearstart / ay_is_active

    Single choke point for this decision so schedule_unified_analyze,
    schedule_unified_validate and sis_import_confirm never disagree about
    which bucket a given AY+semester falls into.
    """
    cur.execute("""
        SELECT semesterid, semstartdate, semenddate, isactive
        FROM semester
        WHERE academicyearid = %s AND semestertype = %s
        ORDER BY isactive DESC NULLS LAST, semesterid DESC
    """, (ay_id, sem_type))
    sem_rows = cur.fetchall()
    if not sem_rows:
        return None

    sem_res     = sem_rows[0]
    sem_id      = sem_res['semesterid']
    sem_start   = sem_res['semstartdate']
    sem_end     = sem_res['semenddate']
    all_sem_ids = [r['semesterid'] for r in sem_rows]

    # academicyear.status may not exist yet on a DB that hasn't lazily run
    # this migration via one of the AY-management routes -- ensure it here
    # too so this function never depends on call order elsewhere. Runs in
    # the same transaction as the SELECT below, so no separate commit needed.
    _ensure_ay_status_col(cur)
    cur.execute("SELECT yearstart, isactive, status FROM academicyear WHERE academicyearid = %s", (ay_id,))
    ay_row       = cur.fetchone()
    ay_yearstart = int(ay_row['yearstart']) if ay_row and ay_row['yearstart'] is not None else None
    ay_is_active = bool(ay_row and ay_row['isactive'])
    ay_status    = (ay_row['status'] if ay_row else None) or 'Upcoming'

    from datetime import date as _date_cls
    today = _date_cls.today()

    # "Historical" means this semester has actually ENDED -- not "we're
    # outside its date window" and not "this isn't the flagged-active AY".
    if sem_end is not None:
        is_past = today > sem_end
    else:
        is_past = (ay_status in ('Past', 'Finalized')) or \
                  ((ay_yearstart is not None) and (ay_yearstart < today.year) and not ay_is_active)

    # "Future" means it hasn't STARTED yet -- a schedule being prepared ahead
    # of time. Only checked once we know it isn't already past.
    if is_past:
        is_future = False
    elif sem_start is not None:
        is_future = today < sem_start
    else:
        is_future = (ay_status == 'Upcoming')

    period = 'historical' if is_past else ('future' if is_future else 'current')

    return {
        'period':       period,
        'sem_id':       sem_id,
        'all_sem_ids':  all_sem_ids,
        'sem_start':    sem_start,
        'sem_end':      sem_end,
        'ay_yearstart': ay_yearstart,
        'ay_is_active': ay_is_active,
    }


def _resolve_hist_empnum(cur, inst_name):
    """Resolve an instructor name string to an employee number using DB lookup.
    Returns the employee number string, or None if unresolved/ambiguous."""
    if not inst_name or not inst_name.strip():
        return None
    parts = inst_name.strip().split(',', 1)
    lastname = parts[0].strip()
    firstname_key = parts[1].strip().split()[0].rstrip('.') if len(parts) > 1 and parts[1].strip() else ''
    if not lastname:
        return None
    # Try last name + first name prefix
    if firstname_key:
        cur.execute("""
            SELECT employeenumber FROM faculty
            WHERE UPPER(lastname) = UPPER(%s)
              AND (f.employeestatus IS NULL OR f.employeestatus != 'Archive')
              AND UPPER(firstname) LIKE UPPER(%s) || '%%'
            LIMIT 2
        """.replace('f.', ''), (lastname, firstname_key))
        rows = cur.fetchall()
        if len(rows) == 1:
            return str(rows[0]['employeenumber'])
    # Try last name only
    cur.execute("""
        SELECT employeenumber FROM faculty
        WHERE UPPER(lastname) = UPPER(%s)
          AND (employeestatus IS NULL OR employeestatus != 'Archive')
        LIMIT 2
    """, (lastname,))
    rows = cur.fetchall()
    if len(rows) == 1:
        return str(rows[0]['employeenumber'])
    return None  # ambiguous or not found


def _insert_historical(cur, inst, s_code, subj_name, prog, yl, days_raw, time_raw, room, sem_id, ay_id, lec, lab, unit, hrs, emp_num=None, sectionid=None, course_raw=None):
    """Archive one row to historical_data. Returns True if a row was actually
    inserted, False if an identical row for this semester already exists
    (historical_data has no FK-based identity to dedupe on the way `schedule`
    does via curriculumsubjectid+sectionid+semesterid, so this matches on the
    same flat fields a re-import of the same file — or a repeated semester
    rollover — would reproduce verbatim) — callers should only count/report
    a row as archived when this returns True, so re-running an import never
    piles up duplicate historical rows.

    sectionid/course_raw are optional (added for the Historical Data Import
    feature): sectionid is the resolved FK into `sections`, course_raw is the
    exact original "Course" cell text (e.g. "BEED 1"). Both are included in
    the dedup key so a section-resolved historical import never collides
    with an older, section-less fallback row for the same class."""
    # Guard column-length limits before inserting
    s_code    = (s_code    or '')[:15]
    inst      = (inst      or '')[:150]
    subj_name = (subj_name or '')[:150]
    prog      = (prog      or '')[:20]
    room      = (room      or '')[:100]
    days_raw  = (days_raw  or '')[:50]
    time_raw  = (time_raw  or '')[:100]
    course_raw = (course_raw or '')[:100] or None

    cur.execute("""
        SELECT 1 FROM historical_data
        WHERE semesterid = %s AND "Subject Code" = %s AND "Instructor" = %s
          AND "Program" = %s AND "Year Level" = %s
          AND "Day/s" = %s AND "Time" = %s AND "Room" = %s
          AND sectionid IS NOT DISTINCT FROM %s
        LIMIT 1
    """, (sem_id, s_code, inst, prog, yl, days_raw, time_raw, room, sectionid))
    if cur.fetchone():
        return False

    cur.execute("""
        INSERT INTO historical_data (
            "Instructor", "Subject Code", "Subject Name", "Program", "Year Level",
            "Day/s", "Time", "Room", semesterid, academicyearid,
            "Lecture Hours", "Laboratory Hours", "Credit Units", "Hours",
            employeenumber, sectionid, "Course"
        ) VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
    """, (inst, s_code, subj_name, prog, yl, days_raw, time_raw, room,
          sem_id, ay_id, lec, lab, unit, hrs, emp_num or None, sectionid, course_raw))
    return True


def _resolve_historical_section(cur, course_raw, ay_id, create=False, manual_prog=None, manual_yl=None,
                                sem_type=None):
    """Resolve a historical file's raw "Course" cell (e.g. "BEED 1") to a
    Section, auto-creating the parent program_yearlevel/section when
    create=True and neither exists yet.

    create=False (preview): pure lookup, no writes -- reports what *would*
    happen so the Import Preview can show Existing/New without touching the
    DB before the user confirms.
    create=True (confirm): SAVEPOINT-guarded auto-create on miss, mirroring
    the program_yearlevel/sections chain used for current-schedule import
    (see the "Find or create program_yearlevel"/"Find or create section"
    steps above in sis_import_confirm).

    manual_prog/manual_yl: when the Course text can't be auto-parsed into a
    program+year level (status would be 'unresolved'), the Academic Head
    can pick a Program/Year Level by hand in the Sections resolution panel.
    When both are supplied, they're used verbatim instead of parsing
    `course` -- the raw Course text itself is still preserved by the
    caller regardless (spec: never lose the original text).

    Returns {course, program, yearlevel, section_name, sectionid, status}
    where status is 'existing', 'new', or 'unresolved' (course text didn't
    parse into a program+year level at all -- caller should flag the row,
    not silently drop it).
    """
    import re
    course = re.sub(r'\s+', ' ', (course_raw or '').strip())
    result = {'course': course, 'program': '', 'yearlevel': 0,
              'section_name': course, 'sectionid': None, 'status': 'unresolved'}
    if not course:
        return result

    if manual_prog and manual_yl:
        prog, yl = manual_prog.strip().upper(), int(manual_yl)
    else:
        prog_raw, yl = _course_to_offering_yl(course)
        if not prog_raw:
            prog_raw, yl = _section_to_prog_yl(course)
        if not prog_raw or not yl:
            return result
        prog = _sis_norm_prog(prog_raw) or prog_raw.upper()
    result['program']   = prog
    result['yearlevel'] = yl

    cur.execute("""
        SELECT programyearlevelid FROM program_yearlevel
        WHERE UPPER(programcode) = UPPER(%s) AND academicyearid = %s AND yearlevel = %s
        LIMIT 1
    """, (prog, ay_id, yl))
    pyl_row = cur.fetchone()
    pyl_id  = pyl_row['programyearlevelid'] if pyl_row else None

    if not pyl_id and create:
        cur.execute("SELECT yearstart FROM academicyear WHERE academicyearid = %s", (ay_id,))
        _ayr = cur.fetchone()
        ay_yearstart = int(_ayr['yearstart']) if _ayr and _ayr['yearstart'] is not None else None
        entry_year   = (ay_yearstart - (yl - 1)) if ay_yearstart else None

        # startacademicyear is an FK to academicyear.academicyearid (e.g.
        # "AY2223"), NOT a "YYYY-YYYY" display string -- resolve the actual
        # AY row for the cohort's entry year; fall back to this semester's
        # own AY (guaranteed to exist) when no row goes back that far, which
        # is the common case for a first-time historical import.
        entry_ay_id = ay_id
        if entry_year:
            cur.execute("SELECT academicyearid FROM academicyear WHERE yearstart = %s LIMIT 1", (entry_year,))
            _eayr = cur.fetchone()
            if _eayr: entry_ay_id = _eayr['academicyearid']

        # program_yearlevel.curriculumid is NOT NULL, so it must be supplied
        # even though historical sections never use it for curriculumsubject
        # matching. Reuse the exact same lookup the current-schedule import
        # already does (see the "Resolve entry year and best-matching
        # curriculum" step in sis_import_confirm) so this doesn't invent a
        # new resolution rule, then fall back to auto-creating a minimal
        # curriculum stub only if the program genuinely has none at all.
        curriculum_id = None
        if entry_year:
            cur.execute("""
                SELECT curriculumid FROM curriculum
                WHERE UPPER(programcode)=UPPER(%s) AND curriculumtype = 'REGULAR'
                  AND CAST(SUBSTRING(curriculumyear, 1, 4) AS INT) <= %s
                ORDER BY curriculumyear DESC LIMIT 1
            """, (prog, entry_year))
            _cr = cur.fetchone()
            curriculum_id = _cr['curriculumid'] if _cr else None
        if not curriculum_id:
            cur.execute("""
                SELECT curriculumid FROM curriculum
                WHERE UPPER(programcode)=UPPER(%s) AND curriculumtype = 'REGULAR'
                ORDER BY curriculumyear DESC NULLS LAST LIMIT 1
            """, (prog,))
            _cr2 = cur.fetchone()
            curriculum_id = _cr2['curriculumid'] if _cr2 else None
        if not curriculum_id:
            cur.execute("SELECT curriculumid FROM curriculum WHERE UPPER(programcode)=UPPER(%s) ORDER BY curriculumyear DESC NULLS LAST LIMIT 1", (prog,))
            _cr3 = cur.fetchone()
            curriculum_id = _cr3['curriculumid'] if _cr3 else None
        if not curriculum_id:
            _cy = str(entry_year) if entry_year else str(ay_yearstart or '')
            _cc = f"CY{_cy[-2:]}{(int(_cy) + 1) % 100:02d}" if _cy.isdigit() and len(_cy) == 4 else 'CY0000'
            try:
                cur.execute("SAVEPOINT hist_curr_auto")
                cur.execute("""
                    INSERT INTO curriculum (programcode, curriculumcode, curriculumyear, isactive)
                    VALUES (%s, %s, %s, TRUE)
                    RETURNING curriculumid
                """, (prog.upper(), _cc, _cy))
                _ca = cur.fetchone()
                cur.execute("RELEASE SAVEPOINT hist_curr_auto")
                if _ca: curriculum_id = _ca['curriculumid']
            except Exception:
                cur.execute("ROLLBACK TO SAVEPOINT hist_curr_auto")
                cur.execute("SELECT curriculumid FROM curriculum WHERE UPPER(programcode)=UPPER(%s) ORDER BY curriculumyear DESC NULLS LAST LIMIT 1", (prog,))
                _ca2 = cur.fetchone()
                if _ca2: curriculum_id = _ca2['curriculumid']

        try:
            cur.execute("SAVEPOINT hist_pyl_create")
            cur.execute("""
                INSERT INTO program_yearlevel (programcode, academicyearid, startacademicyear, yearlevel, curriculumid, isactive)
                VALUES (%s, %s, %s, %s, %s, TRUE)
                ON CONFLICT (programcode, academicyearid, startacademicyear, yearlevel)
                DO UPDATE SET isactive = TRUE
                RETURNING programyearlevelid
            """, (prog.upper(), ay_id, entry_ay_id, yl, curriculum_id))
            _pylr2 = cur.fetchone()
            cur.execute("RELEASE SAVEPOINT hist_pyl_create")
            if _pylr2: pyl_id = _pylr2['programyearlevelid']
        except Exception as _pyle:
            cur.execute("ROLLBACK TO SAVEPOINT hist_pyl_create")
            print(f'[_resolve_historical_section] program_yearlevel create failed for {prog!r}/{ay_id!r}/{yl!r}: {_pyle}')
            cur.execute("""
                SELECT programyearlevelid FROM program_yearlevel
                WHERE UPPER(programcode) = UPPER(%s) AND academicyearid = %s AND yearlevel = %s
                LIMIT 1
            """, (prog, ay_id, yl))
            _pylr3 = cur.fetchone()
            if _pylr3: pyl_id = _pylr3['programyearlevelid']

    if not pyl_id:
        # Preview (create=False): program_yearlevel doesn't exist yet, so
        # neither can a section under it -- report "new" (would be created).
        # Confirm (create=True): we just tried and failed -- a real problem.
        result['status'] = 'unresolved' if create else 'new'
        return result

    sec_name = course[:100]
    # 'BSIT1' / 'BSIT 1' / 'BSIT-1' are one section (see _section_name_key).
    sec_row = _find_section_like(cur, pyl_id, sec_name)
    if sec_row:
        result['sectionid']     = sec_row['sectionid']
        result['status']        = 'existing'
        result['section_name']  = sec_row['sectionname']
        if create:
            _mark_section_start_sem(cur, sec_row['sectionid'], sem_type)
        return result

    if not create:
        result['status'] = 'new'
        return result

    try:
        cur.execute("SAVEPOINT hist_sec_create")
        cur.execute("""
            INSERT INTO sections (programyearlevelid, sectionname, isactive, start_semestertype)
            VALUES (%s, %s, TRUE, %s)
            ON CONFLICT (programyearlevelid, sectionname) DO NOTHING
            RETURNING sectionid
        """, (pyl_id, sec_name, _section_start_sem_for(sem_type)))
        _sr2 = cur.fetchone()
        cur.execute("RELEASE SAVEPOINT hist_sec_create")
        if _sr2:
            result['sectionid'] = _sr2['sectionid']
            result['status']    = 'new'
    except Exception as _sece:
        cur.execute("ROLLBACK TO SAVEPOINT hist_sec_create")
        print(f'[_resolve_historical_section] section create failed for {sec_name!r} under pyl={pyl_id}: {_sece}')
        cur.execute("""
            SELECT sectionid FROM sections
            WHERE programyearlevelid = %s AND UPPER(sectionname) = UPPER(%s)
            LIMIT 1
        """, (pyl_id, sec_name))
        _sr3 = cur.fetchone()
        if _sr3:
            result['sectionid'] = _sr3['sectionid']
            result['status']    = 'existing'

    result['section_name'] = sec_name
    return result


@app.route('/academic/schedule/import', methods=['POST'])
def import_schedule():
    if session.get('role') != 'Academic Head': return redirect(url_for('login'))
    file, ay_id, sem_type = request.files.get('file'), request.form.get('ay_id'), request.form.get('semester_type')
    
    # HELPER: Converts empty strings or text to 0 for Integer columns
    def safe_int(val):
        if not val or str(val).strip() == "": return 0
        try:
            # Extract only digits (handles cases like "3 units")
            numeric_part = ''.join(filter(str.isdigit, str(val)))
            return int(numeric_part) if numeric_part else 0
        except: return 0

    DAY_MAP = {
        'M': 'Monday', 'MON': 'Monday',
        'T': 'Tuesday', 'TUE': 'Tuesday', 'TUES': 'Tuesday',
        'W': 'Wednesday', 'WED': 'Wednesday',
        'TH': 'Thursday', 'THU': 'Thursday', 'THUR': 'Thursday', 'THURS': 'Thursday',
        'F': 'Friday', 'FRI': 'Friday',
        'SAT': 'Saturday', 'S': 'Saturday',
        'SUN': 'Sunday',
    }

    def parse_days(days_raw):
        """Handle slash-separated ('M/TH', 'TF/W') and concatenated ('MTH', 'MTHS', 'FSAT') formats."""
        # Longest-first greedy tokenizer; S=Saturday must come after SAT/SUN
        _tokens = ['THURS', 'THUR', 'WED', 'SAT', 'SUN', 'THU', 'TH', 'MON', 'TUES', 'TUE', 'FRI', 'M', 'T', 'W', 'F', 'S']

        def _greedy(s):
            result, s = [], s.upper().strip()
            while s:
                for tok in _tokens:
                    if s.startswith(tok):
                        result.append(tok)
                        s = s[len(tok):]
                        break
                else:
                    s = s[1:]
            return result

        if '/' in days_raw:
            result = []
            for part in days_raw.split('/'):
                part = part.strip()
                if not part:
                    continue
                if part.upper() in DAY_MAP:
                    result.append(part.upper())
                else:
                    # e.g. 'TF' or 'MTHS' inside a slash-list
                    result.extend(_greedy(part))
            return result
        return _greedy(days_raw)

    def parse_time_str(t, force_pm=False):
        """Return HH:MM:SS string from a time token like '07:30', '07:30 AM', '07:30 PM'."""
        import re
        t = t.strip()
        m = re.match(r'(\d{1,2}):(\d{2})\s*(AM|PM)?', t, re.IGNORECASE)
        if not m:
            return None
        h, mi, meridiem = int(m.group(1)), int(m.group(2)), (m.group(3) or '').upper()
        if meridiem == 'PM' and h != 12:
            h += 12
        elif meridiem == 'AM' and h == 12:
            h = 0
        elif not meridiem and force_pm and h != 12:
            h += 12
        elif not meridiem:
            total_mins = h * 60 + mi
            # No AM/PM: anything before school-day start of 07:30 → PM
            if 60 <= total_mins < 7 * 60 + 30:
                h += 12
        return f"{h:02d}:{mi:02d}:00"

    def normalize_room(raw):
        r = raw.strip()
        if not r:
            return 'TBA'
        u = r.upper()
        if u == 'TBA':
            return 'TBA'  # room not yet assigned — must stay bare, never "LQ-TBA"
        if u in ('G', 'GYM', 'PUP GYM'):
            return 'PUP GYM'
        if u in ('Q', 'QUAD', 'LQ-QUAD'):
            return 'LQ-Quad'
        if u.startswith('LQ-'):
            return r  # already formatted
        return f'LQ-{r}'  # everything else gets the prefix

    conn = get_db_connection(); cur = conn.cursor(cursor_factory=RealDictCursor)
    # Ensure schedule_version extra columns exist before any INSERT uses them
    try:
        _ensure_source_col(cur)
        _ensure_original_status_col(cur)
        conn.commit()
    except Exception:
        pass
    try:
        cur.execute("""
            SELECT semesterid, semstartdate, semenddate
            FROM semester
            WHERE academicyearid = %s AND semestertype = %s
        """, (ay_id, sem_type))
        sem_res = cur.fetchone()
        if not sem_res:
            flash("Semester not found. Please check the academic year and semester settings.")
            return redirect(url_for('schedule'))

        sem_id  = sem_res['semesterid']
        sem_end = sem_res['semenddate']
        from datetime import date as _date, timedelta as _td
        today      = _date.today()

        # Determine whether this import belongs to the current (active) semester.
        # A schedule is "current" ONLY if:
        #   1. The selected AY is the active AY in the system (academicyear.isactive = TRUE), AND
        #   2. The specific semester's end date has NOT passed yet
        # Any schedule for a past semester (even in the active AY) goes to historical_data.
        cur.execute("SELECT academicyearid FROM academicyear WHERE isactive = TRUE LIMIT 1")
        _active_ay_row = cur.fetchone()
        _active_ay = _active_ay_row['academicyearid'] if _active_ay_row else None
        is_current = (ay_id == _active_ay) and not (sem_end and sem_end < today)
        print(f"\n[DEBUG IMPORT] ay_id={ay_id!r} sem_type={sem_type!r} sem_id={sem_id!r} sem_end={sem_end} active_ay={_active_ay!r} is_current={is_current}")

        # Pre-compute values used by auto-create logic inside the row loop
        cur.execute("SELECT yearstart FROM academicyear WHERE academicyearid = %s", (ay_id,))
        _ay_info = cur.fetchone()
        _ay_yearstart = _ay_info['yearstart'] if _ay_info else None
        _sem_char = 'B' if ('2' in str(sem_type or '') or str(sem_type or '').upper() == 'B') else \
                    'C' if ('SUM' in str(sem_type or '').upper() or str(sem_type or '').upper() == 'C') else 'A'

        stream = io.StringIO(file.stream.read().decode("UTF8"), newline=None)
        csv_input = csv.DictReader(stream)

        saved_current = 0
        saved_historical = 0
        # Initialised before loop so the except block can always report context.
        prog = ''; yl = 1; s_code = ''

        for row in csv_input:
            row = {k.strip(): v.strip() for k, v in row.items() if k}

            inst       = row.get('Instructor', '')
            s_code     = row.get('SubjectCode') or row.get('Subject Code') or row.get('SubjectCo') or ''
            # Strip trailing year-level number from program (e.g. "BSIT 3" → "BSIT")
            import re as _re_prog
            prog       = _re_prog.sub(r'\s+\d+$', '', row.get('Program', '').strip()).strip()
            # Clamp yl to 1-5 — prevents smallint overflow when CSV has bad data in YearLevel column
            _yl_raw = safe_int(row.get('YearLevel') or row.get('Year Level')) or 0
            yl      = max(1, min(_yl_raw, 5)) if 0 < _yl_raw <= 32767 else 0

            # Fallback: parse program / year level from Course column when
            # dedicated columns are absent — e.g. "BSIT 2", "DCPET 3"
            _course_col = (row.get('Course') or row.get('Section') or row.get('course') or '').strip()
            if (_course_col and (not prog or not yl)):
                _mc_csv = _re_prog.match(
                    r'^([A-Z][A-Z0-9\-]{1,15})\s+([1-5])(?:[^0-9]|$)',
                    _course_col.upper()
                )
                if _mc_csv:
                    if not prog:
                        prog = _mc_csv.group(1)
                    if not yl:
                        yl = int(_mc_csv.group(2))

            yl = yl or 1  # final fallback
            lec        = min(safe_int(row.get('LectureHours') or row.get('Lecture Hours') or row.get('Lec')), 999)
            lab        = min(safe_int(row.get('LaboratoryHours') or row.get('Laboratory Hours') or row.get('Lab')), 999)
            unit       = min(safe_int(row.get('CreditUnits') or row.get('Credit Units') or row.get('Units')), 999)
            hrs        = min(safe_int(row.get('Hours')) or (lec + lab), 999)
            days_raw   = (row.get('Day/s') or row.get('Days') or '').strip()
            time_raw   = (row.get('Time') or '').strip()
            room_raw   = (row.get('Room') or '').strip()
            subj_name  = (row.get('SubjectName') or row.get('Subject Name') or '').strip()

            # Skip completely empty rows (e.g. trailing blank lines in CSV)
            if not inst and not s_code:
                continue

            inserted_as_current = False

            if is_current:
                # --- Resolve FKs needed for the normalized schedule tables ---

                # 1. Faculty by name — match only, never create new records
                emp_num = None
                if inst:
                    parts = inst.split(',', 1)
                    lastname      = parts[0].strip()
                    firstname_key = parts[1].strip().split()[0] if len(parts) > 1 and parts[1].strip() else ''

                    # Pass 1: last name + first word of first name
                    cur.execute("""
                        SELECT employeenumber FROM faculty
                        WHERE UPPER(lastname) = UPPER(%s) AND UPPER(firstname) LIKE UPPER(%s) || '%%'
                        LIMIT 1
                    """, (lastname, firstname_key))
                    r = cur.fetchone()
                    emp_num = r['employeenumber'] if r else None

                    # Pass 2: last name only
                    if not emp_num:
                        cur.execute("""
                            SELECT employeenumber FROM faculty
                            WHERE UPPER(lastname) = UPPER(%s)
                            LIMIT 1
                        """, (lastname,))
                        r = cur.fetchone()
                        emp_num = r['employeenumber'] if r else None
                    # No match → emp_num stays None; row saved to schedule with NULL instructor (TBA)

                # 2. Curriculum subject — try program+subjectcode, fallback to subjectcode only
                cs_id = None
                if s_code and prog:
                    cur.execute("""
                        SELECT cs.curriculumsubjectid
                        FROM curriculumsubject cs
                        JOIN curriculum c ON cs.curriculumid = c.curriculumid
                        WHERE c.programcode = %s AND UPPER(cs.subjectcode) = UPPER(%s)
                        LIMIT 1
                    """, (prog, s_code))
                    r = cur.fetchone()
                    cs_id = r['curriculumsubjectid'] if r else None
                if not cs_id and s_code:
                    cur.execute("""
                        SELECT curriculumsubjectid FROM curriculumsubject
                        WHERE subjectcode = %s LIMIT 1
                    """, (s_code,))
                    r = cur.fetchone()
                    cs_id = r['curriculumsubjectid'] if r else None

                # 3. Section — program_yearlevel join (active, then all, then any year)
                sec_id = None
                if prog and yl:
                    cur.execute("""
                        SELECT sec.sectionid FROM sections sec
                        JOIN program_yearlevel pyl ON sec.programyearlevelid = pyl.programyearlevelid
                        WHERE UPPER(pyl.programcode)=UPPER(%s) AND pyl.yearlevel=%s AND sec.isactive=TRUE
                        ORDER BY sec.sectionname LIMIT 1
                    """, (prog, yl))
                    r = cur.fetchone(); sec_id = r['sectionid'] if r else None
                if not sec_id and prog and yl:
                    cur.execute("""
                        SELECT sec.sectionid FROM sections sec
                        JOIN program_yearlevel pyl ON sec.programyearlevelid = pyl.programyearlevelid
                        WHERE UPPER(pyl.programcode)=UPPER(%s) AND pyl.yearlevel=%s
                        ORDER BY sec.sectionname LIMIT 1
                    """, (prog, yl))
                    r = cur.fetchone(); sec_id = r['sectionid'] if r else None
                if not sec_id and prog:
                    cur.execute("""
                        SELECT sec.sectionid FROM sections sec
                        JOIN program_yearlevel pyl ON sec.programyearlevelid = pyl.programyearlevelid
                        WHERE UPPER(pyl.programcode)=UPPER(%s)
                        ORDER BY pyl.yearlevel, sec.sectionname LIMIT 1
                    """, (prog,))
                    r = cur.fetchone(); sec_id = r['sectionid'] if r else None

                # ── Auto-create missing records so imported data always lands in
                #    the schedule tables (not historical_data) for the current AY ──
                # Only auto-create for current semesters; past semesters go to historical_data
                if is_current and not (cs_id and sec_id) and s_code and prog:
                    # 1. Find best curriculum for this program
                    _best_curr_id = None
                    _entry_year = (_ay_yearstart - (yl - 1)) if _ay_yearstart else None
                    if _entry_year:
                        cur.execute("""
                            SELECT curriculumid FROM curriculum
                            WHERE UPPER(programcode)=UPPER(%s)
                              AND curriculumtype = 'REGULAR'
                              AND CAST(SUBSTRING(curriculumyear, 1, 4) AS INT) <= %s
                            ORDER BY curriculumyear DESC LIMIT 1
                        """, (prog, _entry_year))
                        _cr = cur.fetchone(); _best_curr_id = _cr['curriculumid'] if _cr else None
                    if not _best_curr_id:
                        cur.execute("""
                            SELECT curriculumid FROM curriculum
                            WHERE UPPER(programcode)=UPPER(%s)
                              AND curriculumtype = 'REGULAR'
                            ORDER BY curriculumyear DESC NULLS LAST LIMIT 1
                        """, (prog,))
                        _cr = cur.fetchone(); _best_curr_id = _cr['curriculumid'] if _cr else None
                    if not _best_curr_id:
                        _cy = str(_entry_year) if _entry_year else str(_ay_yearstart or 'IMPORTED')
                        # curriculumcode is VARCHAR(6) — "{prog}-{year}" (e.g.
                        # "BSARCH-2022", 11 chars) silently failed this auto-create
                        # every time (the insert below is inside a savepoint that
                        # swallows its own errors), so use the same CY{yy}{yy} form
                        # the rest of the app uses instead.
                        _cc = f"CY{_cy[-2:]}{(int(_cy) + 1) % 100:02d}" if _cy.isdigit() and len(_cy) == 4 else 'CY0000'
                        try:
                            cur.execute("SAVEPOINT curr_auto")
                            cur.execute("""
                                INSERT INTO curriculum (programcode, curriculumcode, curriculumyear, isactive)
                                VALUES (%s, %s, %s, TRUE) RETURNING curriculumid
                            """, (prog.upper(), _cc, _cy))
                            _ca = cur.fetchone()
                            cur.execute("RELEASE SAVEPOINT curr_auto")
                            if _ca: _best_curr_id = _ca['curriculumid']
                        except Exception:
                            cur.execute("ROLLBACK TO SAVEPOINT curr_auto")
                            cur.execute("SELECT curriculumid FROM curriculum WHERE UPPER(programcode)=UPPER(%s) AND curriculumtype='REGULAR' ORDER BY curriculumyear DESC NULLS LAST LIMIT 1", (prog,))
                            _ca2 = cur.fetchone()
                            if _ca2: _best_curr_id = _ca2['curriculumid']

                    # 2. Find or create program_yearlevel
                    _pyl_id = None
                    _start_ay_str = f"{_entry_year}-{_entry_year+1}" if _entry_year else ''
                    if _start_ay_str:
                        cur.execute("""
                            SELECT programyearlevelid FROM program_yearlevel
                            WHERE UPPER(programcode)=UPPER(%s) AND academicyearid=%s
                              AND startacademicyear=%s AND yearlevel=%s LIMIT 1
                        """, (prog, ay_id, _start_ay_str, yl))
                        _pylr = cur.fetchone(); _pyl_id = _pylr['programyearlevelid'] if _pylr else None
                    if not _pyl_id:
                        cur.execute("""
                            SELECT programyearlevelid FROM program_yearlevel
                            WHERE UPPER(programcode)=UPPER(%s) AND academicyearid=%s AND yearlevel=%s LIMIT 1
                        """, (prog, ay_id, yl))
                        _pylr = cur.fetchone(); _pyl_id = _pylr['programyearlevelid'] if _pylr else None
                    if not _pyl_id:
                        try:
                            cur.execute("SAVEPOINT pyl_create")
                            cur.execute("""
                                INSERT INTO program_yearlevel (programcode, academicyearid, startacademicyear, yearlevel, curriculumid, isactive)
                                VALUES (%s, %s, %s, %s, %s, TRUE)
                                ON CONFLICT (programcode, academicyearid, startacademicyear, yearlevel) DO UPDATE SET curriculumid=EXCLUDED.curriculumid, isactive=TRUE
                                RETURNING programyearlevelid
                            """, (prog.upper(), ay_id, _start_ay_str or '', yl, _best_curr_id))
                            _pylr2 = cur.fetchone()
                            cur.execute("RELEASE SAVEPOINT pyl_create")
                            if _pylr2: _pyl_id = _pylr2['programyearlevelid']
                        except Exception:
                            cur.execute("ROLLBACK TO SAVEPOINT pyl_create")
                            cur.execute("SELECT programyearlevelid FROM program_yearlevel WHERE UPPER(programcode)=UPPER(%s) AND academicyearid=%s AND yearlevel=%s LIMIT 1", (prog, ay_id, yl))
                            _pylr3 = cur.fetchone()
                            if _pylr3: _pyl_id = _pylr3['programyearlevelid']

                    # 3. Find or create section
                    if not sec_id and _pyl_id:
                        # Pass 0: match by course column value (e.g. "BSIT 2", "DCPET 3"),
                        # ignoring spaces/dashes ("BSIT2" = "BSIT-2") — see _section_name_key.
                        if _course_col:
                            _sr = _find_section_like(cur, _pyl_id, _course_col)
                            sec_id = _sr['sectionid'] if _sr else None
                            if sec_id:
                                _mark_section_start_sem(cur, sec_id, sem_type)
                        # Pass 1: any active section under this program_yearlevel
                        if not sec_id:
                            cur.execute("SELECT sectionid FROM sections WHERE programyearlevelid=%s AND isactive=TRUE ORDER BY sectionname LIMIT 1", (_pyl_id,))
                            _sr = cur.fetchone(); sec_id = _sr['sectionid'] if _sr else None
                        if not sec_id:
                            cur.execute("SELECT sectionid FROM sections WHERE programyearlevelid=%s ORDER BY sectionname LIMIT 1", (_pyl_id,))
                            _sr = cur.fetchone(); sec_id = _sr['sectionid'] if _sr else None
                        if not sec_id:
                            # Prefer course column value as the section name; fall back to generic.
                            # A new section starts in THIS import's semester of its academic year.
                            _sec_nm = (_course_col if _course_col else f"{prog.upper()}-{yl}A")[:10]
                            try:
                                cur.execute("SAVEPOINT sec_create")
                                cur.execute("""
                                    INSERT INTO sections (programyearlevelid, sectionname, isactive, start_semestertype)
                                    VALUES (%s, %s, TRUE, %s)
                                    ON CONFLICT (programyearlevelid, sectionname) DO NOTHING
                                    RETURNING sectionid
                                """, (_pyl_id, _sec_nm, _section_start_sem_for(sem_type)))
                                _sr2 = cur.fetchone()
                                cur.execute("RELEASE SAVEPOINT sec_create")
                                if _sr2: sec_id = _sr2['sectionid']
                            except Exception:
                                cur.execute("ROLLBACK TO SAVEPOINT sec_create")
                                cur.execute("SELECT sectionid FROM sections WHERE programyearlevelid=%s AND UPPER(sectionname)=UPPER(%s) LIMIT 1", (_pyl_id, _sec_nm))
                                _sr3 = cur.fetchone()
                                if _sr3: sec_id = _sr3['sectionid']

                    # NOTE: previously this auto-created a curriculumsubject row here when the
                    # imported schedule referenced a code not already in the curriculum — that
                    # silently polluted the curriculum (phantom subjects like ROTC/BIOL 313 that
                    # were never in the actual curriculum file). Schedule import must not add
                    # subjects to the curriculum; leaving cs_id unset here makes the row fall
                    # through to historical_data below instead, which is reported to the admin
                    # as "could not be matched" rather than silently mutating the curriculum.

                # Only insert into current schedule tables for current semesters
                if is_current and cs_id and sec_id:
                    import re as _re2

                    # 4. Skip if already imported for this semester (prevent duplicates on re-import)
                    cur.execute("""
                        SELECT scheduleid FROM schedule
                        WHERE curriculumsubjectid = %s AND sectionid = %s AND semesterid = %s
                        LIMIT 1
                    """, (cs_id, sec_id, sem_id))
                    if cur.fetchone():
                        print(f"[IMPORT DUPLICATE SKIP] subj={s_code!r} prog={prog!r} yl={yl} cs_id={cs_id} sec_id={sec_id}")
                        inserted_as_current = True
                        saved_current += 1
                    else:
                        cur.execute("""
                            INSERT INTO schedule (curriculumsubjectid, sectionid, employeenumber, semesterid)
                            VALUES (%s, %s, %s, %s) RETURNING scheduleid
                        """, (cs_id, sec_id, emp_num, sem_id))
                        sched_id = cur.fetchone()['scheduleid']

                        cur.execute("""
                            INSERT INTO schedule_version (scheduleid, version_number, status, source, original_status)
                            VALUES (%s, 1, 'Published', 'import', 'Published') RETURNING versionid
                        """, (sched_id,))
                        ver_id = cur.fetchone()['versionid']

                        # 5. Parse sessions
                        days_parts  = parse_days(days_raw)
                        # Split on "/" or newlines, then on spaces-between-ranges ("HH:MM-HH:MM HH:MM-HH:MM")
                        _raw_t = [b.strip() for b in _re2.split(r'[/\n]', time_raw) if b.strip()]
                        times_parts = []
                        for _blk in _raw_t:
                            _sub = _re2.split(r'(?<=\d)\s+(?=\d{1,2}:\d{2}\s*-)', _blk)
                            times_parts.extend([s.strip() for s in _sub if s.strip()])
                        rooms_parts = [r.strip() for r in room_raw.split('/') if r.strip()]

                        def _resolve_session(day_abbr, time_seg, room_seg):
                            day_full = DAY_MAP.get(day_abbr.upper(), day_abbr) if day_abbr else None

                            start_str = end_str = None
                            if time_seg and '-' in time_seg:
                                _parts = _re2.split(r'\s*-\s*', time_seg, maxsplit=1)
                                if len(_parts) == 2:
                                    _s_raw, _e_raw = _parts[0].strip(), _parts[1].strip()
                                    _e_merid = _re2.search(r'(AM|PM)\s*$', _e_raw, _re2.IGNORECASE)
                                    _s_merid = _re2.search(r'(AM|PM)', _s_raw, _re2.IGNORECASE)
                                    _force_pm = bool(_e_merid and _e_merid.group(1).upper() == 'PM' and not _s_merid)
                                    start_str = parse_time_str(_s_raw, force_pm=_force_pm)
                                    end_str   = parse_time_str(_e_raw)

                            s_id = e_id = None
                            if start_str:
                                cur.execute("SELECT timeid FROM timeslot WHERE timevalue = %s::time", (start_str,))
                                _r = cur.fetchone(); s_id = _r['timeid'] if _r else None
                            if end_str:
                                cur.execute("SELECT timeid FROM timeslot WHERE timevalue = %s::time", (end_str,))
                                _r = cur.fetchone(); e_id = _r['timeid'] if _r else None
                            # Shift unlabeled PM end time +12h if end <= start
                            if s_id and e_id and e_id <= s_id and end_str:
                                m2 = _re2.match(r'(\d{2}):(\d{2}):00', end_str)
                                if m2:
                                    eh = int(m2.group(1))
                                    if eh < 12:
                                        alt = f"{eh + 12:02d}:{m2.group(2)}:00"
                                        cur.execute("SELECT timeid FROM timeslot WHERE timevalue = %s::time", (alt,))
                                        _r = cur.fetchone()
                                        if _r: e_id = _r['timeid']

                            rm_id = None
                            if room_seg and room_seg.upper() not in ('TBA', ''):
                                norm_room = normalize_room(room_seg)
                                cur.execute("SELECT roomid FROM room WHERE UPPER(roomname) = UPPER(%s)", (norm_room,))
                                _r = cur.fetchone(); rm_id = _r['roomid'] if _r else None
                                if not rm_id and norm_room.upper().startswith('LQ-'):
                                    bare = norm_room[3:]
                                    cur.execute("SELECT roomid FROM room WHERE UPPER(roomname) = UPPER(%s)", (bare,))
                                    _r = cur.fetchone(); rm_id = _r['roomid'] if _r else None
                                if not rm_id:
                                    cur.execute("SELECT roomid FROM room WHERE UPPER(roomname) LIKE '%%' || UPPER(%s) || '%%' LIMIT 1", (room_seg.strip(),))
                                    _r = cur.fetchone(); rm_id = _r['roomid'] if _r else None
                            return day_full, s_id, e_id, rm_id

                        def _slot_hours(time_seg):
                            """Decimal hours for a 'HH:MM-HH:MM' range string."""
                            if not time_seg or '-' not in time_seg:
                                return 0.0
                            ps = _re2.split(r'\s*-\s*', time_seg, maxsplit=1)
                            if len(ps) != 2:
                                return 0.0
                            s = parse_time_str(ps[0].strip())
                            e = parse_time_str(ps[1].strip())
                            if not s or not e:
                                return 0.0
                            def _m(t): return int(t[:2]) * 60 + int(t[3:5])
                            dur = _m(e) - _m(s)
                            if dur <= 0:
                                dur += 720  # 12-hr PM correction
                            return dur / 60.0

                        def _room_for(idx):
                            if not rooms_parts: return ''
                            return rooms_parts[idx] if idx < len(rooms_parts) else rooms_parts[0]

                        n_days, n_times = len(days_parts), len(times_parts)
                        if n_days == 0 or n_times == 0:
                            session_plan = []
                        elif n_days == 1:
                            # All blocks on the single listed day
                            session_plan = [
                                (days_parts[0], times_parts[t], _room_for(t))
                                for t in range(n_times)
                            ]
                        elif hrs <= 0:
                            # Hours unknown: cycle through blocks for all days
                            session_plan = [
                                (days_parts[i], times_parts[i % n_times], _room_for(i % n_times))
                                for i in range(n_days)
                            ]
                        else:
                            _block_h = [_slot_hours(t) for t in times_parts]
                            _sum_h   = sum(_block_h)
                            _hours_if_shared = _sum_h * n_days
                            if _hours_if_shared <= hrs:
                                # Shared: every block applies to every day
                                session_plan = [
                                    (days_parts[d], times_parts[t], _room_for(t))
                                    for d in range(n_days) for t in range(n_times)
                                ]
                            else:
                                # Cycling: one block per day, wrap when more days than blocks
                                session_plan = [
                                    (days_parts[i], times_parts[i % n_times], _room_for(i % n_times))
                                    for i in range(n_days)
                                ]

                        sessions_inserted = 0
                        for day_abbr, time_seg, room_seg in session_plan:
                            day_full, start_id, end_id, room_id = _resolve_session(day_abbr, time_seg, room_seg)
                            if day_full and start_id and end_id:
                                cur.execute("""
                                    INSERT INTO schedule_sessions (versionid, daydesc, starttimeid, endtimeid, roomid)
                                    VALUES (%s, %s, %s, %s, %s)
                                """, (ver_id, day_full, start_id, end_id, room_id))
                                sessions_inserted += 1

                        inserted_as_current = True
                        saved_current += 1

            # Insert to historical_data if: (1) past semester, OR (2) current semester but couldn't insert
            if not is_current or not inserted_as_current:
                # Skip if already inserted as current (prevents duplicates for current semester)
                if not inserted_as_current:
                    norm_hist_room = normalize_room(room_raw) if room_raw.strip() else ''
                    hist_emp_num = _resolve_hist_empnum(cur, inst)
                    if _insert_historical(cur, inst, s_code, subj_name, prog, yl, days_raw, time_raw, norm_hist_room, sem_id, ay_id, lec, lab, unit, hrs, emp_num=hist_emp_num):
                        saved_historical += 1

        conn.commit()
        if is_current:
            msg = f"Import successful! {saved_current} row(s) saved to current schedule."
            if saved_historical:
                msg += f" {saved_historical} row(s) could not be matched and were saved to historical data."
        else:
            msg = f"Import successful! {saved_historical} row(s) saved to historical data (semester is not currently active)."
        flash(msg, 'success')
    except Exception as e:
        conn.rollback()
        _yl_name = {1:'First',2:'Second',3:'Third',4:'Fourth',5:'Fifth'}.get(yl, str(yl))
        _ctx = f"Program: {prog or '(unknown)'}, {_yl_name} Year, Subject: {s_code or '(unknown)'}"
        print(f"Import Error Detail [{_ctx}]: {str(e)}")
        flash(f"Import failed — {_ctx}: {str(e)}")
    finally: cur.close(); conn.close()
    return redirect(url_for('schedule'))


def _parse_sis_excel(file_obj, dedupe=True):
    """Parse a PUP LQ Subject Offerings Excel file.

    dedupe=False preserves every section's row instead of collapsing
    multiple sections of the same subject into one (see _sis_post_process's
    dedupe=False docstring) -- used for Historical Data Import.

    Actual file structure (per program block):
      Row 1       : Title   "SUBJECT OFFERINGS FOR …"
      Row 2       : Yellow  "LOPEZ, QUEZON CAMPUS"  ← campus, skip
      Row 4       : Bold    "BACHELOR OF ELEMENTARY EDUCATION (BEED)"  ← PROGRAM HEADER
      Row 6       : Plain   "FIRST YEAR"            ← year-level marker
      Row 7       : Column  Instructor | Subject Code | Subject Description | …
      Rows 8+     : Data rows

    Program headers are BOLD rows (not necessarily yellow) whose text contains
    known programme keywords or a parenthesised code like (BSIT).
    Yellow rows are typically campus banners or instructor names — both are skipped.
    The Course column (G) holds section identifiers like "BEED 1" or "BSIT-2-A";
    program code and year level are also inferred from there as a fallback.
    """
    import openpyxl, re

    YEAR_MAP   = {'FIRST': 1, 'SECOND': 2, 'THIRD': 3, 'FOURTH': 4, 'FIFTH': 5}
    TOTAL_KW   = ('TOTAL', 'SUB-TOTAL', 'SUBTOTAL', 'GRAND TOTAL')
    HEADER_KW  = ('INSTRUCTOR', 'SUBJ', 'DESCRIPTION', 'LEC', 'LAB',
                  'CREDIT', 'HOURS', 'DAY', 'TIME', 'ROOM')
    SKIP_WORDS = ('DEAR FACULTY', 'YOU ARE HEREBY', 'TENTATIVELY ASSIGNED',
                  'FOLLOWING SUBJECTS', 'SEMESTER,')
    PROG_KW    = ('BACHELOR', 'MASTER', 'DIPLOMA', 'ASSOCIATE', 'DEGREE',
                  'BSIT', 'BSED', 'BSEE', 'BSCE', 'BSAM', 'BSND', 'BSHM',
                  'BSOA', 'BSARCH', 'BSBA', 'BSBIO', 'BSA', 'BSND',
                  'DCET', 'DCVET', 'DEET', 'DOMT', 'DIT',
                  'BPA', 'BEED', 'COLLEGE OF', 'DEPARTMENT OF', 'SCHOOL OF')

    # ── Canonical programme codes: hardcoded base + all active DB programs ───
    _base_valid = frozenset({
        'BEED', 'BPA', 'BPAFA', 'BSARCH', 'BSA', 'BSAM',
        'BSBAFM', 'BSBAMM', 'BSBIO', 'BSCE', 'BSEDMT',
        'BSEE', 'BSHM', 'BSIT', 'BSND', 'BSOA',
        'DCET', 'DCVET', 'DEET', 'DIT', 'DOMT-LOM',
    })
    _db_prog_rows = query_db("SELECT UPPER(programcode) AS programcode FROM programs WHERE isactive = TRUE")
    _db_prog_codes = frozenset(r['programcode'] for r in (_db_prog_rows or []))
    # Build a stripped-code map: strip spaces+hyphens from both file code and DB code
    # so "BSBIO AT", "BSBIO-AT", "BSBIOAT" all resolve to the same DB canonical code.
    _db_stripped_map = {}
    for _c in _db_prog_codes:
        _stripped = re.sub(r'[-\s]', '', _c)
        _db_stripped_map.setdefault(_stripped, _c)
    # VALID_PROGS includes both the exact DB codes and their stripped forms
    VALID_PROGS = _base_valid | _db_prog_codes | frozenset(_db_stripped_map.keys())
    # Add DB program codes to keyword detection so header rows are recognized
    PROG_KW = PROG_KW + tuple(_db_prog_codes)

    # Map every SIS-file variant → the matching canonical code above.
    PROG_NORM = {
        # ── BPA / BPAFA ──────────────────────────────────────────────────────
        'BPA-FA':   'BPAFA',
        'BPAFA':    'BPAFA',
        'BPAPFM':   'BPAFA',    # old erroneous alias
        # ── BSAM ─────────────────────────────────────────────────────────────
        'BSAME':    'BSAM',     # old erroneous alias
        # ── BSBA specializations ─────────────────────────────────────────────
        'BSBA-FM':  'BSBAFM',
        'BSBA FM':  'BSBAFM',
        'BSBAFM':   'BSBAFM',
        'BSBA-MM':  'BSBAMM',
        'BSBA MM':  'BSBAMM',
        'BSBAMM':   'BSBAMM',
        # ── BSED (Mathematics specialisation only at this campus) ─────────────
        'BSED':     'BSEDMT',
        'BSED-MT':  'BSEDMT',
        'BSED MT':  'BSEDMT',
        'BSEDMT':   'BSEDMT',
        # ── BSOA ─────────────────────────────────────────────────────────────
        'BASOA':    'BSOA',     # old erroneous alias
        'BSOA-LOA': 'BSOA',    # old erroneous alias
        'BSOALOA':  'BSOA',    # old erroneous alias
        # ── DCET = Diploma in Computer Engineering Technology ─────────────────
        'DCPET':    'DCET',     # old erroneous alias
        # ── DOMT-LOM (only LOM track at this campus) ─────────────────────────
        'DOMT-LOM': 'DOMT-LOM',
        'DOMT - LOM':'DOMT-LOM',
        'DOMTLOM':  'DOMT-LOM',
        'LOM':      'DOMT-LOM',
        'DOMT':     'DOMT-LOM',
        # Old combined codes that should now resolve to the single LOM track
        'DOMT-MOM':         'DOMT-LOM',
        'DOMT - MOM':       'DOMT-LOM',
        'DOMTMOM':          'DOMT-LOM',
        'MOM':              'DOMT-LOM',
        'DOMT-LOM/DOMT-MOM':'DOMT-LOM',
        'DOMTLOM/DOMTMOM':  'DOMT-LOM',
    }

    def _norm_prog(code):
        if not code: return ''
        normalised = re.sub(r'\s*[-–—]\s*', '-', code.strip()).upper()
        # DB lookup FIRST — exact code takes priority over all hardcoded aliases.
        # This prevents old entries like 'BPAPFM'→'BPAFA' from overriding
        # an actual DB program like 'BPA-PFM'.
        if normalised in _db_prog_codes:
            return normalised
        stripped = re.sub(r'[-\s]', '', normalised)
        if stripped in _db_stripped_map:
            return _db_stripped_map[stripped]
        # Hardcoded aliases (backward-compat for files that use old codes)
        if normalised in PROG_NORM:
            return PROG_NORM[normalised]
        first = normalised.split('/')[0].strip()
        if first and first != normalised and first in PROG_NORM:
            return PROG_NORM[first]
        # Full programme name matching (e.g. "BACHELOR OF SCIENCE IN IT" → "BSIT")
        global_result = _sis_norm_prog(code)
        if global_result:
            return global_result
        return normalised

    def _is_yellow(cell):
        try:
            f = cell.fill
            if f.fill_type != 'solid': return False
            c = f.fgColor
            if c.type == 'rgb' and c.rgb and c.rgb != '00000000':
                rgb = c.rgb[-6:]
                r, g, b = int(rgb[0:2],16), int(rgb[2:4],16), int(rgb[4:6],16)
                return r > 180 and g > 180 and b < 120
        except:
            pass
        return False

    def _is_bold(cell):
        try:
            return bool(cell.font and cell.font.bold)
        except:
            return False

    def _cv(v):
        if v is None: return ''
        if isinstance(v, float) and v == int(v): return str(int(v))
        return str(v).strip()

    def _is_person_name(txt):
        """True when txt looks like  LASTNAME, FIRSTNAME [M.I.]"""
        t = txt.strip()
        if ',' not in t: return False
        before, after = t.split(',', 1)
        if not re.match(r'^[A-Za-z\s\-\.]+$', before.strip()): return False
        return bool(re.search(r'[A-Za-z]', after))

    def _detect_prog_header(vals, row):
        """
        Return (True, prog_name) when the row is a programme header.
        Detects:
          - bold row whose text contains programme keywords, OR
          - parenthesised code pattern  "… (BSIT)"
        Returns (False, '') otherwise.
        """
        non_empty = [v for v in vals if v]
        if not non_empty: return False, ''
        txt = ' '.join(non_empty).strip()
        tu  = txt.upper()

        # Ignore year-level rows
        if any(w + ' YEAR' in tu for w in YEAR_MAP): return False, ''
        # Ignore column header rows
        col_hit = sum(1 for kw in HEADER_KW if kw in tu)
        if col_hit >= 3: return False, ''
        # Ignore TOTAL rows
        if any(kw in tu for kw in TOTAL_KW): return False, ''

        has_prog_kw = any(kw in tu for kw in PROG_KW)
        has_code    = bool(re.search(r'\([A-Z][A-Z0-9\-/]{1,20}\)', tu))
        is_bold_row = _is_bold(row[0])

        if not (has_prog_kw or has_code): return False, ''
        # Ignore rows that look like data (many filled cells) but keep clear programme headers
        # Use a higher threshold to avoid dropping headers that span several merged/unmerged cells
        if len(non_empty) > 8 and not has_code: return False, ''

        # Extract short programme code from parentheses if present (supports DCET/DCPET style)
        m = re.search(r'\(([A-Z][A-Z0-9\-/\s]{1,20})\)', tu)
        if m:
            return True, m.group(1).strip()
        # Short all-caps token at start (e.g. "BSIT – Bachelor…")
        m2 = re.match(r'^([A-Z]{2,10}(?:[- ][A-Z]{1,5})?)\b', tu)
        if m2 and has_prog_kw:
            return True, m2.group(1).strip()
        # Use first non-empty cell as programme name (full name)
        return True, non_empty[0].strip()

    wb = openpyxl.load_workbook(file_obj, data_only=True)
    rows_out = []

    for ws in wb.worksheets:
        # Resolve merged cells
        mc_map = {}
        for rng in ws.merged_cells.ranges:
            top_val = ws.cell(rng.min_row, rng.min_col).value
            for ri in range(rng.min_row, rng.max_row + 1):
                for ci in range(rng.min_col, rng.max_col + 1):
                    mc_map[(ri, ci)] = top_val

        current_prog     = ''
        current_raw_prog = ''   # original code from file before normalization
        current_yl       = 1
        current_yl_label = ''   # full original year-level header text (e.g. "FIRST YEAR – BRIDGE COURSES")
        col_map          = {}

        for row in ws.iter_rows():
            vals        = [_cv(mc_map.get((c.row, c.column), c.value)) for c in row]
            actual_vals = [_cv(c.value) for c in row]   # raw cell values without merged-range propagation
            non_empty   = [v for v in vals if v]
            if not non_empty: continue

            full_upper = ' '.join(non_empty).upper()

            # ── Skip narrative letter-text rows ───────────────────────────
            if any(kw in full_upper for kw in SKIP_WORDS):
                continue

            # ── Signatory / approval section → stop reading this sheet ────
            # Once the signatory block is reached there is no more schedule data.
            if _is_signatory_section(full_upper, len(non_empty)):
                break

            # ── Section marker row (e.g. "Section: BEED1"), as written by our
            # own Class Schedule report export when a Program+Year-Level block
            # holds more than one section — skip it WITHOUT touching
            # current_prog/current_yl/current_yl_label/col_map. Without this,
            # its bold short text would otherwise fall into the "bold
            # programme header" detection below, which fails VALID_PROGS,
            # wipes the current year-level label, and forces every later row
            # in this block to fall back on a section-code guess instead of
            # the year level actually printed above it (harmless only by
            # coincidence when the section name happens to end with the
            # right digit — never for a bridging "FIRST YEAR – BRIDGE
            # COURSES" label, which this reset would silently lose).
            if re.match(r'^SECTION\s*:', full_upper.strip()):
                continue

            # ── 1. Yellow row (campus banner or instructor name) → skip ───
            any_yellow = _is_yellow(row[0]) or any(_is_yellow(c) for c in row[1:4])
            if any_yellow:
                # If it looks like a person's name, it's an instructor header row
                # (instructor-organised SIS).  If it's a programme name, capture it.
                yt = vals[0] or (non_empty[0] if non_empty else '')
                yu = yt.upper()
                is_yr = any(w + ' YEAR' in yu for w in YEAR_MAP)
                if not is_yr:
                    if not _is_person_name(yt):
                        # Could be a genuine programme yellow header
                        ok, code = _detect_prog_header(vals, row)
                        if ok:
                            candidate = _norm_prog(code)
                            if candidate and candidate in VALID_PROGS:
                                # Recognised programme — update both context vars
                                current_raw_prog = code.strip().upper() if code else candidate
                                current_prog     = candidate
                            else:
                                # False positive (e.g. instructor name) — clear context
                                current_raw_prog = ''
                                current_prog     = ''
                            col_map = {}
                continue  # always skip yellow rows as data

            # ── 2. Bold programme header row ──────────────────────────────
            ok, prog_code = _detect_prog_header(vals, row)
            if ok:
                candidate = _norm_prog(prog_code)
                if candidate and candidate in VALID_PROGS:
                    # Known programme — save original file code alongside canonical
                    current_raw_prog = prog_code.strip().upper() if prog_code else candidate
                    current_prog     = candidate
                else:
                    # Unrecognised header (person name, room label, etc.) — clear context
                    current_raw_prog = ''
                    current_prog     = ''
                current_yl       = 1
                current_yl_label = ''
                col_map          = {}
                continue

            # ── 3. Year-level header ──────────────────────────────────────
            yl_found = False
            for w, n in YEAR_MAP.items():
                if w + ' YEAR' in full_upper:
                    current_yl = n
                    # Use actual_vals (no merged-cell propagation) so a merged header row
                    # like "FIRST YEAR" spanning 11 columns doesn't become
                    # "FIRST YEAR FIRST YEAR FIRST YEAR …" repeated 11 times.
                    actual_ne = [v for v in actual_vals if v]
                    raw_lbl = (actual_ne[0] if actual_ne else non_empty[0] if non_empty else '').strip()
                    current_yl_label = ' '.join(raw_lbl.split())  # collapse any internal whitespace
                    yl_found = True; break
            if yl_found:
                continue

            # ── 4. Column header row ──────────────────────────────────────
            upper_vals = [v.upper() for v in vals]
            hdr_score  = sum(1 for kw in HEADER_KW if any(kw in v for v in upper_vals))
            if hdr_score >= 4:
                col_map   = {}
                kw_fields = [
                    ('INSTRUCTOR', 'instructor'), ('SUBJ', 'subj_code'),
                    ('DESCRIPTION', 'subj_name'), ('LEC',  'lec_hrs'),
                    ('LAB',  'lab_hrs'),  ('CREDIT', 'credit_units'),
                    ('COURSE', 'course'), ('HOURS',  'hours'),
                    ('DAY',  'days'),     ('TIME',   'time'), ('ROOM', 'room'),
                ]
                used = set()
                for i, v in enumerate(upper_vals):
                    for kw, fld in kw_fields:
                        if kw in v and fld not in used:
                            col_map[fld] = i; used.add(fld); break
                continue

            # ── 5. Total / summary row ────────────────────────────────────
            if any(kw in full_upper for kw in TOTAL_KW):
                continue

            # ── 6. Data row ───────────────────────────────────────────────
            def gc(fld, di):
                idx = col_map.get(fld, di)
                return vals[idx] if idx < len(vals) else ''

            inst     = gc('instructor',   0)
            s_code   = ' '.join(gc('subj_code', 1).split())   # normalize internal whitespace
            subj_nm  = gc('subj_name',    2)
            lec_raw  = gc('lec_hrs',      3)
            lab_raw  = gc('lab_hrs',      4)
            unit_raw = gc('credit_units', 5)
            course   = gc('course',       6)
            hrs_raw  = gc('hours',        7)
            days_raw = gc('days',         8)
            time_raw = gc('time',         9)
            room_raw = gc('room',         10)

            # Subject code must be present and short (not narrative text)
            if not s_code or len(s_code) > 25:
                continue
            if any(kw in s_code.upper() for kw in SKIP_WORDS):
                continue
            # Reject subject codes that look like signatory labels (names with commas,
            # position titles, etc.) — these are footer rows that slipped past the
            # per-row signatory break because the keyword landed in a non-first cell.
            if _is_signatory_code(s_code):
                continue
            # Skip continuation rows from vertically merged cells:
            # if the subject-code cell has no actual value it inherited its value
            # from a merged cell above and this row is formatting-only.
            s_code_idx = col_map.get('subj_code', 1)
            if s_code_idx < len(actual_vals) and not actual_vals[s_code_idx]:
                continue

            # ── Derive programme & year level ─────────────────────────────
            # Priority 1: explicit bold programme header (current_prog)
            # Priority 2: section code in Course column (must contain a digit)
            prog             = current_prog
            raw_prog_for_row = current_raw_prog   # from header (may be '' if header was invalid)
            yl               = current_yl

            # Extract FULL offering code from COURSE column (e.g. "BSBIO AT" from "BSBIO AT 3")
            course_offering, course_yl = _course_to_offering_yl(course)

            # Offering code: COURSE column takes priority (preserves track suffix like "AT"/"PT")
            offering_code = course_offering if course_offering else (raw_prog_for_row or prog or '')

            # Derive base programme from offering code's first token for VALID_PROGS check
            if not prog and course_offering:
                base_from_course = _norm_prog(course_offering.split()[0])
                if base_from_course in VALID_PROGS:
                    prog             = base_from_course
                    raw_prog_for_row = course_offering  # keep full offering for display

            # A track-suffixed Course value (e.g. "BSBA-MM2", "BSOA-LOA3", "BSBIO-AT3",
            # "DOMT-LOM1") carries more specific programme info than a block's own bold
            # header, which at this campus is often just written as the generic base
            # code ("BSBA", "BSOA", "BSBIO", "DOMT") even though every section under it
            # is really a specific major/track ("BSBAMM"/"BSBAFM", "BSOALOA",
            # "BSBIO-AT"/"BSBIOPT", "DOMTLOM"/"DOMT-MOM") -- each registered as its own
            # programme in Curriculum Management, separate from the base code's own
            # (often empty/unused) curriculum. When the Course column resolves to a
            # different, valid programme than what the header already set, prefer the
            # Course column's -- it's specific to this exact row, whereas the header is
            # only a once-per-block guess.
            if course_offering:
                course_prog = _norm_prog(course_offering)
                if course_prog and course_prog in VALID_PROGS and course_prog != prog:
                    prog             = course_prog
                    raw_prog_for_row = course_offering

            sec_prog, sec_yl = _section_to_prog_yl(course)
            if not prog and sec_prog:
                prog             = sec_prog
                raw_prog_for_row = sec_prog       # program resolved from section code
            # Only fall back to the section-derived year level when no year-level header
            # has been seen yet.  In PUP SIS files the trailing digit in a section code
            # like "BEED 1-A" is the section-group number, not the year level, so
            # unconditionally overriding current_yl would pull subjects from every year
            # block into FIRST YEAR whenever Course starts with "<PROG> 1…".
            if course_yl and not current_yl_label:
                yl = course_yl
            elif sec_yl and not current_yl_label:
                yl = sec_yl

            prog = _norm_prog(prog)   # resolve to canonical programme code

            # Skip rows with no programme or a programme not in the official 21
            if not prog or prog not in VALID_PROGS:
                continue

            # Normalise offering code: fall back to canonical prog if nothing better was found
            if not offering_code:
                offering_code = prog

            rows_out.append({
                'instructor': inst,  'subj_code': s_code,   'subj_name': subj_nm,
                'lec_hrs':  lec_raw, 'lab_hrs':   lab_raw,  'credit_units': unit_raw,
                'course':   course,  'hours':     hrs_raw,  'days': days_raw,
                'time':     time_raw,'room':       room_raw,
                'program':        prog,
                'offering_code':  offering_code.upper().strip(),  # full code e.g. "BSBIO AT"
                'raw_program':    raw_prog_for_row or prog,  # original file code; fallback to canonical
                'year_level':     yl,
                'year_label':     current_yl_label,  # full original header text preserved from Excel
            })

    # ── Deduplicate across sections ───────────────────────────────────────────────
    # The SIS Excel has one data row per SECTION per subject.  E.g. ELED 101 may
    # appear 6 times (BEED 1-A through 1-F).  Collapse to one row per unique
    # subject code within each (program, year-level, year-label) group so the
    # preview shows the same number of subjects as the Excel curriculum list.
    #
    # year_label normalisation:
    #   "" (no header found)      → standard name  e.g. "FIRST YEAR"
    #   "FIRST YEAR"              → "FIRST YEAR"
    #   "FIRST YEAR – BRIDGE …"   → kept as-is (its own separate group)
    _YL_STD = {1:'FIRST YEAR', 2:'SECOND YEAR', 3:'THIRD YEAR', 4:'FOURTH YEAR', 5:'FIFTH YEAR'}

    def _label_key(label, yl):
        # Collapse ALL whitespace variants (tabs, double-spaces, non-breaking spaces)
        # to single ASCII spaces before comparing, so "FIRST  YEAR" == "FIRST YEAR".
        s = ' '.join((label or '').upper().split())
        return s if s else _YL_STD.get(yl, f'{yl} YEAR')

    def _code_key(code):
        return ' '.join((code or '').upper().split())

    if not dedupe:
        # Historical Data Import: keep every section's row distinct (see
        # _sis_post_process's dedupe=False docstring for why) -- still
        # normalise year_label and sort for a stable, grouped preview.
        for r in rows_out:
            r['year_label']     = _label_key(r.get('year_label', ''), r['year_level'])
            r['section_count']  = 1
            r['conflict_notes'] = ''
        rows_out.sort(key=lambda r: (
            r.get('offering_code', r['program']),
            r['year_level'],
            r.get('year_label', '').upper(),
            r['subj_code'].upper(),
        ))
        return rows_out

    from collections import OrderedDict as _OD
    seen = _OD()
    for r in rows_out:
        lk  = _label_key(r.get('year_label', ''), r['year_level'])
        # Use offering_code (not just program) so BSBIO, BSBIO AT, BSBIO PT are separate groups
        key = (r.get('offering_code', r['program']), r['year_level'], lk, _code_key(r['subj_code']))
        if key not in seen:
            r['year_label']     = lk          # store the normalised label
            r['section_count']  = 1
            r['conflict_notes'] = ''
            seen[key] = r

    deduped = list(seen.values())
    deduped.sort(key=lambda r: (
        r.get('offering_code', r['program']),
        r['year_level'],
        r.get('year_label', '').upper(),
        r['subj_code'].upper(),
    ))
    return deduped


@app.route('/academic/schedule/import/sis/preview', methods=['POST'])
def sis_import_preview():
    if session.get('role') != 'Academic Head':
        return jsonify({'error': 'Unauthorized'}), 403

    file     = request.files.get('file')
    ay_id    = request.form.get('ay_id')
    sem_type = request.form.get('semester_type')
    if not file:
        return jsonify({'error': 'No file uploaded'}), 400

    try:
        raw_rows = _parse_sis_excel(file.stream)
    except Exception as e:
        return jsonify({'error': f'Could not parse Excel file: {e}'}), 400

    if not raw_rows:
        return jsonify({'error': 'No data rows found. Ensure the file is in SIS format.'}), 400

    def _si(val):
        if not val: return 0
        try:
            f = float(str(val).strip())
            return int(f) if f == int(f) else f
        except: return 0

    def _nr(raw):
        r = raw.strip()
        if not r: return 'TBA'
        u = r.upper()
        if u == 'TBA': return 'TBA'  # room not yet assigned — must stay bare, never "LQ-TBA"
        if u in ('G', 'GYM', 'PUP GYM'): return 'PUP GYM'
        if u in ('Q', 'QUAD', 'LQ-QUAD'): return 'LQ-Quad'
        if u.startswith('LQ-'): return r
        return f'LQ-{r}'

    conn = get_db_connection(); cur = conn.cursor(cursor_factory=RealDictCursor)
    # Ensure all programs have program_yearlevel rows + default sections before we look them up
    try:
        _auto_setup_program_yearlevels(cur)
        conn.commit()
    except Exception:
        pass

    # Resolve the import AY's yearstart so we can calculate each program_yearlevel's entry year
    ay_yearstart = None
    if ay_id:
        cur.execute("SELECT yearstart FROM academicyear WHERE academicyearid=%s", (ay_id,))
        _ayr = cur.fetchone()
        ay_yearstart = int(_ayr['yearstart']) if _ayr else None

    # Build offering-code normalization map (space ↔ hyphen variants → DB canonical code)
    _db_progs_prev = query_db("SELECT programcode FROM programs WHERE isactive=TRUE") or []
    _prog_norm_prev = {}
    for _pp in _db_progs_prev:
        _cc = _pp['programcode'].upper()
        import re as _re_prev
        for _v in [_cc, _re_prev.sub(r'\s+', '-', _cc), _re_prev.sub(r'-', ' ', _cc), _re_prev.sub(r'[-\s]', '', _cc)]:
            _prog_norm_prev.setdefault(_v, _cc)
        # Also map the suffix after the last hyphen (e.g. "LOM" → "DOMT-LOM")
        if '-' in _cc:
            _prog_norm_prev.setdefault(_cc.rsplit('-', 1)[-1], _cc)

    preview_rows = []
    try:
        for item in raw_rows:
            inst          = item['instructor']
            s_code        = item['subj_code']
            prog          = item['program']
            offering_code = (item.get('offering_code') or prog or '').strip().upper()
            offering_code = _prog_norm_prev.get(offering_code, offering_code)
            yl            = item['year_level']
            room_raw      = item['room']
            flags, status = [], 'ready'

            cs_id = None
            if s_code and offering_code:
                # Strict: subject must exist in this specific offering's own curriculum only
                cur.execute("""
                    SELECT cs.curriculumsubjectid FROM curriculumsubject cs
                    JOIN curriculum c ON cs.curriculumid = c.curriculumid
                    WHERE UPPER(c.programcode)=UPPER(%s) AND UPPER(cs.subjectcode)=UPPER(%s) LIMIT 1
                """, (offering_code, s_code))
                r = cur.fetchone(); cs_id = r['curriculumsubjectid'] if r else None
            if not cs_id:
                status = 'blocked'
                flags.append(f'Subject "{s_code or "—"}" not in {offering_code or "—"} curriculum')

            emp_num = None
            if inst:
                parts = inst.split(',', 1)
                ln = parts[0].strip()
                fn = parts[1].strip().split()[0] if len(parts) > 1 and parts[1].strip() else ''
                if fn:
                    cur.execute("""
                        SELECT employeenumber FROM faculty
                        WHERE UPPER(lastname)=UPPER(%s) AND UPPER(firstname) LIKE UPPER(%s)||'%%' LIMIT 1
                    """, (ln, fn))
                    r = cur.fetchone(); emp_num = r['employeenumber'] if r else None
                if not emp_num:
                    cur.execute("SELECT employeenumber FROM faculty WHERE UPPER(lastname)=UPPER(%s) LIMIT 1", (ln,))
                    r = cur.fetchone(); emp_num = r['employeenumber'] if r else None
            if not emp_num:
                if status != 'blocked': status = 'warning'
                flags.append('Instructor not matched → TBA')

            # ── Resolve entry year and best-matching curriculum ──
            entry_year = (ay_yearstart - (yl - 1)) if ay_yearstart and yl else None
            best_curr_id = None
            if offering_code and entry_year:
                cur.execute("""
                    SELECT curriculumid FROM curriculum
                    WHERE UPPER(programcode)=UPPER(%s)
                      AND curriculumtype = 'REGULAR'
                      AND CAST(SUBSTRING(curriculumyear, 1, 4) AS INT) <= %s
                    ORDER BY curriculumyear DESC LIMIT 1
                """, (offering_code, entry_year))
                _cr = cur.fetchone()
                best_curr_id = _cr['curriculumid'] if _cr else None
            if not best_curr_id and offering_code:
                # Fallback: latest Regular curriculum for this program
                cur.execute("""
                    SELECT curriculumid FROM curriculum
                    WHERE UPPER(programcode)=UPPER(%s)
                      AND curriculumtype = 'REGULAR'
                    ORDER BY curriculumyear DESC NULLS LAST LIMIT 1
                """, (offering_code,))
                _cr = cur.fetchone()
                best_curr_id = _cr['curriculumid'] if _cr else None

            # Resolve entry academicyearid (e.g. AY2023)
            entry_ay_id = None
            if entry_year:
                cur.execute("SELECT academicyearid FROM academicyear WHERE yearstart=%s LIMIT 1", (entry_year,))
                _eayr = cur.fetchone()
                entry_ay_id = _eayr['academicyearid'] if _eayr else f'AY{entry_year}'

            # ── Find section via program_yearlevel ──
            sec_id = None
            if offering_code and ay_id:
                cur.execute("""
                    SELECT sec.sectionid FROM sections sec
                    JOIN program_yearlevel pyl ON sec.programyearlevelid = pyl.programyearlevelid
                    WHERE UPPER(pyl.programcode) = UPPER(%s) AND pyl.yearlevel = %s
                      AND pyl.academicyearid = %s AND sec.isactive = TRUE
                    ORDER BY sec.sectionname LIMIT 1
                """, (offering_code, yl, ay_id))
                _sr = cur.fetchone(); sec_id = _sr['sectionid'] if _sr else None
                if not sec_id:
                    cur.execute("""
                        SELECT sec.sectionid FROM sections sec
                        JOIN program_yearlevel pyl ON sec.programyearlevelid = pyl.programyearlevelid
                        WHERE UPPER(pyl.programcode) = UPPER(%s) AND pyl.yearlevel = %s
                          AND pyl.academicyearid = %s
                        ORDER BY sec.sectionname LIMIT 1
                    """, (offering_code, yl, ay_id))
                    _sr = cur.fetchone(); sec_id = _sr['sectionid'] if _sr else None

            if not sec_id:
                if not best_curr_id:
                    status = 'blocked'
                    flags.append(f'No curriculum found for "{offering_code or "—"}" — cannot import')
                else:
                    if status != 'blocked': status = 'warning'
                    flags.append(f'Cohort/section for "{offering_code or "—"}" Yr {yl} will be auto-created')

            room_display = room_raw or 'TBA'
            if room_raw and room_raw.upper() not in ('TBA', ''):
                norm_r = _nr(room_raw)
                cur.execute("SELECT roomid FROM room WHERE UPPER(roomname)=UPPER(%s)", (norm_r,))
                _rx = cur.fetchone()
                if not _rx and norm_r.upper().startswith('LQ-'):
                    cur.execute("SELECT roomid FROM room WHERE UPPER(roomname)=UPPER(%s)", (norm_r[3:],))
                    _rx = cur.fetchone()
                if not _rx:
                    cur.execute("SELECT roomid FROM room WHERE UPPER(roomname) LIKE '%%'||UPPER(%s)||'%%' LIMIT 1", (room_raw.strip(),))
                    _rx = cur.fetchone()
                if not _rx:
                    if status != 'blocked': status = 'warning'
                    flags.append(f'Room "{room_raw}" not found → TBA')
                    room_display = f'{room_raw} → TBA'

            preview_rows.append({
                **item,
                'lec_hrs': _si(item['lec_hrs']), 'lab_hrs': _si(item['lab_hrs']),
                'credit_units': _si(item['credit_units']), 'hours': _si(item['hours']),
                'status': status, 'flags': '; '.join(flags), 'room_display': room_display,
            })
    finally:
        try: conn.commit()
        except Exception: pass
        cur.close(); conn.close()

    stats = {
        'ready':   sum(1 for rw in preview_rows if rw['status'] == 'ready'),
        'warning': sum(1 for rw in preview_rows if rw['status'] == 'warning'),
        'blocked': sum(1 for rw in preview_rows if rw['status'] == 'blocked'),
        'total':   len(preview_rows),
    }
    return jsonify({'rows': preview_rows, 'stats': stats, 'ay_id': ay_id, 'semester_type': sem_type})


# "TBA" (and its common spellings) in an Instructor column means no instructor
# was assigned -- it is a placeholder, never a real faculty member's name.
# Used to keep it out of every Faculty resolution panel/list built from a
# schedule import (it would otherwise show up asking to be matched or
# "Add[ed] as New Faculty", which makes no sense for a non-name).
_TBA_NAMES = {'TBA', 'T.B.A', 'T.B.A.', 'TO BE ANNOUNCED', 'N/A', 'NA', 'NONE', '-'}


def _confirm_historical_import(cur, data, ay_id, rows, period_info):
    """Historical-period branch of sis_import_confirm: resolves/creates
    Sections and Faculty, then archives every row straight to
    historical_data. No curriculum/schedule/schedule_version involvement --
    historical rows aren't subject to current CSP scheduling constraints
    (see historical-import spec §8-9).

    Unresolved Sections/Faculty are ALLOWED here -- historical_data must
    never be blocked by an unresolved relationship (revised spec §1-2):
    a Course that doesn't resolve keeps sectionid=NULL, an Instructor that
    doesn't resolve (or whose supplied resolution turns out incomplete/
    invalid/duplicate) keeps employeenumber=NULL. Problems with an
    individual faculty resolution are recorded in the returned
    `faculty_issues` list rather than aborting the whole import -- only a
    genuine DB/transaction failure raises and rolls back the batch."""
    import re

    def _si(val):
        if not val or str(val).strip() == '': return 0
        try:
            f = float(str(val).strip())
            return int(f) if f == int(f) else f
        except: return 0

    sem_id      = period_info['sem_id']
    all_sem_ids = period_info['all_sem_ids']
    faculty_resolutions = data.get('faculty_resolutions') or {}
    
    cur.execute("DELETE FROM historical_data WHERE semesterid = ANY(%s)", (all_sem_ids,))
  
    try:
        from scheduler import invalidate_cbr_cache
        invalidate_cbr_cache()
    except Exception:
        pass
    section_resolutions = data.get('section_resolutions') or {}
    section_map = {}
    for row in rows:
        course = (row.get('course') or '').strip()
        if not course or course in section_map:
            continue
        sec_res = section_resolutions.get(course)
        if sec_res and sec_res.get('program') and sec_res.get('yearlevel'):
            section_map[course] = _resolve_historical_section(
                cur, course, ay_id, create=True,
                manual_prog=sec_res['program'], manual_yl=sec_res['yearlevel'],
                sem_type=data.get('semester_type'))
        else:
            # Fall back to the program/year level the parser already resolved
            # for this row (from the sheet's own header rows -- see
            # _parse_sis_excel) before trying to re-derive it from the Course
            # text alone. A Course value like "3LQ" (year digit + campus/
            # branch code, no programme prefix) never parses via
            # _course_to_offering_yl/_section_to_prog_yl, which used to leave
            # it permanently unresolved (sectionid=NULL) even though the
            # row's actual programme was already known and correct.
            _row_prog = (row.get('program') or '').strip()
            _row_yl   = row.get('year_level') or 0
            section_map[course] = _resolve_historical_section(
                cur, course, ay_id, create=True,
                manual_prog=(_row_prog or None), manual_yl=(_row_yl or None),
                sem_type=data.get('semester_type'))
    sections_created =sum(1 for v in section_map.values() if v['status'] == 'new' and v.get('sectionid'))

    # ── Resolve/create Faculty (one per unique Instructor value) ──
    # "TBA" (and equivalent placeholders) means no instructor was assigned in
    # the source file -- it is never a real faculty member's name, so it must
    # never show up in the resolution panel asking to be matched or
    # "Add[ed] as New Faculty". Rows written as TBA already resolve to
    # employeenumber=NULL further down without needing an entry here.
    instructor_names = sorted({
        (row.get('instructor') or '').strip() for row in rows
        if (row.get('instructor') or '').strip() and (row.get('instructor') or '').strip().upper() not in _TBA_NAMES
    })
    faculty_map = resolve_faculty_names(cur, instructor_names) if instructor_names else {}
    empnum_map  = {}
    used_new_empnums = set()
    faculty_created  = 0
    faculty_issues   = []   # informational only -- never blocks the import

    for name in instructor_names:
        info = faculty_map.get(name, {'status': 'new'})
        if info.get('status') == 'matched':
            empnum_map[name] = info.get('employeenumber')
            continue

        # No resolution supplied -- perfectly fine, leave unresolved.
        resolution = faculty_resolutions.get(name)
        empnum_map[name] = None
        if not resolution or not resolution.get('action'):
            continue

        action = resolution.get('action')
        if action == 'existing':
            emp_num = (resolution.get('employeenumber') or '').strip()
            if not emp_num:
                continue
            cur.execute("SELECT employeenumber FROM faculty WHERE employeenumber=%s", (emp_num,))
            if not cur.fetchone():
                faculty_issues.append(f'Selected faculty "{emp_num}" for "{name}" was not found -- left unresolved')
                continue
            empnum_map[name] = emp_num

        elif action == 'new':
            emp_num = (resolution.get('employeenumber') or '').strip()
            fname   = (resolution.get('firstname') or '').strip()
            lname   = (resolution.get('lastname') or '').strip()
            mname   = (resolution.get('middlename') or '').strip() or None
            email   = (resolution.get('email') or '').strip()
            contact = (resolution.get('contact') or '').strip()
            spec_id = resolution.get('specializationid') or None
            type_id = resolution.get('employeetypeid') or None
            status  = (resolution.get('employeestatus') or '').strip()
            desig_id = resolution.get('designationid') or None

            if not (emp_num and fname and lname and email and contact and spec_id and type_id and status):
                faculty_issues.append(f'Incomplete new-faculty details for "{name}" -- left unresolved')
                continue
            if emp_num in used_new_empnums:
                faculty_issues.append(f'Employee number "{emp_num}" reused for more than one new faculty member -- "{name}" left unresolved')
                continue
            cur.execute("SELECT 1 FROM faculty WHERE employeenumber=%s", (emp_num,))
            if cur.fetchone():
                faculty_issues.append(f'Employee number "{emp_num}" already belongs to another faculty member -- "{name}" left unresolved')
                continue

            cur.execute("""
                INSERT INTO Faculty (EmployeeNumber, FirstName, MiddleName, LastName, Email,
                                      ContactNumber, SpecializationID, EmployeeTypeID, DesignationID, EmployeeStatus)
                VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
            """, (emp_num, fname, mname, lname, email, contact, spec_id, type_id, desig_id, status))
            used_new_empnums.add(emp_num)
            faculty_created += 1
            empnum_map[name] = emp_num

    # ── Insert every row into historical_data ──
    saved_historical = 0
    for row in rows:
        inst    = (row.get('instructor') or '').strip()
        s_code  = row.get('subj_code', '')
        subj_nm = row.get('subj_name', '')
        course  = (row.get('course') or '').strip()
        sec_info = section_map.get(course, {})
        prog = sec_info.get('program') or re.sub(r'\s+\d+$', '', (row.get('program') or '').strip()).strip()
        yl   = sec_info.get('yearlevel') or max(1, min(_si(row.get('year_level')) or 1, 5))
        lec  = min(_si(row.get('lec_hrs')), 999)
        lab  = min(_si(row.get('lab_hrs')), 999)
        unit = min(_si(row.get('credit_units')), 999)
        hrs  = min(_si(row.get('hours')) or lec + lab, 999)
        days_raw = str(row.get('days', '') or '').strip()
        time_raw = str(row.get('time', '') or '').strip()
        room_raw = str(row.get('room', '') or '').strip() or 'TBA'
        emp_num  = empnum_map.get(inst)

        if not inst and not s_code:
            continue

        if _insert_historical(cur, inst, s_code, subj_nm, prog, yl, days_raw, time_raw, room_raw,
                               sem_id, ay_id, lec, lab, unit, hrs, emp_num=emp_num,
                               sectionid=sec_info.get('sectionid'), course_raw=course):
            saved_historical += 1

    unresolved_sections = sum(1 for v in section_map.values() if not v.get('sectionid'))
    unresolved_faculty  = sum(1 for emp in empnum_map.values() if not emp)

    msg = f'Historical schedule imported. {saved_historical} record(s) archived to historical data.'
    if sections_created:
        msg += f' {sections_created} section(s) created.'
    if faculty_created:
        msg += f' {faculty_created} faculty record(s) created.'
    if unresolved_sections or unresolved_faculty:
        msg += f' {unresolved_sections} section(s) and {unresolved_faculty} instructor(s) remain unresolved (original Course/Instructor text preserved).'

    return {
        'success':             True,
        'message':             msg,
        'saved_current':       0,
        'saved_historical':    saved_historical,
        'saved_skipped':       0,
        'sections_created':    sections_created,
        'faculty_created':     faculty_created,
        'unresolved_sections': unresolved_sections,
        'unresolved_faculty':  unresolved_faculty,
        'faculty_issues':      faculty_issues,
        'skipped_details':     [],
    }


@app.route('/academic/schedule/import/sis/confirm', methods=['POST'])
def sis_import_confirm():
    if session.get('role') not in ('Academic Head', 'Admin'):
        return jsonify({'error': 'Unauthorized'}), 403

    data = request.get_json()
    if not data:
        return jsonify({'error': 'No data received'}), 400

    ay_id    = data.get('ay_id')
    sem_type = data.get('semester_type')
    rows     = data.get('rows', [])
    override = data.get('override', False)
    if not rows:
        return jsonify({'error': 'No rows to import'}), 400

    import re

    DAY_MAP = {
        'M': 'Monday', 'MON': 'Monday',
        'T': 'Tuesday', 'TUE': 'Tuesday', 'TUES': 'Tuesday',
        'W': 'Wednesday', 'WED': 'Wednesday',
        'TH': 'Thursday', 'THU': 'Thursday', 'THUR': 'Thursday', 'THURS': 'Thursday',
        'F': 'Friday', 'FRI': 'Friday',
        'SAT': 'Saturday', 'S': 'Saturday', 'SUN': 'Sunday',
    }

    def _si(val):
        if not val or str(val).strip() == '': return 0
        try:
            f = float(str(val).strip())
            return int(f) if f == int(f) else f
        except: return 0

    def _pd(days_raw):
        _tk = ['THURS','THUR','WED','SAT','SUN','THU','TH','MON','TUES','TUE','FRI','M','T','W','F','S']
        def _g(s):
            res, s = [], s.upper().strip()
            while s:
                for t in _tk:
                    if s.startswith(t): res.append(t); s = s[len(t):]; break
                else: s = s[1:]
            return res
        if '/' in days_raw:
            out = []
            for p in days_raw.split('/'):
                p = p.strip()
                if not p: continue
                if p.upper() in DAY_MAP: out.append(p.upper())
                else: out.extend(_g(p))
            return out
        return _g(days_raw)

    def _pts(t, force_pm=False):
        t = t.strip()
        m = re.match(r'(\d{1,2}):(\d{2})\s*(AM|PM)?', t, re.IGNORECASE)
        if not m: return None
        h, mi, mer = int(m.group(1)), int(m.group(2)), (m.group(3) or '').upper()
        if mer == 'PM' and h != 12: h += 12
        elif mer == 'AM' and h == 12: h = 0
        elif not mer and force_pm and h != 12: h += 12
        elif not mer:
            if 60 <= h * 60 + mi < 7 * 60 + 30: h += 12
        return f"{h:02d}:{mi:02d}:00"

    def _nr(raw):
        r = raw.strip()
        if not r: return 'TBA'
        u = r.upper()
        if u == 'TBA': return 'TBA'  # room not yet assigned — must stay bare, never "LQ-TBA"
        if u in ('G', 'GYM', 'PUP GYM'): return 'PUP GYM'
        if u in ('Q', 'QUAD', 'LQ-QUAD'): return 'LQ-Quad'
        if u.startswith('LQ-'): return r
        return f'LQ-{r}'

    conn = get_db_connection(); cur = conn.cursor(cursor_factory=RealDictCursor)

    # ── Historical Data Import: classify the period once, up front. A past
    # semester never touches curriculum/schedule/schedule_version at all --
    # it's archived straight to historical_data via Section/Faculty
    # resolution (see _resolve_historical_section / resolve_faculty_names).
    # Current/future periods fall through unchanged to the existing logic
    # below (which already handles both identically).
    try:
        _period_info = _classify_schedule_period(cur, ay_id, sem_type)
    except Exception as _pe:
        conn.rollback(); cur.close(); conn.close()
        return jsonify({'error': f'Could not classify import period: {_pe}'}), 400
    if not _period_info:
        cur.close(); conn.close()
        return jsonify({'error': 'Semester not found'}), 400

    if _period_info['period'] == 'historical':
        try:
            _hist_result = _confirm_historical_import(cur, data, ay_id, rows, _period_info)
            conn.commit()
            return jsonify(_hist_result)
        except Exception as _he:
            conn.rollback()
            return jsonify({'error': str(_he)}), 400
        finally:
            cur.close(); conn.close()

    # Ensure schedule_version extra columns exist before any INSERT uses them
    try:
        _ensure_source_col(cur)
        _ensure_original_status_col(cur)
        conn.commit()
    except Exception:
        pass
    # Ensure all programs have program_yearlevel rows + default sections before we look them up
    try:
        _auto_setup_program_yearlevels(cur)
        conn.commit()
    except Exception:
        pass

    # Build a map from uppercase programcode -> exact DB programcode for normalization
    cur.execute("SELECT programcode FROM programs")
    _prog_norm_map = {r['programcode'].strip().upper(): r['programcode'].strip() for r in cur.fetchall()}

    saved_c = 0; saved_h = 0; created_sec = 0; saved_skip = 0
    # Initialised before loop so the except block can always report context.
    prog = ''; yl = 1; s_code = ''
    _substep = 'setup'  # updated right before each write not covered by its own
                         # savepoint, so an uncaught error names the exact insert

    try:
        # Fetch ALL semester rows for this AY+type — multiple rows can exist if
        # the semester was re-created, causing schedules to accumulate across IDs.
        cur.execute("""
            SELECT semesterid, semstartdate, semenddate, isactive
            FROM semester
            WHERE academicyearid=%s AND semestertype=%s
            ORDER BY isactive DESC NULLS LAST, semesterid DESC
        """, (ay_id, sem_type))
        sem_rows = cur.fetchall()
        if not sem_rows:
            return jsonify({'error': 'Semester not found'}), 400

        # Canonical semesterid for inserting new records: prefer isactive=TRUE, else latest
        sem_res    = sem_rows[0]
        sem_id     = sem_res['semesterid']
        s_dt       = sem_res['semstartdate']
        e_dt       = sem_res['semenddate']
        all_sem_ids = [r['semesterid'] for r in sem_rows]

        # Resolve yearstart + active flag of the import AY
        cur.execute("SELECT yearstart, isactive FROM academicyear WHERE academicyearid=%s", (ay_id,))
        _ayr2 = cur.fetchone()
        ay_yearstart  = int(_ayr2['yearstart']) if _ayr2 else None
        ay_is_active  = bool(_ayr2 and _ayr2['isactive'])
        from datetime import date as _date2
        _today2 = _date2.today()
        # "Current" (→ live schedule/schedule_version tables) means this
        # semester hasn't concluded yet — NOT "we're inside its date window
        # right now" and NOT "this is the system's flagged-active AY". Only a
        # semester that has actually ENDED belongs in historical_data.
        #
        # The previous check required both: today falls between
        # semstartdate/semenddate, AND the academic year is the one currently
        # flagged active. That silently sent every future semester —
        # including a not-yet-started 2nd/3rd term of the very AY that IS
        # active, and any future academic year being prepared in advance
        # (whose semester dates are typically still unset, isactive=FALSE) —
        # into historical_data right alongside genuinely past terms, purely
        # because "not active yet" and "already over" both failed that
        # narrow date-window test.
        if e_dt is not None:
            is_past = _today2 > e_dt
        else:
            # No end date recorded yet (a future AY/semester still being set
            # up). Only treat it as already-over via the academic year's own
            # year-start — a year that hasn't started can't possibly have
            # ended, regardless of the isactive flag.
            is_past = (ay_yearstart is not None) and (ay_yearstart < _today2.year) and not ay_is_active
        is_cur = not is_past

        # Purge stale historical_data for ALL semesterids of this period — this
        # runs for past terms too now (not just current ones): a row that used
        # to fall back to historical_data on an earlier import attempt may now
        # resolve to a real Archive-status section/schedule instead, and a
        # stale historical_data copy left behind would just be a duplicate.
        cur.execute("DELETE FROM historical_data WHERE semesterid = ANY(%s)", (all_sem_ids,))
        print(f"[SIS Confirm] Purged historical_data for semesterids={all_sem_ids}")

        # Override: clear ALL schedule data across every semesterid for this AY+type —
        # refused (and the historical_data purge above rolled back) when request or Local
        # Scheduler history still references those schedules.
        if override:
            cur.execute("SELECT scheduleid FROM schedule WHERE semesterid = ANY(%s)", (all_sem_ids,))
            _ov_blockers = _schedule_delete_blockers(cur, [r['scheduleid'] for r in cur.fetchall()])
            if _ov_blockers:
                conn.rollback()
                return jsonify({'success': False, 'code': 'SCHEDULE_HISTORY_REFERENCED',
                                'error': _schedule_delete_blocked_message(_ov_blockers),
                                'references': _ov_blockers}), 409
            cur.execute("""
                DELETE FROM schedule_sessions
                WHERE versionid IN (
                    SELECT sv.versionid FROM schedule_version sv
                    JOIN schedule s ON sv.scheduleid = s.scheduleid
                    WHERE s.semesterid = ANY(%s)
                )
            """, (all_sem_ids,))
            cur.execute("""
                DELETE FROM schedule_version
                WHERE scheduleid IN (SELECT scheduleid FROM schedule WHERE semesterid = ANY(%s))
            """, (all_sem_ids,))
            cur.execute("DELETE FROM schedule WHERE semesterid = ANY(%s)", (all_sem_ids,))
            print(f"[SIS Override] Cleared existing schedule for semesterids={all_sem_ids}")

        saved_skip = 0; created_sec = 0
        skipped_details = []

        # Build a normalization map so "BSBIO AT" (space) → "BSBIO-AT" (hyphen),
        # "BSBIO-AT" → "BSBIO-AT", etc. — handles all format variants the SIS
        # file produces vs. how programs are actually stored in the DB.
        _db_progs_conf = query_db("SELECT programcode FROM programs WHERE isactive=TRUE") or []
        _prog_norm_map = {}
        for _p in _db_progs_conf:
            _c = _p['programcode'].upper()
            for _variant in [
                _c,
                re.sub(r'\s+', '-', _c),        # spaces → hyphen
                re.sub(r'-', ' ', _c),            # hyphens → space
                re.sub(r'[-\s]', '', _c),         # no separator
            ]:
                _prog_norm_map.setdefault(_variant, _c)
            # Also map the suffix after the last hyphen (e.g. "LOM" → "DOMT-LOM")
            if '-' in _c:
                _prog_norm_map.setdefault(_c.rsplit('-', 1)[-1], _c)
        faculty_resolutions = data.get('faculty_resolutions') or {}
        _resolved_empnum_map = {}
        _new_faculty_created = 0
        _used_new_empnums = set()
        for _name, _res in faculty_resolutions.items():
            _res = _res or {}
            action = _res.get('action')
            if action == 'existing':
                emp_num = (_res.get('employeenumber') or '').strip()
                if emp_num:
                    cur.execute("SELECT employeenumber FROM faculty WHERE employeenumber=%s", (emp_num,))
                    if cur.fetchone():
                        _resolved_empnum_map[_name] = emp_num
            elif action == 'new':
                emp_num  = (_res.get('employeenumber') or '').strip()
                fname    = (_res.get('firstname') or '').strip()
                lname    = (_res.get('lastname') or '').strip()
                mname    = (_res.get('middlename') or '').strip() or None
                email    = (_res.get('email') or '').strip()
                contact  = (_res.get('contact') or '').strip()
                spec_id  = _res.get('specializationid') or None
                type_id  = _res.get('employeetypeid') or None
                estatus  = (_res.get('employeestatus') or '').strip()
                desig_id = _res.get('designationid') or None
                if not (emp_num and fname and lname and email and contact and spec_id and type_id and estatus):
                    continue
                if emp_num in _used_new_empnums:
                    _resolved_empnum_map[_name] = emp_num
                    continue
                cur.execute("SELECT 1 FROM faculty WHERE employeenumber=%s", (emp_num,))
                if cur.fetchone():
                    _resolved_empnum_map[_name] = emp_num
                    continue
                cur.execute("""
                    INSERT INTO Faculty (EmployeeNumber, FirstName, MiddleName, LastName, Email,
                                          ContactNumber, SpecializationID, EmployeeTypeID, DesignationID, EmployeeStatus)
                    VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                """, (emp_num, fname, mname, lname, email, contact, spec_id, type_id, desig_id, estatus))
                _used_new_empnums.add(emp_num)
                _new_faculty_created += 1
                _resolved_empnum_map[_name] = emp_num

        # A row's year-level header (e.g. "FIRST YEAR – BRIDGE COURSES", kept
        # verbatim in year_label by the SIS parser -- see _sis_post_process)
        # marks it as belonging to that program's Bridging curriculum, not
        # the Regular one. Recognizing this up front avoids two separate
        # rounds of manual fixing after import: (1) a Bridging-only subject
        # code (e.g. HRMA 001) has no match in the Regular curriculum, so
        # cs_id below would resolve to None and the row would silently fail
        # to schedule; (2) even for subject codes present in both, the
        # section's Manual Editor view defaults to Regular until someone
        # flips it, which is what section_curriculum_lock (set below) fixes.
        _ensure_curriculum_lock_table(cur)

        # Manual Section resolutions from the Import Preview's Sections panel
        # -- a Program + Year Level the admin picked by hand for a Course
        # value that couldn't be auto-resolved from the row at all (e.g.
        # "2LQBRANCH", "4LQ": year digit + campus/branch code, no programme
        # prefix, and no programme captured elsewhere on that row either).
        # Keyed by the exact Course text, same as Historical's
        # section_resolutions. Available for every period now, not just
        # Historical.
        _section_resolutions = data.get('section_resolutions') or {}

        for row in rows:
            _is_bridging_row = 'BRIDGE' in (row.get('year_label') or '').upper()
            inst          = row.get('instructor', '')
            s_code        = row.get('subj_code', '')
            subj_nm       = row.get('subj_name', '')
            prog          = re.sub(r'\s+\d+$', '', row.get('program', '').strip()).strip()
            _sec_res      = _section_resolutions.get((row.get('course') or '').strip())
            if _sec_res and _sec_res.get('program') and _sec_res.get('yearlevel'):
                prog = _sec_res['program'].strip()
                row  = {**row, 'year_level': _sec_res['yearlevel'], 'offering_code': prog}
            offering_code = (row.get('offering_code') or prog or '').strip().upper()
            # Normalize offering_code to the exact programcode stored in the DB. The
            # variant map above only derives FROM each DB code's own hyphen/space
            # pattern, so it can't help when the DB code has no separator at all
            # (e.g. "BSBAFM", "BSOALOA") but the file's Course-derived text does
            # (e.g. "BSBA-FM", "BSOA-LOA") -- stripping both sides before the second
            # lookup catches that direction too, same as _norm_prog's own stripped
            # DB-code match already does inside the Excel parser.
            offering_code = _prog_norm_map.get(offering_code) \
                or _prog_norm_map.get(re.sub(r'[-\s]', '', offering_code)) \
                or offering_code
            yl            = max(1, min(_si(row.get('year_level')) or 1, 5))
            lec           = min(_si(row.get('lec_hrs')), 999)
            lab           = min(_si(row.get('lab_hrs')), 999)
            unit          = min(_si(row.get('credit_units')), 999)
            hrs           = min(_si(row.get('hours')) or lec + lab, 999)
            days_raw      = str(row.get('days', '') or '').strip()
            time_raw      = str(row.get('time', '') or '').strip()
            room_raw      = str(row.get('room', '') or '').strip()

            if not inst and not s_code: continue
            ins_cur = False

            # Resolve to a real section/schedule row regardless of whether the
            # term is current or past — a past term just lands its
            # schedule_version as 'Archive' instead of 'Published' below, so it
            # shows up as a real (read-only-by-convention) Section in the
            # normal Class Schedule views instead of only in historical_data.
            # historical_data stays as the fallback for whatever a given row
            # still can't be resolved to (see the is_cur branches below).
            if True:
                emp_num = _resolved_empnum_map.get(inst.strip()) if inst else None
                if inst and not emp_num:
                    parts = inst.split(',', 1)
                    ln = parts[0].strip()
                    fn = parts[1].strip().split()[0] if len(parts) > 1 and parts[1].strip() else ''
                    if fn:
                        cur.execute("""
                            SELECT employeenumber FROM faculty
                            WHERE UPPER(lastname)=UPPER(%s) AND UPPER(firstname) LIKE UPPER(%s)||'%%' LIMIT 1
                        """, (ln, fn))
                        r = cur.fetchone(); emp_num = r['employeenumber'] if r else None
                    if not emp_num:
                        cur.execute("SELECT employeenumber FROM faculty WHERE UPPER(lastname)=UPPER(%s) LIMIT 1", (ln,))
                        r = cur.fetchone(); emp_num = r['employeenumber'] if r else None

                # ── Resolve entry year and best-matching curriculum ──
                # A Bridging row (_is_bridging_row) tries the program's
                # WITH_BRIDGING curriculum first -- Bridging-only subject
                # codes (e.g. HRMA 001) don't exist in the Regular curriculum
                # at all, so searching REGULAR-only here would leave cs_id
                # unset below and silently drop the row instead of scheduling
                # it. Falls back to REGULAR if the program has no Bridging
                # curriculum on file, same as a non-Bridging row would use.
                entry_year = (ay_yearstart - (yl - 1)) if ay_yearstart else None
                best_curr_id = None
                _curr_types = ['WITH_BRIDGING', 'REGULAR'] if _is_bridging_row else ['REGULAR']
                if offering_code and entry_year:
                    for _ctype in _curr_types:
                        cur.execute("""
                            SELECT curriculumid FROM curriculum
                            WHERE UPPER(programcode)=UPPER(%s)
                              AND curriculumtype = %s
                              AND CAST(SUBSTRING(curriculumyear, 1, 4) AS INT) <= %s
                            ORDER BY curriculumyear DESC LIMIT 1
                        """, (offering_code, _ctype, entry_year))
                        _cr = cur.fetchone()
                        if _cr: best_curr_id = _cr['curriculumid']; break
                if not best_curr_id and offering_code:
                    for _ctype in _curr_types:
                        cur.execute("""
                            SELECT curriculumid FROM curriculum
                            WHERE UPPER(programcode)=UPPER(%s)
                              AND curriculumtype = %s
                            ORDER BY curriculumyear DESC NULLS LAST LIMIT 1
                        """, (offering_code, _ctype))
                        _cr = cur.fetchone()
                        if _cr: best_curr_id = _cr['curriculumid']; break

                # ── Auto-create a minimal curriculum if still none found ──
                if not best_curr_id and offering_code:
                    _cy = str(entry_year) if entry_year else str(ay_yearstart or '')
                    # curriculumcode is VARCHAR(6) — must stay in the same CY{yy}{yy}
                    # form the rest of the app uses. The old "{prog}-{year}" form here
                    # (e.g. "BSARCH-2022", 11 chars) silently failed this auto-create
                    # every time, making every row for that program/year fall through
                    # as skipped instead of getting a curriculum, since this insert is
                    # inside a savepoint that swallows its own errors below.
                    _cc = f"CY{_cy[-2:]}{(int(_cy) + 1) % 100:02d}" if _cy.isdigit() and len(_cy) == 4 else 'CY0000'
                    _new_ctype = _curr_types[0]
                    try:
                        cur.execute("SAVEPOINT curr_auto")
                        cur.execute("""
                            INSERT INTO curriculum (programcode, curriculumcode, curriculumyear, curriculumtype, isactive)
                            VALUES (%s, %s, %s, %s, TRUE)
                            RETURNING curriculumid
                        """, (offering_code.upper(), _cc, _cy, _new_ctype))
                        _ca = cur.fetchone()
                        cur.execute("RELEASE SAVEPOINT curr_auto")
                        if _ca: best_curr_id = _ca['curriculumid']
                    except Exception:
                        cur.execute("ROLLBACK TO SAVEPOINT curr_auto")
                        cur.execute("""
                            SELECT curriculumid FROM curriculum
                            WHERE UPPER(programcode)=UPPER(%s)
                              AND curriculumtype = %s
                            ORDER BY curriculumyear DESC NULLS LAST LIMIT 1
                        """, (offering_code, _new_ctype))
                        _ca2 = cur.fetchone()
                        if _ca2: best_curr_id = _ca2['curriculumid']

                # Resolve entry academicyearid -- startacademicyear is an FK to
                # academicyear.academicyearid (e.g. "AY2223"), NOT a "YYYY-YYYY"
                # display string. Fall back to this semester's own AY (always
                # a valid FK target) rather than fabricating an "AY{year}"
                # string that may not correspond to any real row.
                entry_ay_id = ay_id
                if entry_year:
                    cur.execute("SELECT academicyearid FROM academicyear WHERE yearstart=%s LIMIT 1",
                                (entry_year,))
                    _eayr = cur.fetchone()
                    if _eayr: entry_ay_id = _eayr['academicyearid']

                # ── Find or create program_yearlevel for this program+entry-year ──
                _pyl_id = None
                if offering_code and ay_id:
                    cur.execute("""
                        SELECT programyearlevelid FROM program_yearlevel
                        WHERE UPPER(programcode)=UPPER(%s) AND academicyearid=%s
                          AND startacademicyear=%s AND yearlevel=%s
                        LIMIT 1
                    """, (offering_code, ay_id, entry_ay_id, yl))
                    _pylr = cur.fetchone()
                    _pyl_id = _pylr['programyearlevelid'] if _pylr else None

                    if not _pyl_id:
                        try:
                            cur.execute("SAVEPOINT pyl_create")
                            cur.execute("""
                                INSERT INTO program_yearlevel
                                    (programcode, academicyearid, startacademicyear, yearlevel, curriculumid, isactive)
                                VALUES (%s, %s, %s, %s, %s, TRUE)
                                ON CONFLICT (programcode, academicyearid, startacademicyear, yearlevel)
                                    DO UPDATE SET curriculumid = EXCLUDED.curriculumid, isactive = TRUE
                                RETURNING programyearlevelid
                            """, (offering_code.upper(), ay_id, entry_ay_id, yl, best_curr_id))
                            _pylr2 = cur.fetchone()
                            cur.execute("RELEASE SAVEPOINT pyl_create")
                            if _pylr2: _pyl_id = _pylr2['programyearlevelid']
                        except Exception as _pyle:
                            cur.execute("ROLLBACK TO SAVEPOINT pyl_create")
                            print(f'[sis_import_confirm] program_yearlevel create failed for {offering_code!r}/{ay_id!r}/{yl!r}: {_pyle}')
                            cur.execute("""
                                SELECT programyearlevelid FROM program_yearlevel
                                WHERE UPPER(programcode)=UPPER(%s) AND academicyearid=%s
                                  AND yearlevel=%s LIMIT 1
                            """, (offering_code, ay_id, yl))
                            _pylr3 = cur.fetchone()
                            if _pylr3: _pyl_id = _pylr3['programyearlevelid']

                # ── cs_id: look up subject in the program_yearlevel's curriculum ──
                cs_id = None
                if s_code and best_curr_id:
                    cur.execute("""
                        SELECT curriculumsubjectid FROM curriculumsubject
                        WHERE curriculumid=%s AND UPPER(subjectcode)=UPPER(%s) LIMIT 1
                    """, (best_curr_id, s_code))
                    r = cur.fetchone(); cs_id = r['curriculumsubjectid'] if r else None
                    if not cs_id:
                        # Fallback: same subject code once hyphens/spaces are ignored on
                        # both sides (e.g. schedule file "ELEC BEED -GEE1" vs curriculum
                        # "ELEC BEED-GEE1") -- a single stray space or hyphen shouldn't
                        # sink an otherwise-genuine match and silently drop the row.
                        cur.execute("""
                            SELECT curriculumsubjectid FROM curriculumsubject
                            WHERE curriculumid=%s
                              AND REGEXP_REPLACE(UPPER(subjectcode), '[-\\s]', '', 'g')
                                = REGEXP_REPLACE(UPPER(%s), '[-\\s]', '', 'g')
                            LIMIT 1
                        """, (best_curr_id, s_code))
                        r = cur.fetchone(); cs_id = r['curriculumsubjectid'] if r else None

                # ── Find or create section under that program_yearlevel ──
                # Section name comes from the SIS Course column (e.g. "BSIT-2-A").
                # Only fall back to a generic name if the course field is empty.
                _course_raw = str(row.get('course', '') or '').strip()
                _sec_nm = (_course_raw if _course_raw else f"{offering_code.upper()}-{yl}A")[:10]

                sec_id = None
                if _pyl_id:
                    # Look for the specific section by name first, ignoring spaces/dashes
                    # ("BSIT1" = "BSIT 1" = "BSIT-1") — see _section_name_key.
                    _sr = _find_section_like(cur, _pyl_id, _sec_nm)
                    sec_id = _sr['sectionid'] if _sr else None

                    if sec_id:
                        _mark_section_start_sem(cur, sec_id, sem_type)
                    if not sec_id:
                        # Section doesn't exist yet — create it from the Course column value,
                        # starting in THIS import's semester of its academic year.
                        try:
                            cur.execute("SAVEPOINT sec_create")
                            cur.execute("""
                                INSERT INTO sections (programyearlevelid, sectionname, isactive, start_semestertype)
                                VALUES (%s, %s, TRUE, %s)
                                ON CONFLICT (programyearlevelid, sectionname) DO NOTHING
                                RETURNING sectionid
                            """, (_pyl_id, _sec_nm, _section_start_sem_for(sem_type)))
                            _sr2 = cur.fetchone()
                            cur.execute("RELEASE SAVEPOINT sec_create")
                            if _sr2: created_sec += 1; sec_id = _sr2['sectionid']
                        except Exception:
                            cur.execute("ROLLBACK TO SAVEPOINT sec_create")
                        if not sec_id:
                            cur.execute("""
                                SELECT sectionid FROM sections
                                WHERE programyearlevelid=%s AND UPPER(sectionname)=UPPER(%s) LIMIT 1
                            """, (_pyl_id, _sec_nm))
                            _sr3 = cur.fetchone()
                            if _sr3: sec_id = _sr3['sectionid']

                # Lock this section+term to the Bridging curriculum so the Manual
                # Editor (and anything else keyed off section_curriculum_lock)
                # shows Bridging subjects immediately -- without this, it would
                # default to Regular until someone flips it by hand for every
                # single Bridging section, which is the "super edit edit" the
                # import is supposed to avoid. DO NOTHING on conflict: a lock
                # already set (e.g. from a confirmed faculty assignment) wins,
                # matching the same first-write-wins rule api_manual_save_assignment
                # uses.
                if sec_id and _is_bridging_row:
                    cur.execute("""
                        INSERT INTO public.section_curriculum_lock (sectionid, semesterid, curriculum_mode)
                        VALUES (%s, %s, 'WITH_BRIDGING')
                        ON CONFLICT (sectionid, semesterid) DO NOTHING
                    """, (sec_id, sem_id))

                # NOTE: previously auto-created a curriculumsubject row here when the SIS
                # schedule data referenced a code not already in the curriculum — that
                # silently polluted the curriculum (phantom subjects that were never in
                # the actual curriculum file). Leaving cs_id unset here makes the row fall
                # through to the skip/historical handling below, which already reports
                # "subject not in curriculum" instead of mutating the curriculum.

                if cs_id and sec_id:
                    cur.execute("""
                        SELECT scheduleid FROM schedule
                        WHERE curriculumsubjectid=%s AND sectionid=%s AND semesterid=%s LIMIT 1
                    """, (cs_id, sec_id, sem_id))
                    if cur.fetchone():
                        ins_cur = True; saved_c += 1
                    else:
                        _substep = 'inserting schedule row'
                        cur.execute("""
                            INSERT INTO schedule (curriculumsubjectid, sectionid, employeenumber, semesterid)
                            VALUES (%s,%s,%s,%s) RETURNING scheduleid
                        """, (cs_id, sec_id, emp_num, sem_id))
                        sched_id = cur.fetchone()['scheduleid']
                        _substep = 'inserting schedule version'
                        _sv_status = 'Published' if is_cur else 'Archive'
                        cur.execute("""
                            INSERT INTO schedule_version (scheduleid, version_number, status, source, original_status)
                            VALUES (%s, 1, %s, 'import', %s) RETURNING versionid
                        """, (sched_id, _sv_status, _sv_status))
                        ver_id = cur.fetchone()['versionid']

                        days_p  = _pd(days_raw) if days_raw else []
                        _rt     = [b.strip() for b in re.split(r'[/\n]', time_raw) if b.strip()] if time_raw else []
                        times_p = []
                        for _b in _rt:
                            _sub = re.split(r'(?<=\d)\s+(?=\d{1,2}:\d{2}\s*-)', _b)
                            times_p.extend([s.strip() for s in _sub if s.strip()])
                        rooms_p = [x.strip() for x in room_raw.split('/') if x.strip()] if room_raw else []

                        def _rs(da, ts, rs):
                            df = DAY_MAP.get(da.upper(), da) if da else None
                            ss2 = es2 = None
                            _sr_raw = _er_raw = ''
                            if ts and '-' in ts:
                                pp = re.split(r'\s*-\s*', ts, maxsplit=1)
                                if len(pp) == 2:
                                    _sr_raw, _er_raw = pp[0].strip(), pp[1].strip()
                                    em = re.search(r'(AM|PM)\s*$', _er_raw, re.IGNORECASE)
                                    sm = re.search(r'(AM|PM)', _sr_raw, re.IGNORECASE)
                                    ss2 = _pts(_sr_raw, force_pm=bool(em and em.group(1).upper()=='PM' and not sm))
                                    es2 = _pts(_er_raw)
                            si2 = ei2 = None
                            if ss2:
                                cur.execute("SELECT timeid FROM timeslot WHERE timevalue=%s::time", (ss2,))
                                _x = cur.fetchone(); si2 = _x['timeid'] if _x else None
                            if es2:
                                cur.execute("SELECT timeid FROM timeslot WHERE timevalue=%s::time", (es2,))
                                _x = cur.fetchone(); ei2 = _x['timeid'] if _x else None
                            # Recovery 1: if end <= start, try adding 12h to end (unmarked PM end)
                            if si2 and ei2 and ei2 <= si2 and es2:
                                m2 = re.match(r'(\d{2}):(\d{2}):00', es2)
                                if m2:
                                    eh2 = int(m2.group(1))
                                    if eh2 < 12:
                                        alt = f"{eh2+12:02d}:{m2.group(2)}:00"
                                        cur.execute("SELECT timeid FROM timeslot WHERE timevalue=%s::time", (alt,))
                                        _x = cur.fetchone()
                                        if _x: ei2 = _x['timeid']
                            # Recovery 2: if still inverted, the force_pm on start was wrong —
                            # retry start WITHOUT force_pm (e.g. "7:00 - 12:00 PM" → 7:00 AM)
                            if si2 and ei2 and ei2 <= si2 and _sr_raw:
                                ss2_retry = _pts(_sr_raw, force_pm=False)
                                if ss2_retry:
                                    cur.execute("SELECT timeid FROM timeslot WHERE timevalue=%s::time", (ss2_retry,))
                                    _x = cur.fetchone()
                                    if _x and _x['timeid'] < ei2:
                                        si2 = _x['timeid']
                            # Final guard: skip session if still inverted (never crash on constraint)
                            if si2 and ei2 and ei2 <= si2:
                                si2 = ei2 = None
                            ri2 = None
                            if rs and rs.upper() not in ('TBA', ''):
                                nr2 = _nr(rs)
                                cur.execute("SELECT roomid FROM room WHERE UPPER(roomname)=UPPER(%s)", (nr2,))
                                _x = cur.fetchone(); ri2 = _x['roomid'] if _x else None
                                if not ri2 and nr2.upper().startswith('LQ-'):
                                    cur.execute("SELECT roomid FROM room WHERE UPPER(roomname)=UPPER(%s)", (nr2[3:],))
                                    _x = cur.fetchone(); ri2 = _x['roomid'] if _x else None
                                if not ri2:
                                    cur.execute("SELECT roomid FROM room WHERE UPPER(roomname) LIKE '%%'||UPPER(%s)||'%%' LIMIT 1", (rs.strip(),))
                                    _x = cur.fetchone(); ri2 = _x['roomid'] if _x else None
                            return df, si2, ei2, ri2

                        def _sh(ts):
                            if not ts or '-' not in ts: return 0.0
                            pp = re.split(r'\s*-\s*', ts, maxsplit=1)
                            if len(pp) != 2: return 0.0
                            s2 = _pts(pp[0].strip()); e2 = _pts(pp[1].strip())
                            if not s2 or not e2: return 0.0
                            def _m(t): return int(t[:2])*60+int(t[3:5])
                            d = _m(e2)-_m(s2); return (d+720 if d<=0 else d)/60.0

                        def _rf(i):
                            if not rooms_p: return ''
                            return rooms_p[i] if i < len(rooms_p) else rooms_p[0]

                        nd, nt = len(days_p), len(times_p)
                        if nd == 0 or nt == 0:
                            sp = []
                        elif nd == 1:
                            sp = [(days_p[0], times_p[t], _rf(t)) for t in range(nt)]
                        elif hrs <= 0:
                            sp = [(days_p[i], times_p[i%nt], _rf(i%nt)) for i in range(nd)]
                        else:
                            bh = [_sh(t) for t in times_p]; sh2 = sum(bh)
                            if sh2 * nd <= hrs:
                                sp = [(days_p[d], times_p[t], _rf(t)) for d in range(nd) for t in range(nt)]
                            else:
                                sp = [(days_p[i], times_p[i%nt], _rf(i%nt)) for i in range(nd)]

                        si_cnt = 0
                        _substep = 'inserting schedule session(s)'
                        for da, ts, rs in sp:
                            df, s_id, e_id, rm_id = _rs(da, ts, rs)
                            if df and s_id and e_id:
                                cur.execute("""
                                    INSERT INTO schedule_sessions (versionid,daydesc,starttimeid,endtimeid,roomid)
                                    VALUES (%s,%s,%s,%s,%s)
                                """, (ver_id, df, s_id, e_id, rm_id))
                                si_cnt += 1

                        if si_cnt == 0 and (days_raw or time_raw) and not is_cur:
                            # Past semester only: no timeslot match → archive to historical
                            _substep = 'archiving unmatched session to historical data'
                            nr3 = _nr(room_raw) if room_raw else ''
                            if _insert_historical(cur, inst, s_code, subj_nm, prog, yl, days_raw, time_raw, nr3, sem_id, ay_id, lec, lab, unit, hrs):
                                saved_h += 1

                        ins_cur = True; saved_c += 1

            if not ins_cur:
                # Build a human-readable reason for the skip -- a row that can't be
                # placed into this AY+semester's real Schedule always shows up as
                # skipped, for a current/future term or a past one alike. This used
                # to silently archive a past-term row to historical_data instead,
                # which reads as "it got saved somewhere" when the admin has no
                # reason to go looking in Historical Data for a schedule they just
                # imported -- effectively indistinguishable from data loss. If a
                # row can't be resolved into the schedule it was imported for, it
                # is reported as skipped and nothing is silently saved instead.
                _reasons = []
                if not best_curr_id:
                    _reasons.append('no curriculum found for program')
                elif not cs_id:
                    _reasons.append('subject not in curriculum')
                if not _pyl_id:
                    _reasons.append('program year level not set up')
                elif not sec_id:
                    _reasons.append('no section found')
                _reason_str = '; '.join(_reasons) if _reasons else 'unresolved'
                print(f"[SIS skip] prog={offering_code!r} subj={s_code!r} yl={yl} reason={_reason_str}")
                saved_skip += 1
                skipped_details.append({
                    'program': offering_code or prog or '—',
                    'subject': s_code or '—',
                    'yearlevel': yl,
                    'reason': _reason_str,
                })

        conn.commit()
        msg = f'{saved_c} row(s) imported to schedule.'
        if created_sec:
            msg += f' {created_sec} new section(s) auto-created.'
        if _new_faculty_created:
            msg += f' {_new_faculty_created} faculty record(s) created.'
        if saved_skip:
            msg += f' {saved_skip} row(s) could not be placed in the schedule and were skipped (see skip reasons below).'
        if saved_h:
            msg += f' {saved_h} row(s) archived to historical data (past semester).'
        return jsonify({'success': True, 'message': msg, 'saved_current': saved_c, 'saved_historical': saved_h, 'saved_skipped': saved_skip, 'faculty_created': _new_faculty_created, 'skipped_details': skipped_details})

    except Exception as e:
        conn.rollback()
        _yl_name = {1:'First',2:'Second',3:'Third',4:'Fourth',5:'Fifth'}.get(yl, str(yl))
        _ctx = f"Program: {prog or '(unknown)'}, {_yl_name} Year, Subject: {s_code or '(unknown)'}, while {_substep}"
        print(f'SIS Import Confirm Error [{_ctx}]: {e}')
        return jsonify({'error': f'{_ctx} — {str(e)}'}), 500
    finally:
        cur.close(); conn.close()


