    file = request.files.get('file')
    if not file or not file.filename.lower().endswith('.xlsx'):
        return jsonify({'error': 'Please upload a valid Excel (.xlsx) file.'}), 400

    idx = {}
    for i in range(11):
        v = request.form.get(f'col_{i}', '').strip()
