@app.route('/api/user/email/update', methods=['POST'])
def api_user_email_update():
    if 'loggedin' not in session: return jsonify({'success': False}), 401
    conn = get_db_connection(); cur = conn.cursor(cursor_factory=RealDictCursor)
    try:
        username = session.get('username')
        email    = request.form.get('email', '').strip()
        if not re.fullmatch(r"[^@\s]+@[^@\s]+\.[^@\s]+", email) or len(email) > 255:
            return jsonify({'success': False, 'error': 'Please enter a valid email address.'}), 400
        cur.execute("SELECT employeenumber FROM accounts WHERE username = %s", (username,))
        acc = cur.fetchone()
        emp_num = acc['employeenumber'] if acc else None
        if emp_num:
            cur.execute("UPDATE faculty SET email = %s WHERE employeenumber = %s", (email, emp_num))
        else:
            # Standalone accounts with no faculty record (the system Admin) keep
            # their own contact email on accounts — never on a faculty row.
            cur.execute("UPDATE accounts SET email = %s WHERE username = %s AND employeenumber IS NULL",
                        (email, username))
        conn.commit()
        return jsonify({'success': True})
    except Exception as e:
        conn.rollback(); return jsonify({'success': False, 'error': str(e)}), 500
    finally: cur.close(); conn.close()

# --- API: Faculty's own published-schedule assignments (for subject/section dropdown) ---
@app.route('/api/faculty/my_assignments')
def api_faculty_my_assignments():
    if 'loggedin' not in session:
        return jsonify({'success': False}), 401
    try:
        emp_num = session.get('employeenumber')
        if not emp_num:
            acc = query_db("SELECT employeenumber FROM accounts WHERE username = %s",
                           [session.get('username')], one=True)
            emp_num = acc['employeenumber'] if acc else None
        if not emp_num:
            return jsonify({'success': False, 'error': 'No employee number'}), 400

        # The faculty's LIVE teaching occurrences: the effective schedule (Published
        # Official minus occurrences overridden by an active Local Published, plus those
        # Local sessions). Pending Drafts are not live. official_sessionid/versionid always
        # identify the Official occurrence, which Schedule Adjustment requests bind to.
        rows = query_db("WITH " + faculty_load.EFFECTIVE_SESSIONS_CTE + """
            SELECT DISTINCT
                cs.subjectcode,
                cs.subjectname,
                es.scheduleid,
                es.versionid,
                es.official_sessionid,
                es.sectionid,
                COALESCE(sec.sectionname, '')                      AS sectionname,
                COALESCE(pyl.programcode, '')                      AS programcode,
                COALESCE(pyl.yearlevel::text, '')                  AS yearlevel,
                COALESCE(es.daydesc, '')                           AS daydesc,
                TO_CHAR(ts_s.timevalue, 'HH12:MI AM')             AS start_time,
                TO_CHAR(ts_e.timevalue, 'HH12:MI AM')             AS end_time,
                COALESCE(r.roomid::text, '')                       AS roomid,
                COALESCE(r.roomname, '')                           AS roomname,
                COALESCE(b.buildingname, '')                       AS buildingname,
                COALESCE(r.roomtype, 'Lecture')                    AS roomtype,
                'Published'::text                                  AS status,
                es.source
            FROM effective_sessions es
            JOIN semester sem         ON es.semesterid            = sem.semesterid
            JOIN curriculumsubject cs ON es.curriculumsubjectid   = cs.curriculumsubjectid
            LEFT JOIN sections sec    ON es.sectionid             = sec.sectionid
            LEFT JOIN program_yearlevel pyl ON sec.programyearlevelid = pyl.programyearlevelid
            LEFT JOIN room r          ON es.roomid                = r.roomid
            LEFT JOIN building b      ON r.buildingid             = b.buildingid
            LEFT JOIN timeslot ts_s   ON es.starttimeid           = ts_s.timeid
            LEFT JOIN timeslot ts_e   ON es.endtimeid             = ts_e.timeid
            WHERE es.employeenumber = %s
              AND sem.isactive = TRUE
            ORDER BY cs.subjectcode, sectionname, daydesc
        """, [str(emp_num)]) or []
        return jsonify({'success': True, 'assignments': [dict(r) for r in rows],
                        '_debug_emp': str(emp_num), '_count': len(rows)})
    except Exception as e:
        return jsonify({'success': False, 'error': str(e), '_debug_emp': str(emp_num) if 'emp_num' in dir() else 'N/A'}), 500

# --- API: Faculty's blocked time slots for a given day (published schedule occupancy) ---
@app.route('/api/faculty/blocked_times')
def api_faculty_blocked_times():
    if 'loggedin' not in session:
        return jsonify({'success': False}), 401
    day        = request.args.get('day', '').strip()
    req_date   = request.args.get('date', '').strip()
    room_id    = request.args.get('room_id', '').strip()
    section_id = request.args.get('section_id', '').strip()
    if req_date and not day:
        try:
            from datetime import date as _date
            day = _date.fromisoformat(req_date).strftime('%A')
        except Exception:
            pass
    if not day:
        return jsonify({'success': True, 'blocked': []})
    try:
        emp_num = session.get('employeenumber')
        if not emp_num:
            acc = query_db("SELECT employeenumber FROM accounts WHERE username = %s",
                           [session.get('username')], one=True)
            emp_num = acc['employeenumber'] if acc else None
        if not emp_num:
            return jsonify({'success': True, 'blocked': []})
        # LIVE occupancy only (effective schedule, active semester): a Local Published move
        # frees its Official occurrence and occupies the new slot; Drafts never block.
        def _live_blocks(where_sql, params):
            rows = query_db("WITH " + faculty_load.EFFECTIVE_SESSIONS_CTE + f"""
                SELECT DISTINCT
                    TO_CHAR(ts_s.timevalue, 'HH12:MI AM') AS start_time,
                    TO_CHAR(ts_e.timevalue, 'HH12:MI AM') AS end_time,
                    ts_s.timevalue                          AS start_raw,
                    ts_e.timevalue                          AS end_raw
                FROM effective_sessions es
                JOIN semester sem   ON es.semesterid  = sem.semesterid AND sem.isactive = TRUE
                JOIN timeslot ts_s  ON es.starttimeid = ts_s.timeid
                JOIN timeslot ts_e  ON es.endtimeid   = ts_e.timeid
                WHERE UPPER(es.daydesc) = UPPER(%s) AND {where_sql}
                ORDER BY ts_s.timevalue
            """, [day] + list(params)) or []
            return [{'start_time': r['start_time'], 'end_time': r['end_time'],
                     'start_raw': str(r['start_raw']), 'end_raw': str(r['end_raw'])}
                    for r in rows]

        blocked = _live_blocks("es.employeenumber = %s", [str(emp_num)])
        # When a specific room is provided, also block times that room is already occupied
        # so the time dropdown grays out those slots before the user selects them.
        if str(room_id).isdigit():
            blocked += _live_blocks("es.roomid = %s", [int(room_id)])
        # When a section is provided, also block times that section already has another class.
        if str(section_id).isdigit():
            blocked += _live_blocks("es.sectionid = %s", [int(section_id)])
        return jsonify({'success': True, 'blocked': blocked})
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500

# --- API: Faculty full schedule (with lec/lab hours) ---
@app.route('/api/faculty/schedule')
def api_faculty_schedule_full():
    if 'loggedin' not in session:
        return jsonify({'success': False}), 401

    ay_id      = request.args.get('ay_id', '').strip()
    semester   = request.args.get('semester', '').strip()
    program    = request.args.get('program', '').strip()
    year_level = request.args.get('year_level', '').strip()
    section_id = request.args.get('section_id', '').strip()
    emp_num    = request.args.get('emp_num', '').strip()

    filters = [
        "sv.status = 'Published'",
        """NOT EXISTS (
            SELECT 1
            FROM public.local_arrangement_sessions las_x
            JOIN public.local_arrangement la_x
              ON las_x.arrangementid = la_x.arrangementid
            WHERE la_x.status = 'Published'
              AND la_x.is_active = TRUE
              AND la_x.semesterid = sc.semesterid
              AND la_x.sectionid = sc.sectionid
              AND las_x.official_sessionid = ss.sessionid
        )"""
    ]
    params  = []

    if ay_id and semester:
        filters.append("""sc.semesterid = (
            SELECT semesterid FROM semester
            WHERE academicyearid = %s AND semestertype = %s LIMIT 1)""")
        params += [ay_id, semester]

    if program:
        filters.append("UPPER(pyl.programcode) = UPPER(%s)")
        params.append(program)

    if year_level:
        try:
            filters.append("pyl.yearlevel = %s")
            params.append(int(year_level))
        except ValueError:
            pass

    if section_id:
        try:
            filters.append("sc.sectionid = %s")
            params.append(int(section_id))
        except ValueError:
            pass

    if emp_num:
        filters.append("sc.employeenumber = %s")
        params.append(emp_num)

    # Require at least one meaningful filter to prevent dumping all programs
    if not any([program, year_level, section_id, emp_num]):
        return jsonify({'success': False, 'error': 'Select at least one filter'}), 400

    try:
        rows = query_db(f"""
            SELECT
                cs.subjectcode, cs.subjectname, cs.creditunits,
                COALESCE(cs.lecturehours,0) AS lecturehours,
                COALESCE(cs.laboratoryhours,0) AS laboratoryhours,
                sec.sectionname, pyl.yearlevel, pyl.programcode,
                ss.daydesc, r.roomname,
                f.lastname || ', ' || f.firstname AS instructor,
                sc.employeenumber,
                TO_CHAR(ts_s.timevalue, 'HH24:MI') AS start_time,
                TO_CHAR(ts_e.timevalue, 'HH24:MI') AS end_time,
                TO_CHAR(ts_s.timevalue, 'HH12:MI AM') || ' - ' ||
                TO_CHAR(ts_e.timevalue, 'HH12:MI AM') AS time_range,
                (COALESCE(cs.lecturehours,0) + COALESCE(cs.laboratoryhours,0)) AS total_hours,
                ss.sessionid AS official_sessionid,
                'Official' AS schedule_source
            FROM schedule_sessions ss
            JOIN schedule_version sv ON ss.versionid = sv.versionid
            JOIN schedule sc ON sv.scheduleid = sc.scheduleid
            JOIN curriculumsubject cs ON sc.curriculumsubjectid = cs.curriculumsubjectid
            LEFT JOIN sections sec ON sc.sectionid = sec.sectionid
            LEFT JOIN program_yearlevel pyl ON sec.programyearlevelid = pyl.programyearlevelid
            LEFT JOIN room r ON ss.roomid = r.roomid
            LEFT JOIN faculty f ON sc.employeenumber = f.employeenumber
            LEFT JOIN timeslot ts_s ON ss.starttimeid = ts_s.timeid
            LEFT JOIN timeslot ts_e ON ss.endtimeid = ts_e.timeid
            WHERE {' AND '.join(filters)}
            ORDER BY ts_s.timevalue, ss.daydesc
        """, params if params else None) or []

        # This is the endpoint consumed by schedule.faculty.js. Merge Local here
        # once; the frontend must not make a second Local request.
        local_filters = ["la.status = 'Published'", "la.is_active = TRUE"]
        local_params = []
        if ay_id and semester:
            local_filters.append("""la.semesterid = (
                SELECT semesterid FROM semester
                WHERE academicyearid = %s AND semestertype = %s LIMIT 1)""")
            local_params += [ay_id, semester]
        if program:
            local_filters.append("UPPER(la.programcode) = UPPER(%s)")
            local_params.append(program)
        if year_level:
            try:
                local_filters.append("la.yearlevel = %s")
                local_params.append(int(year_level))
            except ValueError:
                pass
        if section_id:
            try:
                local_filters.append("la.sectionid = %s")
                local_params.append(int(section_id))
            except ValueError:
                pass
        if emp_num:
            local_filters.append("las.faculty_employeenumber = %s")
            local_params.append(emp_num)

        local_rows = query_db(f"""
            SELECT
                las.subjectcode,
                COALESCE(cs.subjectname, las.subjectcode) AS subjectname,
                COALESCE(cs.creditunits,0) AS creditunits,
                COALESCE(cs.lecturehours,0) AS lecturehours,
                COALESCE(cs.laboratoryhours,0) AS laboratoryhours,
                sec.sectionname, la.yearlevel, la.programcode,
                las.daydesc, r.roomname,
                COALESCE(f.lastname || ', ' || f.firstname, '') AS instructor,
                las.faculty_employeenumber AS employeenumber,
                TO_CHAR(ts_s.timevalue, 'HH24:MI') AS start_time,
                TO_CHAR(ts_e.timevalue, 'HH24:MI') AS end_time,
                TO_CHAR(ts_s.timevalue, 'HH12:MI AM') || ' - ' ||
                TO_CHAR(ts_e.timevalue, 'HH12:MI AM') AS time_range,
                ROUND(EXTRACT(EPOCH FROM (ts_e.timevalue-ts_s.timevalue))/3600.0,2) AS total_hours,
                las.official_sessionid,
                'Local' AS schedule_source
            FROM public.local_arrangement_sessions las
            JOIN public.local_arrangement la ON las.arrangementid=la.arrangementid
            LEFT JOIN public.sections sec ON la.sectionid=sec.sectionid
            LEFT JOIN public.room r ON las.roomid=r.roomid
            LEFT JOIN public.faculty f ON las.faculty_employeenumber=f.employeenumber
            LEFT JOIN public.timeslot ts_s ON las.starttimeid=ts_s.timeid
            LEFT JOIN public.timeslot ts_e ON las.endtimeid=ts_e.timeid
            LEFT JOIN LATERAL (
                SELECT subjectname, creditunits, lecturehours, laboratoryhours
                FROM public.curriculumsubject
                WHERE UPPER(subjectcode)=UPPER(las.subjectcode)
                LIMIT 1
            ) cs ON TRUE
            WHERE {' AND '.join(local_filters)}
        """, local_params if local_params else None) or []

        effective = [dict(r) for r in rows] + [dict(r) for r in local_rows]
        effective.sort(key=lambda r: (str(r.get('start_time') or ''), str(r.get('daydesc') or '')))
        return jsonify({'success': True, 'sessions': effective})
    except Exception as e:
        print(f"[api_faculty_schedule_full] Error: {e}")
        return jsonify({'success': False, 'error': str(e)}), 500

def _save_makeup_request(data, faculty_empno, existing_requestid=None):
    _ensure_request_tables()
    conn = get_db_connection()
    if not conn:
        return jsonify({'success': False, 'error': 'server_error',
                        'message': 'Database connection failed.'}), 500
    cur = conn.cursor(cursor_factory=RealDictCursor)
    try:
        if existing_requestid is None:
            subject = (data.get('subject_code') or '').strip()
            try:
                section_id = int(data.get('section_id'))
            except (TypeError, ValueError):
                section_id = None
            if not subject or not section_id:
                raise _makeup.MakeupError(400, 'validation_error', 'Please select a subject and section.')
            ctx = _makeup.schedule_context_by_subject_section(cur, subject, section_id)
        else:
            cur.execute("""
                SELECT requestid, scheduleid FROM class_meeting_request
                WHERE requestid = %s AND submitted_by = %s AND status = 'Pending'
                FOR UPDATE
            """, [existing_requestid, str(faculty_empno)])
            existing = cur.fetchone()
            if not existing:
                raise _makeup.MakeupError(404, 'not_found', 'Request not found or no longer editable.')
            ctx = _makeup.schedule_context_by_id(cur, existing['scheduleid'])


        vals = _makeup.validate_submission(
            cur, faculty_empno=faculty_empno, ctx=ctx,
            request_date=data.get('request_date'),
            start_time=data.get('start_time'), end_time=data.get('end_time'),
            room_id=data.get('room_id'), reason=data.get('reason'),
            exclude_requestid=existing_requestid)
        notes = (data.get('note') or '').strip() or None


        if existing_requestid is None:
            cur.execute("""
                INSERT INTO class_meeting_request
                    (scheduleid, requested_date, new_starttimeid, new_endtimeid,
                     new_roomid, reason, notes, submitted_by, status)
                VALUES (%s, %s, %s, %s, %s, %s, %s, %s, 'Pending')
                RETURNING requestid
            """, [vals['scheduleid'], vals['requested_date'], vals['starttimeid'],
                  vals['endtimeid'], vals['roomid'], vals['reason'], notes, str(faculty_empno)])
        else:
            cur.execute("""
                UPDATE class_meeting_request
                SET requested_date = %s, new_starttimeid = %s, new_endtimeid = %s,
                    new_roomid = %s, reason = %s
                WHERE requestid = %s AND status = 'Pending'
                RETURNING requestid
            """, [vals['requested_date'], vals['starttimeid'], vals['endtimeid'],
                  vals['roomid'], vals['reason'], existing_requestid])
        saved = cur.fetchone()
        conn.commit()
        return jsonify({'success': True, 'requestid': saved['requestid'], 'status': 'Pending'})
    except _makeup.MakeupError as me:
        conn.rollback()
        return jsonify(me.to_json()), me.status
    except Exception as e:
        conn.rollback()
        print(f"[_save_makeup_request] Error: {e}")
        return jsonify({'success': False, 'error': 'server_error',
                        'message': 'The make-up request could not be saved. Please try again.'}), 500
    finally:
        cur.close()
        conn.close()


# --- API: Submit a faculty room request ---
@app.route('/api/faculty/submit_request', methods=['POST'])
def api_faculty_submit_request():
    if 'loggedin' not in session or session.get('role') != 'Faculty':
        return jsonify({'success': False, 'error': 'Unauthorized'}), 401
    try:
        from datetime import datetime as _dt
        data       = request.json or {}
        req_type   = data.get('request_type', '')   # 'makeup' | 'adjustment'
        room_id    = data.get('room_id')
        section_id = data.get('section_id')
        subject    = data.get('subject_code', '').strip()
        reason     = data.get('reason', '')
        notes      = data.get('note', '')
        start_time = data.get('start_time', '')     # "07:30 AM"
        end_time   = data.get('end_time', '')
        official_sessionid = data.get('official_sessionid')

        # Resolve submitted_by from session; fall back to accounts lookup
        submitted_by = session.get('employeenumber')
        if not submitted_by:
            acc_row = query_db(
                "SELECT employeenumber FROM accounts WHERE username = %s",
                [session.get('username')]
            )
            submitted_by = acc_row[0]['employeenumber'] if acc_row else None
        if not submitted_by:
            return jsonify({'success': False, 'error': 'Could not determine faculty employee number.'}), 400

        # Map "07:30 AM" → timeid in timeslot table
        def _time_to_id(t_str):
            if not t_str:
                return None
            try:
                t = _dt.strptime(t_str.strip(), '%I:%M %p').time()
                row = query_db("SELECT timeid FROM timeslot WHERE timevalue = %s", [t])
                return row[0]['timeid'] if row else None
            except Exception:
                return None

        start_tid = _time_to_id(start_time)
        end_tid   = _time_to_id(end_time)

        if start_tid and end_tid and end_tid <= start_tid:
            return jsonify({'success': False, 'error': 'End Time must be later than Start Time.'}), 400

        # The requested time span must match the subject's required contact hours
        # (lecture + laboratory) — each timeslot step is 30 minutes.
        if subject and start_tid and end_tid:
            subj_hours_row = query_db(
                "SELECT lecturehours, laboratoryhours FROM curriculumsubject WHERE subjectcode = %s LIMIT 1",
                [subject], one=True)
            if subj_hours_row:
                required_hours = float(subj_hours_row.get('lecturehours') or 0) + float(subj_hours_row.get('laboratoryhours') or 0)
                requested_hours = (end_tid - start_tid) * 0.5
                if req_type == 'makeup':
                    # Make-up: 30 minutes up to one regular session (shared rule).
                    from makeup_requests import makeup_duration_error as _mu_rule
                    _mu_err = _mu_rule(requested_hours, required_hours, subject)
                    if _mu_err:
                        return jsonify({'success': False, 'error': _mu_err}), 400
                elif required_hours > 0 and abs(requested_hours - required_hours) > 0.01:
                    return jsonify({'success': False, 'error':
                        f"Selected time span is {requested_hours:g}h, but {subject} requires "
                        f"{required_hours:g}h per session."}), 400

        # Resolve scheduleid (and versionid) from subject code + section
        sched_row = None
        if subject and section_id:
            try:
                sched_row = query_db("""
                    SELECT sc.scheduleid, sv.versionid
                    FROM schedule sc
                    JOIN schedule_version sv ON sc.scheduleid = sv.scheduleid
                    JOIN curriculumsubject cs ON sc.curriculumsubjectid = cs.curriculumsubjectid
                    WHERE cs.subjectcode = %s AND sc.sectionid = %s AND sv.status = 'Published'
                    ORDER BY sv.version_number DESC LIMIT 1
                """, [subject, int(section_id)])
            except Exception:
                sched_row = None

        scheduleid = sched_row[0]['scheduleid'] if sched_row else None
        versionid  = sched_row[0]['versionid']  if sched_row else None
        rid        = int(room_id) if room_id else None

        conn = get_db_connection()
        if not conn:
            return jsonify({'success': False, 'error': 'Database connection failed.'}), 500
        try:
            cur = conn.cursor()
            if req_type == 'makeup':
                req_date = data.get('request_date') or None
                if not scheduleid:
                    return jsonify({'success': False,
                        'error': 'No published schedule found for the given subject and section.'}), 400
                if not start_tid or not end_tid:
                    return jsonify({'success': False, 'error': 'Invalid time selection.'}), 400
                # Block submission if faculty already has a committed schedule at the requested day/time
                if req_date and start_time and end_time:
                    try:
                        _mk_date = _dt.strptime(req_date, '%Y-%m-%d').date()
                        day_of_week = _mk_date.strftime('%A')
                        _mk_start = _dt.strptime(start_time, '%I:%M %p').time()
                        _mk_end   = _dt.strptime(end_time, '%I:%M %p').time()
                        _mk_sem   = _request_semester_id(scheduleid)
                        _mk_req   = _request_requester(scheduleid)
                        # Effective schedule of that date: effective weekly Official
                        # (minus Local-superseded) + other approved make-ups that day.
                        fac_conflict = (
                            _request_official_conflict(_mk_sem, day_of_week, _mk_start, _mk_end,
                                                       employee_number=submitted_by, requester=_mk_req)
                            or _request_makeup_occupancy(_mk_sem, day_of_week, _mk_start, _mk_end,
                                                         on_date=_mk_date, employee_number=submitted_by,
                                                         requester=_mk_req))
                        if fac_conflict:
                            return jsonify({'success': False,
                                'error': f"You already have {fac_conflict['subjectcode']} scheduled on {day_of_week} at this time. Make-up class cannot be submitted when you have an existing commitment."}), 400
                        local_fac_conflict = _request_local_conflict(
                            scheduleid, day_of_week, _mk_start, _mk_end,
                            employee_number=submitted_by, requester=_mk_req
                        )
                        if local_fac_conflict:
                            return jsonify({'success': False,
                                'error': f"You already have a Local Schedule commitment on {day_of_week} at this time. Make-up class cannot be submitted when you have an existing commitment."}), 400
                    except Exception as _ce:
                        print(f"[submit_request conflict check] {_ce}")
                cur.execute("""
                    INSERT INTO class_meeting_request
                        (scheduleid, requested_date, new_starttimeid, new_endtimeid,
                         new_roomid, reason, notes, submitted_by, status)
                    VALUES (%s, %s, %s, %s, %s, %s, %s, %s, 'Pending')
                """, (scheduleid, req_date, start_tid, end_tid, rid, reason, notes, submitted_by))

            elif req_type == 'adjustment':
                day = data.get('day', '') or None
                try:
                    official_sessionid = int(official_sessionid)
                except (TypeError, ValueError):
                    return jsonify({'success': False,
                        'error': 'Please select the exact class meeting to adjust.'}), 400

                if not scheduleid or not versionid:
                    return jsonify({'success': False,
                        'error': 'No published schedule found for the given subject and section.'}), 400

                occurrence = query_db("""
                    SELECT ss.sessionid
                    FROM schedule_sessions ss
                    JOIN schedule_version sv ON ss.versionid = sv.versionid
                    WHERE ss.sessionid = %s
                      AND sv.versionid = %s
                      AND sv.scheduleid = %s
                      AND sv.status = 'Published'
                    LIMIT 1
                """, [official_sessionid, versionid, scheduleid], one=True)
                if not occurrence:
                    return jsonify({'success': False,
                        'error': 'The selected Official meeting is no longer available. Please select it again.'}), 400

                parts = []
                if day:
                    parts.append('Day')
                if start_tid and end_tid:
                    parts.append('Time')
                if rid:
                    parts.append('Room')
                change_type = '+'.join(parts) if parts else 'Day'

                cur.execute("""
                    INSERT INTO schedule_change_request
                        (scheduleid, versionid, official_sessionid, change_type, new_daydesc,
                         new_starttimeid, new_endtimeid, new_roomid,
                         effective_from, reason, submitted_by, status)
                    VALUES (%s, %s, %s, %s, %s, %s, %s, %s,
                            CURRENT_DATE, %s, %s, 'Pending')
                """, (scheduleid, versionid, official_sessionid, change_type, day,
                      start_tid, end_tid, rid, reason, submitted_by))
            else:
                return jsonify({'success': False, 'error': 'Unknown request type.'}), 400

            conn.commit()
        finally:
            conn.close()

        return jsonify({'success': True})
    except Exception as e:
        print(f"[api_faculty_submit_request] Error: {e}")
        return jsonify({'success': False, 'error': str(e)}), 500

# --- API: Available rooms for a given day/time window ---
@app.route('/api/faculty/check_request_conflicts')
def api_faculty_check_request_conflicts():
    """Check room, faculty, and section conflicts at the requested day+time."""
    if 'loggedin' not in session:
        return jsonify({'success': False}), 401
    req_date    = request.args.get('date', '').strip()
    start_time  = request.args.get('start_time', '').strip()
    end_time    = request.args.get('end_time', '').strip()
    section_id  = request.args.get('section_id', '').strip()
    day         = request.args.get('day', '').strip()
    room_id     = request.args.get('room_id', '').strip()
    schedule_id = request.args.get('schedule_id', '').strip()   # exclude own schedule from conflict check
    subject_code = request.args.get('subject_code', '').strip()
    # Make-up vs Schedule Adjustment decides the duration rule below. The make-up form
    # sends a date (adjustments send a weekday), so that is the fallback signal.
    _req_type = request.args.get('request_type', '').strip().lower()
    _is_makeup_check = _req_type == 'makeup' or (not _req_type and bool(req_date) and not day)
    if not (start_time and end_time):
        return jsonify({'success': True,
                        'faculty_conflict': False, 'section_conflict': False, 'room_conflict': False})
    # Derive day-of-week from date if not provided
    if req_date and not day:
        try:
            from datetime import date as _date
            day = _date.fromisoformat(req_date).strftime('%A')
        except Exception:
            pass
    if not day:
        return jsonify({'success': True,
                        'faculty_conflict': False, 'section_conflict': False, 'room_conflict': False})
    try:
        emp_num = session.get('employeenumber')
        if not emp_num:
            acc = query_db("SELECT employeenumber FROM accounts WHERE username=%s", [session.get('username')], one=True)
            emp_num = acc['employeenumber'] if acc else None

        # Derive semesterid from the schedule being changed, so conflict checks only
        # compare sessions within the same Academic Year and Semester.
        sem_id_for_check = None
        if schedule_id and schedule_id.isdigit():
            _sr = query_db("SELECT semesterid FROM schedule WHERE scheduleid = %s LIMIT 1",
                           [int(schedule_id)], one=True)
            if _sr:
                sem_id_for_check = _sr['semesterid']
        if sem_id_for_check is None:
            # Fallback: use the currently-active semester
            _as = query_db("""
                SELECT s.semesterid FROM semester s WHERE s.isactive = TRUE LIMIT 1
            """, one=True)
            if _as:
                sem_id_for_check = _as['semesterid']

        faculty_conflict = False
        section_conflict = False
        room_conflict    = False
        faculty_detail   = ''
        section_detail   = ''
        room_detail      = ''

        # Effective schedule (same primitives as Academic Head validation and
        # approval): Published Official minus Local-superseded occurrences, plus
        # active Published Local, plus approved one-date make-ups on `date`.
        # Draft/Archived Local and Official Drafts are not operational.
        own_sched = int(schedule_id) if schedule_id.isdigit() else None
        requester = _request_requester(own_sched) if own_sched else None
        _st, _en = _parse_time_str(start_time), _parse_time_str(end_time)
        _on_date = None
        if req_date:
            try:
                from datetime import date as _date2
                _on_date = _date2.fromisoformat(req_date)
            except ValueError:
                _on_date = None
        _excl = {'exclude_schedule_id': own_sched} if own_sched else {}

        def _official(**dim):
            return _request_official_conflict(sem_id_for_check, day, _st, _en,
                                              requester=requester, **dim, **_excl)

        def _makeup(**dim):
            if _on_date is None:
                return None
            return _request_makeup_occupancy(sem_id_for_check, day, _st, _en, on_date=_on_date,
                                             requester=requester, **dim, **_excl)

        def _local(**dim):
            return _request_local_conflict(own_sched, day, _st, _en, requester=requester,
                                           semester_id=sem_id_for_check, **dim)

        if emp_num and _st and _en:
            r = _official(employee_number=str(emp_num)) or _makeup(employee_number=str(emp_num))
            if r:
                faculty_conflict = True
                faculty_detail = f"You already have {r['subjectcode']} ({r['start_t']}–{r['end_t']}) on {day}."
            elif _local(employee_number=str(emp_num)):
                faculty_conflict = True
                faculty_detail = f"You have a Local Arrangement on {day} at this time."

        if section_id and section_id.isdigit() and _st and _en:
            r2 = _official(section_id=int(section_id)) or _makeup(section_id=int(section_id))
            if r2:
                section_conflict = True
                section_detail = f"This section already has {r2['subjectcode']} ({r2['start_t']}–{r2['end_t']}) on {day}."
            elif _local(section_id=int(section_id)):
                section_conflict = True
                section_detail = f"This section has a Local Arrangement on {day} at this time."

        if room_id and room_id.isdigit() and _st and _en:
            r3 = _official(room_id=int(room_id)) or _makeup(room_id=int(room_id))
            if r3:
                room_conflict = True
                room_detail = f"The selected room is already occupied by {r3['subjectcode']} ({r3['start_t']}–{r3['end_t']}) on {day}."
            elif _local(room_id=int(room_id)):
                room_conflict = True
                room_detail = f"The selected room has a Local Arrangement on {day} at this time."

        # Schedule Adjustment (weekly): an approved make-up still to come on this weekday
        # doesn't stop the faculty from submitting, but the Academic Head can approve
        # only after that make-up date — tell the faculty up front.
        makeup_notice = ''
        if not _is_makeup_check and day and _st and _en:
            from datetime import date as _date_today
            _dims = []
            if room_id and room_id.isdigit():
                _dims.append(('room', {'room_id': int(room_id)}))
            if emp_num:
                _dims.append(('faculty', {'employee_number': str(emp_num)}))
            if section_id and section_id.isdigit():
                _dims.append(('section', {'section_id': int(section_id)}))
            for _dim, _kw in _dims:
                _mk = _request_makeup_occupancy(sem_id_for_check, day, _st, _en,
                                                from_date=_date_today.today(),
                                                requester=requester, **_kw, **_excl)
                if _mk:
                    makeup_notice = _makeup_wait_message(_mk, _dim, 'This adjustment')
                    break

        # Duration check: the requested time span must match the subject's required
        # contact hours (lecture + laboratory) — flagged the same way as the other
        # conflict types so the UI can show it in the same banner.
        duration_conflict = False
        duration_detail   = ''
        if subject_code:
            try:
                from datetime import datetime as _dt3
                _s = _dt3.strptime(start_time, '%I:%M %p')
                _e = _dt3.strptime(end_time, '%I:%M %p')
                req_hours = (_e - _s).total_seconds() / 3600.0
                subj_row = query_db(
                    "SELECT lecturehours, laboratoryhours FROM curriculumsubject WHERE subjectcode = %s LIMIT 1",
                    [subject_code], one=True)
                if subj_row:
                    required_hours = float(subj_row.get('lecturehours') or 0) + float(subj_row.get('laboratoryhours') or 0)
                    if _is_makeup_check:
                        # Make-up: 30 minutes up to one regular session (shared rule).
                        # (imported by name: this route defines its own local `_makeup` helper)
                        from makeup_requests import makeup_duration_error as _mu_rule
                        _mu_err = _mu_rule(req_hours, required_hours, subject_code)
                        if _mu_err:
                            duration_conflict = True
                            duration_detail = _mu_err
                    elif required_hours > 0 and abs(req_hours - required_hours) > 0.01:
                        duration_conflict = True
                        duration_detail = (
                            f"This time span is {req_hours:g}h, but {subject_code} requires "
                            f"{required_hours:g}h per session."
                        )
            except Exception:
                pass

        return jsonify({
            'success':           True,
            'faculty_conflict':  faculty_conflict,
            'section_conflict':  section_conflict,
            'room_conflict':     room_conflict,
            'duration_conflict': duration_conflict,
            'faculty_detail':    faculty_detail,
            'section_detail':    section_detail,
            'room_detail':       room_detail,
            'duration_detail':   duration_detail,
            'makeup_notice':     makeup_notice,
        })
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/faculty/available_rooms')
def api_faculty_available_rooms():
    if 'loggedin' not in session:
        return jsonify({'success': False}), 401

    day         = request.args.get('day',         '').strip()
    start_time  = request.args.get('start_time',  '').strip()
    end_time    = request.args.get('end_time',    '').strip()
    room_type   = request.args.get('room_type',   '').strip()
    building_id = request.args.get('building_id', '').strip()
    # Optional: specific date — when provided, also checks approved makeup classes
    req_date    = request.args.get('date',        '').strip()
    # If date provided and day not, derive day-of-week from date
    if req_date and not day:
        try:
            from datetime import date as _date
            _d = _date.fromisoformat(req_date)
            day = _d.strftime('%A')
        except Exception:
            pass

    try:
        room_sql    = """
            SELECT r.roomid, r.roomname, r.roomtype, r.roomcapacity,
                   b.buildingid, b.buildingname
            FROM room r JOIN building b ON r.buildingid = b.buildingid
            WHERE b.isactive = TRUE
        """
        room_params = []
        if room_type:
            room_sql += " AND LOWER(r.roomtype) = LOWER(%s)"
            room_params.append(room_type)
        if building_id:
            try:
                room_sql += " AND b.buildingid = %s"
                room_params.append(int(building_id))
            except ValueError:
                pass
        room_sql += " ORDER BY b.buildingname, r.roomname"

        all_rooms = query_db(room_sql, room_params if room_params else None) or []

        if not (day and start_time and end_time):
            return jsonify({'success': True, 'rooms': [
                {**dict(r), 'available': True} for r in all_rooms
            ]})

        # PHASE 6.1 — effective Official occupancy. An Official occurrence is
        # free only when that exact schedule_session has been superseded by an
        # active Published Local session; another meeting of the same subject
        # remains occupied.
        booked_official = query_db("""
            SELECT DISTINCT ss.roomid
            FROM schedule_sessions ss
            JOIN schedule_version sv ON ss.versionid = sv.versionid
            JOIN schedule s ON sv.scheduleid = s.scheduleid
            JOIN timeslot ts_s ON ss.starttimeid = ts_s.timeid
            JOIN timeslot ts_e ON ss.endtimeid   = ts_e.timeid
            WHERE sv.status = 'Published'
              AND UPPER(ss.daydesc) LIKE UPPER(%s)
              AND ts_s.timevalue < %s::time
              AND ts_e.timevalue > %s::time
              AND NOT EXISTS (
                  SELECT 1
                  FROM local_arrangement_sessions las_x
                  JOIN local_arrangement la_x
                    ON las_x.arrangementid = la_x.arrangementid
                  WHERE la_x.status = 'Published'
                    AND la_x.is_active = TRUE
                    AND la_x.semesterid = s.semesterid
                    AND la_x.sectionid = s.sectionid
                    AND las_x.official_sessionid = ss.sessionid
              )
        """, (f'%{day}%', end_time, start_time)) or []

        # Published local arrangement occupancy
        booked_local = query_db("""
            SELECT DISTINCT las.roomid
            FROM local_arrangement_sessions las
            JOIN local_arrangement la ON las.arrangementid = la.arrangementid
            JOIN timeslot ts_s ON las.starttimeid = ts_s.timeid
            JOIN timeslot ts_e ON las.endtimeid   = ts_e.timeid
            WHERE la.status = 'Published'
              AND la.is_active = TRUE
              AND UPPER(las.daydesc) LIKE UPPER(%s)
              AND ts_s.timevalue < %s::time
              AND ts_e.timevalue > %s::time
        """, (f'%{day}%', end_time, start_time)) or []

        booked_ids = {r['roomid'] for r in booked_official} | {r['roomid'] for r in booked_local}

        # If a specific date was given, also block rooms with approved makeup classes on that date
        if req_date and start_time and end_time:
            try:
                _ensure_request_tables()
                booked_makeup = query_db("""
                    SELECT DISTINCT cmr.new_roomid AS roomid
                    FROM class_meeting_request cmr
                    JOIN timeslot ts_s ON cmr.new_starttimeid = ts_s.timeid
                    JOIN timeslot ts_e ON cmr.new_endtimeid   = ts_e.timeid
                    WHERE cmr.status = 'Approved'
                      AND cmr.requested_date = %s
                      AND ts_s.timevalue < %s::time
                      AND ts_e.timevalue > %s::time
                """, (req_date, end_time, start_time)) or []
                booked_ids |= {r['roomid'] for r in booked_makeup if r['roomid']}
            except Exception as _me:
                print(f"[available_rooms makeup check] {_me}")

        available  = [{**dict(r), 'available': r['roomid'] not in booked_ids} for r in all_rooms]
        # Return only truly available rooms
        available  = [r for r in available if r['available']]
        return jsonify({'success': True, 'rooms': available})
    except Exception as e:
        print(f"[api_faculty_available_rooms] Error: {e}")
        return jsonify({'success': False, 'error': str(e)}), 500



def _structured_violation(code: str, v: dict) -> dict:
    """Shape one CSPValidator violation dict into the full structured schema
    (every field always present, None when this rule/check doesn't know it) so
    Generation, Manual Editor, Requests and Publish all display the same shape
    for the same violation, and the frontend can place an error indicator on
    the exact affected cell(s) via 'affected_components' instead of always
    defaulting to the Instructor column."""
    return {
        'rule':                      v.get('rule'),
        'rule_name':                 v.get('rule_name') or v.get('type'),
        'subject_code':              v.get('subject_code') or code,
        'assignment_id':             v.get('assignment_id'),
        'affected_components':       v.get('affected_components') or [],
        'faculty_id':                v.get('faculty_id'),
        'faculty_name':              v.get('faculty_name'),
        'room_id':                   v.get('room_id'),
        'room_name':                 v.get('room_name'),
        'section_id':                v.get('section_id'),
        'section_name':              v.get('section_name'),
        'normalized_days':           v.get('normalized_days') or [],
        'start_time':                v.get('start_time'),
        'end_time':                  v.get('end_time'),
        'conflicting_assignment_id': v.get('conflicting_assignment_id'),
        'conflicting_subject':       v.get('conflicting_subject'),
        'source':                    v.get('source') or 'current_result',
        'schedule_id':               v.get('schedule_id'),
        'schedule_version_id':       v.get('schedule_version_id'),
        'type':                      v.get('type'),
        'detail':                    v.get('detail'),
    }


def _json_safe(value):
    """
    Recursively convert a Python value into something json.dumps/jsonify can
    serialize natively, using EXPLICIT per-type rules — never a blind str()
    for any type this function already knows how to handle correctly. This is
    applied ONLY at the API response boundary, right before jsonify; internal
    CSP/GA/CBR code keeps real datetime.time objects (and any other native
    Python types it needs) for correct time-arithmetic comparisons — this
    function must never be called on data that is still headed back into the
    scheduler/validator, only on a payload about to leave as an HTTP response.
    """
    if value is None or isinstance(value, (bool, int, float, str)):
        return value
    # datetime is a subclass of date, so it must be checked first.
    if isinstance(value, datetime):
        return value.isoformat()
    if isinstance(value, time):
        return value.strftime('%H:%M')
    if isinstance(value, date):
        return value.isoformat()
    if isinstance(value, Decimal):
        return float(value)
    if isinstance(value, dict):
        return {k: _json_safe(v) for k, v in value.items()}
    if isinstance(value, (list, tuple, set, frozenset)):
        return [_json_safe(v) for v in value]
    # Last-resort, LOGGED fallback for a genuinely unrecognized type — never
    # the primary strategy for a known type, and never silent.
    print(f"[API SERIALIZE] Coercing unrecognized type {type(value).__name__} via str(): {value!r}")
    return str(value)


def _safe_json_response(payload, status=200):
    """
    The single place API responses in this route are serialized to JSON.
    Sanitizes the WHOLE payload (schedule rows, evaluation data, violations,
    exact_reuse metadata, conflicting-assignment data — everything, via
    _json_safe's recursive walk) and only then calls jsonify(). If something
    still fails to serialize afterward (a genuinely unanticipated type), the
    real exception is logged server-side and a structured
    RETRIEVE_PREVIOUS_SERIALIZATION_ERROR response is returned instead of a
    raw exception string — this must never be confused with "no previous
    schedule exists": the data WAS found, it just couldn't be prepared for
    display.
    """
    try:
        safe = _json_safe(payload)
        return jsonify(safe), status
    except Exception:
        import traceback; traceback.print_exc()
        return jsonify({
            'success': False,
            'error_code': 'RETRIEVE_PREVIOUS_SERIALIZATION_ERROR',
            'message': 'The previous schedule was found but could not be prepared for display.',
        }), 500


def _display_time_range(start, end):
    """Unambiguous 12-hour display range, e.g. "3:00 PM - 6:00 PM" — no
    leading zero on the hour, single hyphen with spaces. Distinct from
    scheduler.format_time_12h (which zero-pads the hour and is paired with an
    en-dash elsewhere in the app) — this is a dedicated formatter for this
    specific display requirement, not a change to the existing one."""
    def _one(t):
        h12 = t.hour % 12 or 12
        return f"{h12}:{t.minute:02d} {'AM' if t.hour < 12 else 'PM'}"
    return f"{_one(start)} - {_one(end)}"


