import time as _time_mod
_faculty_map_cache: dict = {}          # {'data': ..., 'ts': float}
_FACULTY_MAP_TTL = 60                  # seconds — refresh after 1 minute

def _load_faculty_map(force_refresh: bool = False):
    global _faculty_map_cache
    now = _time_mod.monotonic()
    if (not force_refresh
            and _faculty_map_cache.get('data')
            and now - _faculty_map_cache.get('ts', 0) < _FACULTY_MAP_TTL):
        return _faculty_map_cache['data']

    rows = query_db("""
        SELECT f.employeenumber, CONCAT(f.lastname, ', ', f.firstname) AS fullname,
               f.employeestatus, f.designationid, COALESCE(et.typename, '') AS typename,
               et.regularload, et.parttimeload,
               COALESCE(et.teachingsubstitution, 0) AS teachingsubstitution,
               et.regular_start, et.regular_end, et.parttime_start, et.parttime_end,
               COALESCE(et.restrict_pt_hours, TRUE) AS restrict_pt_hours,
               d.nightteachingservice, COALESCE(d.regularloadunit, 0) AS designation_regular_load,
               sp.specializationname
        FROM faculty f
        JOIN employeetype et ON f.employeetypeid = et.employeetypeid
        LEFT JOIN designation d       ON f.designationid    = d.designationid
        LEFT JOIN specialization sp   ON f.specializationid = sp.specializationid
        WHERE f.employeestatus != 'Archive'
    """)
    faculty_map = {}
    for row in (rows or []):
        fnum = row['employeenumber']
        # Cap lookup via faculty_load (shared with the GA and every other load surface) —
        # regularload/parttimeload/teachingsubstitution/regularloadunit are HOUR caps now.
        eff_regular, eff_parttime, eff_ts = faculty_load.get_faculty_caps(row)
        faculty_map[fnum] = {
            'employeenumber': fnum, 'fullname': row['fullname'],
            'employeestatus': row['employeestatus'], 'designationid': row['designationid'],
            'nightteachingservice': row['nightteachingservice'],
            'specializationname': row.get('specializationname') or '',
            'employeetype': {
                'regularload': eff_regular, 'parttimeload': eff_parttime,
                'teachingsubstitution': eff_ts,
                'regular_start': row['regular_start'] or time(7, 30),
                'regular_end': row['regular_end'] or time(16, 30),
                'parttime_start': row['parttime_start'], 'parttime_end': row['parttime_end'],
                'restrict_pt_hours': bool(row['restrict_pt_hours']),
            },
        }
    _faculty_map_cache = {'data': faculty_map, 'ts': now}
    return faculty_map


class ConstraintCheckUnavailable(RuntimeError):
    """A cross-section constraint check (HC8 / HC9 / HC15) could not read the
    data it validates against. Raised only when the caller asked to fail
    closed (Official Publish): an unverifiable check must block publication
    instead of silently reporting "no conflicts". Advisory callers (generation,
    Save Draft) keep the old non-blocking empty-result behavior."""


def _check_cross_program_faculty_loads(schedule_list, faculty_map, sem_id,
                                       exclude_program=None, exclude_year_level=None,
                                       fail_closed=False, exclude_section_id=None):
    """
    #11: Returns overload dicts for faculty who exceed their total load limit when
    the submitted schedule is combined with their existing Published/Draft load in
    OTHER sections this semester.

    HC9/HC17 (Phase 2): existing load comes from the shared merge-aware,
    Draft-preferred batch (faculty_load.get_faculty_load_batch) instead of a raw
    SUM that added a subject's Draft AND Published versions together and counted a
    same-faculty merged class once per section. Submitted rows are counted per
    meeting day, merge-aware, and a meeting that is the same valid merged class as
    one already counted in another section adds nothing. With exclude_section_id
    only the current section is excluded, so sibling sections of the same
    program/year still count.
    """
    if not schedule_list or not sem_id:
        return []

    from collections import defaultdict as _dd

    # _rehydrate_schedule (called earlier by the /approve path, mutating these dicts
    # in place since they're shared references from the same request.json payload)
    # may have already converted times from strings to datetime.time objects — accept
    # either shape rather than assuming raw JSON strings.
    def _t(v):
        return _parse_time_str(v) if isinstance(v, str) else v

    submitted_rows: dict = _dd(list)
    for cls in schedule_list:
        fid = cls.get('faculty_id') or cls.get('employeenumber')
        if not fid or str(fid).strip().upper() == 'TBA':
            continue  # TBA has no faculty to load-check
        start, end = _t(cls.get('start_time')), _t(cls.get('end_time'))
        if not start or not end or end <= start:
            continue
        days = cls.get('days_list') or [cls.get('day') or cls.get('daydesc')]
        if isinstance(days, str):
            days = _parse_days(days)
        days = [d for d in (days or []) if d]
        if not days:
            continue
        submitted_rows[fid].append({
            'faculty_id':   fid,
            'subject_code': cls.get('subject_code') or cls.get('subjectcode'),
            'days_list':    days,
            'start_time':   start,
            'end_time':     end,
            'programcode':  cls.get('course') or cls.get('program') or cls.get('programcode')
                            or exclude_program,
            'section_name': cls.get('section_name') or cls.get('sectionname'),
        })
    if not submitted_rows:
        return []

    conn = None
    try:
        conn = get_db_connection()
        if conn is None:
            if fail_closed:
                raise ConstraintCheckUnavailable('faculty load (HC9): database unavailable')
            return []
        cur  = conn.cursor(cursor_factory=RealDictCursor)
        cur.execute("SELECT academicyearid, semestertype FROM semester WHERE semesterid = %s",
                    (sem_id,))
        sem_row = cur.fetchone()
        if not sem_row:
            raise LookupError(f'semester {sem_id} not found')
        merge_cfg = load_scheduler_config()
        existing_loads = faculty_load.get_faculty_load_batch(
            cur, sem_row['academicyearid'], sem_row['semestertype'],
            exclude_program=(exclude_program or '').upper() or None,
            exclude_year_level=int(exclude_year_level) if exclude_year_level else None,
            exclude_section_id=_section_id_or_none(exclude_section_id),
            config=merge_cfg)
        cur.close()
    except ConstraintCheckUnavailable:
        raise
    except Exception as exc:
        if fail_closed:
            raise ConstraintCheckUnavailable(f'faculty load (HC9): {exc}') from exc
        return []
    finally:
        if conn is not None:
            conn.close()

    submitted_hrs = {}
    for fid, rows in submitted_rows.items():
        existing_summary = existing_loads.get(fid) or {}
        submitted_hrs[fid] = faculty_load.merge_aware_additional_hours(
            rows, existing_summary.get('slices') or [], config=merge_cfg)

    violations = []
    for fid, new_units in submitted_hrs.items():
        fac = faculty_map.get(fid, {})
        if not fac:
            continue
        et        = fac.get('employeetype', {})
        max_total = ((et.get('regularload') or 0)
                     + (et.get('parttimeload') or 0)
                     + (et.get('teachingsubstitution') or 0))
        if max_total <= 0:
            max_total = 99  # no configured limit → no cap
        existing  = faculty_load.load_total(existing_loads.get(fid))
        total     = round(existing + new_units, 2)
        if total > max_total:
            violations.append({
                'type':         'Conflict: Faculty Load',
                'faculty_id':   fid,
                'faculty_name': fac.get('fullname') or fid,
                'current_load': existing,
                'new_units':    new_units,
                'total_load':   total,
                'max_load':     max_total,
                'overload_by':  total - max_total,
            })
    return violations


def _check_designee_night_limit(schedule_list, faculty_map, sem_id,
                                exclude_program=None, exclude_year_level=None,
                                fail_closed=False, exclude_section_id=None,
                                replaced_codes=None):
    """
    Final HC8 (Designee PT Teaching-Night Limit) across sections. The in-schedule
    check is CSPValidator._check_night_pt_cap; this adds the nights a designee
    already uses elsewhere this semester, so saving/approving one section detects
    "this designee already teaches N nights elsewhere."

    Existing nights come from the LIVE effective schedule (Published Official minus
    Local-overridden occurrences, plus active Local Published) — never Drafts, so a
    Published subject and its pending Draft are not both counted. The candidate
    (schedule_list) REPLACES the live occurrences it stands for: with
    exclude_section_id, the live occurrences of `replaced_codes` (default: the
    candidate's own subjects) in that section are left out; the section's other live
    subjects and every sibling section still count. Without a section the legacy
    program+year exclusion applies.

    Uses the SAME shared rule helpers as CSPValidator and the GA
    (scheduler.designee_night_allowance / is_night_service_slice /
    designee_night_limit_detail): PT/Night Teaching Service = max DISTINCT days
    per week with teaching inside 6:00-9:00 PM; 0 = not allowed; 4:30-6:00 PM
    never counts.
    """
    from scheduler import (designee_night_allowance, is_night_service_slice,
                           designee_night_limit_detail, night_service_days, sort_days)

    def _t(v):
        return _parse_time_str(v) if isinstance(v, str) else v

    # Night days the submitted payload uses, per designee faculty
    submitted_nights: dict = {}
    for cls in schedule_list:
        fid = cls.get('faculty_id') or cls.get('employeenumber')
        if not fid or str(fid).strip().upper() == 'TBA':
            continue
        if designee_night_allowance(faculty_map.get(fid)) is None:
            continue
        if not is_night_service_slice(_t(cls.get('start_time')), _t(cls.get('end_time'))):
            continue
        days = cls.get('days_list') or [cls.get('day') or cls.get('daydesc')]
        if isinstance(days, str):
            days = _parse_days(days)
        for day in night_service_days(days):
            submitted_nights.setdefault(fid, set()).add(day)

    if not submitted_nights:
        return []

    conn = None
    try:
        conn = get_db_connection()
        if conn is None:
            if fail_closed:
                raise ConstraintCheckUnavailable('designee night limit (HC8): database unavailable')
            return []
        cur = conn.cursor(cursor_factory=RealDictCursor)
        if exclude_section_id:
            codes = replaced_codes
            if codes is None:
                codes = {(c.get('subject_code') or c.get('subjectcode') or '') for c in schedule_list}
            codes = sorted({str(c).strip().upper() for c in codes if str(c or '').strip()})
            exclusion, excl_params = ("es.sectionid = %s AND UPPER(cs.subjectcode) = ANY(%s)",
                                      [int(exclude_section_id), codes])
        else:
            exclusion, excl_params = ("UPPER(c.programcode) = %s AND cs.yearlevel = %s",
                                      [(exclude_program or '').upper(), int(exclude_year_level or 0)])
        cur.execute("WITH " + faculty_load.EFFECTIVE_SESSIONS_CTE + f"""
            SELECT es.employeenumber AS faculty_id, es.daydesc,
                   TO_CHAR(ts_s.timevalue, 'HH24:MI') AS start_time,
                   TO_CHAR(ts_e.timevalue, 'HH24:MI') AS end_time
            FROM effective_sessions es
            JOIN curriculumsubject cs ON es.curriculumsubjectid = cs.curriculumsubjectid
            JOIN curriculum c         ON cs.curriculumid        = c.curriculumid
            LEFT JOIN timeslot ts_s   ON es.starttimeid         = ts_s.timeid
            LEFT JOIN timeslot ts_e   ON es.endtimeid           = ts_e.timeid
            WHERE es.semesterid = %s
              AND es.employeenumber = ANY(%s)
              AND NOT ({exclusion})
        """, [sem_id, list(submitted_nights.keys())] + excl_params)
        rows = cur.fetchall() or []
        cur.close()
    except ConstraintCheckUnavailable:
        raise
    except Exception as exc:
        if fail_closed:
            raise ConstraintCheckUnavailable(f'designee night limit (HC8): {exc}') from exc
        return []
    finally:
        if conn is not None:
            conn.close()

    existing_nights: dict = {}
    for r in rows:
        fid = r['faculty_id']
        if fid not in submitted_nights or not night_service_days([r['daydesc']]):
            continue
        if not is_night_service_slice(_t(r['start_time']), _t(r['end_time'])):
            continue
        existing_nights.setdefault(fid, set()).add(r['daydesc'])

    violations = []
    for fid, new_days in submitted_nights.items():
        fac       = faculty_map[fid]
        allowance = designee_night_allowance(fac)
        already   = existing_nights.get(fid, set())
        combined  = already | new_days
        if len(combined) > allowance:
            violations.append({
                'rule':            'HC8',
                'type':            'Conflict: Faculty Night Load',
                'faculty_id':      fid,
                'faculty_name':    fac.get('fullname') or fid,
                'allowed_nights':  allowance,
                'existing_nights': sort_days(already),
                'night_days':      sort_days(combined),
                'total_nights':    len(combined),
                'detail': (
                    designee_night_limit_detail(fac, allowance, combined)
                    + (f' ({", ".join(sort_days(already))} already used in other sections this term.)'
                       if already else '')
                ),
            })
    return violations


def _parse_days(days_str: str) -> list:
    """Canonical day normalization for this module — delegates to
    scheduler.normalize_day_tokens (the same function CBR historical retrieval
    and CSP validation use) so compound tokens like 'MW'/'TTH'/'MTH' expand
    into their real component days here too, instead of this call site keeping
    its own weaker, single-token-only map that left them unrecognized. Falls
    back to the original per-token map for anything the canonical parser can't
    resolve (e.g. already-full day names like 'Monday'), so existing callers
    that already send well-formed input are unaffected.
    """
    if not days_str:
        return []
    try:
        from scheduler import normalize_day_tokens
        normalized = normalize_day_tokens(days_str)
        if normalized:
            return normalized
    except Exception:
        pass
    abbr_map = {'MON': 'Monday', 'TUE': 'Tuesday', 'WED': 'Wednesday', 'THU': 'Thursday', 'FRI': 'Friday', 'SAT': 'Saturday', 'SUN': 'Sunday'}
    return [abbr_map.get(d.strip().upper(), d.strip()) for d in days_str.split('/')]

def _parse_time_str(t_str: str):
    from datetime import datetime as _dt
    for fmt in ('%I:%M %p', '%H:%M', '%H:%M:%S'):
        try: return _dt.strptime(t_str.strip(), fmt).time()
        except ValueError: continue
    return None

def _serialize_class(cls: dict) -> dict:
    safe = {}
    for key, val in cls.items():
        # A datetime.time isn't JSON-serializable — stringify it ("HH:MM:SS", which
        # _parse_time_str's '%H:%M:%S' format below already round-trips) instead of
        # dropping the key entirely. Silently omitting start_time/end_time meant no
        # caller of this endpoint ever received them, and _rehydrate_schedule (used
        # when data comes back from the Manual Editor) already expects to find them
        # as strings and convert back — this was breaking that round-trip.
        if isinstance(val, time): safe[key] = val.strftime('%H:%M:%S')
        elif isinstance(val, list): safe[key] = [str(v) for v in val]
        else: safe[key] = val
    return safe

def _rehydrate_schedule(schedule_data: list) -> list:
    # Lazy-load room_type lookup map so final HC13 can check room type from room_id.
    _room_type_map = {}
    # Exclude non-numeric room ids (e.g. the 'TBA' sentinel) — passing one to the IN (...)
    # query below would raise a type error and silently drop room_type backfill for every
    # id in the batch, not just the TBA one.
    _room_ids_missing = [
        cls.get('room_id') for cls in schedule_data
        if cls.get('room_id') and not cls.get('room_type') and not cls.get('roomtype')
        and str(cls.get('room_id')).isdigit()
    ]
    if _room_ids_missing:
        try:
            _rt_rows = query_db(
                f"SELECT roomid, roomtype FROM room WHERE roomid IN ({','.join(['%s']*len(_room_ids_missing))})",
                _room_ids_missing
            ) or []
            _room_type_map = {str(r['roomid']): (r['roomtype'] or '') for r in _rt_rows}
        except Exception:
            pass

    for cls in schedule_data:
        if 'start_time' not in cls and 'time' in cls:
            try:
                parts = cls['time'].replace('–', '-').split('-')
                if len(parts) == 2:
                    cls['start_time'] = _parse_time_str(parts[0].strip())
                    cls['end_time']   = _parse_time_str(parts[1].strip())
            except Exception: pass
        # Also convert string start/end times to Python time objects
        # (the CSP validator requires time objects, not strings)
        if 'start_time' in cls and isinstance(cls['start_time'], str):
            cls['start_time'] = _parse_time_str(cls['start_time'])
        if 'end_time' in cls and isinstance(cls['end_time'], str):
            cls['end_time'] = _parse_time_str(cls['end_time'])
        if 'days_list' not in cls and 'days' in cls:
            cls['days_list'] = _parse_days(cls['days'])
        if 'day' not in cls and 'days_list' in cls and cls['days_list']:
            cls['day'] = cls['days_list'][0]
        # Normalize the hours field: manual editor sends 'units'; CSP validator
        # expects 'total_hours' or 'total_subject_hrs' for HC7 day-pairing check.
        if 'total_hours' not in cls and 'total_subject_hrs' not in cls:
            u = cls.get('units')
            if u is not None:
                try:
                    cls['total_hours'] = float(u)
                except (ValueError, TypeError):
                    pass
        # Populate room_type from DB lookup if client did not send it.
        # HC13 (_check_lab_room) needs this to verify lab-hour subjects are in lab rooms.
        if not cls.get('room_type') and not cls.get('roomtype'):
            rid = str(cls.get('room_id') or '')
            if rid and rid in _room_type_map:
                cls['room_type'] = _room_type_map[rid]
                cls['roomtype']  = _room_type_map[rid]
    return schedule_data

def _fmt_12h(t_str):
    try:
        parts = str(t_str).split(':')
        h, m = int(parts[0]), int(parts[1])
        suffix = 'PM' if h >= 12 else 'AM'
        h12 = h - 12 if h > 12 else (12 if h == 0 else h)
        return f"{h12}:{m:02d} {suffix}"
    except Exception: return str(t_str) if t_str else ''

def _get_semester_id(cur, acad_year, term):
    cur.execute("SELECT semesterid FROM public.semester WHERE academicyearid = %s AND semestertype = %s", (acad_year, term))
    result = cur.fetchone()
    if not result: raise Exception(f"Semester not found for {acad_year} {term}")
    return result['semesterid']

# ── DATABASE BATCH VERSIONING LOGIC ───────────────────────────────────

_SCHEDULE_REFERENCE_LABELS = {
    'local_sessions':      'Local Scheduler session(s) bound to these Official occurrences',
    'local_arrangements':  'Local Scheduler arrangement(s) anchored to these Official versions',
    'adjustment_requests': 'Schedule Adjustment request(s)',
    'makeup_requests':     'Make-up class request(s)',
    'exception_log':       'schedule exception log entr(ies)',
    'legacy_adjustments':  'legacy local schedule adjustment(s)',
}


def _schedule_delete_blockers(cur, scheduleids):
    """History / audit rows that still reference these Official schedule rows.

    Hard-deleting the schedules (and, by cascade, their versions and sessions) would orphan
    them or — for Archived Local history — would have to bypass its immutability. Callers
    must refuse the delete when this returns anything. Returns {kind: count} (non-zero only).
    """
    ids = [int(i) for i in (scheduleids or [])]
    if not ids:
        return {}
    cur.execute("""
        SELECT
          (SELECT COUNT(*) FROM public.local_arrangement_sessions las
             JOIN public.schedule_sessions ss ON ss.sessionid = las.official_sessionid
             JOIN public.schedule_version sv ON sv.versionid = ss.versionid
            WHERE sv.scheduleid = ANY(%(ids)s))                                   AS local_sessions,
          (SELECT COUNT(*) FROM public.local_arrangement la
             JOIN public.schedule_version sv ON sv.versionid = la.ref_versionid
            WHERE sv.scheduleid = ANY(%(ids)s))                                   AS local_arrangements,
          (SELECT COUNT(*) FROM public.schedule_change_request
            WHERE scheduleid = ANY(%(ids)s)
               OR versionid IN (SELECT versionid FROM public.schedule_version
                                WHERE scheduleid = ANY(%(ids)s)))                 AS adjustment_requests,
          (SELECT COUNT(*) FROM public.class_meeting_request
            WHERE scheduleid = ANY(%(ids)s))                                      AS makeup_requests,
          (SELECT COUNT(*) FROM public.schedule_exception_log
            WHERE scheduleid = ANY(%(ids)s))                                      AS exception_log,
          (SELECT COUNT(*) FROM public.local_schedule_adjustment
            WHERE scheduleid = ANY(%(ids)s))                                      AS legacy_adjustments
    """, {'ids': ids})
    row = cur.fetchone() or {}
    row = row if isinstance(row, dict) else dict(zip(_SCHEDULE_REFERENCE_LABELS, row))
    return {k: int(v) for k, v in row.items() if v}


def _schedule_delete_blocked_message(blockers):
    parts = [f"{n} {_SCHEDULE_REFERENCE_LABELS.get(k, k)}" for k, n in blockers.items()]
    return ('Cannot delete: these schedules are referenced by ' + '; '.join(parts)
            + '. Deleting them would destroy request / Local Scheduler history. '
              'Archive or resolve those records first.')


def _next_version_number(cur, program, year_level, semester_id, section_id=None):
    """Next schedule_version.version_number for a program/year-level (+ section) batch.

    Counted across ALL sources (manual_editor, import, official, local...). uq_schedule_
    version_number is UNIQUE(scheduleid, version_number) whatever the source, so a counter
    partitioned by source collides with e.g. an imported V1 on the very first manual Draft.
    The section's own schedule rows are included explicitly so a row reachable only through
    the section (not the program's curriculum join) can never be missed.
    """
    cur.execute("""
        SELECT COALESCE(MAX(sv.version_number), 0) AS max_v
        FROM public.schedule_version sv
        JOIN public.schedule s ON sv.scheduleid = s.scheduleid
        JOIN public.curriculumsubject cs ON s.curriculumsubjectid = cs.curriculumsubjectid
        JOIN public.curriculum c ON cs.curriculumid = c.curriculumid
        WHERE s.semesterid = %s
          AND ((UPPER(c.programcode) = UPPER(%s) AND cs.yearlevel = %s)
               OR (%s::int IS NOT NULL AND s.sectionid = %s::int))
    """, (semester_id, program, year_level, section_id, section_id))
    row = cur.fetchone()
    max_v = row['max_v'] if isinstance(row, dict) else row[0]
    return int(max_v or 0) + 1


def _resolve_timeids(cur):
    """Return a resolver mapping 'HH:MM', 'HH:MM:SS' or a time value to timeslot.timeid."""
    cur.execute("SELECT timeid, CAST(timevalue AS TEXT) AS tv FROM public.timeslot")
    ts_map = {}
    for r in (cur.fetchall() or []):
        tv = str(r['tv'] if isinstance(r, dict) else r[1])
        tid = r['timeid'] if isinstance(r, dict) else r[0]
        ts_map[tv] = tid
        ts_map[tv[:5]] = tid

    def _resolve(t):
        if t is None or t == '':
            return None
        s = str(t).strip()
        return ts_map.get(s) or ts_map.get(s[:8]) or ts_map.get(s[:5])
    return _resolve


def _removal_draft_codes(cur, semester_id, section_id, codes=None):
    """Subject codes whose current Official Draft in this section is a removal marker."""
    cur.execute("""
        SELECT DISTINCT UPPER(cs.subjectcode) AS code
        FROM public.schedule_version sv
        JOIN public.schedule s ON sv.scheduleid = s.scheduleid
        JOIN public.curriculumsubject cs ON s.curriculumsubjectid = cs.curriculumsubjectid
        WHERE s.semesterid = %s AND s.sectionid = %s
          AND sv.status = 'Draft' AND sv.is_removal = TRUE
          AND sv.source IS DISTINCT FROM 'local'
          AND (%s::text[] IS NULL OR UPPER(cs.subjectcode) = ANY(%s::text[]))
        ORDER BY 1
    """, (semester_id, section_id, codes, codes))
    return [r['code'] for r in (cur.fetchall() or [])]


def _published_scheduleids_for_codes(cur, semester_id, section_id, codes):
    """{CODE: scheduleid} for subjects that currently have a Published Official version."""
    if not codes:
        return {}
    cur.execute("""
        SELECT DISTINCT UPPER(cs.subjectcode) AS code, s.scheduleid
        FROM public.schedule_version sv
        JOIN public.schedule s ON sv.scheduleid = s.scheduleid
        JOIN public.curriculumsubject cs ON s.curriculumsubjectid = cs.curriculumsubjectid
        WHERE s.semesterid = %s AND s.sectionid = %s
          AND sv.status = 'Published' AND sv.source IS DISTINCT FROM 'local'
          AND UPPER(cs.subjectcode) = ANY(%s)
    """, (semester_id, section_id, list(codes)))
    return {r['code']: r['scheduleid'] for r in (cur.fetchall() or [])}


def _insert_removal_drafts(cur, scheduleids_by_code, version_number, source):
    """Write one removal-marker Draft (no sessions) per subject."""
    for code, sched_id in sorted(scheduleids_by_code.items()):
        cur.execute("""
            INSERT INTO public.schedule_version
                (scheduleid, version_number, status, datecreated, source, original_status, is_removal)
            VALUES (%s, %s, 'Draft', NOW(), %s, 'Draft', TRUE)
        """, (sched_id, version_number, source))


def _consume_published_drafts(cur, semester_id, section_id, published_rows,
                              subject_codes, removed_codes=(), version_number=None):
    """Retire the Official Draft content that a Publish actually replaced.

    Only Drafts of the subjects being published (subject_codes) or explicitly removed
    (removed_codes) are touched — an untouched subject's pending Draft stays exactly as it
    is (same versionid, same is_incomplete flag) and is NOT published.

    A Draft slice counts as published when the published rows carry its sessionid (an edit
    of that very slice) or publish the same subject+day+start. A published subject's
    remaining Draft slices (e.g. ones the user left unselected in the publish dialog) are
    re-saved as that subject's new Draft so nothing pending is lost. Removed subjects lose
    their whole Draft. Returns the version_number used for re-saved remainders, or None.
    """
    codes = sorted({str(c).upper() for c in subject_codes if c} | {str(c).upper() for c in removed_codes if c})
    if not codes:
        return None
    removed = {str(c).upper() for c in removed_codes if c}
    resolve = _resolve_timeids(cur)

    published_ids, published_slots = set(), set()
    for r in published_rows:
        code = str(r.get('subjectcode') or r.get('subject_code') or '').upper()
        sid = r.get('sessionid')
        if str(sid or '').strip().isdigit():
            published_ids.add(int(sid))
        start_id = resolve(r.get('start_time'))
        days = list(r.get('days_list') or []) or [r.get('daydesc') or r.get('day') or '']
        for day in days:
            if day and start_id:
                published_slots.add((code, str(day), start_id))

    cur.execute("""
        SELECT sv.versionid, sv.scheduleid, sv.source, sv.employeenumber,
               sv.is_incomplete, sv.incomplete_components, UPPER(cs.subjectcode) AS code
        FROM public.schedule_version sv
        JOIN public.schedule s ON sv.scheduleid = s.scheduleid
        JOIN public.curriculumsubject cs ON s.curriculumsubjectid = cs.curriculumsubjectid
        WHERE s.semesterid = %s
          AND s.sectionid = %s
          AND sv.status = 'Draft'
          AND sv.source IS DISTINCT FROM 'local'
          AND UPPER(cs.subjectcode) = ANY(%s)
        ORDER BY sv.versionid
        FOR UPDATE OF sv
    """, (semester_id, section_id, codes))
    drafts = cur.fetchall() or []
    used_version = None
    for d in drafts:
        cur.execute("""
            SELECT sessionid, daydesc, starttimeid, endtimeid, roomid
            FROM public.schedule_sessions WHERE versionid = %s ORDER BY sessionid
        """, (d['versionid'],))
        sessions = cur.fetchall() or []
        if d['code'] in removed:
            remaining = []
        else:
            remaining = [s for s in sessions
                         if s['sessionid'] not in published_ids
                         and (d['code'], str(s['daydesc']), s['starttimeid']) not in published_slots]
        cur.execute("UPDATE public.schedule_version SET status = 'Archive' WHERE versionid = %s",
                    (d['versionid'],))
        if not remaining:
            continue
        if version_number is None:
            raise ValueError('version_number is required to re-save a Draft remainder')
        cur.execute("""
            INSERT INTO public.schedule_version
                (scheduleid, version_number, status, datecreated, source, original_status,
                 employeenumber, is_incomplete, incomplete_components)
            VALUES (%s, %s, 'Draft', NOW(), %s, 'Draft', %s, %s, %s)
            RETURNING versionid
        """, (d['scheduleid'], version_number, d['source'] or 'manual_editor', d['employeenumber'],
              bool(d['is_incomplete']),
              json.dumps(d['incomplete_components']) if d['incomplete_components'] is not None else None))
        new_vid = cur.fetchone()['versionid']
        for s in remaining:
            cur.execute("""
                INSERT INTO public.schedule_sessions (versionid, daydesc, starttimeid, endtimeid, roomid)
                VALUES (%s, %s, %s, %s, %s)
            """, (new_vid, s['daydesc'], s['starttimeid'], s['endtimeid'], s['roomid']))
        used_version = version_number
    return used_version


def _archive_status(cur, program, year_level, term, semester_id, status_to_archive, source=None, section_id=None):
    # 'term' kept for signature compatibility; 's.semesterid = %s' already identifies the semester.
    # The old 'cs.semester = %s' filter was incorrectly restricting archiving to subjects whose
    # curriculum semester designation matched the current term, leaving other subjects un-archived
    # and causing duplicate Published records in SIS queries.
    #
    # section_id MUST be passed whenever the caller is acting on behalf of one specific section
    # (saving/publishing/deleting/restoring a draft for that section). Without it, this archives
    # every OTHER section of the same program+yearlevel+semester too — e.g. saving a draft for
    # BSCE1-2 would silently archive BSCE1-1's Draft/Published rows as collateral damage.
    extra = "AND sv.source = %s" if source else ""
    extra_sect = "AND s.sectionid = %s" if section_id else ""
    params = [program, year_level, semester_id, status_to_archive]
    if source:
        params.append(source)
    if section_id:
        params.append(section_id)
    cur.execute(f"""
        UPDATE public.schedule_version sv
        SET status = 'Archive'
        FROM public.schedule s, public.curriculumsubject cs, public.curriculum c
        WHERE sv.scheduleid = s.scheduleid AND s.curriculumsubjectid = cs.curriculumsubjectid
          AND cs.curriculumid = c.curriculumid
          AND c.programcode = %s
          AND cs.yearlevel = %s AND s.semesterid = %s AND sv.status = %s
          {extra}
          {extra_sect}
    """, params)

def _archive_status_for_subjects(cur, program, year_level, term, semester_id, status_to_archive, subject_codes, section_id=None):
    """Archive only sessions for specific subject codes, leaving other subjects' versions intact.

    section_id MUST be passed when the caller is acting on behalf of one specific section — see
    the warning in _archive_status above; the same cross-section bleed applies here otherwise.
    """
    if not subject_codes: return
    upper_codes = [s.upper() for s in subject_codes]
    placeholders = ','.join(['%s'] * len(upper_codes))
    extra_sect = "AND s.sectionid = %s" if section_id else ""
    # 'term' kept for signature compatibility; removed cs.semester = %s (same fix as _archive_status)
    params = [program, year_level, semester_id, status_to_archive] + upper_codes
    if section_id:
        params.append(section_id)
    cur.execute(f"""
        UPDATE public.schedule_version sv
        SET status = 'Archive'
        FROM public.schedule s, public.curriculumsubject cs, public.curriculum c
        WHERE sv.scheduleid = s.scheduleid AND s.curriculumsubjectid = cs.curriculumsubjectid
          AND cs.curriculumid = c.curriculumid
          AND c.programcode = %s
          AND cs.yearlevel = %s AND s.semesterid = %s AND sv.status = %s
          AND UPPER(cs.subjectcode) IN ({placeholders})
          {extra_sect}
    """, params)

def _group_carry_forward_sessions(sessions):
    """Group per-day rows from _fetch_section_sessions into multi-day items.

    _fetch_section_sessions returns one row per schedule_sessions entry (one per day).
    A paired-day subject yields two rows (e.g. Tuesday + Friday). Grouping them ensures
    _insert_batch creates a single schedule+version record with multiple sessions rows
    instead of two separate schedule+version records.
    """
    groups = {}
    order  = []
    for row in sessions:
        key = (
            (row.get('subjectcode') or '').upper(),
            str(row.get('employeenumber') or ''),
            str(row.get('start_time', '')),
            str(row.get('end_time', '')),
        )
        if key not in groups:
            item = dict(row)
            item['days_list'] = [row['daydesc']] if row.get('daydesc') else []
            groups[key] = item
            order.append(key)
        else:
            if row.get('daydesc') and row['daydesc'] not in groups[key]['days_list']:
                groups[key]['days_list'].append(row['daydesc'])
    return [groups[k] for k in order]


def _find_or_create_schedule(cur, cs_id, section_id, semester_id, employeenumber, target_status):
    """Find-or-create the ONE base public.schedule row for a logical
    (curriculumsubjectid, sectionid, semesterid) key, as required by
    uq_schedule_subject_section_semester — every Draft/Published/Archive version
    of that same subject+section+semester must share the same scheduleid instead
    of each save minting a new one (that was the root cause of the duplicate-key
    error: the old code unconditionally INSERTed a fresh schedule row on every
    save, which collided with this constraint the moment a subject was edited a
    second time).

    Uses INSERT ... ON CONFLICT DO NOTHING (find-first, not try/except-on-violation)
    so a concurrent duplicate save race is resolved atomically by Postgres itself,
    with the UNIQUE constraint kept in place as the actual safety net — never as
    normal control flow.

    schedule.employeenumber is shared by every version under this scheduleid (the
    schema has no per-version faculty column on schedule itself — see
    _ensure_schedule_version_empnum_col for where the per-version value actually
    lives). To keep an in-progress Draft edit from silently changing what the
    live Published version's faculty looks like to the many app-wide queries that
    still read schedule.employeenumber directly, this only overwrites it when:
      - the version being written is itself 'Published' (i.e. this save/publish
        IS the new source of truth), or
      - there is no Published version for this schedule yet (nothing to protect —
        e.g. a brand-new subject's very first Draft, or a subject that was never
        actually published).
    Returns the scheduleid to use for this save.
    """
    cur.execute("""
        INSERT INTO public.schedule (curriculumsubjectid, sectionid, employeenumber, semesterid, datecreated)
        VALUES (%s, %s, %s, %s, NOW())
        ON CONFLICT (curriculumsubjectid, sectionid, semesterid) DO NOTHING
        RETURNING scheduleid
    """, (cs_id, section_id, employeenumber, semester_id))
    row = cur.fetchone()
    if row:
        return row['scheduleid']

    # Row already existed — reuse it instead of creating a duplicate.
    cur.execute("""
        SELECT scheduleid FROM public.schedule
        WHERE curriculumsubjectid = %s AND sectionid = %s AND semesterid = %s
    """, (cs_id, section_id, semester_id))
    sched_id = cur.fetchone()['scheduleid']

    protect_published = (target_status != 'Published')
    if protect_published:
        cur.execute("""
            SELECT 1 FROM public.schedule_version
            WHERE scheduleid = %s AND status = 'Published' LIMIT 1
        """, (sched_id,))
        protect_published = cur.fetchone() is not None

    if not protect_published:
        cur.execute(
            "UPDATE public.schedule SET employeenumber = %s WHERE scheduleid = %s",
            (employeenumber, sched_id)
        )
    return sched_id


def _insert_batch(cur, schedule_data, semester_id, target_status, version_number, program, year_level, source='manual_editor', section_id=None, incomplete_map=None):
    """
    incomplete_map: optional {subject_code_upper: [reason, ...]} — subjects the
    caller (api_save_draft, from a PARTIAL_VALID generation result) knows have
    at least one unresolved component. schedule_version is one row PER SUBJECT
    (lecture+lab slices of the same subject share one scheduleid — see the
    _sched_to_version comment below), so this flags the whole version
    is_incomplete=True and records the reasons in incomplete_components.
    Returns the set of incomplete_map subject codes that never got a
    schedule_version row at all (every one of their slices lacked a real
    day/time and was skipped below — see the known limitation in the
    implementation report: a subject with ZERO resolved slices can't be
    represented in schedule_sessions, whose day/time columns are NOT NULL).
    """
    incomplete_map = incomplete_map or {}
    if not section_id:
        # Filter by the AY derived from semester_id so sections from other academic years
        # are not accidentally selected when multiple AYs share the same program/year-level.
        cur.execute("""
            SELECT sec.sectionid FROM public.sections sec
            JOIN public.program_yearlevel pyl ON sec.programyearlevelid = pyl.programyearlevelid
            WHERE UPPER(pyl.programcode) = UPPER(%s)
              AND pyl.yearlevel = %s
              AND pyl.academicyearid = (
                  SELECT academicyearid FROM public.semester WHERE semesterid = %s LIMIT 1
              )
            LIMIT 1
        """, (program, year_level, semester_id))
        sec_res = cur.fetchone()
        section_id = sec_res['sectionid'] if sec_res else None
    if not section_id:
        cur.execute("SELECT sectionid FROM public.sections LIMIT 1")
        section_id = cur.fetchone()['sectionid']

    # ── Pre-load lookup tables once instead of querying per subject ──────────
    # Timeslot map: "HH:MM:SS" → timeid
    cur.execute("SELECT timeid, CAST(timevalue AS TEXT) AS tv FROM public.timeslot")
    _ts_map = {}
    for r in (cur.fetchall() or []):
        tv = str(r['tv'])
        _ts_map[tv] = r['timeid']
        if len(tv) == 8:                 # "HH:MM:SS" → also index short form "HH:MM"
            _ts_map[tv[:5]] = r['timeid']

    def _ts_id(t):
        if not t: return None
        s = str(t).strip()
        return _ts_map.get(s) or _ts_map.get(s[:8]) or _ts_map.get(s[:5])

    # Curriculum subject map: UPPER(subjectcode) → curriculumsubjectid
    # Load all subjects for this program to avoid per-iteration SELECTs.
    cur.execute("""
        SELECT UPPER(cs.subjectcode) AS code, cs.curriculumsubjectid,
               cs.yearlevel, cs.semester
        FROM public.curriculumsubject cs
        JOIN public.curriculum c ON cs.curriculumid = c.curriculumid
        WHERE c.programcode = %s
    """, (program,))
    _cs_rows = cur.fetchall() or []
    # Full key (code+yl+sem) takes priority; fallback key (code+yl) tolerates a missing/
    # mismatched semester but must NEVER cross year levels — a subject that only exists in
    # the curriculum at one year level must not get silently attached to a different year
    # level's section just because the subject code happens to match.
    _cs_full: dict = {}   # (code, yl, sem) → cs_id
    _cs_yl:   dict = {}   # (code, yl) → cs_id  (fallback: ignores semester mismatch only)
    for r in _cs_rows:
        _cs_full[(r['code'], r['yearlevel'], r['semester'])] = r['curriculumsubjectid']
        _cs_yl[(r['code'], r['yearlevel'])] = r['curriculumsubjectid']
    # ─────────────────────────────────────────────────────────────────────────

    # A subject whose weekly meetings run at different times (e.g. a lecture and a lab
    # on different days/times/rooms) is NOT merged by _group_carry_forward_sessions —
    # that grouping only merges rows sharing an identical start/end time (paired-day GE
    # subjects). Such a subject therefore arrives here as multiple separate `cls` entries
    # that all resolve to the same scheduleid via _find_or_create_schedule. Without this
    # cache, each one would try to INSERT its own schedule_version row at the same
    # version_number and collide with uq_schedule_version_number (scheduleid, version_number)
    # — surfacing as "a schedule record for this subject/section/semester already exists"
    # even for subjects the caller never touched. Reusing the version row created for the
    # first slice keeps every slice of that subject under one version, as intended.
    _sched_to_version = {}
    _subjects_inserted: set = set()

    for cls in schedule_data:
        s_code = cls.get('subjectcode') or cls.get('subject_code')
        f_num  = cls.get('employeenumber') or cls.get('faculty_id')
        r_id   = cls.get('roomid') or cls.get('room_id')
        start_t, end_t = cls.get('start_time'), cls.get('end_time')

        # 'TBA' sentinel means faculty is To Be Announced — stored as NULL in the DB
        if str(f_num or '').strip().upper() == 'TBA':
            f_num = None

        # Collect all days — GA items have days_list with both days; per-day items use daydesc/day
        days_to_insert = list(cls.get('days_list') or [])
        if not days_to_insert:
            single = cls.get('daydesc') or cls.get('day')
            if single:
                days_to_insert = [single]

        # f_num may be None for TBA schedules — only skip if core fields are missing
        if not all([s_code, start_t, end_t]) or not days_to_insert: continue

        # Resolve curriculumsubjectid from pre-loaded map (no DB round-trip)
        code_up  = s_code.upper()
        cls_sem  = cls.get('sem') or cls.get('semester', '')
        cs_id    = (_cs_full.get((code_up, year_level, cls_sem))
                    or _cs_yl.get((code_up, year_level)))
        if not cs_id: continue

        # Resolve timeslot IDs from pre-loaded map (no DB round-trip)
        s_id = _ts_id(start_t)
        e_id = _ts_id(end_t)
        if not (s_id and e_id): continue

        sched_id = _find_or_create_schedule(cur, cs_id, section_id, semester_id, f_num, target_status)

        ver_id = _sched_to_version.get(sched_id)
        if ver_id is None:
            reasons = incomplete_map.get(code_up) or []
            cur.execute("""
                INSERT INTO public.schedule_version
                    (scheduleid, version_number, status, datecreated, source, original_status,
                     employeenumber, is_incomplete, incomplete_components)
                VALUES (%s, %s, %s, NOW(), %s, %s, %s, %s, %s) RETURNING versionid
            """, (sched_id, version_number, target_status, source, target_status, f_num,
                  bool(reasons), json.dumps(reasons) if reasons else None))
            ver_id = cur.fetchone()['versionid']
            _sched_to_version[sched_id] = ver_id

        _subjects_inserted.add(code_up)

        # Insert ONE schedule_sessions row per day (paired subjects get two rows under the same version)
        for day in days_to_insert:
            cur.execute("INSERT INTO public.schedule_sessions (versionid, daydesc, starttimeid, endtimeid, roomid) VALUES (%s, %s, %s, %s, %s)",
                        (ver_id, day, s_id, e_id, r_id if str(r_id).isdigit() else None))

    # Subjects the caller flagged incomplete that never got a single resolved
    # slice — no schedule_version row exists for them at all (see docstring).
    return {code for code in incomplete_map if code not in _subjects_inserted}

def _build_published_baseline(cur, program, year_level, sem_id, subject_codes, priority_sessions):
    """Return [] — all submitted subjects are fully replaced by sched_data.

    The old slot-level priority_keys approach carried forward any old Published session
    whose (subject, day, start_time) didn't match the new submission.  When the generator
    changed a subject's time or room, the stale old session appeared in existing_for_conflict
    at approval time and produced false 'room conflict' errors.

    The correct model: approving a schedule is a complete replacement for every submitted
    subject.  No old Published slot for a submitted subject should survive.
    Non-submitted subjects are already handled by other_sessions in api_approve_schedule.
    """
    return []


def _fetch_section_sessions(cur, program, year_level, sem_id, exclude_codes=None,
                            published_only=False, draft_only=False, section_id=None):
    """Return active manual_editor sessions for a section, excluding specified subject codes.

    Default (save-draft carry-forward):
        Draft-preferred: for each subject, Draft takes priority over Published.
        Subjects with only a Draft are included. Subjects with only Published are included
        via fallback — but see draft_only for a stricter carry-forward.

    published_only=True (used by approve/publish):
        Only subjects that have a current Published version are returned, with their
        Published rows — never a pending Draft's content. Draft-only subjects are excluded
        entirely so they don't bleed into Published snapshots.

    draft_only=True (used by save-draft carry-forward):
        Only subjects that have an active Draft version are carried forward.
        Subjects with only Published (never drafted) are excluded so Published content
        doesn't pollute the new Draft snapshot.

    section_id: when given, scopes rows to that section only. A program+year-level can have
        multiple sections (BSIT 1, BSIT 2, ...), each with its own independent schedule rows —
        omitting this let another section's Draft/Published sessions bleed into this section's
        carry-forward snapshot.
    """
    upper_excl = [c.upper() for c in (exclude_codes or [])]
    ph = ','.join(['%s'] * len(upper_excl)) if upper_excl else None
    excl_sql = f"AND UPPER(cs.subjectcode) NOT IN ({ph})" if ph else ""
    sect_sql = "AND sg.sectionid = %s" if section_id else ""
    if published_only:
        status_filter = "'Published'"
    elif draft_only:
        status_filter = "'Draft'"
    else:
        status_filter = "'Draft', 'Published'"

    cur.execute(f"""
        SELECT cs.subjectcode, cs.semester, COALESCE(sv.employeenumber, sg.employeenumber) AS employeenumber,
               ss.roomid, ss.daydesc,
               t_s.timevalue::text AS start_time,
               t_e.timevalue::text AS end_time,
               sv.status, sv.version_number
        FROM   schedule_version sv
        JOIN   schedule sg           ON sv.scheduleid          = sg.scheduleid
        JOIN   curriculumsubject cs   ON sg.curriculumsubjectid = cs.curriculumsubjectid
        JOIN   curriculum c           ON cs.curriculumid        = c.curriculumid
        JOIN   schedule_sessions ss   ON sv.versionid           = ss.versionid
        JOIN   timeslot t_s           ON ss.starttimeid         = t_s.timeid
        JOIN   timeslot t_e           ON ss.endtimeid           = t_e.timeid
        WHERE  c.programcode = %s
          AND  cs.yearlevel    = %s
          AND  sg.semesterid        = %s
          AND  sv.status IN ({status_filter})
          AND  sv.source != 'local'
          {excl_sql}
          {sect_sql}
    """, [program, year_level, sem_id] + upper_excl + ([int(section_id)] if section_id else []))

    rows = [dict(r) for r in cur.fetchall()]
    if not rows:
        return []

    subj_groups = {}
    for row in rows:
        subj_groups.setdefault(row['subjectcode'].upper(), []).append(row)

    result = []
    for rows_for_code in subj_groups.values():
        if published_only:
            # Carry an untouched subject into the new Published snapshot with its CURRENT
            # PUBLISHED content. A pending Draft on top of it was never approved: publishing
            # another subject must not publish it. That Draft stays pending as a Draft
            # (api_approve_schedule only retires Drafts of the subjects it publishes).
            chosen = [r for r in rows_for_code if r['status'] == 'Published']
        elif draft_only:
            # Only subjects with an actual Draft; subjects with only Published are skipped
            chosen = [r for r in rows_for_code if r['status'] == 'Draft']
        else:
            # Draft-preferred: use Draft if available, otherwise fall back to Published
            draft_rows = [r for r in rows_for_code if r['status'] == 'Draft']
            chosen = draft_rows or [r for r in rows_for_code if r['status'] == 'Published']
        if not chosen:
            continue
        best_v = max(r['version_number'] for r in chosen)
        result.extend(r for r in chosen if r['version_number'] == best_v)
    return result

